(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("virgil-aeneid-b",[{"sp":"HDR","t":"Liber I","st":"1"},{"sp":"N","t":"Arma virumque cano, Troiae qui primus ab oris<br>Italiam, fato profugus, Laviniaque venit<br>litora, multum ille et terris iactatus et alto<br>vi superum saevae memorem Iunonis ob iram;<br>multa quoque et bello passus, dum conderet urbem,   5<br>inferretque deos Latio, genus unde Latinum,<br>Albanique patres, atque altae moenia Romae.","st":"1"},{"sp":"N","t":"Musa, mihi causas memora, quo numine laeso,<br>quidve dolens, regina deum tot volvere casus<br>insignem pietate virum, tot adire labores   10<br>impulerit. Tantaene animis caelestibus irae?","st":"1"},{"sp":"N","t":"Urbs antiqua fuit, Tyrii tenuere coloni,<br>Karthago, Italiam contra Tiberinaque longe<br>ostia, dives opum studiisque asperrima belli;<br>quam Iuno fertur terris magis omnibus unam   15<br>posthabita coluisse Samo; hic illius arma,<br>hic currus fuit; hoc regnum dea gentibus esse,<br>si qua fata sinant, iam tum tenditque fovetque.<br>Progeniem sed enim Troiano a sanguine duci<br>audierat, Tyrias olim quae verteret arces;   20<br>hinc populum late regem belloque superbum<br>venturum excidio Libyae: sic volvere Parcas.<br>Id metuens, veterisque memor Saturnia belli,<br>prima quod ad Troiam pro caris gesserat Argis — <br>necdum etiam causae irarum saevique dolores   25<br>exciderant animo: manet alta mente repostum<br>iudicium Paridis spretaeque iniuria formae,<br>et genus invisum, et rapti Ganymedis honores.<br>His accensa super, iactatos aequore toto<br>Troas, reliquias Danaum atque immitis Achilli,   30<br>arcebat longe Latio, multosque per annos<br>errabant, acti fatis, maria omnia circum.<br>Tantae molis erat Romanam condere gentem!","st":"1"},{"sp":"N","t":"Vix e conspectu Siculae telluris in altum<br>vela dabant laeti, et spumas salis aere ruebant,   35<br>cum Iuno, aeternum servans sub pectore volnus,<br>haec secum: ‘Mene incepto desistere victam,<br>nec posse Italia Teucrorum avertere regem?<br>Quippe vetor fatis. Pallasne exurere classem<br>Argivom atque ipsos potuit submergere ponto,   40<br>unius ob noxam et furias Aiacis Oilei?<br>Ipsa, Iovis rapidum iaculata e nubibus ignem,<br>disiecitque rates evertitque aequora ventis,<br>illum expirantem transfixo pectore flammas<br>turbine corripuit scopuloque infixit acuto.   45<br>Ast ego, quae divom incedo regina, Iovisque<br>et soror et coniunx, una cum gente tot annos<br>bella gero! Et quisquam numen Iunonis adoret<br>praeterea, aut supplex aris imponet honorem?’","st":"1"},{"sp":"N","t":"Talia flammato secum dea corde volutans   50<br>nimborum in patriam, loca feta furentibus austris,<br>Aeoliam venit. Hic vasto rex Aeolus antro<br>luctantes ventos tempestatesque sonoras<br>imperio premit ac vinclis et carcere frenat.<br>Illi indignantes magno cum murmure montis   55<br>circum claustra fremunt; celsa sedet Aeolus arce<br>sceptra tenens, mollitque animos et temperat iras.<br>Ni faciat, maria ac terras caelumque profundum<br>quippe ferant rapidi secum verrantque per auras.<br>Sed pater omnipotens speluncis abdidit atris,   60<br>hoc metuens, molemque et montis insuper altos<br>imposuit, regemque dedit, qui foedere certo<br>et premere et laxas sciret dare iussus habenas.<br>Ad quem tum Iuno supplex his vocibus usa est:","st":"1"},{"sp":"N","t":"‘Aeole, namque tibi divom pater atque hominum rex   65<br>et mulcere dedit fluctus et tollere vento,<br>gens inimica mihi Tyrrhenum navigat aequor,<br>Ilium in Italiam portans victosque Penates:<br>incute vim ventis submersasque obrue puppes,<br>aut age diversos et disiice corpora ponto.   70<br>Sunt mihi bis septem praestanti corpore nymphae,<br>quarum quae forma pulcherrima Deiopea,<br>conubio iungam stabili propriamque dicabo,<br>omnis ut tecum meritis pro talibus annos<br>exigat, et pulchra faciat te prole parentem.’   75","st":"1"},{"sp":"N","t":"Aeolus haec contra: ‘Tuus, O regina, quid optes<br>explorare labor; mihi iussa capessere fas est.<br>Tu mihi, quodcumque hoc regni, tu sceptra Iovemque<br>concilias, tu das epulis accumbere divom,<br>nimborumque facis tempestatumque potentem.’   80","st":"1"},{"sp":"N","t":"Haec ubi dicta, cavum conversa cuspide montem<br>impulit in latus: ac venti, velut agmine facto,<br>qua data porta, ruunt et terras turbine perflant.<br>Incubuere mari, totumque a sedibus imis<br>una Eurusque Notusque ruunt creberque procellis   85<br>Africus, et vastos volvunt ad litora fluctus.<br>Insequitur clamorque virum stridorque rudentum.<br>Eripiunt subito nubes caelumque diemque<br>Teucrorum ex oculis; ponto nox incubat atra.<br>Intonuere poli, et crebris micat ignibus aether,   90<br>praesentemque viris intentant omnia mortem.","st":"1"},{"sp":"N","t":"Extemplo Aeneae solvuntur frigore membra:<br>ingemit, et duplicis tendens ad sidera palmas<br>talia voce refert: ‘O terque quaterque beati,<br>quis ante ora patrum Troiae sub moenibus altis   95<br>contigit oppetere! O Danaum fortissime gentis<br>Tydide! Mene Iliacis occumbere campis<br>non potuisse, tuaque animam hanc effundere dextra,<br>saevus ubi Aeacidae telo iacet Hector, ubi ingens<br>Sarpedon, ubi tot Simois correpta sub undis   100<br>scuta virum galeasque et fortia corpora volvit?’","st":"1"},{"sp":"N","t":"Talia iactanti stridens Aquilone procella<br>velum adversa ferit, fluctusque ad sidera tollit.<br>Franguntur remi; tum prora avertit, et undis<br>dat latus; insequitur cumulo praeruptus aquae mons.   105<br>Hi summo in flucta pendent; his unda dehiscens<br>terram inter fluctus aperit; furit aestus harenis.<br>Tris Notus abreptas in saxa latentia torquet — <br>saxa vocant Itali mediis quae in fluctibus aras — <br>dorsum immane mari summo; tris Eurus ab alto   110<br>in brevia et Syrtis urguet, miserabile visu,<br>inliditque vadis atque aggere cingit harenae.<br>Unam, quae Lycios fidumque vehebat Oronten,<br>ipsius ante oculos ingens a vertice pontus<br>in puppim ferit: excutitur pronusque magister   115<br>volvitur in caput; ast illam ter fluctus ibidem<br>torquet agens circum, et rapidus vorat aequore vortex.<br>Adparent rari nantes in gurgite vasto,<br>arma virum, tabulaeque, et Troia gaza per undas.<br>Iam validam Ilionei navem, iam fortis Achati,   120<br>et qua vectus Abas, et qua grandaevus Aletes,<br>vicit hiems; laxis laterum compagibus omnes<br>accipiunt inimicum imbrem, rimisque fatiscunt.","st":"1"},{"sp":"N","t":"Interea magno misceri murmure pontum,<br>emissamque hiemem sensit Neptunus, et imis   125<br>stagna refusa vadis, graviter commotus; et alto<br>prospiciens, summa placidum caput extulit unda.<br>Disiectam Aeneae, toto videt aequore classem,<br>fluctibus oppressos Troas caelique ruina,<br>nec latuere doli fratrem Iunonis et irae.   130<br>Eurum ad se Zephyrumque vocat, dehinc talia fatur:","st":"1"},{"sp":"N","t":"‘Tantane vos generis tenuit fiducia vestri?<br>Iam caelum terramque meo sine numine, venti,<br>miscere, et tantas audetis tollere moles?<br>Quos ego — sed motos praestat componere fluctus.   135<br>Post mihi non simili poena commissa luetis.<br>Maturate fugam, regique haec dicite vestro:<br>non illi imperium pelagi saevumque tridentem,<br>sed mihi sorte datum. Tenet ille immania saxa,<br>vestras, Eure, domos; illa se iactet in aula   140<br>Aeolus, et clauso ventorum carcere regnet.’","st":"1"},{"sp":"N","t":"Sic ait, et dicto citius tumida aequora placat,<br>collectasque fugat nubes, solemque reducit.<br>Cymothoe simul et Triton adnixus acuto<br>detrudunt navis scopulo; levat ipse tridenti;   145<br>et vastas aperit syrtis, et temperat aequor,<br>atque rotis summas levibus perlabitur undas.<br>Ac veluti magno in populo cum saepe coorta est<br>seditio, saevitque animis ignobile volgus,<br>iamque faces et saxa volant — furor arma ministrat;   150<br>tum, pietate gravem ac meritis si forte virum quem<br>conspexere, silent, arrectisque auribus adstant;<br>ille regit dictis animos, et pectora mulcet, — <br>sic cunctus pelagi cecidit fragor, aequora postquam<br>prospiciens genitor caeloque invectus aperto   155<br>flectit equos, curruque volans dat lora secundo.","st":"1"},{"sp":"N","t":"Defessi Aeneadae, quae proxima litora, cursu<br>contendunt petere, et Libyae vertuntur ad oras.<br>Est in secessu longo locus: insula portum<br>efficit obiectu laterum, quibus omnis ab alto   160<br>frangitur inque sinus scindit sese unda reductos.<br>Hinc atque hinc vastae rupes geminique minantur<br>in caelum scopuli, quorum sub vertice late<br>aequora tuta silent; tum silvis scaena coruscis<br>desuper horrentique atrum nemus imminet umbra.   165<br>Fronte sub adversa scopulis pendentibus antrum,<br>intus aquae dulces vivoque sedilia saxo,<br>nympharum domus: hic fessas non vincula navis<br>ulla tenent, unco non alligat ancora morsu.<br>Huc septem Aeneas collectis navibus omni   170<br>ex numero subit; ac magno telluris amore<br>egressi optata potiuntur Troes harena,<br>et sale tabentis artus in litore ponunt.<br>Ac primum silici scintillam excudit Achates,<br>succepitque ignem foliis, atque arida circum   175<br>nutrimenta dedit, rapuitque in fomite flammam.<br>Tum Cererem corruptam undis Cerealiaque arma<br>expediunt fessi rerum, frugesque receptas<br>et torrere parant flammis et frangere saxo.","st":"1"},{"sp":"N","t":"Aeneas scopulum interea conscendit, et omnem   180<br>prospectum late pelago petit, Anthea si quem<br>iactatum vento videat Phrygiasque biremis,<br>aut Capyn, aut celsis in puppibus arma Caici.<br>Navem in conspectu nullam, tris litore cervos<br>prospicit errantis; hos tota armenta sequuntur   185<br>a tergo, et longum per vallis pascitur agmen.<br>Constitit hic, arcumque manu celerisque sagittas<br>corripuit, fidus quae tela gerebat Achates;<br>ductoresque ipsos primum, capita alta ferentis<br>cornibus arboreis, sternit, tum volgus, et omnem   190<br>miscet agens telis nemora inter frondea turbam;<br>nec prius absistit, quam septem ingentia victor<br>corpora fundat humi, et numerum cum navibus aequet.<br>Hinc portum petit, et socios partitur in omnes.<br>Vina bonus quae deinde cadis onerarat Acestes   195<br>litore Trinacrio dederatque abeuntibus heros,<br>dividit, et dictis maerentia pectora mulcet:","st":"1"},{"sp":"N","t":"‘O socii — neque enim ignari sumus ante malorum — <br>O passi graviora, dabit deus his quoque finem.<br>Vos et Scyllaeam rabiem penitusque sonantis   200<br>accestis scopulos, vos et Cyclopea saxa<br>experti: revocate animos, maestumque timorem<br>mittite: forsan et haec olim meminisse iuvabit.<br>Per varios casus, per tot discrimina rerum<br>tendimus in Latium; sedes ubi fata quietas   205<br>ostendunt; illic fas regna resurgere Troiae.<br>Durate, et vosmet rebus servate secundis.’","st":"1"},{"sp":"N","t":"Talia voce refert, curisque ingentibus aeger<br>spem voltu simulat, premit altum corde dolorem.<br>Illi se praedae accingunt, dapibusque futuris;   210<br>tergora deripiunt costis et viscera nudant;<br>pars in frusta secant veribusque trementia figunt;<br>litore aena locant alii, flammasque ministrant.<br>Tum victu revocant vires, fusique per herbam<br>implentur veteris Bacchi pinguisque ferinae.   215<br>Postquam exempta fames epulis mensaeque remotae,<br>amissos longo socios sermone requirunt,<br>spemque metumque inter dubii, seu vivere credant,<br>sive extrema pati nec iam exaudire vocatos.<br>Praecipue pius Aeneas nunc acris Oronti,   220<br>nunc Amyci casum gemit et crudelia secum<br>fata Lyci, fortemque Gyan, fortemque Cloanthum.","st":"1"},{"sp":"N","t":"Et iam finis erat, cum Iuppiter aethere summo<br>despiciens mare velivolum terrasque iacentis<br>litoraque et latos populos, sic vertice caeli   225<br>constitit, et Libyae defixit lumina regnis.<br>Atque illum talis iactantem pectore curas<br>tristior et lacrimis oculos suffusa nitentis<br>adloquitur Venus: ‘O qui res hominumque deumque<br>aeternis regis imperiis, et fulmine terres,   230<br>quid meus Aeneas in te committere tantum,<br>quid Troes potuere, quibus, tot funera passis,<br>cunctus ob Italiam terrarum clauditur orbis?<br>Certe hinc Romanos olim, volventibus annis,<br>hinc fore ductores, revocato a sanguine Teucri,   235<br>qui mare, qui terras omni dicione tenerent,<br>pollicitus, quae te, genitor, sententia vertit?<br>Hoc equidem occasum Troiae tristisque ruinas<br>solabar, fatis contraria fata rependens;<br>nunc eadem fortuna viros tot casibus actos   240<br>insequitur. Quem das finem, rex magne, laborum?<br>Antenor potuit, mediis elapsus Achivis,<br>Illyricos penetrare sinus, atque intima tutus<br>regna Liburnorum, et fontem superare Timavi,<br>unde per ora novem vasto cum murmure montis   245<br>it mare proruptum et pelago premit arva sonanti.<br>Hic tamen ille urbem Patavi sedesque locavit<br>Teucrorum, et genti nomen dedit, armaque fixit<br>Troia; nunc placida compostus pace quiescit:<br>nos, tua progenies, caeli quibus adnuis arcem,   250<br>navibus (infandum!) amissis, unius ob iram<br>prodimur atque Italis longe disiungimur oris.<br>Hic pietatis honos? Sic nos in sceptra reponis?’","st":"1"},{"sp":"N","t":"Olli subridens hominum sator atque deorum,<br>voltu, quo caelum tempestatesque serenat,   255<br>oscula libavit natae, dehinc talia fatur:<br>‘Parce metu, Cytherea: manent immota tuorum<br>fata tibi; cernes urbem et promissa Lavini<br>moenia, sublimemque feres ad sidera caeli<br>magnanimum Aenean; neque me sententia vertit.   260<br>Hic tibi (fabor enim, quando haec te cura remordet,<br>longius et volvens fatorum arcana movebo)<br>bellum ingens geret Italia, populosque feroces<br>contundet, moresque viris et moenia ponet,<br>tertia dum Latio regnantem viderit aestas,   265<br>ternaque transierint Rutulis hiberna subactis.<br>At puer Ascanius, cui nunc cognomen Iulo<br>additur, — Ilus erat, dum res stetit Ilia regno, — <br>triginta magnos volvendis mensibus orbis<br>imperio explebit, regnumque ab sede Lavini   270<br>transferet, et longam multa vi muniet Albam.<br>Hic iam ter centum totos regnabitur annos<br>gente sub Hectorea, donec regina sacerdos,<br>Marte gravis, geminam partu dabit Ilia prolem.<br>Inde lupae fulvo nutricis tegmine laetus   275<br>Romulus excipiet gentem, et Mavortia condet<br>moenia, Romanosque suo de nomine dicet.<br>His ego nec metas rerum nec tempora pono;<br>imperium sine fine dedi. Quin aspera Iuno,<br>quae mare nunc terrasque metu caelumque fatigat,   280<br>consilia in melius referet, mecumque fovebit<br>Romanos rerum dominos gentemque togatam:<br>sic placitum. Veniet lustris labentibus aetas,<br>cum domus Assaraci Phthiam clarasque Mycenas<br>servitio premet, ac victis dominabitur Argis.   285<br>Nascetur pulchra Troianus origine Caesar,<br>imperium oceano, famam qui terminet astris, — <br>Iulius, a magno demissum nomen Iulo.<br>Hunc tu olim caelo, spoliis Orientis onustum,<br>accipies secura; vocabitur hic quoque votis.   290<br>Aspera tum positis mitescent saecula bellis;<br>cana Fides, et Vesta, Remo cum fratre Quirinus,<br>iura dabunt; dirae ferro et compagibus artis<br>claudentur Belli portae; Furor impius intus,<br>saeva sedens super arma, et centum vinctus aenis   295<br>post tergum nodis, fremet horridus ore cruento.’","st":"1"},{"sp":"N","t":"Haec ait, et Maia genitum demittit ab alto,<br>ut terrae, utque novae pateant Karthaginis arces<br>hospitio Teucris, ne fati nescia Dido<br>finibus arceret: volat ille per aera magnum   300<br>remigio alarum, ac Libyae citus adstitit oris.<br>Et iam iussa facit, ponuntque ferocia Poeni<br>corda volente deo; in primis regina quietum<br>accipit in Teucros animum mentemque benignam.","st":"1"},{"sp":"N","t":"At pius Aeneas, per noctem plurima volvens,   305<br>ut primum lux alma data est, exire locosque<br>explorare novos, quas vento accesserit oras,<br>qui teneant, nam inculta videt, hominesne feraene,<br>quaerere constituit, sociisque exacta referre<br>Classem in convexo nemorum sub rupe cavata   310<br>arboribus clausam circum atque horrentibus umbris<br>occulit; ipse uno graditur comitatus Achate,<br>bina manu lato crispans hastilia ferro.","st":"1"},{"sp":"N","t":"Cui mater media sese tulit obvia silva,<br>virginis os habitumque gerens, et virginis arma   315<br>Spartanae, vel qualis equos Threissa fatigat<br>Harpalyce, volucremque fuga praevertitur Hebrum.<br>Namque umeris de more habilem suspenderat arcum<br>venatrix, dederatque comam diffundere ventis,<br>nuda genu, nodoque sinus collecta fluentis.   320<br>Ac prior, ‘Heus’ inquit ‘iuvenes, monstrate mearum<br>vidistis si quam hic errantem forte sororum,<br>succinctam pharetra et maculosae tegmine lyncis,<br>aut spumantis apri cursum clamore prementem.’","st":"1"},{"sp":"N","t":"Sic Venus; et Veneris contra sic filius orsus:   325<br>‘Nulla tuarum audita mihi neque visa sororum — <br>O quam te memorem, virgo? Namque haud tibi voltus<br>mortalis, nec vox hominem sonat: O, dea certe — <br>an Phoebi soror? an nympharum sanguinis una? — <br>sis felix, nostrumque leves, quaecumque, laborem,   330<br>et, quo sub caelo tandem, quibus orbis in oris<br>iactemur, doceas. Ignari hominumque locorumque<br>erramus, vento huc vastis et fluctibus acti:<br>multa tibi ante aras nostra cadet hostia dextra.’","st":"1"},{"sp":"N","t":"Tum Venus: ‘Haud equidem tali me dignor honore;   335<br>virginibus Tyriis mos est gestare pharetram,<br>purpureoque alte suras vincire cothurno.<br>Punica regna vides, Tyrios et Agenoris urbem;<br>sed fines Libyci, genus intractabile bello.<br>Imperium Dido Tyria regit urbe profecta,   340<br>germanum fugiens. Longa est iniuria, longae<br>ambages; sed summa sequar fastigia rerum.","st":"1"},{"sp":"N","t":"‘Huic coniunx Sychaeus erat, ditissimus agri<br>Phoenicum, et magno miserae dilectus amore,<br>cui pater intactam dederat, primisque iugarat   345<br>ominibus. Sed regna Tyri germanus habebat<br>Pygmalion, scelere ante alios immanior omnes.<br>Quos inter medius venit furor. Ille Sychaeum<br>impius ante aras, atque auri caecus amore,<br>clam ferro incautum superat, securus amorum   350<br>germanae; factumque diu celavit, et aegram,<br>multa malus simulans, vana spe lusit amantem.<br>Ipsa sed in somnis inhumati venit imago<br>coniugis, ora modis attollens pallida miris,<br>crudeles aras traiectaque pectora ferro   355<br>nudavit, caecumque domus scelus omne retexit.<br>Tum celerare fugam patriaque excedere suadet,<br>auxiliumque viae veteres tellure recludit<br>thesauros, ignotum argenti pondus et auri.<br>His commota fugam Dido sociosque parabat:   360<br>conveniunt, quibus aut odium crudele tyranni<br>aut metus acer erat; navis, quae forte paratae,<br>corripiunt, onerantque auro: portantur avari<br>Pygmalionis opes pelago; dux femina facti.<br>Devenere locos, ubi nunc ingentia cernis   365<br>moenia surgentemque novae Karthaginis arcem,<br>mercatique solum, facti de nomine Byrsam,<br>taurino quantum possent circumdare tergo.<br>Sed vos qui tandem, quibus aut venistis ab oris,<br>quove tenetis iter? ‘Quaerenti talibus ille   370<br>suspirans, imoque trahens a pectore vocem:","st":"1"},{"sp":"N","t":"‘O dea, si prima repetens ab origine pergam,<br>et vacet annalis nostrorum audire laborum,<br>ante diem clauso componat Vesper Olympo.<br>Nos Troia antiqua, si vestras forte per auris   375<br>Troiae nomen iit, diversa per aequora vectos<br>forte sua Libycis tempestas adpulit oris.<br>Sum pius Aeneas, raptos qui ex hoste Penates<br>classe veho mecum, fama super aethera notus.<br>Italiam quaero patriam et genus ab Iove summo.   380<br>Bis denis Phrygium conscendi navibus aequor,<br>matre dea monstrante viam, data fata secutus;<br>vix septem convolsae undis Euroque supersunt.<br>Ipse ignotus, egens, Libyae deserta peragro,<br>Europa atque Asia pulsus.’ Nec plura querentem   385<br>passa Venus medio sic interfata dolore est:","st":"1"},{"sp":"N","t":"‘Quisquis es, haud, credo, invisus caelestibus auras<br>vitalis carpis, Tyriam qui adveneris urbem.<br>Perge modo, atque hinc te reginae ad limina perfer,<br>Namque tibi reduces socios classemque relatam   390<br>nuntio, et in tutum versis aquilonibus actam,<br>ni frustra augurium vani docuere parentes.<br>Aspice bis senos laetantis agmine cycnos,<br>aetheria quos lapsa plaga Iovis ales aperto<br>turbabat caelo; nunc terras ordine longo   395<br>aut capere, aut captas iam despectare videntur:<br>ut reduces illi ludunt stridentibus alis,<br>et coetu cinxere polum, cantusque dedere,<br>haud aliter puppesque tuae pubesque tuorum<br>aut portum tenet aut pleno subit ostia velo.   400<br>Perge modo, et, qua te ducit via, dirige gressum.’","st":"1"},{"sp":"N","t":"Dixit, et avertens rosea cervice refulsit,<br>ambrosiaeque comae divinum vertice odorem<br>spiravere, pedes vestis defluxit ad imos,<br>et vera incessu patuit dea. Ille ubi matrem   405<br>adgnovit, tali fugientem est voce secutus:<br>‘Quid natum totiens, crudelis tu quoque, falsis<br>ludis imaginibus? Cur dextrae iungere dextram<br>non datur, ac veras audire et reddere voces?’","st":"1"},{"sp":"N","t":"Talibus incusat, gressumque ad moenia tendit:   410<br>at Venus obscuro gradientes aere saepsit,<br>et multo nebulae circum dea fudit amictu,<br>cernere ne quis eos, neu quis contingere posset,<br>molirive moram, aut veniendi poscere causas.<br>Ipsa Paphum sublimis abit, sedesque revisit   415<br>laeta suas, ubi templum illi, centumque Sabaeo<br>ture calent arae, sertisque recentibus halant.","st":"1"},{"sp":"N","t":"Corripuere viam interea, qua semita monstrat.<br>Iamque ascendebant collem, qui plurimus urbi<br>imminet, adversasque adspectat desuper arces.   420<br>Miratur molem Aeneas, magalia quondam,<br>miratur portas strepitumque et strata viarum.<br>Instant ardentes Tyrii pars ducere muros,<br>molirique arcem et manibus subvolvere saxa,<br>pars optare locum tecto et concludere sulco.   425<br>[Iura magistratusque legunt sanctumque senatum;]<br>hic portus alii effodiunt; hic alta theatris<br>fundamenta locant alii, immanisque columnas<br>rupibus excidunt, scaenis decora alta futuris.<br>Qualis apes aestate nova per florea rura   430<br>exercet sub sole labor, cum gentis adultos<br>educunt fetus, aut cum liquentia mella<br>stipant et dulci distendunt nectare cellas,<br>aut onera accipiunt venientum, aut agmine facto<br>ignavom fucos pecus a praesepibus arcent:   435<br>fervet opus, redolentque thymo fragrantia mella.<br>‘O fortunati, quorum iam moenia surgunt!’<br>Aeneas ait, et fastigia suspicit urbis.<br>Infert se saeptus nebula, mirabile dictu,<br>per medios, miscetque viris, neque cernitur ulli.   440","st":"1"},{"sp":"N","t":"Lucus in urbe fuit media, laetissimus umbra,<br>quo primum iactati undis et turbine Poeni<br>effodere loco signum, quod regia Iuno<br>monstrarat, caput acris equi; sic nam fore bello<br>egregiam et facilem victu per saecula gentem.   445<br>Hic templum Iunoni ingens Sidonia Dido<br>condebat, donis opulentum et numine divae,<br>aerea cui gradibus surgebant limina, nexaeque<br>aere trabes, foribus cardo stridebat aenis.<br>Hoc primum in luco nova res oblata timorem   450<br>leniit, hic primum Aeneas sperare salutem<br>ausus, et adflictis melius confidere rebus.<br>Namque sub ingenti lustrat dum singula templo,<br>reginam opperiens, dum, quae fortuna sit urbi,<br>artificumque manus inter se operumque laborem   455<br>miratur, videt Iliacas ex ordine pugnas,<br>bellaque iam fama totum volgata per orbem,<br>Atridas, Priamumque, et saevum ambobus Achillem.<br>Constitit, et lacrimans, ‘Quis iam locus’ inquit ‘Achate,<br>quae regio in terris nostri non plena laboris?   460<br>En Priamus! Sunt hic etiam sua praemia laudi;<br>sunt lacrimae rerum et mentem mortalia tangunt.<br>Solve metus; feret haec aliquam tibi fama salutem.’<br>Sic ait, atque animum pictura pascit inani,<br>multa gemens, largoque umectat flumine voltum.   465","st":"1"},{"sp":"N","t":"Namque videbat, uti bellantes Pergama circum<br>hac fugerent Graii, premeret Troiana iuventus,<br>hac Phryges, instaret curru cristatus Achilles.<br>Nec procul hinc Rhesi niveis tentoria velis<br>adgnoscit lacrimans, primo quae prodita somno   470<br>Tydides multa vastabat caede cruentus,<br>ardentisque avertit equos in castra, prius quam<br>pabula gustassent Troiae Xanthumque bibissent.<br>Parte alia fugiens amissis Troilus armis,<br>infelix puer atque impar congressus Achilli,   475<br>fertur equis, curruque haeret resupinus inani,<br>lora tenens tamen; huic cervixque comaeque trahuntur<br>per terram, et versa pulvis inscribitur hasta.<br>Interea ad templum non aequae Palladis ibant<br>crinibus Iliades passis peplumque ferebant,   480<br>suppliciter tristes et tunsae pectora palmis;<br>diva solo fixos oculos aversa tenebat.<br>Ter circum Iliacos raptaverat Hectora muros,<br>exanimumque auro corpus vendebat Achilles.<br>Tum vero ingentem gemitum dat pectore ab imo,   485<br>ut spolia, ut currus, utque ipsum corpus amici,<br>tendentemque manus Priamum conspexit inermis.<br>Se quoque principibus permixtum adgnovit Achivis,<br>Eoasque acies et nigri Memnonis arma.<br>Ducit Amazonidum lunatis agmina peltis   490<br>Penthesilea furens, mediisque in milibus ardet,<br>aurea subnectens exsertae cingula mammae,<br>bellatrix, audetque viris concurrere virgo.","st":"1"},{"sp":"N","t":"Haec dum Dardanio Aeneae miranda videntur,<br>dum stupet, obtutuque haeret defixus in uno,   495<br>regina ad templum, forma pulcherrima Dido,<br>incessit magna iuvenum stipante caterva.<br>Qualis in Eurotae ripis aut per iuga Cynthi<br>exercet Diana choros, quam mille secutae<br>hinc atque hinc glomerantur oreades; illa pharetram   500<br>fert umero, gradiensque deas supereminet omnis:<br>Latonae tacitum pertemptant gaudia pectus:<br>talis erat Dido, talem se laeta ferebat<br>per medios, instans operi regnisque futuris.<br>Tum foribus divae, media testudine templi,   505<br>saepta armis, solioque alte subnixa resedit.<br>Iura dabat legesque viris, operumque laborem<br>partibus aequabat iustis, aut sorte trahebat:<br>cum subito Aeneas concursu accedere magno<br>Anthea Sergestumque videt fortemque Cloanthum,   510<br>Teucrorumque alios, ater quos aequore turbo<br>dispulerat penitusque alias avexerat oras.<br>Obstipuit simul ipse simul perculsus Achates<br>laetitiaque metuque; avidi coniungere dextras<br>ardebant; sed res animos incognita turbat.   515<br>Dissimulant, et nube cava speculantur amicti,<br>quae fortuna viris, classem quo litore linquant,<br>quid veniant; cunctis nam lecti navibus ibant,<br>orantes veniam, et templum clamore petebant.","st":"1"},{"sp":"N","t":"Postquam introgressi et coram data copia fandi,   520<br>maximus Ilioneus placido sic pectore coepit:<br>‘O Regina, novam cui condere Iuppiter urbem<br>iustitiaque dedit gentis frenare superbas,<br>Troes te miseri, ventis maria omnia vecti,<br>oramus, prohibe infandos a navibus ignis,   525<br>parce pio generi, et propius res aspice nostras.<br>Non nos aut ferro Libycos populare Penatis<br>venimus, aut raptas ad litora vertere praedas;<br>non ea vis animo, nec tanta superbia victis.<br>Est locus, Hesperiam Grai cognomine dicunt,   530<br>terra antiqua, potens armis atque ubere glaebae;<br>Oenotri coluere viri; nunc fama minores<br>Italiam dixisse ducis de nomine gentem.<br>Hic cursus fuit:<br>cum subito adsurgens fluctu nimbosus Orion   535<br>in vada caeca tulit, penitusque procacibus austris<br>perque undas, superante salo, perque invia saxa<br>dispulit; huc pauci vestris adnavimus oris.<br>Quod genus hoc hominum? Quaeve hunc tam barbara morem<br>permittit patria? Hospitio prohibemur harenae;   540<br>bella cient, primaque vetant consistere terra.<br>Si genus humanum et mortalia temnitis arma<br>at sperate deos memores fandi atque nefandi.","st":"1"},{"sp":"N","t":"‘Rex erat Aeneas nobis, quo iustior alter,<br>nec pietate fuit, nec bello maior et armis.   545<br>Quem si fata virum servant, si vescitur aura<br>aetheria, neque adhuc crudelibus occubat umbris,<br>non metus; officio nec te certasse priorem<br>poeniteat. Sunt et Siculis regionibus urbes<br>armaque, Troianoque a sanguine clarus Acestes.   550<br>Quassatam ventis liceat subducere classem,<br>et silvis aptare trabes et stringere remos:<br>si datur Italiam, sociis et rege recepto,<br>tendere, ut Italiam laeti Latiumque petamus;<br>sin absumpta salus, et te, pater optime Teucrum,   555<br>pontus habet Libyae, nec spes iam restat Iuli,<br>at freta Sicaniae saltem sedesque paratas,<br>unde huc advecti, regemque petamus Acesten.’","st":"1"},{"sp":"N","t":"Talibus Ilioneus; cuncti simul ore fremebant<br>Dardanidae.               560","st":"1"},{"sp":"N","t":"Tum breviter Dido, voltum demissa, profatur:<br>‘Solvite corde metum, Teucri, secludite curas.<br>Res dura et regni novitas me talia cogunt<br>moliri, et late finis custode tueri.<br>Quis genus Aeneadum, quis Troiae nesciat urbem,   565<br>virtutesque virosque, aut tanti incendia belli?<br>Non obtusa adeo gestamus pectora Poeni,<br>nec tam aversus equos Tyria Sol iungit ab urbe.<br>Seu vos Hesperiam magnam Saturniaque arva,<br>sive Erycis finis regemque optatis Acesten,   570<br>auxilio tutos dimittam, opibusque iuvabo.<br>Voltis et his mecum pariter considere regnis;<br>urbem quam statuo vestra est, subducite navis;<br>Tros Tyriusque mihi nullo discrimine agetur.<br>Atque utinam rex ipse Noto compulsus eodem   575<br>adforet Aeneas! Equidem per litora certos<br>dimittam et Libyae lustrare extrema iubebo,<br>si quibus eiectus silvis aut urbibus errat.’","st":"1"},{"sp":"N","t":"His animum arrecti dictis et fortis Achates<br>et pater Aeneas iamdudum erumpere nubem   580<br>ardebant. Prior Aenean compellat Achates:<br>‘Nate dea, quae nunc animo sententia surgit?<br>omnia tuta vides, classem sociosque receptos.<br>Unus abest, medio in fluctu quem vidimus ipsi<br>submersum; dictis respondent cetera matris.’   585","st":"1"},{"sp":"N","t":"Vix ea fatus erat, cum circumfusa repente<br>scindit se nubes et in aethera purgat apertum.<br>Restitit Aeneas claraque in luce refulsit,<br>os umerosque deo similis; namque ipsa decoram<br>caesariem nato genetrix lumenque iuventae   590<br>purpureum et laetos oculis adflarat honores:<br>quale manus addunt ebori decus, aut ubi flavo<br>argentum Pariusve lapis circumdatur auro.","st":"1"},{"sp":"N","t":"Tum sic reginam adloquitur, cunctisque repente<br>improvisus ait: ‘Coram, quem quaeritis, adsum,   595<br>Troius Aeneas, Libycis ereptus ab undis.<br>O sola infandos Troiae miserata labores,<br>quae nos, reliquias Danaum, terraeque marisque<br>omnibus exhaustos iam casibus, omnium egenos,<br>urbe, domo, socias, grates persolvere dignas   600<br>non opis est nostrae, Dido, nec quicquid ubique est<br>gentis Dardaniae, magnum quae sparsa per orbem.<br>Di tibi, si qua pios respectant numina, si quid<br>usquam iustitia est et mens sibi conscia recti,<br>praemia digna ferant. Quae te tam laeta tulerunt   605<br>saecula? Qui tanti talem genuere parentes?<br>In freta dum fluvii current, dum montibus umbrae<br>lustrabunt convexa, polus dum sidera pascet,<br>semper honos nomenque tuum laudesque manebunt,<br>quae me cumque vocant terrae.’ Sic fatus, amicum   610<br>Ilionea petit dextra, laevaque Serestum,<br>post alios, fortemque Gyan fortemque Cloanthum.","st":"1"},{"sp":"N","t":"Obstipuit primo aspectu Sidonia Dido,<br>casu deinde viri tanto, et sic ore locuta est:<br>‘Quis te, nate dea, per tanta pericula casus   615<br>insequitur? Quae vis immanibus applicat oris?<br>Tune ille Aeneas, quem Dardanio Anchisae<br>alma Venus Phrygii genuit Simoentis ad undam?<br>Atque equidem Teucrum memini Sidona venire<br>finibus expulsum patriis, nova regna petentem   620<br>auxilio Beli; genitor tum Belus opimam<br>vastabat Cyprum, et victor dicione tenebat.<br>Tempore iam ex illo casus mihi cognitus urbis<br>Troianae nomenque tuum regesque Pelasgi.<br>Ipse hostis Teucros insigni laude ferebat,   625<br>seque ortum antiqua Teucrorum ab stirpe volebat.<br>Quare agite, O tectis, iuvenes, succedite nostris.<br>Me quoque per multos similis fortuna labores<br>iactatam hac demum voluit consistere terra.<br>Non ignara mali, miseris succurrere disco.’   630","st":"1"},{"sp":"N","t":"Sic memorat; simul Aenean in regia ducit<br>tecta, simul divom templis indicit honorem.<br>Nec minus interea sociis ad litora mittit<br>viginti tauros, magnorum horrentia centum<br>terga suum, pinguis centum cum matribus agnos,   635<br>munera laetitiamque dii.","st":"1"},{"sp":"N","t":"At domus interior regali splendida luxu<br>instruitur, mediisque parant convivia tectis:<br>arte laboratae vestes ostroque superbo,<br>ingens argentum mensis, caelataque in auro   640<br>fortia facta patrum, series longissima rerum<br>per tot ducta viros antiqua ab origine gentis.","st":"1"},{"sp":"N","t":"Aeneas (neque enim patrius consistere mentem<br>passus amor) rapidum ad navis praemittit Achaten,<br>Ascanio ferat haec, ipsumque ad moenia ducat;   645<br>omnis in Ascanio cari stat cura parentis.<br>Munera praeterea, Iliacis erepta ruinis,<br>ferre iubet, pallam signis auroque rigentem,<br>et circumtextum croceo velamen acantho,<br>ornatus Argivae Helenae, quos illa Mycenis,   650<br>Pergama cum peteret inconcessosque hymenaeos,<br>extulerat, matris Ledae mirabile donum:<br>praeterea sceptrum, Ilione quod gesserat olim,<br>maxima natarum Priami, colloque monile<br>bacatum, et duplicem gemmis auroque coronam.   655<br>Haec celerans ita ad naves tendebat Achates.","st":"1"},{"sp":"N","t":"At Cytherea novas artes, nova pectore versat<br>Consilia, ut faciem mutatus et ora Cupido<br>pro dulci Ascanio veniat, donisque furentem<br>incendat reginam, atque ossibus implicet ignem;   660<br>quippe domum timet ambiguam Tyriosque bilinguis;<br>urit atrox Iuno, et sub noctem cura recursat.<br>Ergo his aligerum dictis adfatur Amorem:","st":"1"},{"sp":"N","t":"‘Nate, meae vires, mea magna potentia solus,<br>nate, patris summi qui tela Typhoia temnis,   665<br>ad te confugio et supplex tua numina posco.<br>Frater ut Aeneas pelago tuus omnia circum<br>litora iactetur odiis Iunonis iniquae,<br>nota tibi, et nostro doluisti saepe dolore.<br>Hunc Phoenissa tenet Dido blandisque moratur   670<br>vocibus; et vereor, quo se Iunonia vertant<br>hospitia; haud tanto cessabit cardine rerum.<br>Quocirca capere ante dolis et cingere flamma<br>reginam meditor, ne quo se numine mutet,<br>sed magno Aeneae mecum teneatur amore.   675<br>Qua facere id possis, nostram nunc accipe mentem.<br>Regius accitu cari genitoris ad urbem<br>Sidoniam puer ire parat, mea maxima cura,<br>dona ferens, pelago et flammis restantia Troiae:<br>hunc ego sopitum somno super alta Cythera   680<br>aut super Idalium sacrata sede recondam,<br>ne qua scire dolos mediusve occurrere possit.<br>Tu faciem illius noctem non amplius unam<br>falle dolo, et notos pueri puer indue voltus,<br>ut, cum te gremio accipiet laetissima Dido   685<br>regalis inter mensas laticemque Lyaeum,<br>cum dabit amplexus atque oscula dulcia figet,<br>occultum inspires ignem fallasque veneno.’","st":"1"},{"sp":"N","t":"Paret Amor dictis carae genetricis, et alas<br>exuit, et gressu gaudens incedit Iuli.   690<br>At Venus Ascanio placidam per membra quietem<br>inrigat, et fotum gremio dea tollit in altos<br>Idaliae lucos, ubi mollis amaracus illum<br>floribus et dulci adspirans complectitur umbra.","st":"1"},{"sp":"N","t":"Iamque ibat dicto parens et dona Cupido   695<br>regia portabat Tyriis, duce laetus Achate.<br>Cum venit, aulaeis iam se regina superbis<br>aurea composuit sponda mediamque locavit.<br>Iam pater Aeneas et iam Troiana iuventus<br>conveniunt, stratoque super discumbitur ostro.   700<br>Dant famuli manibus lymphas, Cereremque canistris<br>expediunt, tonsisque ferunt mantelia villis.<br>Quinquaginta intus famulae, quibus ordine longam<br>cura penum struere, et flammis adolere Penatis;<br>centum aliae totidemque pares aetate ministri,   705<br>qui dapibus mensas onerent et pocula ponant.<br>Nec non et Tyrii per limina laeta frequentes<br>convenere, toris iussi discumbere pictis.<br>Mirantur dona Aeneae, mirantur Iulum<br>flagrantisque dei voltus simulataque verba,   710<br>[pallamque et pictum croceo velamen acantho.]<br>Praecipue infelix, pesti devota futurae,<br>expleri mentem nequit ardescitque tuendo<br>Phoenissa, et pariter puero donisque movetur.<br>Ille ubi complexu Aeneae colloque pependit   715<br>et magnum falsi implevit genitoris amorem,<br>reginam petit haec oculis, haec pectore toto<br>haeret et interdum gremio fovet, inscia Dido,<br>insidat quantus miserae deus; at memor ille<br>matris Acidaliae paulatim abolere Sychaeum   720<br>incipit, et vivo temptat praevertere amore<br>iam pridem resides animos desuetaque corda.","st":"1"},{"sp":"N","t":"Postquam prima quies epulis, mensaeque remotae,<br>crateras magnos statuunt et vina coronant.<br>Fit strepitus tectis, vocemque per ampla volutant   725<br>atria; dependent lychni laquearibus aureis<br>incensi, et noctem flammis funalia vincunt.<br>Hic regina gravem gemmis auroque poposcit<br>implevitque mero pateram, quam Belus et omnes<br>a Belo soliti; tum facta silentia tectis:   730<br>‘Iuppiter, hospitibus nam te dare iura loquuntur,<br>hunc laetum Tyriisque diem Troiaque profectis<br>esse velis, nostrosque huius meminisse minores.<br>Adsit laetitiae Bacchus dator, et bona Iuno;<br>et vos, O, coetum, Tyrii, celebrate faventes.’   735<br>Dixit, et in mensam laticum libavit honorem,<br>primaque, libato, summo tenus attigit ore,<br>tum Bitiae dedit increpitans; ille impiger hausit<br>spumantem pateram, et pleno se proluit auro<br>post alii proceres. Cithara crinitus Iopas   740<br>personat aurata, docuit quem maximus Atlas.<br>Hic canit errantem lunam solisque labores;<br>unde hominum genus et pecudes; unde imber et ignes;<br>Arcturum pluviasque Hyadas geminosque Triones;<br>quid tantum Oceano properent se tinguere soles   745<br>hiberni, vel quae tardis mora noctibus obstet.<br>Ingeminant plausu Tyrii, Troesque sequuntur.<br>Nec non et vario noctem sermone trahebat<br>infelix Dido, longumque bibebat amorem,<br>multa super Priamo rogitans, super Hectore multa;   750<br>nunc quibus Aurorae venisset filius armis,<br>nunc quales Diomedis equi, nunc quantus Achilles.<br>‘Immo age, et a prima dic, hospes, origine nobis<br>insidias,’ inquit, ‘Danaum, casusque tuorum,<br>erroresque tuos; nam te iam septima portat   755<br>omnibus errantem terris et fluctibus aestas.’","st":"1"},{"sp":"HDR","t":"Liber II","st":"2"},{"sp":"N","t":"Conticuere omnes intentique ora tenebant<br>inde toro pater Aeneas sic orsus ab alto:","st":"2"},{"sp":"N","t":"Infandum, regina, iubes renouare dolorem,<br>Troianas ut opes et lamentabile regnum<br>eruerint Danai, quaeque ipse miserrima uidi   5<br>et quorum pars magna fui. quis talia fando<br>Myrmidonum Dolopumue aut duri miles Vlixi<br>temperet a lacrimis? et iam nox umida caelo<br>praecipitat suadentque cadentia sidera somnos.<br>sed si tantus amor casus cognoscere nostros   10<br>et breuiter Troiae supremum audire laborem,<br>quamquam animus meminisse horret luctuque refugit,<br>incipiam. fracti bello fatisque repulsi<br>ductores Danaum tot iam labentibus annis<br>instar montis equum diuina Palladis arte   15<br>aedificant, sectaque intexunt abiete costas;<br>uotum pro reditu simulant; ea fama uagatur.<br>huc delecta uirum sortiti corpora furtim<br>includunt caeco lateri penitusque cauernas<br>ingentis uterumque armato milite complent.   20<br>est in conspectu Tenedos, notissima fama<br>insula, diues opum Priami dum regna manebant,<br>nunc tantum sinus et statio male fida carinis:<br>huc se prouecti deserto in litore condunt;<br>nos abiisse rati et uento petiisse Mycenas.   25<br>ergo omnis longo soluit se Teucria luctu;<br>panduntur portae, iuuat ire et Dorica castra<br>desertosque uidere locos litusque relictum:<br>hic Dolopum manus, hic saeuus tendebat Achilles;<br>classibus hic locus, hic acie certare solebant.   30<br>pars stupet innuptae donum exitiale Mineruae<br>et molem mirantur equi; primusque Thymoetes<br>duci intra muros hortatur et arce locari,<br>siue dolo seu iam Troiae sic fata ferebant.<br>at Capys, et quorum melior sententia menti,   35<br>aut pelago Danaum insidias suspectaque dona<br>praecipitare iubent subiectisque urere flammis,<br>aut terebrare cauas uteri et temptare latebras.<br>scinditur incertum studia in contraria uulgus.","st":"2"},{"sp":"N","t":"Primus ibi ante omnis magna comitante caterua   40<br>Laocoon ardens summa decurrit ab arce,<br>et procul ‘o miseri, quae tanta insania, ciues?<br>creditis auectos hostis? aut ulla putatis<br>dona carere dolis Danaum? sic notus Vlixes?<br>aut hoc inclusi ligno occultantur Achiui,   45<br>aut haec in nostros fabricata est machina muros,<br>inspectura domos uenturaque desuper urbi,<br>aut aliquis latet error; equo ne credite, Teucri.<br>quidquid id est, timeo Danaos et dona ferentis.’<br>sic fatus ualidis ingentem uiribus hastam   50<br>in latus inque feri curuam compagibus aluum<br>contorsit. stetit illa tremens, uteroque recusso<br>insonuere cauae gemitumque dedere cauernae.<br>et, si fata deum, si mens non laeua fuisset,<br>impulerat ferro Argolicas foedare latebras,   55<br>Troiaque nunc staret, Priamique arx alta maneres.","st":"2"},{"sp":"N","t":"Ecce, manus iuuenem interea post terga reuinctum<br>pastores magno ad regem clamore trahebant<br>Dardanidae, qui se ignotum uenientibus ultro,<br>hoc ipsum ut strueret Troiamque aperiret Achiuis,   60<br>obtulerat, fidens animi atque in utrumque paratus,<br>seu uersare dolos seu certae occumbere morti.<br>undique uisendi studio Troiana iuuentus<br>circumfusa ruit certantque inludere capto.<br>accipe nunc Danaum insidias et crimine ab uno   65<br>disce omnis.<br>namque ut conspectu in medio turbatus, inermis<br>constitit atque oculis Phrygia agmina circumspexit,<br>‘heu, quae nunc tellus,’ inquit, ‘quae me aequora possunt<br>accipere? aut quid iam misero mihi denique restat,   70<br>cui neque apud Danaos usquam locus, et super ipsi<br>Dardanidae infensi poenas cum sanguine poscunt?’<br>quo gemitu conuersi animi compressus et omnis<br>impetus. hortamur fari quo sanguine cretus,<br>quidue ferat; memoret quae sit fiducia capto.   75","st":"2"},{"sp":"N","t":"‘Cuncta equidem tibi, rex, fuerit quodcumque, fatebor   77<br>uera,’ inquit; ‘neque me Argolica de gente negabo.<br>hoc primum; nec, si miserum Fortuna Sinonem<br>finxit, uanum etiam mendacemque improba finget.   80<br>fando aliquod si forte tuas peruenit ad auris<br>Belidae nomen Palamedis et incluta fama<br>gloria, quem falsa sub proditione Pelasgi<br>insontem infando indicio, quia bella uetabat,<br>demisere neci, nunc cassum lumine lugent:   85<br>illi me comitem et consanguinitate propinquum<br>pauper in arma pater primis huc misit ab annis.<br>dum stabat regno incolumis regumque uigebat<br>conciliis, et nos aliquod nomenque decusque<br>gessimus. inuidia postquam pellacis Vlixi   90<br>(haud ignota loquor) superis concessit ab oris,<br>adflictus uitam in tenebris luctuque trahebam<br>et casum insontis mecum indignabar amici.<br>nec tacui demens et me, fors si qua tulisset,<br>si patrios umquam remeassem uictor ad Argos,   95<br>promisi ultorem et uerbis odia aspera moui.<br>hinc mihi prima mali labes, hinc semper Vlixes<br>criminibus terrere nouis, hinc spargere uoces<br>in uulgum ambiguas et quaerere conscius arma.<br>nec requieuit enim, donec Calchante ministro — 100<br>sed quid ego haec autem nequiquam ingrata reuoluo,<br>quidue moror? si omnis uno ordine habetis Achiuos,<br>idque audire sat est, iamdudum sumite poenas:<br>hoc Ithacus uelit et magno mercentur Atridae.’","st":"2"},{"sp":"N","t":"Tum uero ardemus scitari et quaerere causas,   105<br>ignari scelerum tantorum artisque Pelasgae.<br>prosequitur pauitans et ficto pectore fatur:","st":"2"},{"sp":"N","t":"‘Saepe fugam Danai Troia cupiere relicta<br>moliri et longo fessi discedere bello;<br>fecissentque utinam! saepe illos aspera ponti   110<br>interclusit hiems et terruit Auster euntis.<br>praecipue cum iam hic trabibus contextus acernis<br>staret equus, toto sonuerunt aethere nimbi.<br>suspensi Eurypylum scitatum oracula Phoebi<br>mittimus, isque adytis haec tristia dicta reportat:   115<br>“sanguine placastis uentos et uirgine caesa,<br>cum primum Iliacas, Danai, uenistis ad oras;<br>sanguine quaerendi reditus animaque litandum<br>Argolica.” uulgi quae uox ut uenit ad auris,<br>obstipuere animi gelidusque per ima cucurrit    120<br>ossa tremor, cui fata parent, quem poscat Apollo.<br>hic Ithacus uatem magno Calchanta tumultu<br>protrahit in medios; quae sint ea numina diuum<br>flagitat. et mihi iam multi crudele canebant<br>artificis scelus, et taciti uentura uidebant.   125<br>bis quinos silet ille dies tectusque recusat<br>prodere uoce sua quemquam aut opponere morti.<br>uix tandem, magnis Ithaci clamoribus actus,<br>composito rumpit uocem et me destinat arae.<br>adsensere omnes et, quae sibi quisque timebat,   130<br>unius in miseri exitium conuersa tulere.<br>iamque dies infanda aderat; mihi sacra parari<br>et salsae fruges et circum tempora uittae.<br>eripui, fateor, leto me et uincula rupi,<br>limosoque lacu per noctem obscurus in ulua   135<br>delitui dum uela darent, si forte dedissent.<br>nec mihi iam patriam antiquam spes ulla uidendi<br>nec dulcis natos exoptatumque parentem,<br>quos illi fors et poenas ob nostra reposcent<br>effugia, et culpam hanc miserorum morte piabunt.   140<br>quod te per superos et conscia numina ueri,<br>per si qua est quae restet adhuc mortalibus usquam<br>intemerata fides, oro, miserere laborum<br>tantorum, miserere animi non digna ferentis.’","st":"2"},{"sp":"N","t":"His lacrimis uitam damus et miserescimus ultro.   145<br>ipse uiro primus manicas atque arta leuari<br>uincla iubet Priamus dictisque ita fatur amicis:<br>‘quisquis es, amissos hinc iam obliuiscere Graios<br>(noster eris) mihique haec edissere uera roganti:<br>quo molem hanc immanis equi statuere? quis auctor?   150<br>quidue petunt? quae religio? aut quae machina belli?’<br>dixerat. ille dolis instructus et arte Pelasga<br>sustulit exutas uinclis ad sidera palmas:<br>‘uos, aeterni ignes, et non uiolabile uestrum<br>testor numen,’ ait, ‘uos arae ensesque nefandi,   155<br>quos fugi, uittaeque deum, quas hostia gessi:<br>fas mihi Graiorum sacrata resoluere iura,<br>fas odisse uiros atque omnia ferre sub auras,<br>si qua tegunt, teneor patriae nec legibus ullis.<br>tu modo promissis maneas seruataque serues   160<br>Troia fidem, si uera feram, si magna rependam.<br>omnis spes Danaum et coepti fiducia belli<br>Palladis auxiliis semper stetit. impius ex quo<br>Tydides sed enim scelerumque inuentor Vlixes,<br>fatale adgressi sacrato auellere templo   165<br>Palladium caesis summae custodibus arcis,<br>corripuere sacram effigiem manibusque cruentis<br>uirgineas ausi diuae contingere uittas,<br>ex illo fluere ac retro sublapsa referri<br>spes Danaum, fractae uires, auersa deae mens.   170<br>nec dubiis ea signa dedit Tritonia monstris.<br>uix positum castris simulacrum: arsere coruscae<br>luminibus flammae arrectis, salsusque per artus<br>sudor iit, terque ipsa solo (mirabile dictu)<br>emicuit parmamque ferens hastamque trementem.   175<br>extemplo temptanda fuga canit aequora Calchas,<br>nec posse Argolicis exscindi Pergama telis<br>omina ni repetant Argis numenque reducant<br>quod pelago et curuis secum auexere carinis.<br>et nunc quod patrias uento petiere Mycenas,   180<br>arma deosque parant comites pelagoque remenso<br>improuisi aderunt; ita digerit omina Calchas.<br>hanc pro Palladio moniti, pro numine laeso<br>effigiem statuere, nefas quae triste piaret.<br>hanc tamen immensam Calchas attollere molem   185<br>roboribus textis caeloque educere iussit,<br>ne recipi portis aut duci in moenia posset,<br>neu populum antiqua sub religione tueri.<br>nam si uestra manus uiolasset dona Mineruae,<br>tum magnum exitium (quod di prius omen in ipsum   190<br>conuertant!) Priami imperio Phrygibusque futurum;<br>sin manibus uestris uestram ascendisset in urbem,<br>ultro Asiam magno Pelopea ad moenia bello<br>uenturam, et nostros ea fata manere nepotes.’","st":"2"},{"sp":"N","t":"Talibus insidiis periurique arte Sinonis   195<br>credita res, captique dolis lacrimisque coactis<br>quos neque Tydides nec Larisaeus Achilles,<br>non anni domuere decem, non mille carinae.","st":"2"},{"sp":"N","t":"Hic aliud maius miseris multoque tremendum<br>obicitur magis atque improuida pectora turbat.   200<br>Laocoon, ductus Neptuno sorte sacerdos,<br>sollemnis taurum ingentem mactabat ad aras.<br>ecce autem gemini a Tenedo tranquilla per alta<br>(horresco referens) immensis orbibus angues<br>incumbunt pelago pariterque ad litora tendunt;   205<br>pectora quorum inter fluctus arrecta iubaeque<br>sanguineae superant undas, pars cetera pontum<br>pone legit sinuatque immensa uolumine terga.<br>fit sonitus spumante salo; iamque arua tenebant<br>ardentisque oculos suffecti sanguine et igni   210<br>sibila lambebant linguis uibrantibus ora.<br>diffugimus uisu exsangues. illi agmine certo<br>Laocoonta petunt; et primum parua duorum<br>corpora natorum serpens amplexus uterque<br>implicat et miseros morsu depascitur artus;   215<br>post ipsum auxilio subeuntem ac tela ferentem<br>corripiunt spirisque ligant ingentibus; et iam<br>bis medium amplexi, bis collo squamea circum<br>terga dati superant capite et ceruicibus altis.<br>ille simul manibus tendit diuellere nodos   220<br>perfusus sanie uittas atroque ueneno,<br>clamores simul horrendos ad sidera tollit:<br>qualis mugitus, fugit cum saucius aram<br>taurus et incertam excussit ceruice securim.<br>at gemini lapsu delubra ad summa dracones   225<br>effugiunt saeuaeque petunt Tritonidis arcem,<br>sub pedibusque deae clipeique sub orbe teguntur.<br>tum uero tremefacta nouus per pectora cunctis<br>insinuat pauor, et scelus expendisse merentem<br>Laocoonta ferunt, sacrum qui cuspide robur   230<br>laeserit et tergo sceleratam intorserit hastam.<br>ducendum ad sedes simulacrum orandaque diuae<br>numina conclamant.<br>diuidimus muros et moenia pandimus urbis.<br>accingunt omnes operi pedibusque rotarum   235<br>subiciunt lapsus, et stuppea uincula collo<br>intendunt; scandit fatalis machina muros<br>feta armis. pueri circum innuptaeque puellae<br>sacra canunt funemque manu contingere gaudent;<br>illa subit mediaeque minans inlabitur urbi.   240<br>o patria, o diuum domus Ilium et incluta bello<br>moenia Dardanidum! quater ipso in limine portae<br>substitit atque utero sonitum quater arma dedere;<br>instamus tamen immemores caecique furore<br>et monstrum infelix sacrata sistimus arce.   245<br>tunc etiam fatis aperit Cassandra futuris<br>ora dei iussu non umquam credita Teucris.<br>nos delubra deum miseri, quibus ultimus esset<br>ille dies, festa uelamus fronde per urbem.","st":"2"},{"sp":"N","t":"Vertitur interea caelum et ruit Oceano nox   250<br>inuoluens umbra magna terramque polumque<br>Myrmidonumque dolos; fusi per moenia Teucri<br>conticuere; sopor fessos complectitur artus.<br>et iam Argiua phalanx instructis nauibus ibat<br>a Tenedo tacitae per amica silentia lunae   255<br>litora nota petens, flammas cum regia puppis<br>extulerat, fatisque deum defensus iniquis<br>inclusos utero Danaos et pinea furtim<br>laxat claustra Sinon. illos patefactus ad auras<br>reddit equus laetique cauo se robore promunt   260<br>Thessandrus Sthenelusque duces et dirus Vlixes,<br>demissum lapsi per funem, Acamasque Thoasque<br>Pelidesque Neoptolemus primusque Machaon<br>et Menelaus et ipse doli fabricator Epeos.<br>inuadunt urbem somno uinoque sepultam;   265<br>caeduntur uigiles, portisque patentibus omnis<br>accipiunt socios atque agmina conscia iungunt.","st":"2"},{"sp":"N","t":"Tempus erat quo prima quies mortalibus aegris<br>incipit et dono diuum gratissima serpit.<br>in somnis, ecce, ante oculos maestissimus Hector   270<br>uisus adesse mihi largosque effundere fletus,<br>raptatus bigis ut quondam, aterque cruento<br>puluere perque pedes traiectus lora tumentis.<br>ei mihi, qualis erat, quantum mutatus ab illo<br>Hectore qui redit exuuias indutus Achilli   275<br>uel Danaum Phrygios iaculatus puppibus ignis!<br>squalentem barbam et concretos sanguine crinis<br>uulneraque illa gerens, quae circum plurima muros<br>accepit patrios. ultro flens ipse uidebar<br>compellare uirum et maestas expromere uoces:   280<br>‘o lux Dardaniae, spes o fidissima Teucrum,<br>quae tantae tenuere morae? quibus Hector ab oris<br>exspectate uenis? ut te post multa tuorum<br>funera, post uarios hominumque urbisque labores<br>defessi aspicimus! quae causa indigna serenos   285<br>foedauit uultus? aut cur haec uulnera cerno?’<br>ille nihil, nec me quaerentem uana moratur,<br>sed grauiter gemitus imo de pectore ducens,<br>‘heu fuge, nate dea, teque his’ ait ‘eripe flammis.<br>hostis habet muros; ruit alto a culmine Troia.   290<br>sat patriae Priamoque datum: si Pergama dextra<br>defendi possent, etiam hac defensa fuissent.<br>sacra suosque tibi commendat Troia penatis;<br>hos cape fatorum comites, his moenia quaere<br>magna pererrato statues quae denique ponto.’   295<br>sic ait et manibus uittas Vestamque potentem<br>aeternumque adytis effert penetralibus ignem.","st":"2"},{"sp":"N","t":"Diuerso interea miscentur moenia luctu,<br>et magis atque magis, quamquam secreta parentis<br>Anchisae domus arboribusque obtecta recessit,   300<br>clarescunt sonitus armorumque ingruit horror.<br>excutior somno et summi fastigia tecti<br>ascensu supero atque arrectis auribus asto:<br>in segetem ueluti cum flamma furentibus Austris<br>incidit, aut rapidus montano flumine torrens   305<br>sternit agros, sternit sata laeta boumque labores<br>praecipitisque trahit siluas; stupet inscius alto<br>accipiens sonitum saxi de uertice pastor.<br>tum uero manifesta fides, Danaumque patescunt<br>insidiae. iam Deiphobi dedit ampla ruinam   310<br>Volcano superante domus, iam proximus ardet<br>Vcalegon; Sigea igni freta lata relucent.<br>exoritur clamorque uirum clangorque tubarum.<br>arma amens capio; nec sat rationis in armis,<br>sed glomerare manum bello et concurrere in arcem   315<br>cum sociis ardent animi; furor iraque mentem<br>praecipitat, pulchrumque mori succurrit in armis.","st":"2"},{"sp":"N","t":"Ecce autem telis Panthus elapsus Achiuum,<br>Panthus Othryades, arcis Phoebique sacerdos,<br>sacra manu uictosque deos paruumque nepotem   320<br>ipse trahit cursuque amens ad limina tendit.<br>‘quo res summa loco, Panthu? quam prendimus arcem?’<br>uix ea fatus eram gemitu cum talia reddit:<br>‘uenit summa dies et ineluctabile tempus<br>Dardaniae. fuimus Troes, fuit Ilium et ingens   325<br>gloria Teucrorum; ferus omnia Iuppiter Argos<br>transtulit; incensa Danai dominantur in urbe.<br>arduus armatos mediis in moenibus astans<br>fundit equus uictorque Sinon incendia miscet<br>insultans. portis alii bipatentibus adsunt,   330<br>milia quot magnis umquam uenere Mycenis;<br>obsedere alii telis angusta uiarum<br>oppositis; stat ferri acies mucrone corusco<br>stricta, parata neci; uix primi proelia temptant<br>portarum uigiles et caeco Marte resistunt.’   335<br>talibus Othryadae dictis et numine diuum<br>in flammas et in arma feror, quo tristis Erinys,<br>quo fremitus uocat et sublatus ad aethera clamor.<br>addunt se socios Rhipeus et maximus armis<br>Epytus, oblati per lunam, Hypanisque Dymasque   340<br>et lateri adglomerant nostro, iuuenisque Coroebus<br>Mygdonides — illis ad Troiam forte diebus<br>uenerat insano Cassandrae incensus amore<br>et gener auxilium Priamo Phrygibusque ferebat,<br>infelix qui non sponsae praecepta furentis   345<br>audierit!<br>quos ubi confertos ardere in proelia uidi,<br>incipio super his: ‘iuuenes, fortissima frustra<br>pectora, si uobis audentem extrema cupido<br>certa sequi, quae sit rebus fortuna uidetis:    350<br>excessere omnes adytis arisque relictis<br>di quibus imperium hoc steterat; succurritis urbi<br>incensae. moriamur et in media arma ruamus.<br>una salus uictis nullam sperare salutem.’<br>sic animis iuuenum furor additus. inde, lupi ceu   355<br>raptores atra in nebula, quos improba uentris<br>exegit caecos rabies catulique relicti<br>faucibus exspectant siccis, per tela, per hostis<br>uadimus haud dubiam in mortem mediaeque tenemus<br>urbis iter; nox atra caua circumuolat umbra.   360<br>quis cladem illius noctis, quis funera fando<br>explicet aut possit lacrimis aequare labores?<br>urbs antiqua ruit multos dominata per annos;<br>plurima perque uias sternuntur inertia passim<br>corpora perque domos et religiosa deorum   365<br>limina. nec soli poenas dant sanguine Teucri;<br>quondam etiam uictis redit in praecordia uirtus<br>uictoresque cadunt Danai. crudelis ubique<br>luctus, ubique pauor et plurima mortis imago.","st":"2"},{"sp":"N","t":"Primus se Danaum magna comitante caterua   370<br>Androgeos offert nobis, socia agmina credens<br>inscius, atque ultro uerbis compellat amicis:<br>‘festinate, uiri! nam quae tam sera moratur<br>segnities? alii rapiunt incensa feruntque<br>Pergama: uos celsis nunc primum a nauibus itis?’   375<br>dixit, et extemplo (neque enim responsa dabantur<br>fida satis) sensit medios delapsus in hostis.<br>obstipuit retroque pedem cum uoce repressit.<br>improuisum aspris ueluti qui sentibus anguem<br>pressit humi nitens trepidusque repente refugit   380<br>attollentem iras et caerula colla tumentem,<br>haud secus Androgeos uisu tremefactus abibat.<br>inruimus densis et circumfundimur armis,<br>ignarosque loci passim et formidine captos<br>sternimus; aspirat primo Fortuna labori.   385<br>atque hic successu exsultans animisque Coroebus<br>‘o socii, qua prima’ inquit ‘Fortuna salutis<br>monstrat iter, quaque ostendit se dextra, sequamur:<br>mutemus clipeos Danaumque insignia nobis<br>aptemus. dolus an uirtus, quis in hoste requirat?   390<br>arma dabunt ipsi.’ sic fatus deinde comantem<br>Androgei galeam clipeique insigne decorum<br>induitur laterique Argiuum accommodat ensem.<br>hoc Rhipeus, hoc ipse Dymas omnisque iuuentus<br>laeta facit: spoliis se quisque recentibus armat.   395<br>uadimus immixti Danais haud numine nostro<br>multaque per caecam congressi proelia noctem<br>conserimus, multos Danaum demittimus Orco.<br>diffugiunt alii ad nauis et litora cursu<br>fida petunt; pars ingentem formidine turpi   400<br>scandunt rursus equum et nota conduntur in aluo.","st":"2"},{"sp":"N","t":"Heu nihil inuitis fas quemquam fidere diuis!<br>ecce trahebatur passis Priameia uirgo<br>crinibus a templo Cassandra adytisque Mineruae<br>ad caelum tendens ardentia lumina frustra,   405<br>lumina, nam teneras arcebant uincula palmas.<br>non tulit hanc speciem furiata mente Coroebus<br>et sese medium iniecit periturus in agmen;<br>consequimur cuncti et densis incurrimus armis.<br>hic primum ex alto delubri culmine telis   410<br>nostrorum obruimur oriturque miserrima caedes<br>armorum facie et Graiarum errore iubarum.<br>tum Danai gemitu atque ereptae uirginis ira<br>undique collecti inuadunt, acerrimus Aiax<br>et gemini Atridae Dolopumque exercitus omnis:   415<br>aduersi rupto ceu quondam turbine uenti<br>confligunt, Zephyrusque Notusque et laetus Eois<br>Eurus equis; stridunt siluae saeuitque tridenti<br>spumeus atque imo Nereus ciet aequora fundo.<br>illi etiam, si quos obscura nocte per umbram   420<br>fudimus insidiis totaque agitauimus urbe,<br>apparent; primi clipeos mentitaque tela<br>agnoscunt atque ora sono discordia signant.<br>ilicet obruimur numero, primusque Coroebus<br>Penelei dextra diuae armipotentis ad aram   425<br>procumbit; cadit et Rhipeus, iustissimus unus<br>qui fuit in Teucris et seruantissimus aequi<br>(dis aliter uisum); pereunt Hypanisque Dymasque<br>confixi a sociis; nec te tua plurima, Panthu,<br>labentem pietas nec Apollinis infula texit.   430<br>Iliaci cineres et flamma extrema meorum,<br>testor, in occasu uestro nec tela nec ullas<br>uitauisse uices, Danaum et, si fata fuissent<br>ut caderem, meruisse manu. diuellimur inde,<br>Iphitus et Pelias mecum (quorum Iphitus aeuo   435<br>iam grauior, Pelias et uulnere tardus Vlixi),<br>protinus ad sedes Priami clamore uocati.<br>hic uero ingentem pugnam, ceu cetera nusquam<br>bella forent, nulli tota morerentur in urbe,<br>sic Martem indomitum Danaosque ad tecta ruentis   440<br>cernimus obsessumque acta testudine limen.<br>haerent parietibus scalae postisque sub ipsos<br>nituntur gradibus clipeosque ad tela sinistris<br>protecti obiciunt, prensant fastigia dextris.<br>Dardanidae contra turris ac tota domorum   445<br>culmina conuellunt; his se, quando ultima cernunt,<br>extrema iam in morte parant defendere telis,<br>auratasque trabes, ueterum decora alta parentum,<br>deuoluunt; alii strictis mucronibus imas<br>obsedere fores, has seruant agmine denso.   450<br>instaurati animi regis succurrere tectis<br>auxilioque leuare uiros uimque addere uictis.","st":"2"},{"sp":"N","t":"Limen erat caecaeque fores et peruius usus<br>tectorum inter se Priami, postesque relicti<br>a tergo, infelix qua se, dum regna manebant,   455<br>saepius Andromache ferre incomitata solebat<br>ad soceros et auo puerum Astyanacta trahebat.<br>euado ad summi fastigia culminis, unde<br>tela manu miseri iactabant inrita Teucri.<br>turrim in praecipiti stantem summisque sub astra   460<br>eductam tectis, unde omnis Troia uideri<br>et Danaum solitae naues et Achaica castra,<br>adgressi ferro circum, qua summa labantis<br>iuncturas tabulata dabant, conuellimus altis<br>sedibus impulimusque; ea lapsa repente ruinam   465<br>cum sonitu trahit et Danaum super agmina late<br>incidit. ast alii subeunt, nec saxa nec ullum<br>telorum interea cessat genus.","st":"2"},{"sp":"N","t":"Vestibulum ante ipsum primoque in limine Pyrrhus<br>exsultat telis et luce coruscus aena:   470<br>qualis ubi in lucem coluber mala gramina pastus,<br>frigida sub terra tumidum quem bruma tegebat,<br>nunc, positis nouus exuuiis nitidusque iuuenta,<br>lubrica conuoluit sublato pectore terga<br>arduus ad solem, et linguis micat ore trisulcis.   475<br>una ingens Periphas et equorum agitator Achillis,<br>armiger Automedon, una omnis Scyria pubes<br>succedunt tecto et flammas ad culmina iactant.<br>ipse inter primos correpta dura bipenni<br>limina perrumpit postisque a cardine uellit   480<br>aeratos; iamque excisa trabe firma cauauit<br>robora et ingentem lato dedit ore fenestram.<br>apparet domus intus et atria longa patescunt;<br>apparent Priami et ueterum penetralia regum,<br>armatosque uident stantis in limine primo.   485<br>at domus interior gemitu miseroque tumultu<br>miscetur, penitusque cauae plangoribus aedes<br>femineis ululant; ferit aurea sidera clamor.<br>tum pauidae tectis matres ingentibus errant<br>amplexaeque tenent postis atque oscula figunt.   490<br>instat ui patria Pyrrhus; nec claustra nec ipsi<br>custodes sufferre ualent; labat ariete crebro<br>ianua, et emoti procumbunt cardine postes.<br>fit uia ui; rumpunt aditus primosque trucidant<br>immissi Danai et late loca milite complent.   495<br>non sic, aggeribus ruptis cum spumeus amnis<br>exiit oppositasque euicit gurgite moles,<br>fertur in arua furens cumulo camposque per omnis<br>cum stabulis armenta trahit. uidi ipse furentem<br>caede Neoptolemum geminosque in limine Atridas,   500<br>uidi Hecubam centumque nurus Priamumque per aras<br>sanguine foedantem quos ipse sacrauerat ignis.<br>quinquaginta illi thalami, spes tanta nepotum,<br>barbarico postes auro spoliisque superbi<br>procubuere; tenent Danai qua deficit ignis.   505","st":"2"},{"sp":"N","t":"Forsitan et Priami fuerint quae fata requiras.<br>urbis uti captae casum conuulsaque uidit<br>limina tectorum et medium in penetralibus hostem,<br>arma diu senior desueta trementibus aeuo<br>circumdat nequiquam umeris et inutile ferrum   510<br>cingitur, ac densos fertur moriturus in hostis.<br>aedibus in mediis nudoque sub aetheris axe<br>ingens ara fuit iuxtaque ueterrima laurus<br>incumbens arae atque umbra complexa penatis.<br>hic Hecuba et natae nequiquam altaria circum,   515<br>praecipites atra ceu tempestate columbae,<br>condensae et diuum amplexae simulacra sedebant.<br>ipsum autem sumptis Priamum iuuenalibus armis<br>ut uidit, ‘quae mens tam dira, miserrime coniunx,<br>impulit his cingi telis? aut quo ruis?’ inquit.   520<br>‘non tali auxilio nec defensoribus istis<br>tempus eget; non, si ipse meus nunc adforet Hector.<br>huc tandem concede; haec ara tuebitur omnis,<br>aut moriere simul.’ sic ore effata recepit<br>ad sese et sacra longaeuum in sede locauit.   525","st":"2"},{"sp":"N","t":"Ecce autem elapsus Pyrrhi de caede Polites,<br>unus natorum Priami, per tela, per hostis<br>porticibus longis fugit et uacua atria lustrat<br>saucius. illum ardens infesto uulnere Pyrrhus<br>insequitur, iam iamque manu tenet et premit hasta.   530<br>ut tandem ante oculos euasit et ora parentum,<br>concidit ac multo uitam cum sanguine fudit.<br>hic Priamus, quamquam in media iam morte tenetur,<br>non tamen abstinuit nec uoci iraeque pepercit:<br>‘at tibi pro scelere,’ exclamat, ‘pro talibus ausis   535<br>di, si qua est caelo pietas quae talia curet,<br>persoluant grates dignas et praemia reddant<br>debita, qui nati coram me cernere letum<br>fecisti et patrios foedasti funere uultus.<br>at non ille, satum quo te mentiris, Achilles   540<br>talis in hoste fuit Priamo; sed iura fidemque<br>supplicis erubuit corpusque exsangue sepulcro<br>reddidit Hectoreum meque in mea regna remisit.’<br>sic fatus senior telumque imbelle sine ictu<br>coniecit, rauco quod protinus aere repulsum,   545<br>et summo clipei nequiquam umbone pependit.<br>cui Pyrrhus: ‘referes ergo haec et nuntius ibis<br>Pelidae genitori. illi mea tristia facta<br>degeneremque Neoptolemum narrare memento.<br>nunc morere.’ hoc dicens altaria ad ipsa trementem   550<br>traxit et in multo lapsantem sanguine nati,<br>implicuitque comam laeua, dextraque coruscum<br>extulit ac lateri capulo tenus abdidit ensem.<br>haec finis Priami fatorum, hic exitus illum<br>sorte tulit Troiam incensam et prolapsa uidentem   555<br>Pergama, tot quondam populis terrisque superbum<br>regnatorem Asiae. iacet ingens litore truncus,<br>auulsumque umeris caput et sine nomine corpus.","st":"2"},{"sp":"N","t":"At me tum primum saeuus circumstetit horror.<br>obstipui; subiit cari genitoris imago,   560<br>ut regem aequaeuum crudeli uulnere uidi<br>uitam exhalantem, subiit deserta Creusa<br>et direpta domus et parui casus Iuli.<br>respicio et quae sit me circum copia lustro.<br>deseruere omnes defessi, et corpora saltu   565<br>ad terram misere aut ignibus aegra dedere.","st":"2"},{"sp":"N","t":"[Iamque adeo super unus eram, cum limina Vestae<br>seruantem et tacitam secreta in sede latentem<br>Tyndarida aspicio; dant claram incendia lucem<br>erranti passimque oculos per cuncta ferenti.   570<br>illa sibi infestos euersa ob Pergama Teucros<br>et Danaum poenam et deserti coniugis iras<br>praemetuens, Troiae et patriae communis Erinys,<br>abdiderat sese atque aris inuisa sedebat.<br>exarsere ignes animo; subit ira cadentem   575<br>ulcisci patriam et sceleratas sumere poenas.<br>‘scilicet haec Spartam incolumis patriasque Mycenas<br>aspiciet, partoque ibit regina triumpho?<br>coniugiumque domumque patris natosque uidebit<br>Iliadum turba et Phrygiis comitata ministris?   580<br>occiderit ferro Priamus? Troia arserit igni?<br>Dardanium totiens sudarit sanguine litus?<br>non ita. namque etsi nullum memorabile nomen<br>feminea in poena est, habet haec uictoria laudem;<br>exstinxisse nefas tamen et sumpsisse merentis   585<br>laudabor poenas, animumque explesse iuuabit<br>ultricis ~famam et cineres satiasse meorum.’<br>talia iactabam et furiata mente ferebar,]<br>cum mihi se, non ante oculis tam clara, uidendam<br>obtulit et pura per noctem in luce refulsit   590<br>alma parens, confessa deam qualisque uideri<br>caelicolis et quanta solet, dextraque prehensum<br>continuit roseoque haec insuper addidit ore:<br>‘nate, quis indomitas tantus dolor excitat iras?<br>quid furis? aut quonam nostri tibi cura recessit?   595<br>non prius aspicies ubi fessum aetate parentem<br>liqueris Anchisen, superet coniunxne Creusa<br>Ascaniusque puer? quos omnis undique Graiae<br>circum errant acies et, ni mea cura resistat,<br>iam flammae tulerint inimicus et hauserit ensis.   600<br>non tibi Tyndaridis facies inuisa Lacaenae<br>culpatusue Paris, diuum inclementia, diuum<br>has euertit opes sternitque a culmine Troiam.<br>aspice (namque omnem, quae nunc obducta tuenti<br>mortalis hebetat uisus tibi et umida circum   605<br>caligat, nubem eripiam; tu ne qua parentis<br>iussa time neu praeceptis parere recusa):<br>hic, ubi disiectas moles auulsaque saxis<br>saxa uides, mixtoque undantem puluere fumum,<br>Neptunus muros magnoque emota tridenti   610<br>fundamenta quatit totamque a sedibus urbem<br>eruit. hic Iuno Scaeas saeuissima portas<br>prima tenet sociumque furens a nauibus agmen<br>ferro accincta uocat.<br>iam summas arces Tritonia, respice, Pallas   615<br>insedit nimbo effulgens et Gorgone saeua.<br>ipse pater Danais animos uirisque secundas<br>sufficit, ipse deos in Dardana suscitat arma.<br>eripe, nate, fugam finemque impone labori;<br>nusquam abero et tutum patrio te limine sistam.’   620<br>dixerat et spissis noctis se condidit umbris.<br>apparent dirae facies inimicaque Troiae<br>numina magna deum.","st":"2"},{"sp":"N","t":"Tum uero omne mihi uisum considere in ignis<br>Ilium et ex imo uerti Neptunia Troia:   625<br>ac ueluti summis antiquam in montibus ornum<br>cum ferro accisam crebrisque bipennibus instant<br>eruere agricolae certatim, illa usque minatur<br>et tremefacta comam concusso uertice nutat,<br>uulneribus donec paulatim euicta supremum   630<br>congemuit traxitque iugis auulsa ruinam.<br>descendo ac ducente deo flammam inter et hostis<br>expedior: dant tela locum flammaeque recedunt.","st":"2"},{"sp":"N","t":"Atque ubi iam patriae peruentum ad limina sedis<br>antiquasque domos, genitor, quem tollere in altos   635<br>optabam primum montis primumque petebam,<br>abnegat excisa uitam producere Troia<br>exsiliumque pati. ‘uos o, quibus integer aeui<br>sanguis,’ ait, ‘solidaeque suo stant robore uires,<br>uos agitate fugam.   640<br>me si caelicolae uoluissent ducere uitam,<br>has mihi seruassent sedes. satis una superque<br>uidimus excidia et captae superauimus urbi.<br>sic o sic positum adfati discedite corpus.<br>ipse manu mortem inueniam; miserebitur hostis   645<br>exuuiasque petet. facilis iactura sepulcri.<br>iam pridem inuisus diuis et inutilis annos<br>demoror, ex quo me diuum pater atque hominum rex<br>fulminis adflauit uentis et contigit igni.’","st":"2"},{"sp":"N","t":"Talia perstabat memorans fixusque manebat.   650<br>nos contra effusi lacrimis coniunxque Creusa<br>Ascaniusque omnisque domus, ne uertere secum<br>cuncta pater fatoque urgenti incumbere uellet.<br>abnegat inceptoque et sedibus haeret in isdem.<br>rursus in arma feror mortemque miserrimus opto.   655<br>nam quod consilium aut quae iam fortuna dabatur?<br>‘mene efferre pedem, genitor, te posse relicto<br>sperasti tantumque nefas patrio excidit ore?<br>si nihil ex tanta superis placet urbe relinqui,<br>et sedet hoc animo perituraeque addere Troiae   660<br>teque tuosque iuuat, patet isti ianua leto,<br>iamque aderit multo Priami de sanguine Pyrrhus,<br>natum ante ora patris, patrem qui obtruncat ad aras.<br>hoc erat, alma parens, quod me per tela, per ignis<br>eripis, ut mediis hostem in penetralibus utque   665<br>Ascanium patremque meum iuxtaque Creusam<br>alterum in alterius mactatos sanguine cernam?<br>arma, uiri, ferte arma; uocat lux ultima uictos.<br>reddite me Danais; sinite instaurata reuisam<br>proelia. numquam omnes hodie moriemur inulti.’   670","st":"2"},{"sp":"N","t":"Hinc ferro accingor rursus clipeoque sinistram<br>insertabam aptans meque extra tecta ferebam.<br>ecce autem complexa pedes in limine coniunx<br>haerebat, paruumque patri tendebat Iulum:<br>‘si periturus abis, et nos rape in omnia tecum;   675<br>sin aliquam expertus sumptis spem ponis in armis,<br>hanc primum tutare domum. cui paruus Iulus,<br>cui pater et coniunx quondam tua dicta relinquor?’","st":"2"},{"sp":"N","t":"Talia uociferans gemitu tectum omne replebat,<br>cum subitum dictuque oritur mirabile monstrum.   680<br>namque manus inter maestorumque ora parentum<br>ecce leuis summo de uertice uisus Iuli<br>fundere lumen apex, tactuque innoxia mollis<br>lambere flamma comas et circum tempora pasci.<br>nos pauidi trepidare metu crinemque flagrantem   685<br>excutere et sanctos restinguere fontibus ignis.<br>at pater Anchises oculos ad sidera laetus<br>extulit et caelo palmas cum uoce tetendit:<br>‘Iuppiter omnipotens, precibus si flecteris ullis,<br>aspice nos, hoc tantum, et si pietate meremur,   690<br>da deinde auxilium, pater, atque haec omina firma.’","st":"2"},{"sp":"N","t":"Vix ea fatus erat senior, subitoque fragore<br>intonuit laeuum, et de caelo lapsa per umbras<br>stella facem ducens multa cum luce cucurrit.<br>illam summa super labentem culmina tecti   695<br>cernimus Idaea claram se condere silua<br>signantemque uias; tum longo limite sulcus<br>dat lucem et late circum loca sulphure fumant.<br>hic uero uictus genitor se tollit ad auras<br>adfaturque deos et sanctum sidus adorat.   700<br>‘iam iam nulla mora est; sequor et qua ducitis adsum,<br>di patrii; seruate domum, seruate nepotem.<br>uestrum hoc augurium, uestroque in numine Troia est.<br>cedo equidem nec, nate, tibi comes ire recuso.’<br>dixerat ille, et iam per moenia clarior ignis   705<br>auditur, propiusque aestus incendia uoluunt.<br>‘ergo age, care pater, ceruici imponere nostrae;<br>ipse subibo umeris nec me labor iste grauabit;<br>quo res cumque cadent, unum et commune periclum,<br>una salus ambobus erit. mihi paruus Iulus   710<br>sit comes, et longe seruet uestigia coniunx.<br>uos, famuli, quae dicam animis aduertite uestris.<br>est urbe egressis tumulus templumque uetustum<br>desertae Cereris, iuxtaque antiqua cupressus<br>religione patrum multos seruata per annos;   715<br>hanc ex diuerso sedem ueniemus in unam.<br>tu, genitor, cape sacra manu patriosque penatis;<br>me bello e tanto digressum et caede recenti<br>attrectare nefas, donec me flumine uiuo<br>abluero.’   720<br>haec fatus latos umeros subiectaque colla<br>ueste super fuluique insternor pelle leonis,<br>succedoque oneri; dextrae se paruus Iulus<br>implicuit sequiturque patrem non passibus aequis;<br>pone subit coniunx. ferimur per opaca locorum,   725<br>et me, quem dudum non ulla iniecta mouebant<br>tela neque aduerso glomerati examine Grai,<br>nunc omnes terrent aurae, sonus excitat omnis<br>suspensum et pariter comitique onerique timentem.<br>iamque propinquabam portis omnemque uidebar   730<br>euasisse uiam, subito cum creber ad auris<br>uisus adesse pedum sonitus, genitorque per umbram<br>prospiciens ‘nate,’ exclamat, ‘fuge, nate; propinquant.<br>ardentis clipeos atque aera micantia cerno.’<br>hic mihi nescio quod trepido male numen amicum   735<br>confusam eripuit mentem. namque auia cursu<br>dum sequor et nota excedo regione uiarum,<br>heu misero coniunx fatone erepta Creusa<br>substitit, errauitne uia seu lapsa resedit,<br>incertum; nec post oculis est reddita nostris.   740<br>nec prius amissam respexi animumue reflexi<br>quam tumulum antiquae Cereris sedemque sacratam<br>uenimus: hic demum collectis omnibus una<br>defuit, et comites natumque uirumque fefellit.<br>quem non incusaui amens hominumque deorumque,   745<br>aut quid in euersa uidi crudelius urbe?<br>Ascanium Anchisenque patrem Teucrosque penatis<br>commendo sociis et curua ualle recondo;<br>ipse urbem repeto et cingor fulgentibus armis.<br>stat casus renouare omnis omnemque reuerti   750<br>per Troiam et rursus caput obiectare periclis.<br>principio muros obscuraque limina portae,<br>qua gressum extuleram, repeto et uestigia retro<br>obseruata sequor per noctem et lumine lustro:<br>horror ubique animo, simul ipsa silentia terrent.   755<br>inde domum, si forte pedem, si forte tulisset,<br>me refero: inruerant Danai et tectum omne tenebant.<br>ilicet ignis edax summa ad fastigia uento<br>uoluitur; exsuperant flammae, furit aestus ad auras.<br>procedo et Priami sedes arcemque reuiso:   760<br>et iam porticibus uacuis Iunonis asylo<br>custodes lecti Phoenix et dirus Vlixes<br>praedam adseruabant. huc undique Troia gaza<br>incensis erepta adytis, mensaeque deorum<br>crateresque auro solidi, captiuaque uestis   765<br>congeritur. pueri et pauidae longo ordine matres<br>stant circum.<br>ausus quin etiam uoces iactare per umbram<br>impleui clamore uias, maestusque Creusam<br>nequiquam ingeminans iterumque iterumque uocaui.   770<br>quaerenti et tectis urbis sine fine ruenti<br>infelix simulacrum atque ipsius umbra Creusae<br>uisa mihi ante oculos et nota maior imago.<br>obstipui, steteruntque comae et uox faucibus haesit.<br>tum sic adfari et curas his demere dictis:   775<br>‘quid tantum insano iuuat indulgere dolori,<br>o dulcis coniunx? non haec sine numine diuum<br>eueniunt; nec te comitem hinc portare Creusam<br>fas, aut ille sinit superi regnator Olympi.<br>longa tibi exsilia et uastum maris aequor arandum,   780<br>et terram Hesperiam uenies, ubi Lydius arua","st":"2"},{"sp":"N","t":"inter opima uirum leni fluit agmine Thybris.<br>illic res laetae regnumque et regia coniunx<br>parta tibi; lacrimas dilectae pelle Creusae.<br>non ego Myrmidonum sedes Dolopumue superbas   785<br>aspiciam aut Grais seruitum matribus ibo,<br>Dardanis et diuae Veneris nurus;<br>sed me magna deum genetrix his detinet oris.<br>iamque uale et nati serua communis amorem.’<br>haec ubi dicta dedit, lacrimantem et multa uolentem   790<br>dicere deseruit, tenuisque recessit in auras.<br>ter conatus ibi collo dare bracchia circum;<br>ter frustra comprensa manus effugit imago,<br>par leuibus uentis uolucrique simillima somno.<br>sic demum socios consumpta nocte reuiso.   795","st":"2"},{"sp":"N","t":"Atque hic ingentem comitum adfluxisse nouorum<br>inuenio admirans numerum, matresque uirosque,<br>collectam exsilio pubem, miserabile uulgus.<br>undique conuenere animis opibusque parati<br>in quascumque uelim pelago deducere terras.   800<br>iamque iugis summae surgebat Lucifer Idae<br>ducebatque diem, Danaique obsessa tenebant<br>limina portarum, nec spes opis ulla dabatur.<br>cessi et sublato montis genitore petiui.","st":"2"},{"sp":"HDR","t":"Liber III","st":"3"},{"sp":"N","t":"Postquam res Asiae Priamique euertere gentem<br>immeritam uisum superis, ceciditque superbum<br>Ilium et omnis humo fumat Neptunia Troia,<br>diuersa exsilia et desertas quaerere terras<br>auguriis agimur diuum, classemque sub ipsa   5<br>Antandro et Phrygiae molimur montibus Idae,<br>incerti quo fata ferant, ubi sistere detur,<br>contrahimusque uiros. uix prima inceperat aestas<br>et pater Anchises dare fatis uela iubebat,<br>litora cum patriae lacrimans portusque relinquo   10<br>et campos ubi Troia fuit. feror exsul in altum<br>cum sociis natoque penatibus et magnis dis.","st":"3"},{"sp":"N","t":"Terra procul uastis colitur Mauortia campis<br>(Thraces arant) acri quondam regnata Lycurgo,<br>hospitium antiquum Troiae sociique penates   15<br>dum fortuna fuit. feror huc et litore curuo<br>moenia prima loco fatis ingressus iniquis<br>Aeneadasque meo nomen de nomine fingo.<br>sacra Dionaeae matri diuisque ferebam<br>auspicibus coeptorum operum, superoque nitentem   20<br>caelicolum regi mactabam in litore taurum.<br>forte fuit iuxta tumulus, quo cornea summo<br>uirgulta et densis hastilibus horrida myrtus.<br>accessi uiridemque ab humo conuellere siluam<br>conatus, ramis tegerem ut frondentibus aras,    25<br>horrendum et dictu uideo mirabile monstrum.<br>nam quae prima solo ruptis radicibus arbos<br>uellitur, huic atro liquuntur sanguine guttae<br>et terram tabo maculant. mihi frigidus horror<br>membra quatit gelidusque coit formidine sanguis.   30<br>rursus et alterius lentum conuellere uimen<br>insequor et causas penitus temptare latentis;<br>ater et alterius sequitur de cortice sanguis.<br>multa mouens animo Nymphas uenerabar agrestis<br>Gradiuumque patrem, Geticis qui praesidet aruis,   35<br>rite secundarent uisus omenque leuarent.<br>tertia sed postquam maiore hastilia nisu<br>adgredior genibusque aduersae obluctor harenae,<br>(eloquar an sileam?) gemitus lacrimabilis imo<br>auditur tumulo et uox reddita fertur ad auris:   40<br>‘quid miserum, Aenea, laceras? iam parce sepulto,<br>parce pias scelerare manus. non me tibi Troia<br>externum tulit aut cruor hic de stipite manat.<br>heu fuge crudelis terras, fuge litus auarum:<br>nam Polydorus ego. hic confixum ferrea texit   45<br>telorum seges et iaculis increuit acutis.’<br>tum uero ancipiti mentem formidine pressus<br>obstipui steteruntque comae et uox faucibus haesit.","st":"3"},{"sp":"N","t":"Hunc Polydorum auri quondam cum pondere magno<br>infelix Priamus furtim mandarat alendum   50<br>Threicio regi, cum iam diffideret armis<br>Dardaniae cingique urbem obsidione uideret.<br>ille, ut opes fractae Teucrum et Fortuna recessit,<br>res Agamemnonias uictriciaque arma secutus<br>fas omne abrumpit: Polydorum obtruncat, et auro   55<br>ui potitur. quid non mortalia pectora cogis,<br>auri sacra fames! postquam pauor ossa reliquit,<br>delectos populi ad proceres primumque parentem<br>monstra deum refero, et quae sit sententia posco.<br>omnibus idem animus, scelerata excedere terra,   60<br>linqui pollutum hospitium et dare classibus Austros.<br>ergo instauramus Polydoro funus, et ingens<br>aggeritur tumulo tellus; stant Manibus arae<br>caeruleis maestae uittis atraque cupresso,<br>et circum Iliades crinem de more solutae;   65<br>inferimus tepido spumantia cymbia lacte<br>sanguinis et sacri pateras, animamque sepulcro<br>condimus et magna supremum uoce ciemus.","st":"3"},{"sp":"N","t":"Inde ubi prima fides pelago, placataque uenti<br>dant maria et lenis crepitans uocat Auster in altum,   70<br>deducunt socii nauis et litora complent;<br>prouehimur portu terraeque urbesque recedunt.<br>sacra mari colitur medio gratissima tellus<br>Nereidum matri et Neptuno Aegaeo,<br>quam pius arquitenens oras et litora circum   75<br>errantem Mycono e celsa Gyaroque reuinxit,<br>immotamque coli dedit et contemnere uentos.<br>huc feror, haec fessos tuto placidissima portu<br>accipit; egressi ueneramur Apollinis urbem.<br>rex Anius, rex idem hominum Phoebique sacerdos,   80<br>uittis et sacra redimitus tempora lauro<br>occurrit; ueterem Anchisen agnouit amicum.<br>iungimus hospitio dextras et tecta subimus.","st":"3"},{"sp":"N","t":"Templa dei saxo uenerabar structa uetusto:<br>‘da propriam, Thymbraee, domum; da moenia fessis   85<br>et genus et mansuram urbem; serua altera Troiae<br>Pergama, reliquias Danaum atque immitis Achilli.<br>quem sequimur? quoue ire iubes? ubi ponere sedes?<br>da, pater, augurium atque animis inlabere nostris.’<br>uix ea fatus eram: tremere omnia uisa repente,   90<br>liminaque laurusque dei, totusque moueri<br>mons circum et mugire adytis cortina reclusis.<br>summissi petimus terram et uox fertur ad auris:<br>‘Dardanidae duri, quae uos a stirpe parentum<br>prima tulit tellus, eadem uos ubere laeto   95<br>accipiet reduces. antiquam exquirite matrem.<br>hic domus Aeneae cunctis dominabitur oris<br>et nati natorum et qui nascentur ab illis.’<br>haec Phoebus; mixtoque ingens exorta tumultu<br>laetitia, et cuncti quae sint ea moenia quaerunt,   100<br>quo Phoebus uocet errantis iubeatque reuerti.<br>tum genitor ueterum uoluens monimenta uirorum<br>‘audite, o proceres,’ ait ‘et spes discite uestras.<br>Creta Iouis magni medio iacet insula ponto,<br>mons Idaeus ubi et gentis cunabula nostrae.   105<br>centum urbes habitant magnas, uberrima regna,<br>maximus unde pater, si rite audita recordor,<br>Teucrus Rhoeteas primum est aduectus in oras,<br>optauitque locum regno. nondum Ilium et arces<br>Pergameae steterant; habitabant uallibus imis.   110<br>hinc mater cultrix Cybeli Corybantiaque aera<br>Idaeumque nemus, hinc fida silentia sacris,<br>et iuncti currum dominae subiere leones.<br>ergo agite et diuum ducunt qua iussa sequamur:<br>placemus uentos et Cnosia regna petamus.   115<br>nec longo distant cursu: modo Iuppiter adsit,<br>tertia lux classem Cretaeis sistet in oris.’<br>sic fatus meritos aris mactauit honores,<br>taurum Neptuno, taurum tibi, pulcher Apollo,<br>nigram Hiemi pecudem, Zephyris felicibus albam.   120","st":"3"},{"sp":"N","t":"Fama uolat pulsum regnis cessisse paternis<br>Idomenea ducem, desertaque litora Cretae,<br>hoste uacare domum sedesque astare relictas.<br>linquimus Ortygiae portus pelagoque uolamus<br>bacchatamque iugis Naxon uiridemque Donusam,   125<br>Olearon niueamque Paron sparsasque per aequor<br>Cycladas, et crebris legimus freta concita terris.<br>nauticus exoritur uario certamine clamor:<br>hortantur socii Cretam proauosque petamus.<br>prosequitur surgens a puppi uentus euntis,   130<br>et tandem antiquis Curetum adlabimur oris.<br>ergo auidus muros optatae molior urbis<br>Pergameamque uoco, et laetam cognomine gentem<br>hortor amare focos arcemque attollere tectis.","st":"3"},{"sp":"N","t":"Iamque fere sicco subductae litore puppes,   135<br>conubiis aruisque nouis operata iuuentus,<br>iura domosque dabam, subito cum tabida membris<br>corrupto caeli tractu miserandaque uenit<br>arboribusque satisque lues et letifer annus.<br>linquebant dulcis animas aut aegra trahebant   140<br>corpora; tum sterilis exurere Sirius agros,<br>arebant herbae et uictum seges aegra negabat.<br>rursus ad oraclum Ortygiae Phoebumque remenso<br>hortatur pater ire mari ueniamque precari,<br>quam fessis finem rebus ferat, unde laborum   145<br>temptare auxilium iubeat, quo uertere cursus.","st":"3"},{"sp":"N","t":"Nox erat et terris animalia somnus habebat:<br>effigies sacrae diuum Phrygiique penates,<br>quos mecum a Troia mediisque ex ignibus urbis<br>extuleram, uisi ante oculos astare iacentis   150<br>in somnis multo manifesti lumine, qua se<br>plena per insertas fundebat luna fenestras;<br>tum sic adfari et curas his demere dictis:<br>‘quod tibi delato Ortygiam dicturus Apollo est,<br>hic canit et tua nos en ultro ad limina mittit.   155<br>nos te Dardania incensa tuaque arma secuti,<br>nos tumidum sub te permensi classibus aequor,<br>idem uenturos tollemus in astra nepotes<br>imperiumque urbi dabimus. tu moenia magnis<br>magna para longumque fugae ne linque laborem.   160<br>mutandae sedes. non haec tibi litora suasit<br>Delius aut Cretae iussit considere Apollo.<br>est locus, Hesperiam Grai cognomine dicunt,<br>terra antiqua, potens armis atque ubere glaebae;<br>Oenotri coluere uiri; nunc fama minores   165<br>Italiam dixisse ducis de nomine gentem.<br>hae nobis propriae sedes, hinc Dardanus ortus<br>Iasiusque pater, genus a quo principe nostrum.<br>surge age et haec laetus longaeuo dicta parenti<br>haud dubitanda refer: Corythum terrasque requirat   170<br>Ausonias; Dictaea negat tibi Iuppiter arua.’<br>talibus attonitus uisis et uoce deorum<br>(nec sopor illud erat, sed coram agnoscere uultus<br>uelatasque comas praesentiaque ora uidebar;<br>tum gelidus toto manabat corpore sudor)   175<br>corripio e stratis corpus tendoque supinas<br>ad caelum cum uoce manus et munera libo<br>intemerata focis. perfecto laetus honore<br>Anchisen facio certum remque ordine pando.<br>agnouit prolem ambiguam geminosque parentis,   180<br>seque nouo ueterum deceptum errore locorum.<br>tum memorat: ‘nate, Iliacis exercite fatis,<br>sola mihi talis casus Cassandra canebat.<br>nunc repeto haec generi portendere debita nostro<br>et saepe Hesperiam, saepe Itala regna uocare.   185<br>sed quis ad Hesperiae uenturos litora Teucros<br>crederet? aut quem tum uates Cassandra moueret?<br>cedamus Phoebo et moniti meliora sequamur.’<br>sic ait, et cuncti dicto paremus ouantes.<br>hanc quoque deserimus sedem paucisque relictis   190<br>uela damus uastumque caua trabe currimus aequor.","st":"3"},{"sp":"N","t":"Postquam altum tenuere rates nec iam amplius ullae<br>apparent terrae, caelum undique et undique pontus,<br>tum mihi caeruleus supra caput astitit imber<br>noctem hiememque ferens, et inhorruit unda tenebris.   195<br>continuo uenti uoluunt mare magnaque surgunt<br>aequora, dispersi iactamur gurgite uasto;<br>inuoluere diem nimbi et nox umida caelum<br>abstulit, ingeminant abruptis nubibus ignes,<br>excutimur cursu et caecis erramus in undis.   200<br>ipse diem noctemque negat discernere caelo<br>nec meminisse uiae media Palinurus in unda.<br>tris adeo incertos caeca caligine soles<br>erramus pelago, totidem sine sidere noctes.<br>quarto terra die primum se attollere tandem   205<br>uisa, aperire procul montis ac uoluere fumum.<br>uela cadunt, remis insurgimus; haud mora, nautae<br>adnixi torquent spumas et caerula uerrunt.<br>seruatum ex undis Strophadum me litora primum<br>excipiunt. Strophades Graio stant nomine dictae   210<br>insulae Ionio in magno, quas dira Celaeno<br>Harpyiaeque colunt aliae, Phineia postquam<br>clausa domus mensasque metu liquere priores.<br>tristius haud illis monstrum, nec saeuior ulla<br>pestis et ira deum Stygiis sese extulit undis.   215<br>uirginei uolucrum uultus, foedissima uentris<br>proluuies uncaeque manus et pallida semper<br>ora fame.<br>huc ubi delati portus intrauimus, ecce<br>laeta boum passim campis armenta uidemus   220<br>caprigenumque pecus nullo custode per herbas.<br>inruimus ferro et diuos ipsumque uocamus<br>in partem praedamque Iouem; tum litore curuo<br>exstruimusque toros dapibusque epulamur opimis.<br>at subitae horrifico lapsu de montibus adsunt   225<br>Harpyiae et magnis quatiunt clangoribus alas,<br>diripiuntque dapes contactuque omnia foedant<br>immundo; tum uox taetrum dira inter odorem.<br>rursum in secessu longo sub rupe cauata<br>[arboribus clausam circum atque horrentibus umbris]   230<br>instruimus mensas arisque reponimus ignem;<br>rursum ex diuerso caeli caecisque latebris<br>turba sonans praedam pedibus circumuolat uncis,<br>polluit ore dapes. sociis tunc arma capessant<br>edico, et dira bellum cum gente gerendum.   235<br>haud secus ac iussi faciunt tectosque per herbam<br>disponunt ensis et scuta latentia condunt.<br>ergo ubi delapsae sonitum per curua dedere<br>litora, dat signum specula Misenus ab alta<br>aere cauo. inuadunt socii et noua proelia temptant,   240<br>obscenas pelagi ferro foedare uolucris.<br>sed neque uim plumis ullam nec uulnera tergo<br>accipiunt, celerique fuga sub sidera lapsae<br>semesam praedam et uestigia foeda relinquunt.<br>una in praecelsa consedit rupe Celaeno,   245<br>infelix uates, rumpitque hanc pectore uocem;<br>‘bellum etiam pro caede boum stratisque iuuencis,<br>Laomedontiadae, bellumne inferre paratis<br>et patrio Harpyias insontis pellere regno?<br>accipite ergo animis atque haec mea figite dicta,   250<br>quae Phoebo pater omnipotens, mihi Phoebus Apollo<br>praedixit, uobis Furiarum ego maxima pando.<br>Italiam cursu petitis uentisque uocatis:<br>ibitis Italiam portusque intrare licebit.<br>sed non ante datam cingetis moenibus urbem   255<br>quam uos dira fames nostraeque iniuria caedis<br>ambesas subigat malis absumere mensas.’<br>dixit, et in siluam pennis ablata refugit.<br>at sociis subita gelidus formidine sanguis<br>deriguit: cecidere animi, nec iam amplius armis,   260<br>sed uotis precibusque iubent exposcere pacem,<br>siue deae seu sint dirae obscenaeque uolucres.<br>et pater Anchises passis de litore palmis<br>numina magna uocat meritosque indicit honores:<br>‘di, prohibete minas; di, talem auertite casum   265<br>et placidi seruate pios.’ tum litore funem<br>deripere excussosque iubet laxare rudentis.<br>tendunt uela Noti: fugimus spumantibus undis<br>qua cursum uentusque gubernatorque uocabat.<br>iam medio apparet fluctu nemorosa Zacynthos   270<br>Dulichiumque Sameque et Neritos ardua saxis.<br>effugimus scopulos Ithacae, Laertia regna,<br>et terram altricem saeui exsecramur Vlixi.<br>mox et Leucatae nimbosa cacumina montis<br>et formidatus nautis aperitur Apollo.   275<br>hunc petimus fessi et paruae succedimus urbi;<br>ancora de prora iacitur, stant litore puppes.","st":"3"},{"sp":"N","t":"Ergo insperata tandem tellure potiti<br>lustramurque Ioui uotisque incendimus aras,<br>Actiaque Iliacis celebramus litora ludis.   280<br>exercent patrias oleo labente palaestras<br>nudati socii: iuuat euasisse tot urbes<br>Argolicas mediosque fugam tenuisse per hostis.<br>interea magnum sol circumuoluitur annum<br>et glacialis hiems Aquilonibus asperat undas.   285<br>aere cauo clipeum, magni gestamen Abantis,<br>postibus aduersis figo et rem carmine signo:<br>aeneas haec de danais victoribvs arma;<br>linquere tum portus iubeo et considere transtris.<br>certatim socii feriunt mare et aequora uerrunt:   290<br>protinus aerias Phaeacum abscondimus arces<br>litoraque Epiri legimus portuque subimus<br>Chaonio et celsam Buthroti accedimus urbem.","st":"3"},{"sp":"N","t":"Hic incredibilis rerum fama occupat auris,<br>Priamiden Helenum Graias regnare per urbis   295<br>coniugio Aeacidae Pyrrhi sceptrisque potitum,<br>et patrio Andromachen iterum cessisse marito.<br>obstipui, miroque incensum pectus amore<br>compellare uirum et casus cognoscere tantos.<br>progredior portu classis et litora linquens,   300<br>sollemnis cum forte dapes et tristia dona<br>ante urbem in luco falsi Simoentis ad undam<br>libabat cineri Andromache manisque uocabat<br>Hectoreum ad tumulum, uiridi quem caespite inanem<br>et geminas, causam lacrimis, sacrauerat aras.   305<br>ut me conspexit uenientem et Troia circum<br>arma amens uidit, magnis exterrita monstris<br>deriguit uisu in medio, calor ossa reliquit,<br>labitur, et longo uix tandem tempore fatur:<br>‘uerane te facies, uerus mihi nuntius adfers,   310<br>nate dea? uiuisne? aut, si lux alma recessit,<br>Hector ubi est?’ dixit, lacrimasque effudit et omnem<br>impleuit clamore locum. uix pauca furenti<br>subicio et raris turbatus uocibus hisco:<br>‘uiuo equidem uitamque extrema per omnia duco;   315<br>ne dubita, nam uera uides.<br>heu! quis te casus deiectam coniuge tanto<br>excipit, aut quae digna satis fortuna reuisit,<br>Hectoris Andromache? Pyrrhin conubia seruas?’<br>deiecit uultum et demissa uoce locuta est:   320<br>‘o felix una ante alias Priameia uirgo,<br>hostilem ad tumulum Troiae sub moenibus altis<br>iussa mori, quae sortitus non pertulit ullos<br>nec uictoris heri tetigit captiua cubile!<br>nos patria incensa diuersa per aequora uectae   325<br>stirpis Achilleae fastus iuuenemque superbum<br>seruitio enixae tulimus; qui deinde secutus<br>Ledaeam Hermionen Lacedaemoniosque hymenaeos<br>me famulo famulamque Heleno transmisit habendam.<br>ast illum ereptae magno flammatus amore   330<br>coniugis et scelerum furiis agitatus Orestes<br>excipit incautum patriasque obtruncat ad aras.<br>morte Neoptolemi regnorum reddita cessit<br>pars Heleno, qui Chaonios cognomine campos<br>Chaoniamque omnem Troiano a Chaone dixit,   335<br>Pergamaque Iliacamque iugis hanc addidit arcem.<br>sed tibi qui cursum uenti, quae fata dedere?<br>aut quisnam ignarum nostris deus appulit oris?<br>quid puer Ascanius? superatne et uescitur aura?<br>quem tibi iam Troia —            340<br>ecqua tamen puero est amissae cura parentis?<br>ecquid in antiquam uirtutem animosque uirilis<br>et pater Aeneas et auunculus excitat Hector?’<br>talia fundebat lacrimans longosque ciebat<br>incassum fletus, cum sese a moenibus heros   345<br>Priamides multis Helenus comitantibus adfert,<br>agnoscitque suos laetusque ad limina ducit,<br>et multum lacrimas uerba inter singula fundit.<br>procedo et paruam Troiam simulataque magnis<br>Pergama et arentem Xanthi cognomine riuum   350<br>agnosco, Scaeaeque amplector limina portae;<br>nec non et Teucri socia simul urbe fruuntur.<br>illos porticibus rex accipiebat in amplis:<br>aulai medio libabant pocula Bacchi<br>impositis auro dapibus, paterasque tenebant.   355","st":"3"},{"sp":"N","t":"Iamque dies alterque dies processit, et aurae<br>uela uocant tumidoque inflatur carbasus Austro:<br>his uatem adgredior dictis ac talia quaeso:<br>‘Troiugena, interpres diuum, qui numina Phoebi,<br>qui tripodas Clarii et laurus, qui sidera sentis   360<br>et uolucrum linguas et praepetis omina pennae,<br>fare age (namque omnis cursum mihi prospera dixit<br>religio, et cuncti suaserunt numine diui<br>Italiam petere et terras temptare repostas;<br>sola nouum dictuque nefas Harpyia Celaeno   365<br>prodigium canit et tristis denuntiat iras<br>obscenamque famem), quae prima pericula uito?<br>quidue sequens tantos possim superare labores?’<br>hic Helenus caesis primum de more iuuencis<br>exorat pacem diuum uittasque resoluit   370<br>sacrati capitis, meque ad tua limina, Phoebe,<br>ipse manu multo suspensum numine ducit,<br>atque haec deinde canit diuino ex ore sacerdos:","st":"3"},{"sp":"N","t":"‘Nate dea (nam te maioribus ire per altum<br>auspiciis manifesta fides; sic fata deum rex   375<br>sortitur uoluitque uices, is uertitur ordo),<br>pauca tibi e multis, quo tutior hospita lustres<br>aequora et Ausonio possis considere portu,<br>expediam dictis; prohibent nam cetera Parcae<br>scire Helenum farique uetat Saturnia Iuno.    380<br>principio Italiam, quam tu iam rere propinquam<br>uicinosque, ignare, paras inuadere portus,<br>longa procul longis uia diuidit inuia terris.<br>ante et Trinacria lentandus remus in unda<br>et salis Ausonii lustrandum nauibus aequor   385<br>infernique lacus Aeaeaeque insula Circae,<br>quam tuta possis urbem componere terra.<br>signa tibi dicam, tu condita mente teneto:<br>cum tibi sollicito secreti ad fluminis undam<br>litoreis ingens inuenta sub ilicibus sus   390<br>triginta capitum fetus enixa iacebit,<br>alba solo recubans, albi circum ubera nati,<br>is locus urbis erit, requies ea certa laborum.<br>nec tu mensarum morsus horresce futuros:<br>fata uiam inuenient aderitque uocatus Apollo.   395<br>has autem terras Italique hanc litoris oram,<br>proxima quae nostri perfunditur aequoris aestu,<br>effuge; cuncta malis habitantur moenia Grais.<br>hic et Narycii posuerunt moenia Locri,<br>et Sallentinos obsedit milite campos   400<br>Lyctius Idomeneus; hic illa ducis Meliboei<br>parua Philoctetae subnixa Petelia muro.<br>quin ubi transmissae steterint trans aequora classes<br>et positis aris iam uota in litore solues,<br>purpureo uelare comas adopertus amictu,   405<br>ne qua inter sanctos ignis in honore deorum<br>hostilis facies occurrat et omina turbet.<br>hunc socii morem sacrorum, hunc ipse teneto;<br>hac casti maneant in religione nepotes.<br>ast ubi digressum Siculae te admouerit orae   410<br>uentus, et angusti rarescent claustra Pelori,<br>laeua tibi tellus et longo laeua petantur<br>aequora circuitu; dextrum fuge litus et undas.<br>haec loca ui quondam et uasta conuulsa ruina<br>(tantum aeui longinqua ualet mutare uetustas)    415<br>dissiluisse ferunt, cum protinus utraque tellus<br>una foret: uenit medio ui pontus et undis<br>Hesperium Siculo latus abscidit, aruaque et urbes<br>litore diductas angusto interluit aestu.<br>dextrum Scylla latus, laeuum implacata Charybdis   420<br>obsidet, atque imo barathri ter gurgite uastos<br>sorbet in abruptum fluctus rursusque sub auras<br>erigit alternos, et sidera uerberat unda.<br>at Scyllam caecis cohibet spelunca latebris<br>ora exsertantem et nauis in saxa trahentem.   425<br>prima hominis facies et pulchro pectore uirgo<br>pube tenus, postrema immani corpore pistrix<br>delphinum caudas utero commissa luporum.<br>praestat Trinacrii metas lustrare Pachyni<br>cessantem, longos et circumflectere cursus,   430<br>quam semel informem uasto uidisse sub antro<br>Scyllam et caeruleis canibus resonantia saxa.<br>praeterea, si qua est Heleno prudentia uati,<br>si qua fides, animum si ueris implet Apollo,<br>unum illud tibi, nate dea, proque omnibus unum   435<br>praedicam et repetens iterumque iterumque monebo,<br>Iunonis magnae primum prece numen adora,<br>Iunoni cane uota libens dominamque potentem<br>supplicibus supera donis: sic denique uictor<br>Trinacria finis Italos mittere relicta.   440<br>huc ubi delatus Cumaeam accesseris urbem<br>diuinosque lacus et Auerna sonantia siluis,<br>insanam uatem aspicies, quae rupe sub ima<br>fata canit foliisque notas et nomina mandat.<br>quaecumque in foliis descripsit carmina uirgo   445<br>digerit in numerum atque antro seclusa relinquit:<br>illa manent immota locis neque ab ordine cedunt.<br>uerum eadem, uerso tenuis cum cardine uentus<br>impulit et teneras turbauit ianua frondes,<br>numquam deinde cauo uolitantia prendere saxo   450<br>nec reuocare situs aut iungere carmina curat:<br>inconsulti abeunt sedemque odere Sibyllae.<br>hic tibi ne qua morae fuerint dispendia tanti,<br>quamuis increpitent socii et ui cursus in altum<br>uela uocet, possisque sinus implere secundos,   455<br>quin adeas uatem precibusque oracula poscas<br>ipsa canat uocemque uolens atque ora resoluat.<br>illa tibi Italiae populos uenturaque bella<br>et quo quemque modo fugiasque ferasque laborem<br>expediet, cursusque dabit uenerata secundos.   460<br>haec sunt quae nostra liceat te uoce moneri.<br>uade age et ingentem factis fer ad aethera Troiam.’","st":"3"},{"sp":"N","t":"Quae postquam uates sic ore effatus amico est,<br>dona dehinc auro grauia ac secto elephanto<br>imperat ad nauis ferri, stipatque carinis   465<br>ingens argentum Dodonaeosque lebetas,<br>loricam consertam hamis auroque trilicem,<br>et conum insignis galeae cristasque comantis,<br>arma Neoptolemi. sunt et sua dona parenti.<br>addit equos, additque duces,   470<br>remigium supplet, socios simul instruit armis.","st":"3"},{"sp":"N","t":"Interea classem uelis aptare iubebat<br>Anchises, fieret uento mora ne qua ferenti.<br>quem Phoebi interpres multo compellat honore:<br>‘coniugio, Anchisa, Veneris dignate superbo,   475<br>cura deum, bis Pergameis erepte ruinis,<br>ecce tibi Ausoniae tellus: hanc arripe uelis.<br>et tamen hanc pelago praeterlabare necesse est:<br>Ausoniae pars illa procul quam pandit Apollo.<br>uade,’ ait ‘o felix nati pietate. quid ultra   480<br>prouehor et fando surgentis demoror Austros?’<br>nec minus Andromache digressu maesta supremo<br>fert picturatas auri subtemine uestis<br>et Phrygiam Ascanio chlamydem (nec cedit honore)<br>textilibusque onerat donis, ac talia fatur:   485<br>‘accipe et haec, manuum tibi quae monimenta mearum<br>sint, puer, et longum Andromachae testentur amorem,<br>coniugis Hectoreae. cape dona extrema tuorum,<br>o mihi sola mei super Astyanactis imago.<br>sic oculos, sic ille manus, sic ora ferebat;   490<br>et nunc aequali tecum pubesceret aeuo.’<br>hos ego digrediens lacrimis adfabar obortis:<br>‘uiuite felices, quibus est fortuna peracta<br>iam sua: nos alia ex aliis in fata uocamur.<br>uobis parta quies: nullum maris aequor arandum,   495<br>arua neque Ausoniae semper cedentia retro<br>quaerenda. effigiem Xanthi Troiamque uidetis<br>quam uestrae fecere manus, melioribus, opto,<br>auspiciis, et quae fuerit minus obuia Grais.<br>si quando Thybrim uicinaque Thybridis arua   500<br>intraro gentique meae data moenia cernam,<br>cognatas urbes olim populosque propinquos,<br>Epiro Hesperiam (quibus idem Dardanus auctor<br>atque idem casus), unam faciemus utramque<br>Troiam animis: maneat nostros ea cura nepotes.’   505","st":"3"},{"sp":"N","t":"Prouehimur pelago uicina Ceraunia iuxta,<br>unde iter Italiam cursusque breuissimus undis.<br>sol ruit interea et montes umbrantur opaci;<br>sternimur optatae gremio telluris ad undam<br>sortiti remos passimque in litore sicco   510<br>corpora curamus, fessos sopor inrigat artus.<br>necdum orbem medium Nox Horis acta subibat:<br>haud segnis strato surgit Palinurus et omnis<br>explorat uentos atque auribus aera captat;<br>sidera cuncta notat tacito labentia caelo,   515<br>Arcturum pluuiasque Hyadas geminosque Triones,<br>armatumque auro circumspicit Oriona.<br>postquam cuncta uidet caelo constare sereno,<br>dat clarum e puppi signum; nos castra mouemus<br>temptamusque uiam et uelorum pandimus alas.   520","st":"3"},{"sp":"N","t":"Iamque rubescebat stellis Aurora fugatis<br>cum procul obscuros collis humilemque uidemus<br>Italiam. Italiam primus conclamat Achates,<br>Italiam laeto socii clamore salutant.<br>tum pater Anchises magnum cratera corona   525<br>induit impleuitque mero, diuosque uocauit<br>stans celsa in puppi:<br>‘di maris et terrae tempestatumque potentes,<br>ferte uiam uento facilem et spirate secundi.’<br>crebrescunt optatae aurae portusque patescit   530<br>iam propior, templumque apparet in arce Mineruae;<br>uela legunt socii et proras ad litora torquent.<br>portus ab euroo fluctu curuatus in arcum,<br>obiectae salsa spumant aspergine cautes,<br>ipse latet: gemino demittunt bracchia muro   535<br>turriti scopuli refugitque ab litore templum.<br>quattuor hic, primum omen, equos in gramine uidi<br>tondentis campum late, candore niuali.<br>et pater Anchises ‘bellum, o terra hospita, portas:<br>bello armantur equi, bellum haec armenta minantur.    540<br>sed tamen idem olim curru succedere sueti<br>quadripedes et frena iugo concordia ferre:<br>spes et pacis’ ait. tum numina sancta precamur<br>Palladis armisonae, quae prima accepit ouantis,<br>et capita ante aras Phrygio uelamur amictu,   545<br>praeceptisque Heleni, dederat quae maxima, rite<br>Iunoni Argiuae iussos adolemus honores.","st":"3"},{"sp":"N","t":"Haud mora, continuo perfectis ordine uotis<br>cornua uelatarum obuertimus antemnarum,<br>Graiugenumque domos suspectaque linquimus arua.   550<br>hinc sinus Herculei (si uera est fama) Tarenti<br>cernitur, attollit se diua Lacinia contra,<br>Caulonisque arces et nauifragum Scylaceum.<br>tum procul e fluctu Trinacria cernitur Aetna,<br>et gemitum ingentem pelagi pulsataque saxa   555<br>audimus longe fractasque ad litora uoces,<br>exsultantque uada atque aestu miscentur harenae.<br>et pater Anchises ‘nimirum hic illa Charybdis:<br>hos Helenus scopulos, haec saxa horrenda canebat.<br>eripite, o socii, pariterque insurgite remis.’   560<br>haud minus ac iussi faciunt, primusque rudentem<br>contorsit laeuas proram Palinurus ad undas;<br>laeuam cuncta cohors remis uentisque petiuit.<br>tollimur in caelum curuato gurgite, et idem<br>subducta ad Manis imos desedimus unda.   565<br>ter scopuli clamorem inter caua saxa dedere,<br>ter spumam elisam et rorantia uidimus astra.<br>interea fessos uentus cum sole reliquit,<br>ignarique uiae Cyclopum adlabimur oris.","st":"3"},{"sp":"N","t":"Portus ab accessu uentorum immotus et ingens   570<br>ipse: sed horrificis iuxta tonat Aetna ruinis,<br>interdumque atram prorumpit ad aethera nubem<br>turbine fumantem piceo et candente fauilla,<br>attollitque globos flammarum et sidera lambit;<br>interdum scopulos auulsaque uiscera montis   575<br>erigit eructans, liquefactaque saxa sub auras<br>cum gemitu glomerat fundoque exaestuat imo.<br>fama est Enceladi semustum fulmine corpus<br>urgeri mole hac, ingentemque insuper Aetnam<br>impositam ruptis flammam exspirare caminis,   580<br>et fessum quotiens mutet latus, intremere omnem<br>murmure Trinacriam et caelum subtexere fumo.<br>noctem illam tecti siluis immania monstra<br>perferimus, nec quae sonitum det causa uidemus.<br>nam neque erant astrorum ignes nec lucidus aethra   585<br>siderea polus, obscuro sed nubila caelo,<br>et lunam in nimbo nox intempesta tenebat.","st":"3"},{"sp":"N","t":"Postera iamque dies primo surgebat Eoo<br>umentemque Aurora polo dimouerat umbram,<br>cum subito e siluis macie confecta suprema   590<br>ignoti noua forma uiri miserandaque cultu<br>procedit supplexque manus ad litora tendit.<br>respicimus. dira inluuies immissaque barba,<br>consertum tegimen spinis: at cetera Graius,<br>et quondam patriis ad Troiam missus in armis.   595<br>isque ubi Dardanios habitus et Troia uidit<br>arma procul, paulum aspectu conterritus haesit<br>continuitque gradum; mox sese ad litora praeceps<br>cum fletu precibusque tulit: ‘per sidera testor,<br>per superos atque hoc caeli spirabile lumen,   600<br>tollite me, Teucri. quascumque abducite terras:<br>hoc sat erit. scio me Danais e classibus unum<br>et bello Iliacos fateor petiisse penatis.<br>pro quo, si sceleris tanta est iniuria nostri,<br>spargite me in fluctus uastoque immergite ponto;   605<br>si pereo, hominum manibus periisse iuuabit.’<br>dixerat et genua amplexus genibusque uolutans<br>haerebat. qui sit fari, quo sanguine cretus,<br>hortamur, quae deinde agitet fortuna fateri.<br>ipse pater dextram Anchises haud multa moratus   610<br>dat iuueni atque animum praesenti pignore firmat.<br>ille haec deposita tandem formidine fatur:<br>‘sum patria ex Ithaca, comes infelicis Vlixi,<br>nomine Achaemenides, Troiam genitore Adamasto<br>paupere (mansissetque utinam fortuna!) profectus.   615<br>hic me, dum trepidi crudelia limina linquunt,<br>immemores socii uasto Cyclopis in antro<br>deseruere. domus sanie dapibusque cruentis,<br>intus opaca, ingens. ipse arduus, altaque pulsat<br>sidera (di talem terris auertite pestem!)   620<br>nec uisu facilis nec dictu adfabilis ulli;<br>uisceribus miserorum et sanguine uescitur atro.<br>uidi egomet duo de numero cum corpora nostro<br>prensa manu magna medio resupinus in antro<br>frangeret ad saxum, sanieque aspersa natarent   625<br>limina; uidi atro cum membra fluentia tabo<br>manderet et tepidi tremerent sub dentibus artus — <br>haud impune quidem, nec talia passus Vlixes<br>oblitusue sui est Ithacus discrimine tanto.<br>nam simul expletus dapibus uinoque sepultus   630<br>ceruicem inflexam posuit, iacuitque per antrum<br>immensus saniem eructans et frusta cruento<br>per somnum commixta mero, nos magna precati<br>numina sortitique uices una undique circum<br>fundimur, et telo lumen terebramus acuto   635<br>ingens quod torua solum sub fronte latebat,<br>Argolici clipei aut Phoebeae lampadis instar,<br>et tandem laeti sociorum ulciscimur umbras.<br>sed fugite, o miseri, fugite atque ab litore funem<br>rumpite.            640<br>nam qualis quantusque cauo Polyphemus in antro<br>lanigeras claudit pecudes atque ubera pressat,<br>centum alii curua haec habitant ad litora uulgo<br>infandi Cyclopes et altis montibus errant.<br>tertia iam lunae se cornua lumine complent   645<br>cum uitam in siluis inter deserta ferarum<br>lustra domosque traho uastosque ab rupe Cyclopas<br>prospicio sonitumque pedum uocemque tremesco.<br>uictum infelicem, bacas lapidosaque corna,<br>dant rami, et uulsis pascunt radicibus herbae.   650<br>omnia conlustrans hanc primum ad litora classem<br>conspexi uenientem. huic me, quaecumque fuisset,<br>addixi: satis est gentem effugisse nefandam.<br>uos animam hanc potius quocumque absumite leto.’","st":"3"},{"sp":"N","t":"Vix ea fatus erat summo cum monte uidemus   655<br>ipsum inter pecudes uasta se mole mouentem<br>pastorem Polyphemum et litora nota petentem,<br>monstrum horrendum, informe, ingens, cui lumen ademptum.<br>trunca manum pinus regit et uestigia firmat;<br>lanigerae comitantur oues; ea sola uoluptas   660<br>solamenque mali.<br>postquam altos tetigit fluctus et ad aequora uenit,<br>luminis effossi fluidum lauit inde cruorem<br>dentibus infrendens gemitu, graditurque per aequor<br>iam medium, necdum fluctus latera ardua tinxit.    665<br>nos procul inde fugam trepidi celerare recepto<br>supplice sic merito tacitique incidere funem,<br>uertimus et proni certantibus aequora remis.<br>sensit, et ad sonitum uocis uestigia torsit.<br>uerum ubi nulla datur dextra adfectare potestas   670<br>nec potis Ionios fluctus aequare sequendo,<br>clamorem immensum tollit, quo pontus et omnes<br>intremuere undae, penitusque exterrita tellus<br>Italiae curuisque immugiit Aetna cauernis.<br>at genus e siluis Cyclopum et montibus altis   675<br>excitum ruit ad portus et litora complent.<br>cernimus astantis nequiquam lumine toruo<br>Aetnaeos fratres caelo capita alta ferentis,<br>concilium horrendum: quales cum uertice celso<br>aeriae quercus aut coniferae cyparissi   680<br>constiterunt, silua alta Iouis lucusue Dianae.<br>praecipitis metus acer agit quocumque rudentis<br>excutere et uentis intendere uela secundis.<br>contra iussa monent Heleni, Scyllamque Charybdinque<br>inter, utrimque uiam leti discrimine paruo,   685<br>ni teneam cursus: certum est dare lintea retro.<br>ecce autem Boreas angusta ab sede Pelori<br>missus adest: uiuo praeteruehor ostia saxo<br>Pantagiae Megarosque sinus Thapsumque iacentem.<br>talia monstrabat relegens errata retrorsus   690<br>litora Achaemenides, comes infelicis Vlixi.","st":"3"},{"sp":"N","t":"Sicanio praetenta sinu iacet insula contra<br>Plemyrium undosum; nomen dixere priores<br>Ortygiam. Alpheum fama est huc Elidis amnem<br>occultas egisse uias subter mare, qui nunc   695<br>ore, Arethusa, tuo Siculis confunditur undis.<br>iussi numina magna loci ueneramur, et inde<br>exsupero praepingue solum stagnantis Helori.<br>hinc altas cautes proiectaque saxa Pachyni<br>radimus, et fatis numquam concessa moueri   700<br>apparet Camerina procul campique Geloi,<br>immanisque Gela fluuii cognomine dicta.<br>arduus inde Acragas ostentat maxima longe<br>moenia, magnanimum quondam generator equorum;<br>teque datis linquo uentis, palmosa Selinus,   705<br>et uada dura lego saxis Lilybeia caecis.<br>hinc Drepani me portus et inlaetabilis ora<br>accipit. hic pelagi tot tempestatibus actus<br>heu, genitorem, omnis curae casusque leuamen,<br>amitto Anchisen. hic me, pater optime, fessum   710<br>deseris, heu, tantis nequiquam erepte periclis!<br>nec uates Helenus, cum multa horrenda moneret,<br>hos mihi praedixit luctus, non dira Celaeno.<br>hic labor extremus, longarum haec meta uiarum,<br>hinc me digressum uestris deus appulit oris.   715","st":"3"},{"sp":"N","t":"Sic pater Aeneas intentis omnibus unus<br>fata renarrabat diuum cursusque docebat.<br>conticuit tandem factoque hic fine quieuit.","st":"3"},{"sp":"HDR","t":"Liber IV","st":"4"},{"sp":"N","t":"At regina graui iamdudum saucia cura<br>uulnus alit uenis et caeco carpitur igni.<br>multa uiri uirtus animo multusque recursat<br>gentis honos; haerent infixi pectore uultus<br>uerbaque nec placidam membris dat cura quietem.   5<br>postera Phoebea lustrabat lampade terras<br>umentemque Aurora polo dimouerat umbram,<br>cum sic unanimam adloquitur male sana sororem:<br>‘Anna soror, quae me suspensam insomnia terrent!<br>quis nouus hic nostris successit sedibus hospes,   10<br>quem sese ore ferens, quam forti pectore et armis!<br>credo equidem, nec uana fides, genus esse deorum.<br>degeneres animos timor arguit. heu, quibus ille<br>iactatus fatis! quae bella exhausta canebat!<br>si mihi non animo fixum immotumque sederet   15<br>ne cui me uinclo uellem sociare iugali,<br>postquam primus amor deceptam morte fefellit;<br>si non pertaesum thalami taedaeque fuisset,<br>huic uni forsan potui succumbere culpae.<br>Anna (fatebor enim) miseri post fata Sychaei   20<br>coniugis et sparsos fraterna caede penatis<br>solus hic inflexit sensus animumque labantem<br>impulit. agnosco ueteris uestigia flammae.<br>sed mihi uel tellus optem prius ima dehiscat<br>uel pater omnipotens adigat me fulmine ad umbras,    25<br>pallentis umbras Erebo noctemque profundam,<br>ante, pudor, quam te uiolo aut tua iura resoluo.<br>ille meos, primus qui me sibi iunxit, amores<br>abstulit; ille habeat secum seruetque sepulcro.’<br>sic effata sinum lacrimis impleuit obortis.   30","st":"4"},{"sp":"N","t":"Anna refert: ‘o luce magis dilecta sorori,<br>solane perpetua maerens carpere iuuenta<br>nec dulcis natos Veneris nec praemia noris?<br>id cinerem aut manis credis curare sepultos?<br>esto: aegram nulli quondam flexere mariti,   35<br>non Libyae, non ante Tyro; despectus Iarbas<br>ductoresque alii, quos Africa terra triumphis<br>diues alit: placitone etiam pugnabis amori?<br>nec uenit in mentem quorum consederis aruis?<br>hinc Gaetulae urbes, genus insuperabile bello,   40<br>et Numidae infreni cingunt et inhospita Syrtis;<br>hinc deserta siti regio lateque furentes<br>Barcaei. quid bella Tyro surgentia dicam<br>germanique minas?<br>dis equidem auspicibus reor et Iunone secunda   45<br>hunc cursum Iliacas uento tenuisse carinas.<br>quam tu urbem, soror, hanc cernes, quae surgere regna<br>coniugio tali! Teucrum comitantibus armis<br>Punica se quantis attollet gloria rebus!<br>tu modo posce deos ueniam, sacrisque litatis   50<br>indulge hospitio causasque innecte morandi,<br>dum pelago desaeuit hiems et aquosus Orion,<br>quassataeque rates, dum non tractabile caelum.’","st":"4"},{"sp":"N","t":"His dictis impenso animum flammauit amore<br>spemque dedit dubiae menti soluitque pudorem.   55<br>principio delubra adeunt pacemque per aras<br>exquirunt; mactant lectas de more bidentis<br>legiferae Cereri Phoeboque patrique Lyaeo,<br>Iunoni ante omnis, cui uincla iugalia curae.<br>ipsa tenens dextra pateram pulcherrima Dido   60<br>candentis uaccae media inter cornua fundit,<br>aut ante ora deum pinguis spatiatur ad aras,<br>instauratque diem donis, pecudumque reclusis<br>pectoribus inhians spirantia consulit exta.<br>heu, uatum ignarae mentes! quid uota furentem,   65<br>quid delubra iuuant? est mollis flamma medullas<br>interea et tacitum uiuit sub pectore uulnus.<br>uritur infelix Dido totaque uagatur<br>urbe furens, qualis coniecta cerua sagitta,<br>quam procul incautam nemora inter Cresia fixit   70<br>pastor agens telis liquitque uolatile ferrum<br>nescius: illa fuga siluas saltusque peragrat<br>Dictaeos; haeret lateri letalis harundo.<br>nunc media Aenean secum per moenia ducit<br>Sidoniasque ostentat opes urbemque paratam,   75<br>incipit effari mediaque in uoce resistit;<br>nunc eadem labente die conuiuia quaerit,<br>Iliacosque iterum demens audire labores<br>exposcit pendetque iterum narrantis ab ore.<br>post ubi digressi, lumenque obscura uicissim   80<br>luna premit suadentque cadentia sidera somnos,<br>sola domo maeret uacua stratisque relictis<br>incubat. illum absens absentem auditque uidetque,<br>aut gremio Ascanium genitoris imagine capta<br>detinet, infandum si fallere possit amorem.   85<br>non coeptae adsurgunt turres, non arma iuuentus<br>exercet portusue aut propugnacula bello<br>tuta parant: pendent opera interrupta minaeque<br>murorum ingentes aequataque machina caelo.","st":"4"},{"sp":"N","t":"Quam simul ac tali persensit peste teneri   90<br>cara Iouis coniunx nec famam obstare furori,<br>talibus adgreditur Venerem Saturnia dictis:<br>‘egregiam uero laudem et spolia ampla refertis<br>tuque puerque tuus (magnum et memorabile numen),<br>una dolo diuum si femina uicta duorum est.   95<br>nec me adeo fallit ueritam te moenia nostra<br>suspectas habuisse domos Karthaginis altae.<br>sed quis erit modus, aut quo nunc certamine tanto?<br>quin potius pacem aeternam pactosque hymenaeos<br>exercemus? habes tota quod mente petisti:   100<br>ardet amans Dido traxitque per ossa furorem.<br>communem hunc ergo populum paribusque regamus<br>auspiciis; liceat Phrygio seruire marito<br>dotalisque tuae Tyrios permittere dextrae.’","st":"4"},{"sp":"N","t":"Olli (sensit enim simulata mente locutam,   105<br>quo regnum Italiae Libycas auerteret oras)<br>sic contra est ingressa Venus: ‘quis talia demens<br>abnuat aut tecum malit contendere bello?<br>si modo quod memoras factum fortuna sequatur.<br>sed fatis incerta feror, si Iuppiter unam   110<br>esse uelit Tyriis urbem Troiaque profectis,<br>misceriue probet populos aut foedera iungi.<br>tu coniunx, tibi fas animum temptare precando.<br>perge, sequar.’ tum sic excepit regia Iuno:<br>‘mecum erit iste labor. nunc qua ratione quod instat   115<br>confieri possit, paucis (aduerte) docebo.<br>uenatum Aeneas unaque miserrima Dido<br>in nemus ire parant, ubi primos crastinus ortus<br>extulerit Titan radiisque retexerit orbem.<br>his ego nigrantem commixta grandine nimbum,   120<br>dum trepidant alae saltusque indagine cingunt,<br>desuper infundam et tonitru caelum omne ciebo.<br>diffugient comites et nocte tegentur opaca:<br>speluncam Dido dux et Troianus eandem<br>deuenient. adero et, tua si mihi certa uoluntas,   125<br>conubio iungam stabili propriamque dicabo.<br>hic hymenaeus erit.’ non aduersata petenti<br>adnuit atque dolis risit Cytherea repertis.","st":"4"},{"sp":"N","t":"Oceanum interea surgens Aurora reliquit.<br>it portis iubare exorto delecta iuuentus,   130<br>retia rara, plagae, lato uenabula ferro,<br>Massylique ruunt equites et odora canum uis.<br>reginam thalamo cunctantem ad limina primi<br>Poenorum exspectant, ostroque insignis et auro<br>stat sonipes ac frena ferox spumantia mandit.   135<br>tandem progreditur magna stipante caterua<br>Sidoniam picto chlamydem circumdata limbo;<br>cui pharetra ex auro, crines nodantur in aurum,<br>aurea purpuream subnectit fibula uestem.<br>nec non et Phrygii comites et laetus Iulus   140<br>incedunt. ipse ante alios pulcherrimus omnis<br>infert se socium Aeneas atque agmina iungit.<br>qualis ubi hibernam Lyciam Xanthique fluenta<br>deserit ac Delum maternam inuisit Apollo<br>instauratque choros, mixtique altaria circum   145<br>Cretesque Dryopesque fremunt pictique Agathyrsi;<br>ipse iugis Cynthi graditur mollique fluentem<br>fronde premit crinem fingens atque implicat auro,<br>tela sonant umeris: haud illo segnior ibat<br>Aeneas, tantum egregio decus enitet ore.    150<br>postquam altos uentum in montis atque inuia lustra,<br>ecce ferae saxi deiectae uertice caprae<br>decurrere iugis; alia de parte patentis<br>transmittunt cursu campos atque agmina cerui<br>puluerulenta fuga glomerant montisque relinquunt.   155<br>at puer Ascanius mediis in uallibus acri<br>gaudet equo iamque hos cursu, iam praeterit illos,<br>spumantemque dari pecora inter inertia uotis<br>optat aprum, aut fuluum descendere monte leonem.","st":"4"},{"sp":"N","t":"Interea magno misceri murmure caelum   160<br>incipit, insequitur commixta grandine nimbus,<br>et Tyrii comites passim et Troiana iuuentus<br>Dardaniusque nepos Veneris diuersa per agros<br>tecta metu petiere; ruunt de montibus amnes.<br>speluncam Dido dux et Troianus eandem   165<br>deueniunt. prima et Tellus et pronuba Iuno<br>dant signum; fulsere ignes et conscius aether<br>conubiis summoque ulularunt uertice Nymphae.<br>ille dies primus leti primusque malorum<br>causa fuit; neque enim specie famaue mouetur   170<br>nec iam furtiuum Dido meditatur amorem:<br>coniugium uocat, hoc praetexit nomine culpam.","st":"4"},{"sp":"N","t":"Extemplo Libyae magnas it Fama per urbes,<br>Fama, malum qua non aliud uelocius ullum:<br>mobilitate uiget uirisque adquirit eundo,   175<br>parua metu primo, mox sese attollit in auras<br>ingrediturque solo et caput inter nubila condit.<br>illam Terra parens ira inritata deorum<br>extremam, ut perhibent, Coeo Enceladoque sororem<br>progenuit pedibus celerem et pernicibus alis,   180<br>monstrum horrendum, ingens, cui quot sunt corpore plumae,<br>tot uigiles oculi subter (mirabile dictu),<br>tot linguae, totidem ora sonant, tot subrigit auris.<br>nocte uolat caeli medio terraeque per umbram<br>stridens, nec dulci declinat lumina somno;   185<br>luce sedet custos aut summi culmine tecti<br>turribus aut altis, et magnas territat urbes,<br>tam ficti prauique tenax quam nuntia ueri.<br>haec tum multiplici populos sermone replebat<br>gaudens, et pariter facta atque infecta canebat:   190<br>uenisse Aenean Troiano sanguine cretum,<br>cui se pulchra uiro dignetur iungere Dido;<br>nunc hiemem inter se luxu, quam longa, fouere<br>regnorum immemores turpique cupidine captos.<br>haec passim dea foeda uirum diffundit in ora.   195<br>protinus ad regem cursus detorquet Iarban<br>incenditque animum dictis atque aggerat iras.","st":"4"},{"sp":"N","t":"Hic Hammone satus rapta Garamantide nympha<br>templa Ioui centum latis immania regnis,<br>centum aras posuit uigilemque sacrauerat ignem,   200<br>excubias diuum aeternas, pecudumque cruore<br>pingue solum et uariis florentia limina sertis.<br>isque amens animi et rumore accensus amaro<br>dicitur ante aras media inter numina diuum<br>multa Iouem manibus supplex orasse supinis:   205<br>‘Iuppiter omnipotens, cui nunc Maurusia pictis<br>gens epulata toris Lenaeum libat honorem,<br>aspicis haec? an te, genitor, cum fulmina torques<br>nequiquam horremus, caecique in nubibus ignes<br>terrificant animos et inania murmura miscent?   210<br>femina, quae nostris errans in finibus urbem<br>exiguam pretio posuit, cui litus arandum<br>cuique loci leges dedimus, conubia nostra<br>reppulit ac dominum Aenean in regna recepit.<br>et nunc ille Paris cum semiuiro comitatu,    215<br>Maeonia mentum mitra crinemque madentem<br>subnexus, rapto potitur: nos munera templis<br>quippe tuis ferimus famamque fouemus inanem.’","st":"4"},{"sp":"N","t":"Talibus orantem dictis arasque tenentem<br>audiit Omnipotens, oculosque ad moenia torsit   220<br>regia et oblitos famae melioris amantis.<br>tum sic Mercurium adloquitur ac talia mandat:<br>‘uade age, nate, uoca Zephyros et labere pennis<br>Dardaniumque ducem, Tyria Karthagine qui nunc<br>exspectat fatisque datas non respicit urbes,   225<br>adloquere et celeris defer mea dicta per auras.<br>non illum nobis genetrix pulcherrima talem<br>promisit Graiumque ideo bis uindicat armis;<br>sed fore qui grauidam imperiis belloque frementem<br>Italiam regeret, genus alto a sanguine Teucri   230<br>proderet, ac totum sub leges mitteret orbem.<br>si nulla accendit tantarum gloria rerum<br>nec super ipse sua molitur laude laborem,<br>Ascanione pater Romanas inuidet arces?<br>quid struit? aut qua spe inimica in gente moratur   235<br>nec prolem Ausoniam et Lauinia respicit arua?<br>nauiget! haec summa est, hic nostri nuntius esto.’","st":"4"},{"sp":"N","t":"Dixerat. ille patris magni parere parabat<br>imperio; et primum pedibus talaria nectit<br>aurea, quae sublimem alis siue aequora supra   240<br>seu terram rapido pariter cum flamine portant.<br>tum uirgam capit: hac animas ille euocat Orco<br>pallentis, alias sub Tartara tristia mittit,<br>dat somnos adimitque, et lumina morte resignat.<br>illa fretus agit uentos et turbida tranat   245<br>nubila. iamque uolans apicem et latera ardua cernit<br>Atlantis duri caelum qui uertice fulcit,<br>Atlantis, cinctum adsidue cui nubibus atris<br>piniferum caput et uento pulsatur et imbri,<br>nix umeros infusa tegit, tum flumina mento   250<br>praecipitant senis, et glacie riget horrida barba.<br>hic primum paribus nitens Cyllenius alis<br>constitit; hinc toto praeceps se corpore ad undas<br>misit aui similis, quae circum litora, circum<br>piscosos scopulos humilis uolat aequora iuxta.   255<br>haud aliter terras inter caelumque uolabat<br>litus harenosum ad Libyae, uentosque secabat<br>materno ueniens ab auo Cyllenia proles.<br>ut primum alatis tetigit magalia plantis,<br>Aenean fundantem arces ac tecta nouantem   260<br>conspicit. atque illi stellatus iaspide fulua<br>ensis erat Tyrioque ardebat murice laena<br>demissa ex umeris, diues quae munera Dido<br>fecerat, et tenui telas discreuerat auro.<br>continuo inuadit: ‘tu nunc Karthaginis altae   265<br>fundamenta locas pulchramque uxorius urbem<br>exstruis? heu, regni rerumque oblite tuarum!<br>ipse deum tibi me claro demittit Olympo<br>regnator, caelum et terras qui numine torquet,<br>ipse haec ferre iubet celeris mandata per auras:   270<br>quid struis? aut qua spe Libycis teris otia terris?<br>si te nulla mouet tantarum gloria rerum<br>[nec super ipse tua moliris laude laborem,]<br>Ascanium surgentem et spes heredis Iuli<br>respice, cui regnum Italiae Romanaque tellus   275<br>debetur.’ tali Cyllenius ore locutus<br>mortalis uisus medio sermone reliquit<br>et procul in tenuem ex oculis euanuit auram.","st":"4"},{"sp":"N","t":"At uero Aeneas aspectu obmutuit amens,<br>arrectaeque horrore comae et uox faucibus haesit.   280<br>ardet abire fuga dulcisque relinquere terras,<br>attonitus tanto monitu imperioque deorum.<br>heu quid agat? quo nunc reginam ambire furentem<br>audeat adfatu? quae prima exordia sumat?<br>atque animum nunc huc celerem nunc diuidit illuc   285<br>in partisque rapit uarias perque omnia uersat.<br>haec alternanti potior sententia uisa est:<br>Mnesthea Sergestumque uocat fortemque Serestum,<br>classem aptent taciti sociosque ad litora cogant,<br>arma parent et quae rebus sit causa nouandis   290<br>dissimulent; sese interea, quando optima Dido<br>nesciat et tantos rumpi non speret amores,<br>temptaturum aditus et quae mollissima fandi<br>tempora, quis rebus dexter modus. ocius omnes<br>imperio laeti parent et iussa facessunt.   295","st":"4"},{"sp":"N","t":"At regina dolos (quis fallere possit amantem?)<br>praesensit, motusque excepit prima futuros<br>omnia tuta timens. eadem impia Fama furenti<br>detulit armari classem cursumque parari.<br>saeuit inops animi totamque incensa per urbem   300<br>bacchatur, qualis commotis excita sacris<br>Thyias, ubi audito stimulant trieterica Baccho<br>orgia nocturnusque uocat clamore Cithaeron.<br>tandem his Aenean compellat uocibus ultro:<br>‘dissimulare etiam sperasti, perfide, tantum   305<br>posse nefas tacitusque mea decedere terra?<br>nec te noster amor nec te data dextera quondam<br>nec moritura tenet crudeli funere Dido?<br>quin etiam hiberno moliri sidere classem<br>et mediis properas Aquilonibus ire per altum,   310<br>crudelis? quid, si non arua aliena domosque<br>ignotas peteres, et Troia antiqua maneret,<br>Troia per undosum peteretur classibus aequor?<br>mene fugis? per ego has lacrimas dextramque tuam te<br>(quando aliud mihi iam miserae nihil ipsa reliqui),   315<br>per conubia nostra, per inceptos hymenaeos,<br>si bene quid de te merui, fuit aut tibi quicquam<br>dulce meum, miserere domus labentis et istam,<br>oro, si quis adhuc precibus locus, exue mentem.<br>te propter Libycae gentes Nomadumque tyranni   320<br>odere, infensi Tyrii; te propter eundem<br>exstinctus pudor et, qua sola sidera adibam,<br>fama prior. cui me moribundam deseris hospes<br>(hoc solum nomen quoniam de coniuge restat)?<br>quid moror? an mea Pygmalion dum moenia frater   325<br>destruat aut captam ducat Gaetulus Iarbas?<br>saltem si qua mihi de te suscepta fuisset<br>ante fugam suboles, si quis mihi paruulus aula<br>luderet Aeneas, qui te tamen ore referret,<br>non equidem omnino capta ac deserta uiderer.’   330","st":"4"},{"sp":"N","t":"Dixerat. ille Iouis monitis immota tenebat<br>lumina et obnixus curam sub corde premebat.<br>tandem pauca refert: ‘ego te, quae plurima fando<br>enumerare uales, numquam, regina, negabo<br>promeritam, nec me meminisse pigebit Elissae   335<br>dum memor ipse mei, dum spiritus hos regit artus.<br>pro re pauca loquar. neque ego hanc abscondere furto<br>speraui (ne finge) fugam, nec coniugis umquam<br>praetendi taedas aut haec in foedera ueni.<br>me si fata meis paterentur ducere uitam   340<br>auspiciis et sponte mea componere curas,<br>urbem Troianam primum dulcisque meorum<br>reliquias colerem, Priami tecta alta manerent,<br>et recidiua manu posuissem Pergama uictis.<br>sed nunc Italiam magnam Gryneus Apollo,   345<br>Italiam Lyciae iussere capessere sortes;<br>hic amor, haec patria est. si te Karthaginis arces<br>Phoenissam Libycaeque aspectus detinet urbis,<br>quae tandem Ausonia Teucros considere terra<br>inuidia est? et nos fas extera quaerere regna.   350<br>me patris Anchisae, quotiens umentibus umbris<br>nox operit terras, quotiens astra ignea surgunt,<br>admonet in somnis et turbida terret imago;<br>me puer Ascanius capitisque iniuria cari,<br>quem regno Hesperiae fraudo et fatalibus aruis.   355<br>nunc etiam interpres diuum Ioue missus ab ipso<br>(testor utrumque caput) celeris mandata per auras<br>detulit: ipse deum manifesto in lumine uidi<br>intrantem muros uocemque his auribus hausi.<br>desine meque tuis incendere teque querelis;   360<br>Italiam non sponte sequor.’","st":"4"},{"sp":"N","t":"Talia dicentem iamdudum auersa tuetur<br>huc illuc uoluens oculos totumque pererrat<br>luminibus tacitis et sic accensa profatur:<br>‘nec tibi diua parens generis nec Dardanus auctor,   365<br>perfide, sed duris genuit te cautibus horrens<br>Caucasus Hyrcanaeque admorunt ubera tigres.<br>nam quid dissimulo aut quae me ad maiora reseruo?<br>num fletu ingemuit nostro? num lumina flexit?<br>num lacrimas uictus dedit aut miseratus amantem est?   370<br>quae quibus anteferam? iam iam nec maxima Iuno<br>nec Saturnius haec oculis pater aspicit aequis.<br>nusquam tuta fides. eiectum litore, egentem<br>excepi et regni demens in parte locaui.<br>amissam classem, socios a morte reduxi   375<br>(heu furiis incensa feror!): nunc augur Apollo,<br>nunc Lyciae sortes, nunc et Ioue missus ab ipso<br>interpres diuum fert horrida iussa per auras.<br>scilicet is superis labor est, ea cura quietos<br>sollicitat. neque te teneo neque dicta refello:   380<br>i, sequere Italiam uentis, pete regna per undas.<br>spero equidem mediis, si quid pia numina possunt,<br>supplicia hausurum scopulis et nomine Dido<br>saepe uocaturum. sequar atris ignibus absens<br>et, cum frigida mors anima seduxerit artus,   385<br>omnibus umbra locis adero. dabis, improbe, poenas.<br>audiam et haec Manis ueniet mihi fama sub imos.’<br>his medium dictis sermonem abrumpit et auras<br>aegra fugit seque ex oculis auertit et aufert,<br>linquens multa metu cunctantem et multa parantem   390<br>dicere. suscipiunt famulae conlapsaque membra<br>marmoreo referunt thalamo stratisque reponunt.","st":"4"},{"sp":"N","t":"At pius Aeneas, quamquam lenire dolentem<br>solando cupit et dictis auertere curas,<br>multa gemens magnoque animum labefactus amore   395<br>iussa tamen diuum exsequitur classemque reuisit.<br>tum uero Teucri incumbunt et litore celsas<br>deducunt toto nauis. natat uncta carina,<br>frondentisque ferunt remos et robora siluis<br>infabricata fugae studio.   400<br>migrantis cernas totaque ex urbe ruentis:<br>ac uelut ingentem formicae farris aceruum<br>cum populant hiemis memores tectoque reponunt,<br>it nigrum campis agmen praedamque per herbas<br>conuectant calle angusto; pars grandia trudunt   405<br>obnixae frumenta umeris, pars agmina cogunt<br>castigantque moras, opere omnis semita feruet.<br>quis tibi tum, Dido, cernenti talia sensus,<br>quosue dabas gemitus, cum litora feruere late<br>prospiceres arce ex summa, totumque uideres   410<br>misceri ante oculos tantis clamoribus aequor!<br>improbe Amor, quid non mortalia pectora cogis!<br>ire iterum in lacrimas, iterum temptare precando<br>cogitur et supplex animos summittere amori,<br>ne quid inexpertum frustra moritura relinquat.   415","st":"4"},{"sp":"N","t":"‘Anna, uides toto properari litore circum:<br>undique conuenere; uocat iam carbasus auras,<br>puppibus et laeti nautae imposuere coronas.<br>hunc ego si potui tantum sperare dolorem,<br>et perferre, soror, potero. miserae hoc tamen unum   420<br>exsequere, Anna, mihi; solam nam perfidus ille<br>te colere, arcanos etiam tibi credere sensus;<br>sola uiri mollis aditus et tempora noras.<br>i, soror, atque hostem supplex adfare superbum:<br>non ego cum Danais Troianam exscindere gentem   425<br>Aulide iuraui classemue ad Pergama misi,<br>nec patris Anchisae cinerem manisue reuelli:<br>cur mea dicta negat duras demittere in auris?<br>quo ruit? extremum hoc miserae det munus amanti:<br>exspectet facilemque fugam uentosque ferentis.   430<br>non iam coniugium antiquum, quod prodidit, oro,<br>nec pulchro ut Latio careat regnumque relinquat:<br>tempus inane peto, requiem spatiumque furori,<br>dum mea me uictam doceat fortuna dolere.<br>extremam hanc oro ueniam (miserere sororis),   435<br>quam mihi cum dederit cumulatam morte remittam.’","st":"4"},{"sp":"N","t":"Talibus orabat, talisque miserrima fletus<br>fertque refertque soror. sed nullis ille mouetur<br>fletibus aut uoces ullas tractabilis audit;<br>fata obstant placidasque uiri deus obstruit auris.   440<br>ac uelut annoso ualidam cum robore quercum<br>Alpini Boreae nunc hinc nunc flatibus illinc<br>eruere inter se certant; it stridor, et altae<br>consternunt terram concusso stipite frondes;<br>ipsa haeret scopulis et quantum uertice ad auras   445<br>aetherias, tantum radice in Tartara tendit:<br>haud secus adsiduis hinc atque hinc uocibus heros<br>tunditur, et magno persentit pectore curas;<br>mens immota manet, lacrimae uoluuntur inanes.","st":"4"},{"sp":"N","t":"Tum uero infelix fatis exterrita Dido   450<br>mortem orat; taedet caeli conuexa tueri.<br>quo magis inceptum peragat lucemque relinquat,<br>uidit, turicremis cum dona imponeret aris,<br>(horrendum dictu) latices nigrescere sacros<br>fusaque in obscenum se uertere uina cruorem;   455<br>hoc uisum nulli, non ipsi effata sorori.<br>praeterea fuit in tectis de marmore templum<br>coniugis antiqui, miro quod honore colebat,<br>uelleribus niueis et festa fronde reuinctum:<br>hinc exaudiri uoces et uerba uocantis   460<br>uisa uiri, nox cum terras obscura teneret,<br>solaque culminibus ferali carmine bubo<br>saepe queri et longas in fletum ducere uoces;<br>multaque praeterea uatum praedicta priorum<br>terribili monitu horrificant. agit ipse furentem   465<br>in somnis ferus Aeneas, semperque relinqui<br>sola sibi, semper longam incomitata uidetur<br>ire uiam et Tyrios deserta quaerere terra,<br>Eumenidum ueluti demens uidet agmina Pentheus<br>et solem geminum et duplices se ostendere Thebas,   470<br>aut Agamemnonius scaenis agitatus Orestes,<br>armatam facibus matrem et serpentibus atris<br>cum fugit ultricesque sedent in limine Dirae.","st":"4"},{"sp":"N","t":"Ergo ubi concepit furias euicta dolore<br>decreuitque mori, tempus secum ipsa modumque   475<br>exigit, et maestam dictis adgressa sororem<br>consilium uultu tegit ac spem fronte serenat:<br>‘inueni, germana, uiam (gratare sorori)<br>quae mihi reddat eum uel eo me soluat amantem.<br>Oceani finem iuxta solemque cadentem   480<br>ultimus Aethiopum locus est, ubi maximus Atlas<br>axem umero torquet stellis ardentibus aptum:<br>hinc mihi Massylae gentis monstrata sacerdos,<br>Hesperidum templi custos, epulasque draconi<br>quae dabat et sacros seruabat in arbore ramos,   485<br>spargens umida mella soporiferumque papauer.<br>haec se carminibus promittit soluere mentes<br>quas uelit, ast aliis duras immittere curas,<br>sistere aquam fluuiis et uertere sidera retro,<br>nocturnosque mouet Manis: mugire uidebis   490<br>sub pedibus terram et descendere montibus ornos.<br>testor, cara, deos et te, germana, tuumque<br>dulce caput, magicas inuitam accingier artis.<br>tu secreta pyram tecto interiore sub auras<br>erige, et arma uiri thalamo quae fixa reliquit   495<br>impius exuuiasque omnis lectumque iugalem,<br>quo perii, super imponas: abolere nefandi<br>cuncta uiri monimenta iuuat monstratque sacerdos.’<br>haec effata silet, pallor simul occupat ora.<br>non tamen Anna nouis praetexere funera sacris   500<br>germanam credit, nec tantos mente furores<br>concipit aut grauiora timet quam morte Sychaei.<br>ergo iussa parat.","st":"4"},{"sp":"N","t":"At regina, pyra penetrali in sede sub auras<br>erecta ingenti taedis atque ilice secta,   505<br>intenditque locum sertis et fronde coronat<br>funerea; super exuuias ensemque relictum<br>effigiemque toro locat haud ignara futuri.<br>stant arae circum et crinis effusa sacerdos<br>ter centum tonat ore deos, Erebumque Chaosque   510<br>tergeminamque Hecaten, tria uirginis ora Dianae.<br>sparserat et latices simulatos fontis Auerni,<br>falcibus et messae ad lunam quaeruntur aenis<br>pubentes herbae nigri cum lacte ueneni;<br>quaeritur et nascentis equi de fronte reuulsus   515<br>et matri praereptus amor.<br>ipsa mola manibusque piis altaria iuxta<br>unum exuta pedem uinclis, in ueste recincta,<br>testatur moritura deos et conscia fati<br>sidera; tum, si quod non aequo foedere amantis   520<br>curae numen habet iustumque memorque, precatur.","st":"4"},{"sp":"N","t":"Nox erat et placidum carpebant fessa soporem<br>corpora per terras, siluaeque et saeua quierant<br>aequora, cum medio uoluuntur sidera lapsu,<br>cum tacet omnis ager, pecudes pictaeque uolucres,   525<br>quaeque lacus late liquidos quaeque aspera dumis<br>rura tenent, somno positae sub nocte silenti.<br>at non infelix animi Phoenissa, neque umquam   529<br>soluitur in somnos oculisue aut pectore noctem<br>accipit: ingeminant curae rursusque resurgens<br>saeuit amor magnoque irarum fluctuat aestu.<br>sic adeo insistit secumque ita corde uolutat:<br>‘en, quid ago? rursusne procos inrisa priores<br>experiar, Nomadumque petam conubia supplex,   535<br>quos ego sim totiens iam dedignata maritos?<br>Iliacas igitur classis atque ultima Teucrum<br>iussa sequar? quiane auxilio iuuat ante leuatos<br>et bene apud memores ueteris stat gratia facti?<br>quis me autem, fac uelle, sinet ratibusue superbis   540<br>inuisam accipiet? nescis heu, perdita, necdum<br>Laomedonteae sentis periuria gentis?<br>quid tum? sola fuga nautas comitabor ouantis?<br>an Tyriis omnique manu stipata meorum<br>inferar et, quos Sidonia uix urbe reuelli,   545<br>rursus agam pelago et uentis dare uela iubebo?<br>quin morere ut merita es, ferroque auerte dolorem.<br>tu lacrimis euicta meis, tu prima furentem<br>his, germana, malis oneras atque obicis hosti.<br>non licuit thalami expertem sine crimine uitam   550<br>degere more ferae, talis nec tangere curas;<br>non seruata fides cineri promissa Sychaeo.’","st":"4"},{"sp":"N","t":"Tantos illa suo rumpebat pectore questus:<br>Aeneas celsa in puppi iam certus eundi<br>carpebat somnos rebus iam rite paratis.   555<br>huic se forma dei uultu redeuntis eodem<br>obtulit in somnis rursusque ita uisa monere est,<br>omnia Mercurio similis, uocemque coloremque<br>et crinis flauos et membra decora iuuenta:<br>‘nate dea, potes hoc sub casu ducere somnos,   560<br>nec quae te circum stent deinde pericula cernis,<br>demens, nec Zephyros audis spirare secundos?<br>illa dolos dirumque nefas in pectore uersat<br>certa mori, uariosque irarum concitat aestus.<br>non fugis hinc praeceps, dum praecipitare potestas?   565<br>iam mare turbari trabibus saeuasque uidebis<br>conlucere faces, iam feruere litora flammis,<br>si te his attigerit terris Aurora morantem.<br>heia age, rumpe moras. uarium et mutabile semper<br>femina.’ sic fatus nocti se immiscuit atrae.   570","st":"4"},{"sp":"N","t":"Tum uero Aeneas subitis exterritus umbris<br>corripit e somno corpus sociosque fatigat<br>praecipitis: ‘uigilate, uiri, et considite transtris;<br>soluite uela citi. deus aethere missus ab alto<br>festinare fugam tortosque incidere funis   575<br>ecce iterum instimulat. sequimur te, sancte deorum,<br>quisquis es, imperioque iterum paremus ouantes.<br>adsis o placidusque iuues et sidera caelo<br>dextra feras.’ dixit uaginaque eripit ensem<br>fulmineum strictoque ferit retinacula ferro.   580<br>idem omnis simul ardor habet, rapiuntque ruuntque;<br>litora deseruere, latet sub classibus aequor,<br>adnixi torquent spumas et caerula uerrunt.","st":"4"},{"sp":"N","t":"Et iam prima nouo spargebat lumine terras<br>Tithoni croceum linquens Aurora cubile.   585<br>regina e speculis ut primam albescere lucem<br>uidit et aequatis classem procedere uelis,<br>litoraque et uacuos sensit sine remige portus,<br>terque quaterque manu pectus percussa decorum<br>flauentisque abscissa comas ‘pro Iuppiter! ibit   590<br>hic,’ ait ‘et nostris inluserit aduena regnis?<br>non arma expedient totaque ex urbe sequentur,<br>diripientque rates alii naualibus? ite,<br>ferte citi flammas, date tela, impellite remos!<br>quid loquor? aut ubi sum? quae mentem insania mutat?    595<br>infelix Dido, nunc te facta impia tangunt?<br>tum decuit, cum sceptra dabas. en dextra fidesque,<br>quem secum patrios aiunt portare penatis,<br>quem subiisse umeris confectum aetate parentem!<br>non potui abreptum diuellere corpus et undis   600<br>spargere? non socios, non ipsum absumere ferro<br>Ascanium patriisque epulandum ponere mensis?<br>uerum anceps pugnae fuerat fortuna. fuisset:<br>quem metui moritura? faces in castra tulissem<br>implessemque foros flammis natumque patremque   605<br>cum genere exstinxem, memet super ipsa dedissem.<br>Sol, qui terrarum flammis opera omnia lustras,<br>tuque harum interpres curarum et conscia Iuno,<br>nocturnisque Hecate triuiis ululata per urbes<br>et Dirae ultrices et di morientis Elissae,   610<br>accipite haec, meritumque malis aduertite numen<br>et nostras audite preces. si tangere portus<br>infandum caput ac terris adnare necesse est,<br>et sic fata Iouis poscunt, hic terminus haeret,<br>at bello audacis populi uexatus et armis,   615<br>finibus extorris, complexu auulsus Iuli<br>auxilium imploret uideatque indigna suorum<br>funera; nec, cum se sub leges pacis iniquae<br>tradiderit, regno aut optata luce fruatur,<br>sed cadat ante diem mediaque inhumatus harena.   620<br>haec precor, hanc uocem extremam cum sanguine fundo.<br>tum uos, o Tyrii, stirpem et genus omne futurum<br>exercete odiis, cinerique haec mittite nostro<br>munera. nullus amor populis nec foedera sunto.<br>exoriare aliquis nostris ex ossibus ultor   625<br>qui face Dardanios ferroque sequare colonos,<br>nunc, olim, quocumque dabunt se tempore uires.<br>litora litoribus contraria, fluctibus undas<br>imprecor, arma armis: pugnent ipsique nepotesque.’","st":"4"},{"sp":"N","t":"Haec ait, et partis animum uersabat in omnis,   630<br>inuisam quaerens quam primum abrumpere lucem.<br>tum breuiter Barcen nutricem adfata Sychaei,<br>namque suam patria antiqua cinis ater habebat:<br>‘Annam, cara mihi nutrix, huc siste sororem:<br>dic corpus properet fluuiali spargere lympha,   635<br>et pecudes secum et monstrata piacula ducat.<br>sic ueniat, tuque ipsa pia tege tempora uitta.<br>sacra Ioui Stygio, quae rite incepta paraui,<br>perficere est animus finemque imponere curis<br>Dardaniique rogum capitis permittere flammae.’   640<br>sic ait. illa gradum studio celebrabat anili.<br>at trepida et coeptis immanibus effera Dido<br>sanguineam uoluens aciem, maculisque trementis<br>interfusa genas et pallida morte futura,<br>interiora domus inrumpit limina et altos   645<br>conscendit furibunda rogos ensemque recludit<br>Dardanium, non hos quaesitum munus in usus.<br>hic, postquam Iliacas uestis notumque cubile<br>conspexit, paulum lacrimis et mente morata<br>incubuitque toro dixitque nouissima uerba:   650<br>‘dulces exuuiae, dum fata deusque sinebat,<br>accipite hanc animam meque his exsoluite curis.<br>uixi et quem dederat cursum Fortuna peregi,<br>et nunc magna mei sub terras ibit imago.<br>urbem praeclaram statui, mea moenia uidi,   655<br>ulta uirum poenas inimico a fratre recepi,<br>felix, heu nimium felix, si litora tantum<br>numquam Dardaniae tetigissent nostra carinae.’<br>dixit, et os impressa toro ‘moriemur inultae,<br>sed moriamur’ ait. ‘sic, sic iuuat ire sub umbras.   660<br>hauriat hunc oculis ignem crudelis ab alto<br>Dardanus, et nostrae secum ferat omina mortis.’<br>dixerat, atque illam media inter talia ferro<br>conlapsam aspiciunt comites, ensemque cruore<br>spumantem sparsasque manus. it clamor ad alta   665<br>atria: concussam bacchatur Fama per urbem.<br>lamentis gemituque et femineo ululatu<br>tecta fremunt, resonat magnis plangoribus aether,<br>non aliter quam si immissis ruat hostibus omnis<br>Karthago aut antiqua Tyros, flammaeque furentes   670<br>culmina perque hominum uoluantur perque deorum.<br>audiit exanimis trepidoque exterrita cursu<br>unguibus ora soror foedans et pectora pugnis<br>per medios ruit, ac morientem nomine clamat:<br>‘hoc illud, germana, fuit? me fraude petebas?   675<br>hoc rogus iste mihi, hoc ignes araeque parabant?<br>quid primum deserta querar? comitemne sororem<br>spreuisti moriens? eadem me ad fata uocasses,<br>idem ambas ferro dolor atque eadem hora tulisset.<br>his etiam struxi manibus patriosque uocaui   680<br>uoce deos, sic te ut posita, crudelis, abessem?<br>exstinxti te meque, soror, populumque patresque<br>Sidonios urbemque tuam. date, uulnera lymphis<br>abluam et, extremus si quis super halitus errat,<br>ore legam.’ sic fata gradus euaserat altos,   685<br>semianimemque sinu germanam amplexa fouebat<br>cum gemitu atque atros siccabat ueste cruores.<br>illa grauis oculos conata attollere rursus<br>deficit; infixum stridit sub pectore uulnus.<br>ter sese attollens cubitoque adnixa leuauit,   690<br>ter reuoluta toro est oculisque errantibus alto<br>quaesiuit caelo lucem ingemuitque reperta.","st":"4"},{"sp":"N","t":"Tum Iuno omnipotens longum miserata dolorem<br>difficilisque obitus Irim demisit Olympo<br>quae luctantem animam nexosque resolueret artus.   695<br>nam quia nec fato merita nec morte peribat,<br>sed misera ante diem subitoque accensa furore,<br>nondum illi flauum Proserpina uertice crinem<br>abstulerat Stygioque caput damnauerat Orco.<br>ergo Iris croceis per caelum roscida pennis   700<br>mille trahens uarios aduerso sole colores<br>deuolat et supra caput astitit. ‘hunc ego Diti<br>sacrum iussa fero teque isto corpore soluo’:<br>sic ait et dextra crinem secat, omnis et una<br>dilapsus calor atque in uentos uita recessit.","st":"4"},{"sp":"HDR","t":"Liber V","st":"5"},{"sp":"N","t":"Interea medium Aeneas iam classe tenebat<br>certus iter fluctusque atros Aquilone secabat<br>moenia respiciens, quae iam infelicis Elissae<br>conlucent flammis. quae tantum accenderit ignem<br>causa latet; duri magno sed amore dolores   5<br>polluto, notumque furens quid femina possit,<br>triste per augurium Teucrorum pectora ducunt.<br>ut pelagus tenuere rates nec iam amplius ulla<br>occurrit tellus, maria undique et undique caelum,<br>olli caeruleus supra caput astitit imber   10<br>noctem hiememque ferens et inhorruit unda tenebris.<br>ipse gubernator puppi Palinurus ab alta:<br>‘heu quianam tanti cinxerunt aethera nimbi?<br>quidue, pater Neptune, paras?’ sic deinde locutus<br>colligere arma iubet ualidisque incumbere remis,   15<br>obliquatque sinus in uentum ac talia fatur:<br>‘magnanime Aenea, non, si mihi Iuppiter auctor<br>spondeat, hoc sperem Italiam contingere caelo.<br>mutati transuersa fremunt et uespere ab atro<br>consurgunt uenti, atque in nubem cogitur aer.   20<br>nec nos obniti contra nec tendere tantum<br>sufficimus. superat quoniam Fortuna, sequamur,<br>quoque uocat uertamus iter. nec litora longe<br>fida reor fraterna Erycis portusque Sicanos,<br>si modo rite memor seruata remetior astra.’   25<br>tum pius Aeneas: ‘equidem sic poscere uentos<br>iamdudum et frustra cerno te tendere contra.<br>flecte uiam uelis. an sit mihi gratior ulla,<br>quoue magis fessas optem dimittere nauis,<br>quam quae Dardanium tellus mihi seruat Acesten   30<br>et patris Anchisae gremio complectitur ossa?’<br>haec ubi dicta, petunt portus et uela secundi<br>intendunt Zephyri; fertur cita gurgite classis,<br>et tandem laeti notae aduertuntur harenae.","st":"5"},{"sp":"N","t":"At procul ex celso miratus uertice montis   35<br>aduentum sociasque rates occurrit Acestes,<br>horridus in iaculis et pelle Libystidis ursae,<br>Troia Criniso conceptum flumine mater<br>quem genuit. ueterum non immemor ille parentum<br>gratatur reduces et gaza laetus agresti   40<br>excipit, ac fessos opibus solatur amicis.","st":"5"},{"sp":"N","t":"Postera cum primo stellas Oriente fugarat<br>clara dies, socios in coetum litore ab omni<br>aduocat Aeneas tumulique ex aggere fatur:<br>‘Dardanidae magni, genus alto a sanguine diuum,   45<br>annuus exactis completur mensibus orbis,<br>ex quo reliquias diuinique ossa parentis<br>condidimus terra maestasque sacrauimus aras;<br>iamque dies, nisi fallor, adest, quem semper acerbum,<br>semper honoratum (sic di uoluistis) habebo.   50<br>hunc ego Gaetulis agerem si Syrtibus exsul,<br>Argolicoue mari deprensus et urbe Mycenae,<br>annua uota tamen sollemnisque ordine pompas<br>exsequerer strueremque suis altaria donis.<br>nunc ultro ad cineres ipsius et ossa parentis   55<br>haud equidem sine mente, reor, sine numine diuum<br>adsumus et portus delati intramus amicos.<br>ergo agite et laetum cuncti celebremus honorem:<br>poscamus uentos, atque haec me sacra quotannis<br>urbe uelit posita templis sibi ferre dicatis.   60<br>bina boum uobis Troia generatus Acestes<br>dat numero capita in nauis; adhibete penatis<br>et patrios epulis et quos colit hospes Acestes.<br>praeterea, si nona diem mortalibus almum<br>Aurora extulerit radiisque retexerit orbem,   65<br>prima citae Teucris ponam certamina classis;<br>quique pedum cursu ualet, et qui uiribus audax<br>aut iaculo incedit melior leuibusque sagittis,<br>seu crudo fidit pugnam committere caestu,<br>cuncti adsint meritaeque exspectent praemia palmae.   70<br>ore fauete omnes et cingite tempora ramis.’","st":"5"},{"sp":"N","t":"Sic fatus uelat materna tempora myrto.<br>hoc Helymus facit, hoc aeui maturus Acestes,<br>hoc puer Ascanius, sequitur quos cetera pubes.<br>ille e concilio multis cum milibus ibat   75<br>ad tumulum magna medius comitante caterua.<br>hic duo rite mero libans carchesia Baccho<br>fundit humi, duo lacte nouo, duo sanguine sacro,<br>purpureosque iacit flores ac talia fatur:<br>‘salue, sancte parens, iterum; saluete, recepti   80<br>nequiquam cineres animaeque umbraeque paternae.<br>non licuit finis Italos fataliaque arua<br>nec tecum Ausonium, quicumque est, quaerere Thybrim.’<br>dixerat haec, adytis cum lubricus anguis ab imis<br>septem ingens gyros, septena uolumina traxit   85<br>amplexus placide tumulum lapsusque per aras,<br>caeruleae cui terga notae maculosus et auro<br>squamam incendebat fulgor, ceu nubibus arcus<br>mille iacit uarios aduerso sole colores.<br>obstipuit uisu Aeneas. ille agmine longo   90<br>tandem inter pateras et leuia pocula serpens<br>libauitque dapes rursusque innoxius imo<br>successit tumulo et depasta altaria liquit.<br>hoc magis inceptos genitori instaurat honores,<br>incertus geniumne loci famulumne parentis   95<br>esse putet; caedit binas de more bidentis<br>totque sues, totidem nigrantis terga iuuencos,<br>uinaque fundebat pateris animamque uocabat<br>Anchisae magni manisque Acheronte remissos.<br>nec non et socii, quae cuique est copia, laeti   100<br>dona ferunt, onerant aras mactantque iuuencos;<br>ordine aena locant alii fusique per herbam<br>subiciunt ueribus prunas et uiscera torrent.","st":"5"},{"sp":"N","t":"Exspectata dies aderat nonamque serena<br>Auroram Phaethontis equi iam luce uehebant,   105<br>famaque finitimos et clari nomen Acestae<br>excierat; laeto complerant litora coetu<br>uisuri Aeneadas, pars et certare parati.<br>munera principio ante oculos circoque locantur<br>in medio, sacri tripodes uiridesque coronae   110<br>et palmae pretium uictoribus, armaque et ostro<br>perfusae uestes, argenti aurique talenta;<br>et tuba commissos medio canit aggere ludos.","st":"5"},{"sp":"N","t":"Prima pares ineunt grauibus certamina remis<br>quattuor ex omni delectae classe carinae.   115<br>uelocem Mnestheus agit acri remige Pristim,<br>mox Italus Mnestheus, genus a quo nomine Memmi,<br>ingentemque Gyas ingenti mole Chimaeram,<br>urbis opus, triplici pubes quam Dardana uersu<br>impellunt, terno consurgunt ordine remi;   120<br>Sergestusque, domus tenet a quo Sergia nomen,<br>Centauro inuehitur magna, Scyllaque Cloanthus<br>caerulea, genus unde tibi, Romane Cluenti.","st":"5"},{"sp":"N","t":"Est procul in pelago saxum spumantia contra<br>litora, quod tumidis summersum tunditur olim   125<br>fluctibus, hiberni condunt ubi sidera Cauri;<br>tranquillo silet immotaque attollitur unda<br>campus et apricis statio gratissima mergis.<br>hic uiridem Aeneas frondenti ex ilice metam<br>constituit signum nautis pater, unde reuerti   130<br>scirent et longos ubi circumflectere cursus.<br>tum loca sorte legunt ipsique in puppibus auro<br>ductores longe effulgent ostroque decori;<br>cetera populea uelatur fronde iuuentus<br>nudatosque umeros oleo perfusa nitescit.   135<br>considunt transtris, intentaque bracchia remis;<br>intenti exspectant signum, exsultantiaque haurit<br>corda pauor pulsans laudumque arrecta cupido.<br>inde ubi clara dedit sonitum tuba, finibus omnes,<br>haud mora, prosiluere suis; ferit aethera clamor   140<br>nauticus, adductis spumant freta uersa lacertis.<br>infindunt pariter sulcos, totumque dehiscit<br>conuulsum remis rostrisque tridentibus aequor.<br>non tam praecipites biiugo certamine campum<br>corripuere ruuntque effusi carcere currus,   145<br>nec sic immissis aurigae undantia lora<br>concussere iugis pronique in uerbera pendent.<br>tum plausu fremituque uirum studiisque fauentum<br>consonat omne nemus, uocemque inclusa uolutant<br>litora, pulsati colles clamore resultant.   150","st":"5"},{"sp":"N","t":"Effugit ante alios primisque elabitur undis<br>turbam inter fremitumque Gyas; quem deinde Cloanthus<br>consequitur, melior remis, sed pondere pinus<br>tarda tenet. post hos aequo discrimine Pristis<br>Centaurusque locum tendunt superare priorem;   155<br>et nunc Pristis habet, nunc uictam praeterit ingens<br>Centaurus, nunc una ambae iunctisque feruntur<br>frontibus et longa sulcant uada salsa carina.<br>iamque propinquabant scopulo metamque tenebant,<br>cum princeps medioque Gyas in gurgite uictor   160<br>rectorem nauis compellat uoce Menoeten:<br>‘quo tantum mihi dexter abis? huc derige cursum;<br>litus ama et laeua stringat sine palmula cautes;<br>altum alii teneant.’ dixit; sed caeca Menoetes<br>saxa timens proram pelagi detorquet ad undas.   165<br>‘quo diuersus abis?’ iterum ‘pete saxa, Menoete!’<br>cum clamore Gyas reuocabat, et ecce Cloanthum<br>respicit instantem tergo et propiora tenentem.<br>ille inter nauemque Gyae scopulosque sonantis<br>radit iter laeuum interior subitoque priorem   170<br>praeterit et metis tenet aequora tuta relictis.<br>tum uero exarsit iuueni dolor ossibus ingens<br>nec lacrimis caruere genae, segnemque Menoeten<br>oblitus decorisque sui sociumque salutis<br>in mare praecipitem puppi deturbat ab alta;   175<br>ipse gubernaclo rector subit, ipse magister<br>hortaturque uiros clauumque ad litora torquet.<br>at grauis ut fundo uix tandem redditus imo est<br>iam senior madidaque fluens in ueste Menoetes<br>summa petit scopuli siccaque in rupe resedit.   180<br>illum et labentem Teucri et risere natantem<br>et salsos rident reuomentem pectore fluctus.","st":"5"},{"sp":"N","t":"Hic laeta extremis spes est accensa duobus,<br>Sergesto Mnestheique, Gyan superare morantem.<br>Sergestus capit ante locum scopuloque propinquat,   185<br>nec tota tamen ille prior praeeunte carina;<br>parte prior, partim rostro premit aemula Pristis.<br>at media socios incedens naue per ipsos<br>hortatur Mnestheus: ‘nunc, nunc insurgite remis,<br>Hectorei socii, Troiae quos sorte suprema   190<br>delegi comites; nunc illas promite uiris,<br>nunc animos, quibus in Gaetulis Syrtibus usi<br>Ionioque mari Maleaeque sequacibus undis.<br>non iam prima peto Mnestheus neque uincere certo<br>(quamquam o! — sed superent quibus hoc, Neptune, dedisti);   195<br>extremos pudeat rediisse: hoc uincite, ciues,<br>et prohibete nefas.’ olli certamine summo<br>procumbunt: uastis tremit ictibus aerea puppis<br>subtrahiturque solum, tum creber anhelitus artus<br>aridaque ora quatit, sudor fluit undique riuis.   200<br>attulit ipse uiris optatum casus honorem:<br>namque furens animi dum proram ad saxa suburget<br>interior spatioque subit Sergestus iniquo,<br>infelix saxis in procurrentibus haesit.<br>concussae cautes et acuto in murice remi   205<br>obnixi crepuere inlisaque prora pependit.<br>consurgunt nautae et magno clamore morantur<br>ferratasque trudes et acuta cuspide contos<br>expediunt fractosque legunt in gurgite remos.<br>at laetus Mnestheus successuque acrior ipso   210<br>agmine remorum celeri uentisque uocatis<br>prona petit maria et pelago decurrit aperto.<br>qualis spelunca subito commota columba,<br>cui domus et dulces latebroso in pumice nidi,<br>fertur in arua uolans plausumque exterrita pennis   215<br>dat tecto ingentem, mox aere lapsa quieto<br>radit iter liquidum celeris neque commouet alas:<br>sic Mnestheus, sic ipsa fuga secat ultima Pristis<br>aequora, sic illam fert impetus ipse uolantem.<br>et primum in scopulo luctantem deserit alto    220<br>Sergestum breuibusque uadis frustraque uocantem<br>auxilia et fractis discentem currere remis.<br>inde Gyan ipsamque ingenti mole Chimaeram<br>consequitur; cedit, quoniam spoliata magistro est.<br>solus iamque ipso superest in fine Cloanthus,   225<br>quem petit et summis adnixus uiribus urget.","st":"5"},{"sp":"N","t":"Tum uero ingeminat clamor cunctique sequentem<br>instigant studiis, resonatque fragoribus aether.<br>hi proprium decus et partum indignantur honorem<br>ni teneant, uitamque uolunt pro laude pacisci;   230<br>hos successus alit: possunt, quia posse uidentur.<br>et fors aequatis cepissent praemia rostris,<br>ni palmas ponto tendens utrasque Cloanthus<br>fudissetque preces diuosque in uota uocasset:<br>‘di, quibus imperium est pelagi, quorum aequora curro,   235<br>uobis laetus ego hoc candentem in litore taurum<br>constituam ante aras uoti reus, extaque salsos<br>proiciam in fluctus et uina liquentia fundam.’<br>dixit, eumque imis sub fluctibus audiit omnis<br>Nereidum Phorcique chorus Panopeaque uirgo,   240<br>et pater ipse manu magna Portunus euntem<br>impulit: illa Noto citius uolucrique sagitta<br>ad terram fugit et portu se condidit alto.<br>tum satus Anchisa cunctis ex more uocatis<br>uictorem magna praeconis uoce Cloanthum   245<br>declarat uiridique aduelat tempora lauro,<br>muneraque in nauis ternos optare iuuencos<br>uinaque et argenti magnum dat ferre talentum.<br>ipsis praecipuos ductoribus addit honores:<br>uictori chlamydem auratam, quam plurima circum    250<br>purpura maeandro duplici Meliboea cucurrit,<br>intextusque puer frondosa regius Ida<br>uelocis iaculo ceruos cursuque fatigat<br>acer, anhelanti similis, quem praepes ab Ida<br>sublimem pedibus rapuit Iouis armiger uncis;   255<br>longaeui palmas nequiquam ad sidera tendunt<br>custodes, saeuitque canum latratus in auras.<br>at qui deinde locum tenuit uirtute secundum,<br>leuibus huic hamis consertam auroque trilicem<br>loricam, quam Demoleo detraxerat ipse   260<br>uictor apud rapidum Simoenta sub Ilio alto,<br>donat habere, uiro decus et tutamen in armis.<br>uix illam famuli Phegeus Sagarisque ferebant<br>multiplicem conixi umeris; indutus at olim<br>Demoleos cursu palantis Troas agebat.   265<br>tertia dona facit geminos ex aere lebetas<br>cymbiaque argento perfecta atque aspera signis.<br>iamque adeo donati omnes opibusque superbi<br>puniceis ibant euincti tempora taenis,<br>cum saeuo e scopulo multa uix arte reuulsus   270<br>amissis remis atque ordine debilis uno<br>inrisam sine honore ratem Sergestus agebat.<br>qualis saepe uiae deprensus in aggere serpens,<br>aerea quem obliquum rota transiit aut grauis ictu<br>seminecem liquit saxo lacerumque uiator;   275<br>nequiquam longos fugiens dat corpore tortus<br>parte ferox ardensque oculis et sibila colla<br>arduus attollens; pars uulnere clauda retentat<br>nexantem nodis seque in sua membra plicantem:<br>tali remigio nauis se tarda mouebat;   280<br>uela facit tamen et uelis subit ostia plenis.<br>Sergestum Aeneas promisso munere donat<br>seruatam ob nauem laetus sociosque reductos.<br>olli serua datur operum haud ignara Mineruae,<br>Cressa genus, Pholoe, geminique sub ubere nati.   285","st":"5"},{"sp":"N","t":"Hoc pius Aeneas misso certamine tendit<br>gramineum in campum, quem collibus undique curuis<br>cingebant siluae, mediaque in ualle theatri<br>circus erat; quo se multis cum milibus heros<br>consessu medium tulit exstructoque resedit.   290<br>hic, qui forte uelint rapido contendere cursu,<br>inuitat pretiis animos, et praemia ponit.<br>undique conueniunt Teucri mixtique Sicani,<br>Nisus et Euryalus primi,<br>Euryalus forma insignis uiridique iuuenta,   295<br>Nisus amore pio pueri; quos deinde secutus<br>regius egregia Priami de stirpe Diores;<br>hunc Salius simul et Patron, quorum alter Acarnan,<br>alter ab Arcadio Tegeaeae sanguine gentis;<br>tum duo Trinacrii iuuenes, Helymus Panopesque   300<br>adsueti siluis, comites senioris Acestae;<br>multi praeterea, quos fama obscura recondit.<br>Aeneas quibus in mediis sic deinde locutus:<br>‘accipite haec animis laetasque aduertite mentes.<br>nemo ex hoc numero mihi non donatus abibit.   305<br>Cnosia bina dabo leuato lucida ferro<br>spicula caelatamque argento ferre bipennem;<br>omnibus hic erit unus honos. tres praemia primi<br>accipient flauaque caput nectentur oliua.<br>primus equum phaleris insignem uictor habeto;   310<br>alter Amazoniam pharetram plenamque sagittis<br>Threiciis, lato quam circum amplectitur auro<br>balteus et tereti subnectit fibula gemma;<br>tertius Argolica hac galea contentus abito.’","st":"5"},{"sp":"N","t":"Haec ubi dicta, locum capiunt signoque repente   315<br>corripiunt spatia audito limenque relinquunt,<br>effusi nimbo similes. simul ultima signant,<br>primus abit longeque ante omnia corpora Nisus<br>emicat et uentis et fulminis ocior alis;<br>proximus huic, longo sed proximus interuallo,   320<br>insequitur Salius; spatio post deinde relicto<br>tertius Euryalus;<br>Euryalumque Helymus sequitur; quo deinde sub ipso<br>ecce uolat calcemque terit iam calce Diores<br>incumbens umero, spatia et si plura supersint   325<br>transeat elapsus prior ambiguumque relinquat.<br>iamque fere spatio extremo fessique sub ipsam<br>finem aduentabant, leui cum sanguine Nisus<br>labitur infelix, caesis ut forte iuuencis<br>fusus humum uiridisque super madefecerat herbas.   330<br>hic iuuenis iam uictor ouans uestigia presso<br>haud tenuit titubata solo, sed pronus in ipso<br>concidit immundoque fimo sacroque cruore.<br>non tamen Euryali, non ille oblitus amorum:<br>nam sese opposuit Salio per lubrica surgens;   335<br>ille autem spissa iacuit reuolutus harena,<br>emicat Euryalus et munere uictor amici<br>prima tenet, plausuque uolat fremituque secundo.<br>post Helymus subit et nunc tertia palma Diores.<br>hic totum caueae consessum ingentis et ora   340<br>prima patrum magnis Salius clamoribus implet,<br>ereptumque dolo reddi sibi poscit honorem.<br>tutatur fauor Euryalum lacrimaeque decorae,<br>gratior et pulchro ueniens in corpore uirtus.<br>adiuuat et magna proclamat uoce Diores,   345<br>qui subiit palmae frustraque ad praemia uenit<br>ultima, si primi Salio reddentur honores.<br>tum pater Aeneas ‘uestra’ inquit ‘munera uobis<br>certa manent, pueri et palmam mouet ordine nemo;<br>me liceat casus miserari insontis amici.’   350<br>sic fatus tergum Gaetuli immane leonis<br>dat Salio uillis onerosum atque unguibus aureis.<br>hic Nisus ‘si tanta’ inquit ‘sunt praemia uictis,<br>et te lapsorum miseret, quae munera Niso<br>digna dabis, primam merui qui laude coronam   355<br>ni me, quae Salium, fortuna inimica tulisset?’<br>et simul his dictis faciem ostentabat et udo<br>turpia membra fimo. risit pater optimus olli<br>et clipeum efferri iussit, Didymaonis artes,<br>Neptuni sacro Danais de poste refixum.   360<br>hoc iuuenem egregium praestanti munere donat.","st":"5"},{"sp":"N","t":"Post, ubi confecti cursus et dona peregit,<br>‘nunc, si cui uirtus animusque in pectore praesens,<br>adsit et euinctis attollat bracchia palmis’:<br>sic ait, et geminum pugnae proponit honorem,   365<br>uictori uelatum auro uittisque iuuencum,<br>ensem atque insignem galeam solacia uicto.<br>nec mora; continuo uastis cum uiribus effert<br>ora Dares magnoque uirum se murmure tollit,<br>solus qui Paridem solitus contendere contra,   370<br>idemque ad tumulum quo maximus occubat Hector<br>uictorem Buten immani corpore, qui se<br>Bebrycia ueniens Amyci de gente ferebat,<br>perculit et fulua moribundum extendit harena.<br>talis prima Dares caput altum in proelia tollit,    375<br>ostenditque umeros latos alternaque iactat<br>bracchia protendens et uerberat ictibus auras.<br>quaeritur huic alius; nec quisquam ex agmine tanto<br>audet adire uirum manibusque inducere caestus.<br>ergo alacris cunctosque putans excedere palma   380<br>Aeneae stetit ante pedes, nec plura moratus<br>tum laeua taurum cornu tenet atque ita fatur:<br>‘nate dea, si nemo audet se credere pugnae,<br>quae finis standi? quo me decet usque teneri?<br>ducere dona iube.’ cuncti simul ore fremebant   385<br>Dardanidae reddique uiro promissa iubebant.","st":"5"},{"sp":"N","t":"Hic grauis Entellum dictis castigat Acestes,<br>proximus ut uiridante toro consederat herbae:<br>‘Entelle, heroum quondam fortissime frustra,<br>tantane tam patiens nullo certamine tolli   390<br>dona sines? ubi nunc nobis deus ille, magister<br>nequiquam memoratus, Eryx? ubi fama per omnem<br>Trinacriam et spolia illa tuis pendentia tectis?’<br>ille sub haec: ‘non laudis amor nec gloria cessit<br>pulsa metu; sed enim gelidus tardante senecta   395<br>sanguis hebet, frigentque effetae in corpore uires.<br>si mihi quae quondam fuerat quaque improbus iste<br>exsultat fidens, si nunc foret illa iuuentas,<br>haud equidem pretio inductus pulchroque iuuenco<br>uenissem, nec dona moror.’ sic deinde locutus   400<br>in medium geminos immani pondere caestus<br>proiecit, quibus acer Eryx in proelia suetus<br>ferre manum duroque intendere bracchia tergo.<br>obstipuere animi: tantorum ingentia septem<br>terga boum plumbo insuto ferroque rigebant.   405<br>ante omnis stupet ipse Dares longeque recusat,<br>magnanimusque Anchisiades et pondus et ipsa<br>huc illuc uinclorum immensa uolumina uersat.<br>tum senior talis referebat pectore uoces:<br>‘quid, si quis caestus ipsius et Herculis arma   410<br>uidisset tristemque hoc ipso in litore pugnam?<br>haec germanus Eryx quondam tuus arma gerebat<br>(sanguine cernis adhuc sparsoque infecta cerebro),<br>his magnum Alciden contra stetit, his ego suetus,<br>dum melior uiris sanguis dabat, aemula necdum   415<br>temporibus geminis canebat sparsa senectus.<br>sed si nostra Dares haec Troius arma recusat<br>idque pio sedet Aeneae, probat auctor Acestes,<br>aequemus pugnas. Erycis tibi terga remitto<br>(solue metus), et tu Troianos exue caestus.’   420<br>haec fatus duplicem ex umeris reiecit amictum<br>et magnos membrorum artus, magna ossa lacertosque<br>exuit atque ingens media consistit harena.<br>tum satus Anchisa caestus pater extulit aequos<br>et paribus palmas amborum innexuit armis.   425<br>constitit in digitos extemplo arrectus uterque<br>bracchiaque ad superas interritus extulit auras.<br>abduxere retro longe capita ardua ab ictu<br>immiscentque manus manibus pugnamque lacessunt,<br>ille pedum melior motu fretusque iuuenta,   430<br>hic membris et mole ualens; sed tarda trementi<br>genua labant, uastos quatit aeger anhelitus artus.<br>multa uiri nequiquam inter se uulnera iactant,<br>multa cauo lateri ingeminant et pectore uastos<br>dant sonitus, erratque auris et tempora circum   435<br>crebra manus, duro crepitant sub uulnere malae.<br>stat grauis Entellus nisuque immotus eodem<br>corpore tela modo atque oculis uigilantibus exit.<br>ille, uelut celsam oppugnat qui molibus urbem<br>aut montana sedet circum castella sub armis,   440<br>nunc hos, nunc illos aditus, omnemque pererrat<br>arte locum et uariis adsultibus inritus urget.<br>ostendit dextram insurgens Entellus et alte<br>extulit, ille ictum uenientem a uertice uelox<br>praeuidit celerique elapsus corpore cessit;   445<br>Entellus uiris in uentum effudit et ultro<br>ipse grauis grauiterque ad terram pondere uasto<br>concidit, ut quondam caua concidit aut Erymantho<br>aut Ida in magna radicibus eruta pinus.<br>consurgunt studiis Teucri et Trinacria pubes;   450<br>it clamor caelo primusque accurrit Acestes<br>aequaeuumque ab humo miserans attollit amicum.<br>at non tardatus casu neque territus heros<br>acrior ad pugnam redit ac uim suscitat ira;<br>tum pudor incendit uiris et conscia uirtus,   455<br>praecipitemque Daren ardens agit aequore toto<br>nunc dextra ingeminans ictus, nunc ille sinistra.<br>nec mora nec requies: quam multa grandine nimbi<br>culminibus crepitant, sic densis ictibus heros<br>creber utraque manu pulsat uersatque Dareta.   460","st":"5"},{"sp":"N","t":"Tum pater Aeneas procedere longius iras<br>et saeuire animis Entellum haud passus acerbis,<br>sed finem imposuit pugnae fessumque Dareta<br>eripuit mulcens dictis ac talia fatur:<br>‘infelix, quae tanta animum dementia cepit?   465<br>non uiris alias conuersaque numina sentis?<br>cede deo.’ dixitque et proelia uoce diremit.<br>ast illum fidi aequales genua aegra trahentem<br>iactantemque utroque caput crassumque cruorem<br>ore eiectantem mixtosque in sanguine dentes   470<br>ducunt ad nauis; galeamque ensemque uocati<br>accipiunt, palmam Entello taurumque relinquunt.<br>hic uictor superans animis tauroque superbus<br>‘nate dea, uosque haec’ inquit ‘cognoscite, Teucri,<br>et mihi quae fuerint iuuenali in corpore uires   475<br>et qua seruetis reuocatum a morte Dareta.’<br>dixit, et aduersi contra stetit ora iuuenci<br>qui donum astabat pugnae, durosque reducta<br>librauit dextra media inter cornua caestus<br>arduus, effractoque inlisit in ossa cerebro:   480<br>sternitur exanimisque tremens procumbit humi bos.<br>ille super talis effundit pectore uoces:<br>‘hanc tibi, Eryx, meliorem animam pro morte Daretis<br>persoluo; hic uictor caestus artemque repono.’","st":"5"},{"sp":"N","t":"Protinus Aeneas celeri certare sagitta   485<br>inuitat qui forte uelint et praemia dicit,<br>ingentique manu malum de naue Seresti<br>erigit et uolucrem traiecto in fune columbam,<br>quo tendant ferrum, malo suspendit ab alto.<br>conuenere uiri deiectamque aerea sortem   490<br>accepit galea, et primus clamore secundo<br>Hyrtacidae ante omnis exit locus Hippocoontis;<br>quem modo nauali Mnestheus certamine uictor<br>consequitur, uiridi Mnestheus euinctus oliua.<br>tertius Eurytion, tuus, o clarissime, frater,   495<br>Pandare, qui quondam iussus confundere foedus<br>in medios telum torsisti primus Achiuos.<br>extremus galeaque ima subsedit Acestes,<br>ausus et ipse manu iuuenum temptare laborem.<br>tum ualidis flexos incuruant uiribus arcus   500<br>pro se quisque uiri et depromunt tela pharetris,<br>primaque per caelum neruo stridente sagitta<br>Hyrtacidae iuuenis uolucris diuerberat auras,<br>et uenit aduersique infigitur arbore mali.<br>intremuit malus micuitque exterrita pennis   505<br>ales, et ingenti sonuerunt omnia plausu.<br>post acer Mnestheus adducto constitit arcu<br>alta petens, pariterque oculos telumque tetendit.<br>ast ipsam miserandus auem contingere ferro<br>non ualuit; nodos et uincula linea rupit   510<br>quis innexa pedem malo pendebat ab alto;<br>illa Notos atque atra uolans in nubila fugit.<br>tum rapidus, iamdudum arcu contenta parato<br>tela tenens, fratrem Eurytion in uota uocauit,<br>iam uacuo laetam caelo speculatus et alis   515<br>plaudentem nigra figit sub nube columbam.<br>decidit exanimis uitamque reliquit in astris<br>aetheriis fixamque refert delapsa sagittam.","st":"5"},{"sp":"N","t":"Amissa solus palma superabat Acestes,<br>qui tamen aerias telum contendit in auras   520<br>ostentans artemque pater arcumque sonantem.<br>hic oculis subitum obicitur magnoque futurum<br>augurio monstrum; docuit post exitus ingens<br>seraque terrifici cecinerunt omina uates.<br>namque uolans liquidis in nubibus arsit harundo   525<br>signauitque uiam flammis tenuisque recessit<br>consumpta in uentos, caelo ceu saepe refixa<br>transcurrunt crinemque uolantia sidera ducunt.<br>attonitis haesere animis superosque precati<br>Trinacrii Teucrique uiri, nec maximus omen   530<br>abnuit Aeneas, sed laetum amplexus Acesten<br>muneribus cumulat magnis ac talia fatur:<br>‘sume, pater, nam te uoluit rex magnus Olympi<br>talibus auspiciis exsortem ducere honores.<br>ipsius Anchisae longaeui hoc munus habebis,   535<br>cratera impressum signis, quem Thracius olim<br>Anchisae genitori in magno munere Cisseus<br>ferre sui dederat monimentum et pignus amoris.’<br>sic fatus cingit uiridanti tempora lauro<br>et primum ante omnis uictorem appellat Acesten.   540<br>nec bonus Eurytion praelato inuidit honori,<br>quamuis solus auem caelo deiecit ab alto.<br>proximus ingreditur donis qui uincula rupit,<br>extremus uolucri qui fixit harundine malum.","st":"5"},{"sp":"N","t":"At pater Aeneas nondum certamine misso   545<br>custodem ad sese comitemque impubis Iuli<br>Epytiden uocat, et fidam sic fatur ad aurem:<br>‘uade age et Ascanio, si iam puerile paratum<br>agmen habet secum cursusque instruxit equorum,<br>ducat auo turmas et sese ostendat in armis   550<br>dic’ ait. ipse omnem longo decedere circo<br>infusum populum et campos iubet esse patentis.<br>incedunt pueri pariterque ante ora parentum<br>frenatis lucent in equis, quos omnis euntis<br>Trinacriae mirata fremit Troiaeque iuuentus.   555<br>omnibus in morem tonsa coma pressa corona;<br>cornea bina ferunt praefixa hastilia ferro,<br>pars leuis umero pharetras; it pectore summo<br>flexilis obtorti per collum circulus auri.<br>tres equitum numero turmae ternique uagantur   560<br>ductores; pueri bis seni quemque secuti<br>agmine partito fulgent paribusque magistris.<br>una acies iuuenum, ducit quam paruus ouantem<br>nomen aui referens Priamus, tua clara, Polite,<br>progenies, auctura Italos; quem Thracius albis    565<br>portat equus bicolor maculis, uestigia primi<br>alba pedis frontemque ostentans arduus albam.<br>alter Atys, genus unde Atii duxere Latini,<br>paruus Atys pueroque puer dilectus Iulo.<br>extremus formaque ante omnis pulcher Iulus   570<br>Sidonio est inuectus equo, quem candida Dido<br>esse sui dederat monimentum et pignus amoris.<br>cetera Trinacriis pubes senioris Acestae<br>fertur equis.<br>excipiunt plausu pauidos gaudentque tuentes   575<br>Dardanidae, ueterumque agnoscunt ora parentum.<br>postquam omnem laeti consessum oculosque suorum<br>lustrauere in equis, signum clamore paratis<br>Epytides longe dedit insonuitque flagello.<br>olli discurrere pares atque agmina terni   580<br>diductis soluere choris, rursusque uocati<br>conuertere uias infestaque tela tulere.<br>inde alios ineunt cursus aliosque recursus<br>aduersi spatiis, alternosque orbibus orbis<br>impediunt pugnaeque cient simulacra sub armis;   585<br>et nunc terga fuga nudant, nunc spicula uertunt<br>infensi, facta pariter nunc pace feruntur.<br>ut quondam Creta fertur Labyrinthus in alta<br>parietibus textum caecis iter ancipitemque<br>mille uiis habuisse dolum, qua signa sequendi   590<br>frangeret indeprensus et inremeabilis error;<br>haud alio Teucrum nati uestigia cursu<br>impediunt texuntque fugas et proelia ludo,<br>delphinum similes qui per maria umida nando<br>Carpathium Libycumque secant.   595<br>hunc morem cursus atque haec certamina primus<br>Ascanius, Longam muris cum cingeret Albam,<br>rettulit et priscos docuit celebrare Latinos,<br>quo puer ipse modo, secum quo Troia pubes;<br>Albani docuere suos; hinc maxima porro   600<br>accepit Roma et patrium seruauit honorem;<br>Troiaque nunc pueri, Troianum dicitur agmen.<br>hac celebrata tenus sancto certamina patri.","st":"5"},{"sp":"N","t":"Hinc primum Fortuna fidem mutata nouauit.<br>dum uariis tumulo referunt sollemnia ludis,   605<br>Irim de caelo misit Saturnia Iuno<br>Iliacam ad classem uentosque aspirat eunti,<br>multa mouens necdum antiquum saturata dolorem.<br>illa uiam celerans per mille coloribus arcum<br>nulli uisa cito decurrit tramite uirgo.   610<br>conspicit ingentem concursum et litora lustrat<br>desertosque uidet portus classemque relictam.<br>at procul in sola secretae Troades acta<br>amissum Anchisen flebant, cunctaeque profundum<br>pontum aspectabant flentes. heu tot uada fessis   615<br>et tantum superesse maris, uox omnibus una;<br>urbem orant, taedet pelagi perferre laborem.<br>ergo inter medias sese haud ignara nocendi<br>conicit et faciemque deae uestemque reponit;<br>fit Beroe, Tmarii coniunx longaeua Dorycli,   620<br>cui genus et quondam nomen natique fuissent,<br>ac sic Dardanidum mediam se matribus infert.<br>‘o miserae, quas non manus’ inquit ‘Achaica bello<br>traxerit ad letum patriae sub moenibus! o gens<br>infelix, cui te exitio Fortuna reseruat?   625<br>septima post Troiae excidium iam uertitur aestas,<br>cum freta, cum terras omnis, tot inhospita saxa<br>sideraque emensae ferimur, dum per mare magnum<br>Italiam sequimur fugientem et uoluimur undis.<br>hic Erycis fines fraterni atque hospes Acestes:   630<br>quis prohibet muros iacere et dare ciuibus urbem?<br>o patria et rapti nequiquam ex hoste penates,<br>nullane iam Troiae dicentur moenia? nusquam<br>Hectoreos amnis, Xanthum et Simoenta, uidebo?<br>quin agite et mecum infaustas exurite puppis.   635<br>nam mihi Cassandrae per somnum uatis imago<br>ardentis dare uisa faces: “hic quaerite Troiam;<br>hic domus est” inquit “uobis.” iam tempus agi res,<br>nec tantis mora prodigiis. en quattuor arae<br>Neptuno; deus ipse faces animumque ministrat.’   640<br>haec memorans prima infensum ui corripit ignem<br>sublataque procul dextra conixa coruscat<br>et iacit. arrectae mentes stupefactaque corda<br>Iliadum. hic una e multis, quae maxima natu,<br>Pyrgo, tot Priami natorum regia nutrix:   645<br>‘non Beroe uobis, non haec Rhoeteia, matres,<br>est Dorycli coniunx; diuini signa decoris<br>ardentisque notate oculos, qui spiritus illi,<br>qui uultus uocisque sonus uel gressus eunti.<br>ipsa egomet dudum Beroen digressa reliqui   650<br>aegram, indignantem tali quod sola careret<br>munere nec meritos Anchisae inferret honores.’<br>haec effata.<br>at matres primo ancipites oculisque malignis<br>ambiguae spectare rates miserum inter amorem   655<br>praesentis terrae fatisque uocantia regna,<br>cum dea se paribus per caelum sustulit alis<br>ingentemque fuga secuit sub nubibus arcum.<br>tum uero attonitae monstris actaeque furore<br>conclamant, rapiuntque focis penetralibus ignem,   660<br>pars spoliant aras, frondem ac uirgulta facesque<br>coniciunt. furit immissis Volcanus habenis<br>transtra per et remos et pictas abiete puppis.","st":"5"},{"sp":"N","t":"Nuntius Anchisae ad tumulum cuneosque theatri<br>incensas perfert nauis Eumelus, et ipsi   665<br>respiciunt atram in nimbo uolitare fauillam.<br>primus et Ascanius, cursus ut laetus equestris<br>ducebat, sic acer equo turbata petiuit<br>castra, nec exanimes possunt retinere magistri.<br>‘quis furor iste nouus? quo nunc, quo tenditis’ inquit   670<br>‘heu miserae ciues? non hostem inimicaque castra<br>Argiuum, uestras spes uritis. en, ego uester<br>Ascanius!’ — galeam ante pedes proiecit inanem,<br>qua ludo indutus belli simulacra ciebat.<br>accelerat simul Aeneas, simul agmina Teucrum.   675<br>ast illae diuersa metu per litora passim<br>diffugiunt, siluasque et sicubi concaua furtim<br>saxa petunt; piget incepti lucisque, suosque<br>mutatae agnoscunt excussaque pectore Iuno est.","st":"5"},{"sp":"N","t":"Sed non idcirco flamma atque incendia uiris   680<br>indomitas posuere; udo sub robore uiuit<br>stuppa uomens tardum fumum, lentusque carinas<br>est uapor et toto descendit corpore pestis,<br>nec uires heroum infusaque flumina prosunt.<br>tum pius Aeneas umeris abscindere uestem   685<br>auxilioque uocare deos et tendere palmas:<br>‘Iuppiter omnipotens, si nondum exosus ad unum<br>Troianos, si quid pietas antiqua labores<br>respicit humanos, da flammam euadere classi<br>nunc, pater, et tenuis Teucrum res eripe leto.    690<br>uel tu, quod superest, infesto fulmine morti,<br>si mereor, demitte tuaque hic obrue dextra.’<br>uix haec ediderat cum effusis imbribus atra<br>tempestas sine more furit tonitruque tremescunt<br>ardua terrarum et campi; ruit aethere toto   695<br>turbidus imber aqua densisque nigerrimus Austris,<br>implenturque super puppes, semusta madescunt<br>robora, restinctus donec uapor omnis et omnes<br>quattuor amissis seruatae a peste carinae.","st":"5"},{"sp":"N","t":"At pater Aeneas casu concussus acerbo   700<br>nunc huc ingentis, nunc illuc pectore curas<br>mutabat uersans, Siculisne resideret aruis<br>oblitus fatorum, Italasne capesseret oras.<br>tum senior Nautes, unum Tritonia Pallas<br>quem docuit multaque insignem reddidit arte — 705<br>haec responsa dabat, uel quae portenderet ira<br>magna deum uel quae fatorum posceret ordo;<br>isque his Aenean solatus uocibus infit:<br>‘nate dea, quo fata trahunt retrahuntque sequamur;<br>quidquid erit, superanda omnis fortuna ferendo est.   710<br>est tibi Dardanius diuinae stirpis Acestes:<br>hunc cape consiliis socium et coniunge uolentem,<br>huic trade amissis superant qui nauibus et quos<br>pertaesum magni incepti rerumque tuarum est.<br>longaeuosque senes ac fessas aequore matres   715<br>et quidquid tecum inualidum metuensque pericli est<br>delige, et his habeant terris sine moenia fessi;<br>urbem appellabunt permisso nomine Acestam.’","st":"5"},{"sp":"N","t":"Talibus incensus dictis senioris amici<br>tum uero in curas animo diducitur omnis;   720<br>et Nox atra polum bigis subuecta tenebat.<br>uisa dehinc caelo facies delapsa parentis<br>Anchisae subito talis effundere uoces:<br>‘nate, mihi uita quondam, dum uita manebat,<br>care magis, nate Iliacis exercite fatis,   725<br>imperio Iouis huc uenio, qui classibus ignem<br>depulit, et caelo tandem miseratus ab alto est.<br>consiliis pare quae nunc pulcherrima Nautes<br>dat senior; lectos iuuenes, fortissima corda,<br>defer in Italiam. gens dura atque aspera cultu   730<br>debellanda tibi Latio est. Ditis tamen ante<br>infernas accede domos et Auerna per alta<br>congressus pete, nate, meos. non me impia namque<br>Tartara habent, tristes umbrae, sed amoena piorum<br>concilia Elysiumque colo. huc casta Sibylla   735<br>nigrarum multo pecudum te sanguine ducet.<br>tum genus omne tuum et quae dentur moenia disces.<br>iamque uale; torquet medios Nox umida cursus<br>et me saeuus equis Oriens adflauit anhelis.’<br>dixerat et tenuis fugit ceu fumus in auras.   740<br>Aeneas ‘quo deinde ruis? quo proripis?’ inquit,<br>‘quem fugis? aut quis te nostris complexibus arcet?’<br>haec memorans cinerem et sopitos suscitat ignis,<br>Pergameumque Larem et canae penetralia Vestae<br>farre pio et plena supplex ueneratur acerra.   745","st":"5"},{"sp":"N","t":"Extemplo socios primumque accersit Acesten<br>et Iouis imperium et cari praecepta parentis<br>edocet et quae nunc animo sententia constet.<br>haud mora consiliis, nec iussa recusat Acestes:<br>transcribunt urbi matres populumque uolentem   750<br>deponunt, animos nil magnae laudis egentis.<br>ipsi transtra nouant flammisque ambesa reponunt<br>robora nauigiis, aptant remosque rudentisque,<br>exigui numero, sed bello uiuida uirtus.<br>interea Aeneas urbem designat aratro   755<br>sortiturque domos; hoc Ilium et haec loca Troiam<br>esse iubet. gaudet regno Troianus Acestes<br>indicitque forum et patribus dat iura uocatis.<br>tum uicina astris Erycino in uertice sedes<br>fundatur Veneri Idaliae, tumuloque sacerdos   760<br>ac lucus late sacer additus Anchiseo.","st":"5"},{"sp":"N","t":"Iamque dies epulata nouem gens omnis, et aris<br>factus honos: placidi strauerunt aequora uenti<br>creber et aspirans rursus uocat Auster in altum.<br>exoritur procurua ingens per litora fletus;   765<br>complexi inter se noctemque diemque morantur.<br>ipsae iam matres, ipsi, quibus aspera quondam<br>uisa maris facies et non tolerabile numen,<br>ire uolunt omnemque fugae perferre laborem.<br>quos bonus Aeneas dictis solatur amicis   770<br>et consanguineo lacrimans commendat Acestae.<br>tris Eryci uitulos et Tempestatibus agnam<br>caedere deinde iubet soluique ex ordine funem.<br>ipse caput tonsae foliis euinctus oliuae<br>stans procul in prora pateram tenet, extaque salsos   775<br>proicit in fluctus ac uina liquentia fundit.<br>certatim socii feriunt mare et aequora uerrunt;   778<br>prosequitur surgens a puppi uentus euntis.   777","st":"5"},{"sp":"N","t":"At Venus interea Neptunum exercita curis   779<br>adloquitur talisque effundit pectore questus:<br>‘Iunonis grauis ira neque exsaturabile pectus<br>cogunt me, Neptune, preces descendere in omnis;<br>quam nec longa dies pietas nec mitigat ulla,<br>nec Iouis imperio fatisque infracta quiescit.<br>non media de gente Phrygum exedisse nefandis   785<br>urbem odiis satis est nec poenam traxe per omnem<br>reliquias Troiae: cineres atque ossa peremptae<br>insequitur. causas tanti sciat illa furoris.<br>ipse mihi nuper Libycis tu testis in undis<br>quam molem subito excierit: maria omnia caelo   790<br>miscuit Aeoliis nequiquam freta procellis,<br>in regnis hoc ausa tuis.<br>per scelus ecce etiam Troianis matribus actis<br>exussit foede puppis et classe subegit<br>amissa socios ignotae linquere terrae.   795<br>quod superest, oro, liceat dare tuta per undas<br>uela tibi, liceat Laurentem attingere Thybrim,<br>si concessa peto, si dant ea moenia Parcae.’<br>tum Saturnius haec domitor maris edidit alti:<br>‘fas omne est, Cytherea, meis te fidere regnis,   800<br>unde genus ducis. merui quoque; saepe furores<br>compressi et rabiem tantam caelique marisque.<br>nec minor in terris, Xanthum Simoentaque testor,<br>Aeneae mihi cura tui. cum Troia Achilles<br>exanimata sequens impingeret agmina muris,   805<br>milia multa daret leto, gemerentque repleti<br>amnes nec reperire uiam atque euoluere posset<br>in mare se Xanthus, Pelidae tunc ego forti<br>congressum Aenean nec dis nec uiribus aequis<br>nube caua rapui, cuperem cum uertere ab imo   810<br>structa meis manibus periurae moenia Troiae.<br>nunc quoque mens eadem perstat mihi; pelle timores.<br>tutus, quos optas, portus accedet Auerni.<br>unus erit tantum amissum quem gurgite quaeres;<br>unum pro multis dabitur caput.’   815<br>his ubi laeta deae permulsit pectora dictis,<br>iungit equos auro genitor, spumantiaque addit<br>frena feris manibusque omnis effundit habenas.<br>caeruleo per summa leuis uolat aequora curru;<br>subsidunt undae tumidumque sub axe tonanti   820<br>sternitur aequor aquis, fugiunt uasto aethere nimbi.<br>tum uariae comitum facies, immania cete,<br>et senior Glauci chorus Inousque Palaemon<br>Tritonesque citi Phorcique exercitus omnis;<br>laeua tenet Thetis et Melite Panopeaque uirgo,   825<br>Nisaee Spioque Thaliaque Cymodoceque.","st":"5"},{"sp":"N","t":"Hic patris Aeneae suspensam blanda uicissim<br>gaudia pertemptant mentem; iubet ocius omnis<br>attolli malos, intendi bracchia uelis.<br>una omnes fecere pedem pariterque sinistros,   830<br>nunc dextros soluere sinus; una ardua torquent<br>cornua detorquentque; ferunt sua flamina classem.<br>princeps ante omnis densum Palinurus agebat<br>agmen; ad hunc alii cursum contendere iussi.<br>iamque fere mediam caeli Nox umida metam   835<br>contigerat, placida laxabant membra quiete<br>sub remis fusi per dura sedilia nautae,<br>cum leuis aetheriis delapsus Somnus ab astris<br>aera dimouit tenebrosum et dispulit umbras,<br>te, Palinure, petens, tibi somnia tristia portans   840<br>insonti; puppique deus consedit in alta<br>Phorbanti similis funditque has ore loquelas:<br>‘Iaside Palinure, ferunt ipsa aequora classem,<br>aequatae spirant aurae, datur hora quieti.<br>pone caput fessosque oculos furare labori.   845<br>ipse ego paulisper pro te tua munera inibo.’<br>cui uix attollens Palinurus lumina fatur:<br>‘mene salis placidi uultum fluctusque quietos<br>ignorare iubes? mene huic confidere monstro?<br>Aenean credam (quid enim?) fallacibus auris   850<br>et caeli totiens deceptus fraude sereni?’<br>talia dicta dabat, clauumque adfixus et haerens<br>nusquam amittebat oculosque sub astra tenebat.<br>ecce deus ramum Lethaeo rore madentem<br>uique soporatum Stygia super utraque quassat   855<br>tempora, cunctantique natantia lumina soluit.<br>uix primos inopina quies laxauerat artus,<br>et super incumbens cum puppis parte reuulsa<br>cumque gubernaclo liquidas proiecit in undas<br>praecipitem ac socios nequiquam saepe uocantem;   860<br>ipse uolans tenuis se sustulit ales ad auras.<br>currit iter tutum non setius aequore classis<br>promissisque patris Neptuni interrita fertur.<br>iamque adeo scopulos Sirenum aduecta subibat,<br>difficilis quondam multorumque ossibus albos   865<br>(tum rauca adsiduo longe sale saxa sonabant),<br>cum pater amisso fluitantem errare magistro<br>sensit, et ipse ratem nocturnis rexit in undis<br>multa gemens casuque animum concussus amici:<br>‘o nimium caelo et pelago confise sereno,   870<br>nudus in ignota, Palinure, iacebis harena.’","st":"5"},{"sp":"HDR","t":"Liber VI","st":"6"},{"sp":"N","t":"Sic fatur lacrimans, classique immittit habenas<br>et tandem Euboicis Cumarum adlabitur oris.<br>obuertunt pelago proras; tum dente tenaci<br>ancora fundabat nauis et litora curuae<br>praetexunt puppes. iuuenum manus emicat ardens   5<br>litus in Hesperium; quaerit pars semina flammae<br>abstrusa in uenis silicis, pars densa ferarum<br>tecta rapit siluas inuentaque flumina monstrat.<br>at pius Aeneas arces quibus altus Apollo<br>praesidet horrendaeque procul secreta Sibyllae,   10<br>antrum immane, petit, magnam cui mentem animumque<br>Delius inspirat uates aperitque futura.<br>iam subeunt Triuiae lucos atque aurea tecta.","st":"6"},{"sp":"N","t":"Daedalus, ut fama est, fugiens Minoia regna<br>praepetibus pennis ausus se credere caelo   15<br>insuetum per iter gelidas enauit ad Arctos,<br>Chalcidicaque leuis tandem super astitit arce.<br>redditus his primum terris tibi, Phoebe, sacrauit<br>remigium alarum posuitque immania templa.<br>in foribus letum Androgeo; tum pendere poenas   20<br>Cecropidae iussi (miserum!) septena quotannis<br>corpora natorum; stat ductis sortibus urna.<br>contra elata mari respondet Cnosia tellus:<br>hic crudelis amor tauri suppostaque furto<br>Pasiphae mixtumque genus prolesque biformis    25<br>Minotaurus inest, Veneris monimenta nefandae,<br>hic labor ille domus et inextricabilis error;<br>magnum reginae sed enim miseratus amorem<br>Daedalus ipse dolos tecti ambagesque resoluit,<br>caeca regens filo uestigia. tu quoque magnam   30<br>partem opere in tanto, sineret dolor, Icare, haberes.<br>bis conatus erat casus effingere in auro,<br>bis patriae cecidere manus. quin protinus omnia<br>perlegerent oculis, ni iam praemissus Achates<br>adforet atque una Phoebi Triuiaeque sacerdos,   35<br>Deiphobe Glauci, fatur quae talia regi:<br>‘non hoc ista sibi tempus spectacula poscit;<br>nunc grege de intacto septem mactare iuuencos<br>praestiterit, totidem lectas ex more bidentis.’<br>talibus adfata Aenean (nec sacra morantur   40<br>iussa uiri) Teucros uocat alta in templa sacerdos.","st":"6"},{"sp":"N","t":"Excisum Euboicae latus ingens rupis in antrum,<br>quo lati ducunt aditus centum, ostia centum,<br>unde ruunt totidem uoces, responsa Sibyllae.<br>uentum erat ad limen, cum uirgo ‘poscere fata   45<br>tempus’ ait; ‘deus ecce deus!’ cui talia fanti<br>ante fores subito non uultus, non color unus,<br>non comptae mansere comae; sed pectus anhelum,<br>et rabie fera corda tument, maiorque uideri<br>nec mortale sonans, adflata est numine quando   50<br>iam propiore dei. ‘cessas in uota precesque,<br>Tros’ ait ‘Aenea? cessas? neque enim ante dehiscent<br>attonitae magna ora domus.’ et talia fata<br>conticuit. gelidus Teucris per dura cucurrit<br>ossa tremor, funditque preces rex pectore ab imo:   55<br>‘Phoebe, grauis Troiae semper miserate labores,<br>Dardana qui Paridis derexti tela manusque<br>corpus in Aeacidae, magnas obeuntia terras<br>tot maria intraui duce te penitusque repostas<br>Massylum gentis praetentaque Syrtibus arua:   60<br>iam tandem Italiae fugientis prendimus oras.<br>hac Troiana tenus fuerit fortuna secuta;<br>uos quoque Pergameae iam fas est parcere genti,<br>dique deaeque omnes, quibus obstitit Ilium et ingens<br>gloria Dardaniae. tuque, o sanctissima uates,   65<br>praescia uenturi, da (non indebita posco<br>regna meis fatis) Latio considere Teucros<br>errantisque deos agitataque numina Troiae.<br>tum Phoebo et Triuiae solido de marmore templum<br>instituam festosque dies de nomine Phoebi.   70<br>te quoque magna manent regnis penetralia nostris:<br>hic ego namque tuas sortis arcanaque fata<br>dicta meae genti ponam, lectosque sacrabo,<br>alma, uiros. foliis tantum ne carmina manda,<br>ne turbata uolent rapidis ludibria uentis;   75<br>ipsa canas oro.’ finem dedit ore loquendi.","st":"6"},{"sp":"N","t":"At Phoebi nondum patiens immanis in antro<br>bacchatur uates, magnum si pectore possit<br>excussisse deum; tanto magis ille fatigat<br>os rabidum, fera corda domans, fingitque premendo.   80<br>ostia iamque domus patuere ingentia centum<br>sponte sua uatisque ferunt responsa per auras:<br>‘o tandem magnis pelagi defuncte periclis<br>(sed terrae grauiora manent), in regna Lauini<br>Dardanidae uenient (mitte hanc de pectore curam),   85<br>sed non et uenisse uolent. bella, horrida bella,<br>et Thybrim multo spumantem sanguine cerno.<br>non Simois tibi nec Xanthus nec Dorica castra<br>defuerint; alius Latio iam partus Achilles,<br>natus et ipse dea; nec Teucris addita Iuno    90<br>usquam aberit, cum tu supplex in rebus egenis<br>quas gentis Italum aut quas non oraueris urbes!<br>causa mali tanti coniunx iterum hospita Teucris<br>externique iterum thalami.<br>tu ne cede malis, sed contra audentior ito,   95<br>qua tua te Fortuna sinet. uia prima salutis<br>(quod minime reris) Graia pandetur ab urbe.’","st":"6"},{"sp":"N","t":"Talibus ex adyto dictis Cumaea Sibylla<br>horrendas canit ambages antroque remugit,<br>obscuris uera inuoluens: ea frena furenti   100<br>concutit et stimulos sub pectore uertit Apollo.<br>ut primum cessit furor et rabida ora quierunt,<br>incipit Aeneas heros: ‘non ulla laborum,<br>o uirgo, noua mi facies inopinaue surgit;<br>omnia praecepi atque animo mecum ante peregi.   105<br>unum oro: quando hic inferni ianua regis<br>dicitur et tenebrosa palus Acheronte refuso,<br>ire ad conspectum cari genitoris et ora<br>contingat; doceas iter et sacra ostia pandas.<br>illum ego per flammas et mille sequentia tela   110<br>eripui his umeris medioque ex hoste recepi;<br>ille meum comitatus iter maria omnia mecum<br>atque omnis pelagique minas caelique ferebat,<br>inualidus, uiris ultra sortemque senectae.<br>quin, ut te supplex peterem et tua limina adirem,   115<br>idem orans mandata dabat. gnatique patrisque,<br>alma, precor, miserere (potes namque omnia, nec te<br>nequiquam lucis Hecate praefecit Auernis),<br>si potuit manis accersere coniugis Orpheus<br>Threicia fretus cithara fidibusque canoris,   120<br>si fratrem Pollux alterna morte redemit<br>itque reditque uiam totiens. quid Thesea, magnum<br>quid memorem Alciden? et mi genus ab Ioue summo.’","st":"6"},{"sp":"N","t":"Talibus orabat dictis arasque tenebat,<br>cum sic orsa loqui uates: ‘sate sanguine diuum,   125<br>Tros Anchisiade, facilis descensus Auerno:<br>noctes atque dies patet atri ianua Ditis;<br>sed reuocare gradum superasque euadere ad auras,<br>hoc opus, hic labor est. pauci, quos aequus amauit<br>Iuppiter aut ardens euexit ad aethera uirtus,   130<br>dis geniti potuere. tenent media omnia siluae,<br>Cocytusque sinu labens circumuenit atro.<br>quod si tantus amor menti, si tanta cupido est<br>bis Stygios innare lacus, bis nigra uidere<br>Tartara, et insano iuuat indulgere labori,   135<br>accipe quae peragenda prius. latet arbore opaca<br>aureus et foliis et lento uimine ramus,<br>Iunoni infernae dictus sacer; hunc tegit omnis<br>lucus et obscuris claudunt conuallibus umbrae.<br>sed non ante datur telluris operta subire   140<br>auricomos quam quis decerpserit arbore fetus.<br>hoc sibi pulchra suum ferri Proserpina munus<br>instituit. primo auulso non deficit alter<br>aureus, et simili frondescit uirga metallo.<br>ergo alte uestiga oculis et rite repertum   145<br>carpe manu; namque ipse uolens facilisque sequetur,<br>si te fata uocant; aliter non uiribus ullis<br>uincere nec duro poteris conuellere ferro.<br>praeterea iacet exanimum tibi corpus amici<br>(heu nescis) totamque incestat funere classem,   150<br>dum consulta petis nostroque in limine pendes.<br>sedibus hunc refer ante suis et conde sepulcro.<br>duc nigras pecudes; ea prima piacula sunto.<br>sic demum lucos Stygis et regna inuia uiuis<br>aspicies.’ dixit, pressoque obmutuit ore.   155","st":"6"},{"sp":"N","t":"Aeneas maesto defixus lumina uultu<br>ingreditur linquens antrum, caecosque uolutat<br>euentus animo secum. cui fidus Achates<br>it comes et paribus curis uestigia figit.<br>multa inter sese uario sermone serebant,   160<br>quem socium exanimum uates, quod corpus humandum<br>diceret. atque illi Misenum in litore sicco,<br>ut uenere, uident indigna morte peremptum,<br>Misenum Aeoliden, quo non praestantior alter<br>aere ciere uiros Martemque accendere cantu.   165<br>Hectoris hic magni fuerat comes, Hectora circum<br>et lituo pugnas insignis obibat et hasta.<br>postquam illum uita uictor spoliauit Achilles,<br>Dardanio Aeneae sese fortissimus heros<br>addiderat socium, non inferiora secutus.   170<br>sed tum, forte caua dum personat aequora concha,<br>demens, et cantu uocat in certamina diuos,<br>aemulus exceptum Triton, si credere dignum est,<br>inter saxa uirum spumosa immerserat unda.<br>ergo omnes magno circum clamore fremebant,   175<br>praecipue pius Aeneas. tum iussa Sibyllae,<br>haud mora, festinant flentes aramque sepulcri<br>congerere arboribus caeloque educere certant.<br>itur in antiquam siluam, stabula alta ferarum;<br>procumbunt piceae, sonat icta securibus ilex   180<br>fraxineaeque trabes cuneis et fissile robur<br>scinditur, aduoluunt ingentis montibus ornos.","st":"6"},{"sp":"N","t":"Nec non Aeneas opera inter talia primus<br>hortatur socios paribusque accingitur armis.<br>atque haec ipse suo tristi cum corde uolutat    185<br>aspectans siluam immensam, et sic forte precatur:<br>‘si nunc se nobis ille aureus arbore ramus<br>ostendat nemore in tanto! quando omnia uere<br>heu nimium de te uates, Misene, locuta est.’<br>uix ea fatus erat, geminae cum forte columbae   190<br>ipsa sub ora uiri caelo uenere uolantes,<br>et uiridi sedere solo. tum maximus heros<br>maternas agnouit auis laetusque precatur:<br>‘este duces, o, si qua uia est, cursumque per auras<br>derigite in lucos ubi pinguem diues opacat   195<br>ramus humum. tuque, o, dubiis ne defice rebus,<br>diua parens.’ sic effatus uestigia pressit<br>obseruans quae signa ferant, quo tendere pergant.<br>pascentes illae tantum prodire uolando<br>quantum acie possent oculi seruare sequentum.   200<br>inde ubi uenere ad fauces graue olentis Auerni,<br>tollunt se celeres liquidumque per aera lapsae<br>sedibus optatis gemina super arbore sidunt,<br>discolor unde auri per ramos aura refulsit.<br>quale solet siluis brumali frigore uiscum   205<br>fronde uirere noua, quod non sua seminat arbos,<br>et croceo fetu teretis circumdare truncos,<br>talis erat species auri frondentis opaca<br>ilice, sic leni crepitabat brattea uento.<br>corripit Aeneas extemplo auidusque refringit   210<br>cunctantem, et uatis portat sub tecta Sibyllae.","st":"6"},{"sp":"N","t":"Nec minus interea Misenum in litore Teucri<br>flebant et cineri ingrato suprema ferebant.<br>principio pinguem taedis et robore secto<br>ingentem struxere pyram, cui frondibus atris   215<br>intexunt latera et feralis ante cupressos<br>constituunt, decorantque super fulgentibus armis.<br>pars calidos latices et aena undantia flammis<br>expediunt, corpusque lauant frigentis et unguunt.<br>fit gemitus. tum membra toro defleta reponunt   220<br>purpureasque super uestis, uelamina nota,<br>coniciunt. pars ingenti subiere feretro,<br>triste ministerium, et subiectam more parentum<br>auersi tenuere facem. congesta cremantur<br>turea dona, dapes, fuso crateres oliuo.   225<br>postquam conlapsi cineres et flamma quieuit,<br>reliquias uino et bibulam lauere fauillam,<br>ossaque lecta cado texit Corynaeus aeno.<br>idem ter socios pura circumtulit unda<br>spargens rore leui et ramo felicis oliuae,   230<br>lustrauitque uiros dixitque nouissima uerba.<br>at pius Aeneas ingenti mole sepulcrum<br>imponit suaque arma uiro remumque tubamque<br>monte sub aerio, qui nunc Misenus ab illo<br>dicitur aeternumque tenet per saecula nomen.   235","st":"6"},{"sp":"N","t":"His actis propere exsequitur praecepta Sibyllae.<br>spelunca alta fuit uastoque immanis hiatu,<br>scrupea, tuta lacu nigro nemorumque tenebris,<br>quam super haud ullae poterant impune uolantes<br>tendere iter pennis: talis sese halitus atris   240<br>faucibus effundens supera ad conuexa ferebat.<br>[unde locum Grai dixerunt nomine Aornum.]<br>quattuor hic primum nigrantis terga iuuencos<br>constituit frontique inuergit uina sacerdos,<br>et summas carpens media inter cornua saetas   245<br>ignibus imponit sacris, libamina prima,<br>uoce uocans Hecaten caeloque Ereboque potentem.<br>supponunt alii cultros tepidumque cruorem<br>succipiunt pateris. ipse atri uelleris agnam<br>Aeneas matri Eumenidum magnaeque sorori   250<br>ense ferit, sterilemque tibi, Proserpina, uaccam;<br>tum Stygio regi nocturnas incohat aras<br>et solida imponit taurorum uiscera flammis,<br>pingue super oleum fundens ardentibus extis.<br>ecce autem primi sub limina solis et ortus   255<br>sub pedibus mugire solum et iuga coepta moueri<br>siluarum, uisaeque canes ululare per umbram<br>aduentante dea. ‘procul, o procul este, profani,’<br>conclamat uates, ‘totoque absistite luco;<br>tuque inuade uiam uaginaque eripe ferrum:   260<br>nunc animis opus, Aenea, nunc pectore firmo.’<br>tantum effata furens antro se immisit aperto;<br>ille ducem haud timidis uadentem passibus aequat.","st":"6"},{"sp":"N","t":"Di, quibus imperium est animarum, umbraeque silentes<br>et Chaos et Phlegethon, loca nocte tacentia late,   265<br>sit mihi fas audita loqui, sit numine uestro<br>pandere res alta terra et caligine mersas.","st":"6"},{"sp":"N","t":"Ibant obscuri sola sub nocte per umbram<br>perque domos Ditis uacuas et inania regna:<br>quale per incertam lunam sub luce maligna   270<br>est iter in siluis, ubi caelum condidit umbra<br>Iuppiter, et rebus nox abstulit atra colorem.<br>uestibulum ante ipsum primisque in faucibus Orci<br>Luctus et ultrices posuere cubilia Curae,<br>pallentesque habitant Morbi tristisque Senectus,   275<br>et Metus et malesuada Fames ac turpis Egestas,<br>terribiles uisu formae, Letumque Labosque;<br>tum consanguineus Leti Sopor et mala mentis<br>Gaudia, mortiferumque aduerso in limine Bellum,<br>ferreique Eumenidum thalami et Discordia demens   280<br>uipereum crinem uittis innexa cruentis.<br>in medio ramos annosaque bracchia pandit<br>ulmus opaca, ingens, quam sedem Somnia uulgo<br>uana tenere ferunt, foliisque sub omnibus haerent.<br>multaque praeterea uariarum monstra ferarum,   285<br>Centauri in foribus stabulant Scyllaeque biformes<br>et centumgeminus Briareus ac belua Lernae<br>horrendum stridens, flammisque armata Chimaera,<br>Gorgones Harpyiaeque et forma tricorporis umbrae.<br>corripit hic subita trepidus formidine ferrum   290<br>Aeneas strictamque aciem uenientibus offert,<br>et ni docta comes tenuis sine corpore uitas<br>admoneat uolitare caua sub imagine formae,<br>inruat et frustra ferro diuerberet umbras.","st":"6"},{"sp":"N","t":"Hinc uia Tartarei quae fert Acherontis ad undas.   295<br>turbidus hic caeno uastaque uoragine gurges<br>aestuat atque omnem Cocyto eructat harenam.<br>portitor has horrendus aquas et flumina seruat<br>terribili squalore Charon, cui plurima mento<br>canities inculta iacet, stant lumina flamma,   300<br>sordidus ex umeris nodo dependet amictus.<br>ipse ratem conto subigit uelisque ministrat<br>et ferruginea subuectat corpora cumba,<br>iam senior, sed cruda deo uiridisque senectus.<br>huc omnis turba ad ripas effusa ruebat,   305<br>matres atque uiri defunctaque corpora uita<br>magnanimum heroum, pueri innuptaeque puellae,<br>impositique rogis iuuenes ante ora parentum:<br>quam multa in siluis autumni frigore primo<br>lapsa cadunt folia, aut ad terram gurgite ab alto    310<br>quam multae glomerantur aues, ubi frigidus annus<br>trans pontum fugat et terris immittit apricis.<br>stabant orantes primi transmittere cursum<br>tendebantque manus ripae ulterioris amore.<br>nauita sed tristis nunc hos nunc accipit illos,   315<br>ast alios longe summotos arcet harena.<br>Aeneas miratus enim motusque tumultu<br>‘dic,’ ait, ‘o uirgo, quid uult concursus ad amnem?<br>quidue petunt animae? uel quo discrimine ripas<br>hae linquunt, illae remis uada liuida uerrunt?’   320<br>olli sic breuiter fata est longaeua sacerdos:<br>‘Anchisa generate, deum certissima proles,<br>Cocyti stagna alta uides Stygiamque paludem,<br>di cuius iurare timent et fallere numen.<br>haec omnis, quam cernis, inops inhumataque turba est;   325<br>portitor ille Charon; hi, quos uehit unda, sepulti.<br>nec ripas datur horrendas et rauca fluenta<br>transportare prius quam sedibus ossa quierunt.<br>centum errant annos uolitantque haec litora circum;<br>tum demum admissi stagna exoptata reuisunt.’   330<br>constitit Anchisa satus et uestigia pressit<br>multa putans sortemque animo miseratus iniquam.<br>cernit ibi maestos et mortis honore carentis<br>Leucaspim et Lyciae ductorem classis Oronten,<br>quos simul a Troia uentosa per aequora uectos   335<br>obruit Auster, aqua inuoluens nauemque uirosque.","st":"6"},{"sp":"N","t":"Ecce gubernator sese Palinurus agebat,<br>qui Libyco nuper cursu, dum sidera seruat,<br>exciderat puppi mediis effusus in undis.<br>hunc ubi uix multa maestum cognouit in umbra,   340<br>sic prior adloquitur: ‘quis te, Palinure, deorum<br>eripuit nobis medioque sub aequore mersit?<br>dic age. namque mihi, fallax haud ante repertus,<br>hoc uno responso animum delusit Apollo,<br>qui fore te ponto incolumem finisque canebat   345<br>uenturum Ausonios. en haec promissa fides est?’<br>ille autem: ‘neque te Phoebi cortina fefellit,<br>dux Anchisiade, nec me deus aequore mersit.<br>namque gubernaclum multa ui forte reuulsum,<br>cui datus haerebam custos cursusque regebam,   350<br>praecipitans traxi mecum. maria aspera iuro<br>non ullum pro me tantum cepisse timorem,<br>quam tua ne spoliata armis, excussa magistro,<br>deficeret tantis nauis surgentibus undis.<br>tris Notus hibernas immensa per aequora noctes   355<br>uexit me uiolentus aqua; uix lumine quarto<br>prospexi Italiam summa sublimis ab unda.<br>paulatim adnabam terrae; iam tuta tenebam,<br>ni gens crudelis madida cum ueste grauatum<br>prensantemque uncis manibus capita aspera montis   360<br>ferro inuasisset praedamque ignara putasset.<br>nunc me fluctus habet uersantque in litore uenti.<br>quod te per caeli iucundum lumen et auras,<br>per genitorem oro, per spes surgentis Iuli,<br>eripe me his, inuicte, malis: aut tu mihi terram   365<br>inice, namque potes, portusque require Velinos;<br>aut tu, si qua uia est, si quam tibi diua creatrix<br>ostendit (neque enim, credo, sine numine diuum<br>flumina tanta paras Stygiamque innare paludem),<br>da dextram misero et tecum me tolle per undas,   370<br>sedibus ut saltem placidis in morte quiescam.’<br>talia fatus erat coepit cum talia uates:<br>‘unde haec, o Palinure, tibi tam dira cupido?<br>tu Stygias inhumatus aquas amnemque seuerum<br>Eumenidum aspicies, ripamue iniussus adibis?   375<br>desine fata deum flecti sperare precando,<br>sed cape dicta memor, duri solacia casus.<br>nam tua finitimi, longe lateque per urbes<br>prodigiis acti caelestibus, ossa piabunt<br>et statuent tumulum et tumulo sollemnia mittent,   380<br>aeternumque locus Palinuri nomen habebit.’<br>his dictis curae emotae pulsusque parumper<br>corde dolor tristi; gaudet cognomine terra.","st":"6"},{"sp":"N","t":"Ergo iter inceptum peragunt fluuioque propinquant.<br>nauita quos iam inde ut Stygia prospexit ab unda   385<br>per tacitum nemus ire pedemque aduertere ripae,<br>sic prior adgreditur dictis atque increpat ultro:<br>‘quisquis es, armatus qui nostra ad flumina tendis,<br>fare age, quid uenias, iam istinc et comprime gressum.<br>umbrarum hic locus est, somni noctisque soporae:   390<br>corpora uiua nefas Stygia uectare carina.<br>nec uero Alciden me sum laetatus euntem<br>accepisse lacu, nec Thesea Pirithoumque,<br>dis quamquam geniti atque inuicti uiribus essent.<br>Tartareum ille manu custodem in uincla petiuit   395<br>ipsius a solio regis traxitque trementem;<br>hi dominam Ditis thalamo deducere adorti.’<br>quae contra breuiter fata est Amphrysia uates:<br>‘nullae hic insidiae tales (absiste moueri),<br>nec uim tela ferunt; licet ingens ianitor antro   400<br>aeternum latrans exsanguis terreat umbras,<br>casta licet patrui seruet Proserpina limen.<br>Troius Aeneas, pietate insignis et armis,<br>ad genitorem imas Erebi descendit ad umbras.<br>si te nulla mouet tantae pietatis imago,   405<br>at ramum hunc’ (aperit ramum qui ueste latebat)<br>‘agnoscas.’ tumida ex ira tum corda residunt;<br>nec plura his. ille admirans uenerabile donum<br>fatalis uirgae longo post tempore uisum<br>caeruleam aduertit puppim ripaeque propinquat.   410<br>inde alias animas, quae per iuga longa sedebant,<br>deturbat laxatque foros; simul accipit alueo<br>ingentem Aenean. gemuit sub pondere cumba<br>sutilis et multam accepit rimosa paludem.<br>tandem trans fluuium incolumis uatemque uirumque   415<br>informi limo glaucaque exponit in ulua.","st":"6"},{"sp":"N","t":"Cerberus haec ingens latratu regna trifauci<br>personat aduerso recubans immanis in antro.<br>cui uates horrere uidens iam colla colubris<br>melle soporatam et medicatis frugibus offam   420<br>obicit. ille fame rabida tria guttura pandens<br>corripit obiectam, atque immania terga resoluit<br>fusus humi totoque ingens extenditur antro.<br>occupat Aeneas aditum custode sepulto<br>euaditque celer ripam inremeabilis undae.   425","st":"6"},{"sp":"N","t":"Continuo auditae uoces uagitus et ingens<br>infantumque animae flentes, in limine primo<br>quos dulcis uitae exsortis et ab ubere raptos<br>abstulit atra dies et funere mersit acerbo;<br>hos iuxta falso damnati crimine mortis.   430<br>nec uero hae sine sorte datae, sine iudice, sedes:<br>quaesitor Minos urnam mouet; ille silentum<br>consiliumque uocat uitasque et crimina discit.<br>proxima deinde tenent maesti loca, qui sibi letum<br>insontes peperere manu lucemque perosi   435<br>proiecere animas. quam uellent aethere in alto<br>nunc et pauperiem et duros perferre labores!<br>fas obstat, tristisque palus inamabilis undae<br>alligat et nouies Styx interfusa coercet.<br>nec procul hinc partem fusi monstrantur in omnem    440<br>Lugentes campi; sic illos nomine dicunt.<br>hic quos durus amor crudeli tabe peredit<br>secreti celant calles et myrtea circum<br>silua tegit; curae non ipsa in morte relinquunt.<br>his Phaedram Procrinque locis maestamque Eriphylen   445<br>crudelis nati monstrantem uulnera cernit,<br>Euadnenque et Pasiphaen; his Laodamia<br>it comes et iuuenis quondam, nunc femina, Caeneus<br>rursus et in ueterem fato reuoluta figuram.<br>inter quas Phoenissa recens a uulnere Dido   450<br>errabat silua in magna; quam Troius heros<br>ut primum iuxta stetit agnouitque per umbras<br>obscuram, qualem primo qui surgere mense<br>aut uidet aut uidisse putat per nubila lunam,<br>demisit lacrimas dulcique adfatus amore est:   455<br>‘infelix Dido, uerus mihi nuntius ergo<br>uenerat exstinctam ferroque extrema secutam?<br>funeris heu tibi causa fui? per sidera iuro,<br>per superos et si qua fides tellure sub ima est,<br>inuitus, regina, tuo de litore cessi.   460<br>sed me iussa deum, quae nunc has ire per umbras,<br>per loca senta situ cogunt noctemque profundam,<br>imperiis egere suis; nec credere quiui<br>hunc tantum tibi me discessu ferre dolorem.<br>siste gradum teque aspectu ne subtrahe nostro.   465<br>quem fugis? extremum fato quod te adloquor hoc est.’<br>talibus Aeneas ardentem et torua tuentem<br>lenibat dictis animum lacrimasque ciebat.<br>illa solo fixos oculos auersa tenebat<br>nec magis incepto uultum sermone mouetur   470<br>quam si dura silex aut stet Marpesia cautes.<br>tandem corripuit sese atque inimica refugit<br>in nemus umbriferum, coniunx ubi pristinus illi<br>respondet curis aequatque Sychaeus amorem.<br>nec minus Aeneas casu percussus iniquo   475<br>prosequitur lacrimis longe et miseratur euntem.","st":"6"},{"sp":"N","t":"Inde datum molitur iter. iamque arua tenebant<br>ultima, quae bello clari secreta frequentant.<br>hic illi occurrit Tydeus, hic inclutus armis<br>Parthenopaeus et Adrasti pallentis imago,   480<br>hic multum fleti ad superos belloque caduci<br>Dardanidae, quos ille omnis longo ordine cernens<br>ingemuit, Glaucumque Medontaque Thersilochumque,<br>tris Antenoridas Cererique sacrum Polyboeten,<br>Idaeumque etiam currus, etiam arma tenentem.   485<br>circumstant animae dextra laeuaque frequentes,<br>nec uidisse semel satis est; iuuat usque morari<br>et conferre gradum et ueniendi discere causas.<br>at Danaum proceres Agamemnoniaeque phalanges<br>ut uidere uirum fulgentiaque arma per umbras,   490<br>ingenti trepidare metu; pars uertere terga,<br>ceu quondam petiere rates, pars tollere uocem<br>exiguam: inceptus clamor frustratur hiantis.","st":"6"},{"sp":"N","t":"Atque hic Priamiden laniatum corpore toto<br>Deiphobum uidet et lacerum crudeliter ora,   495<br>ora manusque ambas, populataque tempora raptis<br>auribus et truncas inhonesto uulnere naris.<br>uix adeo agnouit pauitantem ac dira tegentem<br>supplicia, et notis compellat uocibus ultro:<br>‘Deiphobe armipotens, genus alto a sanguine Teucri,   500<br>quis tam crudelis optauit sumere poenas?<br>cui tantum de te licuit? mihi fama suprema<br>nocte tulit fessum uasta te caede Pelasgum<br>procubuisse super confusae stragis aceruum.<br>tunc egomet tumulum Rhoeteo in litore inanem   505<br>constitui et magna manis ter uoce uocaui.<br>nomen et arma locum seruant; te, amice, nequiui<br>conspicere et patria decedens ponere terra.’<br>ad quae Priamides: ‘nihil o tibi, amice, relictum;<br>omnia Deiphobo soluisti et funeris umbris.   510<br>sed me fata mea et scelus exitiale Lacaenae<br>his mersere malis; illa haec monimenta reliquit.<br>namque ut supremam falsa inter gaudia noctem<br>egerimus, nosti: et nimium meminisse necesse est.<br>cum fatalis equus saltu super ardua uenit   515<br>Pergama et armatum peditem grauis attulit aluo,<br>illa chorum simulans euhantis orgia circum<br>ducebat Phrygias; flammam media ipsa tenebat<br>ingentem et summa Danaos ex arce uocabat.<br>tum me confectum curis somnoque grauatum   520<br>infelix habuit thalamus, pressitque iacentem<br>dulcis et alta quies placidaeque simillima morti.<br>egregia interea coniunx arma omnia tectis<br>emouet, et fidum capiti subduxerat ensem:<br>intra tecta uocat Menelaum et limina pandit,   525<br>scilicet id magnum sperans fore munus amanti,<br>et famam exstingui ueterum sic posse malorum.<br>quid moror? inrumpunt thalamo, comes additus una<br>hortator scelerum Aeolides. di, talia Grais<br>instaurate, pio si poenas ore reposco.   530<br>sed te qui uiuum casus, age fare uicissim,<br>attulerint. pelagine uenis erroribus actus<br>an monitu diuum? an quae te fortuna fatigat,<br>ut tristis sine sole domos, loca turbida, adires?’","st":"6"},{"sp":"N","t":"Hac uice sermonum roseis Aurora quadrigis   535<br>iam medium aetherio cursu traiecerat axem;<br>et fors omne datum traherent per talia tempus,<br>sed comes admonuit breuiterque adfata Sibylla est:<br>‘nox ruit, Aenea; nos flendo ducimus horas.<br>hic locus est, partis ubi se uia findit in ambas:   540<br>dextera quae Ditis magni sub moenia tendit,<br>hac iter Elysium nobis; at laeua malorum<br>exercet poenas et ad impia Tartara mittit.’<br>Deiphobus contra: ‘ne saeui, magna sacerdos;<br>discedam, explebo numerum reddarque tenebris.   545<br>i decus, i, nostrum; melioribus utere fatis.’<br>tantum effatus, et in uerbo uestigia torsit.","st":"6"},{"sp":"N","t":"Respicit Aeneas subito et sub rupe sinistra<br>moenia lata uidet triplici circumdata muro,<br>quae rapidus flammis ambit torrentibus amnis,   550<br>Tartareus Phlegethon, torquetque sonantia saxa.<br>porta aduersa ingens solidoque adamante columnae,<br>uis ut nulla uirum, non ipsi exscindere bello<br>caelicolae ualeant; stat ferrea turris ad auras,<br>Tisiphoneque sedens palla succincta cruenta   555<br>uestibulum exsomnis seruat noctesque diesque.<br>hinc exaudiri gemitus et saeua sonare<br>uerbera, tum stridor ferri tractaeque catenae.<br>constitit Aeneas strepitumque exterritus hausit.<br>‘quae scelerum facies? o uirgo, effare; quibusue   560<br>urgentur poenis? quis tantus plangor ad auras?’<br>tum uates sic orsa loqui: ‘dux inclute Teucrum,<br>nulli fas casto sceleratum insistere limen;<br>sed me cum lucis Hecate praefecit Auernis,<br>ipsa deum poenas docuit perque omnia duxit.    565<br>Cnosius haec Rhadamanthus habet durissima regna<br>castigatque auditque dolos subigitque fateri<br>quae quis apud superos furto laetatus inani<br>distulit in seram commissa piacula mortem.<br>continuo sontis ultrix accincta flagello   570<br>Tisiphone quatit insultans, toruosque sinistra<br>intentans anguis uocat agmina saeua sororum.<br>tum demum horrisono stridentes cardine sacrae<br>panduntur portae. cernis custodia qualis<br>uestibulo sedeat, facies quae limina seruet?   575<br>quinquaginta atris immanis hiatibus Hydra<br>saeuior intus habet sedem. tum Tartarus ipse<br>bis patet in praeceps tantum tenditque sub umbras<br>quantus ad aetherium caeli suspectus Olympum.<br>hic genus antiquum Terrae, Titania pubes,   580<br>fulmine deiecti fundo uoluuntur in imo.<br>hic et Aloidas geminos immania uidi<br>corpora, qui manibus magnum rescindere caelum<br>adgressi superisque Iouem detrudere regnis.<br>uidi et crudelis dantem Salmonea poenas,   585<br>dum flammas Iouis et sonitus imitatur Olympi.<br>quattuor hic inuectus equis et lampada quassans<br>per Graium populos mediaeque per Elidis urbem<br>ibat ouans, diuumque sibi poscebat honorem,<br>demens, qui nimbos et non imitabile fulmen   590<br>aere et cornipedum pulsu simularet equorum.<br>at pater omnipotens densa inter nubila telum<br>contorsit, non ille faces nec fumea taedis<br>lumina, praecipitemque immani turbine adegit.<br>nec non et Tityon, Terrae omniparentis alumnum,   595<br>cernere erat, per tota nouem cui iugera corpus<br>porrigitur, rostroque immanis uultur obunco<br>immortale iecur tondens fecundaque poenis<br>uiscera rimaturque epulis habitatque sub alto<br>pectore, nec fibris requies datur ulla renatis.   600<br>quid memorem Lapithas, Ixiona Pirithoumque?<br>quos super atra silex iam iam lapsura cadentique<br>imminet adsimilis; lucent genialibus altis<br>aurea fulcra toris, epulaeque ante ora paratae<br>regifico luxu; Furiarum maxima iuxta   605<br>accubat et manibus prohibet contingere mensas,<br>exsurgitque facem attollens atque intonat ore.<br>hic, quibus inuisi fratres, dum uita manebat,<br>pulsatusue parens et fraus innexa clienti,<br>aut qui diuitiis soli incubuere repertis   610<br>nec partem posuere suis (quae maxima turba est),<br>quique ob adulterium caesi, quique arma secuti<br>impia nec ueriti dominorum fallere dextras,<br>inclusi poenam exspectant. ne quaere doceri<br>quam poenam, aut quae forma uiros fortunaue mersit.   615<br>saxum ingens uoluunt alii, radiisque rotarum<br>districti pendent; sedet aeternumque sedebit<br>infelix Theseus, Phlegyasque miserrimus omnis<br>admonet et magna testatur uoce per umbras:<br>“discite iustitiam moniti et non temnere diuos.”   620<br>uendidit hic auro patriam dominumque potentem<br>imposuit; fixit leges pretio atque refixit;<br>hic thalamum inuasit natae uetitosque hymenaeos:<br>ausi omnes immane nefas ausoque potiti.<br>non, mihi si linguae centum sint oraque centum,   625<br>ferrea uox, omnis scelerum comprendere formas,<br>omnia poenarum percurrere nomina possim.’","st":"6"},{"sp":"N","t":"Haec ubi dicta dedit Phoebi longaeua sacerdos,<br>‘sed iam age, carpe uiam et susceptum perfice munus;<br>acceleremus’ ait; ‘Cyclopum educta caminis   630<br>moenia conspicio atque aduerso fornice portas,<br>haec ubi nos praecepta iubent deponere dona.’<br>dixerat et pariter gressi per opaca uiarum<br>corripiunt spatium medium foribusque propinquant.<br>occupat Aeneas aditum corpusque recenti   635<br>spargit aqua ramumque aduerso in limine figit.","st":"6"},{"sp":"N","t":"His demum exactis, perfecto munere diuae,<br>deuenere locos laetos et amoena uirecta<br>fortunatorum nemorum sedesque beatas.<br>largior hic campos aether et lumine uestit   640<br>purpureo, solemque suum, sua sidera norunt.<br>pars in gramineis exercent membra palaestris,<br>contendunt ludo et fulua luctantur harena;<br>pars pedibus plaudunt choreas et carmina dicunt.<br>nec non Threicius longa cum ueste sacerdos   645<br>obloquitur numeris septem discrimina uocum,<br>iamque eadem digitis, iam pectine pulsat eburno.<br>hic genus antiquum Teucri, pulcherrima proles,<br>magnanimi heroes nati melioribus annis,<br>Ilusque Assaracusque et Troiae Dardanus auctor.   650<br>arma procul currusque uirum miratur inanis;<br>stant terra defixae hastae passimque soluti<br>per campum pascuntur equi. quae gratia currum<br>armorumque fuit uiuis, quae cura nitentis<br>pascere equos, eadem sequitur tellure repostos.   655<br>conspicit, ecce, alios dextra laeuaque per herbam<br>uescentis laetumque choro paeana canentis<br>inter odoratum lauris nemus, unde superne<br>plurimus Eridani per siluam uoluitur amnis.<br>hic manus ob patriam pugnando uulnera passi,   660<br>quique sacerdotes casti, dum uita manebat,<br>quique pii uates et Phoebo digna locuti,<br>inuentas aut qui uitam excoluere per artis<br>quique sui memores aliquos fecere merendo:<br>omnibus his niuea cinguntur tempora uitta.   665<br>quos circumfusos sic est adfata Sibylla,<br>Musaeum ante omnis (medium nam plurima turba<br>hunc habet atque umeris exstantem suspicit altis):<br>‘dicite, felices animae tuque optime uates,<br>quae regio Anchisen, quis habet locus? illius ergo   670<br>uenimus et magnos Erebi tranauimus amnis.’<br>atque huic responsum paucis ita reddidit heros:<br>‘nulli certa domus; lucis habitamus opacis,<br>riparumque toros et prata recentia riuis<br>incolimus. sed uos, si fert ita corde uoluntas,   675<br>hoc superate iugum, et facili iam tramite sistam.’<br>dixit, et ante tulit gressum camposque nitentis<br>desuper ostentat; dehinc summa cacumina linquunt.","st":"6"},{"sp":"N","t":"At pater Anchises penitus conualle uirenti<br>inclusas animas superumque ad lumen ituras   680<br>lustrabat studio recolens, omnemque suorum<br>forte recensebat numerum, carosque nepotes<br>fataque fortunasque uirum moresque manusque.<br>isque ubi tendentem aduersum per gramina uidit<br>Aenean, alacris palmas utrasque tetendit,   685<br>effusaeque genis lacrimae et uox excidit ore:<br>‘uenisti tandem, tuaque exspectata parenti<br>uicit iter durum pietas? datur ora tueri,<br>nate, tua et notas audire et reddere uoces?<br>sic equidem ducebam animo rebarque futurum    690<br>tempora dinumerans, nec me mea cura fefellit.<br>quas ego te terras et quanta per aequora uectum<br>accipio! quantis iactatum, nate, periclis!<br>quam metui ne quid Libyae tibi regna nocerent!’<br>ille autem: ‘tua me, genitor, tua tristis imago   695<br>saepius occurrens haec limina tendere adegit;<br>stant sale Tyrrheno classes. da iungere dextram,<br>da, genitor, teque amplexu ne subtrahe nostro.’<br>sic memorans largo fletu simul ora rigabat.<br>ter conatus ibi colo dare bracchia circum;   700<br>ter frustra comprensa manus effugit imago,<br>par leuibus uentis uolucrique simillima somno.","st":"6"},{"sp":"N","t":"Interea uidet Aeneas in ualle reducta<br>seclusum nemus et uirgulta sonantia siluae,<br>Lethaeumque domos placidas qui praenatat amnem.   705<br>hunc circum innumerae gentes populique uolabant:<br>ac ueluti in pratis ubi apes aestate serena<br>floribus insidunt uariis et candida circum<br>lilia funduntur, strepit omnis murmure campus.<br>horrescit uisu subito causasque requirit   710<br>inscius Aeneas, quae sint ea flumina porro,<br>quiue uiri tanto complerint agmine ripas.<br>tum pater Anchises: ‘animae, quibus altera fato<br>corpora debentur, Lethaei ad fluminis undam<br>securos latices et longa obliuia potant.   715<br>has equidem memorare tibi atque ostendere coram<br>iampridem, hanc prolem cupio enumerare meorum,<br>quo magis Italia mecum laetere reperta.’<br>‘o pater, anne aliquas ad caelum hinc ire putandum est<br>sublimis animas iterumque ad tarda reuerti   720<br>corpora? quae lucis miseris tam dira cupido?’<br>‘dicam equidem nec te suspensum, nate, tenebo’<br>suscipit Anchises atque ordine singula pandit.","st":"6"},{"sp":"N","t":"‘Principio caelum ac terras camposque liquentis<br>lucentemque globum lunae Titaniaque astra   725<br>spiritus intus alit, totamque infusa per artus<br>mens agitat molem et magno se corpore miscet.<br>inde hominum pecudumque genus uitaeque uolantum<br>et quae marmoreo fert monstra sub aequore pontus.<br>igneus est ollis uigor et caelestis origo   730<br>seminibus, quantum non noxia corpora tardant<br>terrenique hebetant artus moribundaque membra.<br>hinc metuunt cupiuntque, dolent gaudentque, neque auras<br>dispiciunt clausae tenebris et carcere caeco.<br>quin et supremo cum lumine uita reliquit,   735<br>non tamen omne malum miseris nec funditus omnes<br>corporeae excedunt pestes, penitusque necesse est<br>multa diu concreta modis inolescere miris.<br>ergo exercentur poenis ueterumque malorum<br>supplicia expendunt: aliae panduntur inanes   740<br>suspensae ad uentos, aliis sub gurgite uasto<br>infectum eluitur scelus aut exuritur igni:<br>quisque suos patimur manis. exinde per amplum<br>mittimur Elysium et pauci laeta arua tenemus,<br>donec longa dies perfecto temporis orbe   745<br>concretam exemit labem, purumque relinquit<br>aetherium sensum atque aurai simplicis ignem.<br>has omnis, ubi mille rotam uoluere per annos,<br>Lethaeum ad fluuium deus euocat agmine magno,<br>scilicet immemores supera ut conuexa reuisant   750<br>rursus, et incipiant in corpora uelle reuerti.’","st":"6"},{"sp":"N","t":"Dixerat Anchises natumque unaque Sibyllam<br>conuentus trahit in medios turbamque sonantem,<br>et tumulum capit unde omnis longo ordine posset<br>aduersos legere et uenientum discere uultus.   755","st":"6"},{"sp":"N","t":"‘Nunc age, Dardaniam prolem quae deinde sequatur<br>gloria, qui maneant Itala de gente nepotes,<br>inlustris animas nostrumque in nomen ituras,<br>expediam dictis, et te tua fata docebo.<br>ille, uides, pura iuuenis qui nititur hasta,   760<br>proxima sorte tenet lucis loca, primus ad auras<br>aetherias Italo commixtus sanguine surget,<br>Siluius, Albanum nomen, tua postuma proles,<br>quem tibi longaeuo serum Lauinia coniunx<br>educet siluis regem regumque parentem,   765<br>unde genus Longa nostrum dominabitur Alba.<br>proximus ille Procas, Troianae gloria gentis,<br>et Capys et Numitor et qui te nomine reddet<br>Siluius Aeneas, pariter pietate uel armis<br>egregius, si umquam regnandam acceperit Albam.   770<br>qui iuuenes! quantas ostentant, aspice, uiris<br>atque umbrata gerunt ciuili tempora quercu!<br>hi tibi Nomentum et Gabios urbemque Fidenam,<br>hi Collatinas imponent montibus arces,<br>Pometios Castrumque Inui Bolamque Coramque;   775<br>haec tum nomina erunt, nunc sunt sine nomine terrae.<br>quin et auo comitem sese Mauortius addet<br>Romulus, Assaraci quem sanguinis Ilia mater<br>educet. uiden, ut geminae stant uertice cristae<br>et pater ipse suo superum iam signat honore?   780<br>en huius, nate, auspiciis illa incluta Roma<br>imperium terris, animos aequabit Olympo,<br>septemque una sibi muro circumdabit arces,<br>felix prole uirum: qualis Berecyntia mater<br>inuehitur curru Phrygias turrita per urbes   785<br>laeta deum partu, centum complexa nepotes,<br>omnis caelicolas, omnis supera alta tenentis.<br>huc geminas nunc flecte acies, hanc aspice gentem<br>Romanosque tuos. hic Caesar et omnis Iuli<br>progenies magnum caeli uentura sub axem.   790<br>hic uir, hic est, tibi quem promitti saepius audis,<br>Augustus Caesar, diui genus, aurea condet<br>saecula qui rursus Latio regnata per arua<br>Saturno quondam, super et Garamantas et Indos<br>proferet imperium; iacet extra sidera tellus,   795<br>extra anni solisque uias, ubi caelifer Atlas<br>axem umero torquet stellis ardentibus aptum.<br>huius in aduentum iam nunc et Caspia regna<br>responsis horrent diuum et Maeotia tellus,<br>et septemgemini turbant trepida ostia Nili.   800<br>nec uero Alcides tantum telluris obiuit,<br>fixerit aeripedem ceruam licet, aut Erymanthi<br>pacarit nemora et Lernam tremefecerit arcu;<br>nec qui pampineis uictor iuga flectit habenis<br>Liber, agens celso Nysae de uertice tigris.   805<br>et dubitamus adhuc uirtutem extendere factis,<br>aut metus Ausonia prohibet consistere terra?<br>quis procul ille autem ramis insignis oliuae<br>sacra ferens? nosco crinis incanaque menta<br>regis Romani primam qui legibus urbem   810<br>fundabit, Curibus paruis et paupere terra<br>missus in imperium magnum. cui deinde subibit<br>otia qui rumpet patriae residesque mouebit<br>Tullus in arma uiros et iam desueta triumphis<br>agmina. quem iuxta sequitur iactantior Ancus   815<br>nunc quoque iam nimium gaudens popularibus auris.<br>uis et Tarquinios reges animamque superbam<br>ultoris Bruti, fascisque uidere receptos?<br>consulis imperium hic primus saeuasque securis<br>accipiet, natosque pater noua bella mouentis   820<br>ad poenam pulchra pro libertate uocabit,<br>infelix, utcumque ferent ea facta minores:<br>uincet amor patriae laudumque immensa cupido.<br>quin Decios Drusosque procul saeuumque securi<br>aspice Torquatum et referentem signa Camillum.   825<br>illae autem paribus quas fulgere cernis in armis,<br>concordes animae nunc et dum nocte prementur,<br>heu quantum inter se bellum, si lumina uitae<br>attigerint, quantas acies stragemque ciebunt,<br>aggeribus socer Alpinis atque arce Monoeci   830<br>descendens, gener aduersis instructus Eois!<br>ne, pueri, ne tanta animis adsuescite bella<br>neu patriae ualidas in uiscera uertite uiris;<br>tuque prior, tu parce, genus qui ducis Olympo,<br>proice tela manu, sanguis meus! — 835<br>ille triumphata Capitolia ad alta Corintho<br>uictor aget currum caesis insignis Achiuis.<br>eruet ille Argos Agamemnoniasque Mycenas<br>ipsumque Aeaciden, genus armipotentis Achilli,<br>ultus auos Troiae templa et temerata Mineruae.   840<br>quis te, magne Cato, tacitum aut te, Cosse, relinquat?<br>quis Gracchi genus aut geminos, duo fulmina belli,<br>Scipiadas, cladem Libyae, paruoque potentem<br>Fabricium uel te sulco, Serrane, serentem?<br>quo fessum rapitis, Fabii? tu Maximus ille es,   845","st":"6"},{"sp":"N","t":"unus qui nobis cunctando restituis rem.<br>excudent alii spirantia mollius aera<br>(credo equidem), uiuos ducent de marmore uultus,<br>orabunt causas melius, caelique meatus<br>describent radio et surgentia sidera dicent:   850<br>tu regere imperio populos, Romane, memento<br>(hae tibi erunt artes), pacique imponere morem,<br>parcere subiectis et debellare superbos.’","st":"6"},{"sp":"N","t":"Sic pater Anchises, atque haec mirantibus addit:<br>‘aspice, ut insignis spoliis Marcellus opimis   855<br>ingreditur uictorque uiros supereminet omnis.<br>hic rem Romanam magno turbante tumultu<br>sistet eques, sternet Poenos Gallumque rebellem,<br>tertiaque arma patri suspendet capta Quirino.’<br>atque hic Aeneas (una namque ire uidebat   860<br>egregium forma iuuenem et fulgentibus armis,<br>sed frons laeta parum et deiecto lumina uultu)<br>‘quis, pater, ille, uirum qui sic comitatur euntem?<br>filius, anne aliquis magna de stirpe nepotum?<br>qui strepitus circa comitum! quantum instar in ipso!   865<br>sed nox atra caput tristi circumuolat umbra.’<br>tum pater Anchises lacrimis ingressus obortis:<br>‘o gnate, ingentem luctum ne quaere tuorum;<br>ostendent terris hunc tantum fata nec ultra<br>esse sinent. nimium uobis Romana propago   870<br>uisa potens, superi, propria haec si dona fuissent.<br>quantos ille uirum magnam Mauortis ad urbem<br>campus aget gemitus! uel quae, Tiberine, uidebis<br>funera, cum tumulum praeterlabere recentem!<br>nec puer Iliaca quisquam de gente Latinos    875<br>in tantum spe tollet auos, nec Romula quondam<br>ullo se tantum tellus iactabit alumno.<br>heu pietas, heu prisca fides inuictaque bello<br>dextera! non illi se quisquam impune tulisset<br>obuius armato, seu cum pedes iret in hostem   880<br>seu spumantis equi foderet calcaribus armos.<br>heu, miserande puer, si qua fata aspera rumpas,<br>tu Marcellus eris. manibus date lilia plenis<br>purpureos spargam flores animamque nepotis<br>his saltem accumulem donis, et fungar inani   885<br>munere.’ sic tota passim regione uagantur<br>aeris in campis latis atque omnia lustrant.<br>quae postquam Anchises natum per singula duxit<br>incenditque animum famae uenientis amore,<br>exim bella uiro memorat quae deinde gerenda,   890<br>Laurentisque docet populos urbemque Latini,<br>et quo quemque modo fugiatque feratque laborem.","st":"6"},{"sp":"N","t":"Sunt geminae Somni portae, quarum altera fertur<br>cornea, qua ueris facilis datur exitus umbris,<br>altera candenti perfecta nitens elephanto,   895<br>sed falsa ad caelum mittunt insomnia Manes.<br>his ibi tum natum Anchises unaque Sibyllam<br>prosequitur dictis portaque emittit eburna,<br>ille uiam secat ad nauis sociosque reuisit.","st":"6"},{"sp":"N","t":"Tum se ad Caietae recto fert limite portum.   900<br>ancora de prora iacitur; stant litore puppes.","st":"6"},{"sp":"HDR","t":"Liber VII","st":"7"},{"sp":"N","t":"Tu quoque litoribus nostris, Aeneia nutrix,<br>aeternam moriens famam, Caieta, dedisti;<br>et nunc seruat honos sedem tuus, ossaque nomen<br>Hesperia in magna, si qua est ea gloria, signat.","st":"7"},{"sp":"N","t":"At pius exsequiis Aeneas rite solutis,   5<br>aggere composito tumuli, postquam alta quierunt<br>aequora, tendit iter uelis portumque relinquit.<br>aspirant aurae in noctem nec candida cursus<br>luna negat, splendet tremulo sub lumine pontus.<br>proxima Circaeae raduntur litora terrae,   10<br>diues inaccessos ubi Solis filia lucos<br>adsiduo resonat cantu, tectisque superbis<br>urit odoratam nocturna in lumina cedrum<br>arguto tenuis percurrens pectine telas.<br>hinc exaudiri gemitus iraeque leonum   15<br>uincla recusantum et sera sub nocte rudentum,<br>saetigerique sues atque in praesepibus ursi<br>saeuire ac formae magnorum ululare luporum,<br>quos hominum ex facie dea saeua potentibus herbis<br>induerat Circe in uultus ac terga ferarum.   20<br>quae ne monstra pii paterentur talia Troes<br>delati in portus neu litora dira subirent,<br>Neptunus uentis impleuit uela secundis,<br>atque fugam dedit et praeter uada feruida uexit.","st":"7"},{"sp":"N","t":"Iamque rubescebat radiis mare et aethere ab alto   25<br>Aurora in roseis fulgebat lutea bigis,<br>cum uenti posuere omnisque repente resedit<br>flatus, et in lento luctantur marmore tonsae.<br>atque hic Aeneas ingentem ex aequore lucum<br>prospicit. hunc inter fluuio Tiberinus amoeno   30<br>uerticibus rapidis et multa flauus harena<br>in mare prorumpit. uariae circumque supraque<br>adsuetae ripis uolucres et fluminis alueo<br>aethera mulcebant cantu lucoque uolabant.<br>flectere iter sociis terraeque aduertere proras   35<br>imperat et laetus fluuio succedit opaco.","st":"7"},{"sp":"N","t":"Nunc age, qui reges, Erato, quae tempora, rerum<br>quis Latio antiquo fuerit status, aduena classem<br>cum primum Ausoniis exercitus appulit oris,<br>expediam, et primae reuocabo exordia pugnae.   40<br>tu uatem, tu, diua, mone. dicam horrida bella,<br>dicam acies actosque animis in funera reges,<br>Tyrrhenamque manum totamque sub arma coactam<br>Hesperiam. maior rerum mihi nascitur ordo,<br>maius opus moueo.   45","st":"7"},{"sp":"N","t":"Rex arua Latinus et urbes<br>iam senior longa placidas in pace regebat.<br>hunc Fauno et nympha genitum Laurente Marica<br>accipimus; Fauno Picus pater, isque parentem<br>te, Saturne, refert, tu sanguinis ultimus auctor.<br>filius huic fato diuum prolesque uirilis   50<br>nulla fuit, primaque oriens erepta iuuenta est.<br>sola domum et tantas seruabat filia sedes<br>iam matura uiro, iam plenis nubilis annis.<br>multi illam magno e Latio totaque petebant<br>Ausonia; petit ante alios pulcherrimus omnis    55<br>Turnus, auis atauisque potens, quem regia coniunx<br>adiungi generum miro properabat amore;<br>sed uariis portenta deum terroribus obstant.<br>laurus erat tecti medio in penetralibus altis<br>sacra comam multosque metu seruata per annos,   60<br>quam pater inuentam, primas cum conderet arces,<br>ipse ferebatur Phoebo sacrasse Latinus,<br>Laurentisque ab ea nomen posuisse colonis.<br>huius apes summum densae (mirabile dictu)<br>stridore ingenti liquidum trans aethera uectae   65<br>obsedere apicem, et pedibus per mutua nexis<br>examen subitum ramo frondente pependit.<br>continuo uates ‘externum cernimus’ inquit<br>‘aduentare uirum et partis petere agmen easdem<br>partibus ex isdem et summa dominarier arce.’   70<br>praeterea, castis adolet dum altaria taedis,<br>et iuxta genitorem astat Lauinia uirgo,<br>uisa (nefas) longis comprendere crinibus ignem<br>atque omnem ornatum flamma crepitante cremari,<br>regalisque accensa comas, accensa coronam   75<br>insignem gemmis; tum fumida lumine fuluo<br>inuolui ac totis Volcanum spargere tectis.<br>id uero horrendum ac uisu mirabile ferri:<br>namque fore inlustrem fama fatisque canebant<br>ipsam, sed populo magnum portendere bellum.   80","st":"7"},{"sp":"N","t":"At rex sollicitus monstris oracula Fauni,<br>fatidici genitoris, adit lucosque sub alta<br>consulit Albunea, nemorum quae maxima sacro<br>fonte sonat saeuamque exhalat opaca mephitim.<br>hinc Italae gentes omnisque Oenotria tellus   85<br>in dubiis responsa petunt; huc dona sacerdos<br>cum tulit et caesarum ouium sub nocte silenti<br>pellibus incubuit stratis somnosque petiuit,<br>multa modis simulacra uidet uolitantia miris<br>et uarias audit uoces fruiturque deorum   90<br>conloquio atque imis Acheronta adfatur Auernis.<br>hic et tum pater ipse petens responsa Latinus<br>centum lanigeras mactabat rite bidentis,<br>atque harum effultus tergo stratisque iacebat<br>uelleribus: subita ex alto uox reddita luco est:   95<br>‘ne pete conubiis natam sociare Latinis,<br>o mea progenies, thalamis neu crede paratis;<br>externi uenient generi, qui sanguine nostrum<br>nomen in astra ferant, quorumque a stirpe nepotes<br>omnia sub pedibus, qua sol utrumque recurrens   100<br>aspicit Oceanum, uertique regique uidebunt.’<br>haec responsa patris Fauni monitusque silenti<br>nocte datos non ipse suo premit ore Latinus,<br>sed circum late uolitans iam Fama per urbes<br>Ausonias tulerat, cum Laomedontia pubes   105<br>gramineo ripae religauit ab aggere classem.","st":"7"},{"sp":"N","t":"Aeneas primique duces et pulcher Iulus<br>corpora sub ramis deponunt arboris altae,<br>instituuntque dapes et adorea liba per herbam<br>subiciunt epulis (sic Iuppiter ipse monebat)   110<br>et Cereale solum pomis agrestibus augent.<br>consumptis hic forte aliis, ut uertere morsus<br>exiguam in Cererem penuria adegit edendi,<br>et uiolare manu malisque audacibus orbem<br>fatalis crusti patulis nec parcere quadris:   115<br>‘heus, etiam mensas consumimus?’ inquit Iulus,<br>nec plura, adludens. ea uox audita laborum<br>prima tulit finem, primamque loquentis ab ore<br>eripuit pater ac stupefactus numine pressit.<br>continuo ‘salue fatis mihi debita tellus   120<br>uosque’ ait ‘o fidi Troiae saluete penates:<br>hic domus, haec patria est. genitor mihi talia namque<br>(nunc repeto) Anchises fatorum arcana reliquit:<br>“cum te, nate, fames ignota ad litora uectum<br>accisis coget dapibus consumere mensas,   125<br>tum sperare domos defessus, ibique memento<br>prima locare manu molirique aggere tecta.”<br>haec erat illa fames, haec nos suprema manebat<br>exitiis positura modum.<br>quare agite et primo laeti cum lumine solis   130<br>quae loca, quiue habeant homines, ubi moenia gentis,<br>uestigemus et a portu diuersa petamus.<br>nunc pateras libate Ioui precibusque uocate<br>Anchisen genitorem, et uina reponite mensis.’","st":"7"},{"sp":"N","t":"Sic deinde effatus frondenti tempora ramo   135<br>implicat et geniumque loci primamque deorum<br>Tellurem Nymphasque et adhuc ignota precatur<br>flumina, tum Noctem Noctisque orientia signa<br>Idaeumque Iouem Phrygiamque ex ordine matrem<br>inuocat, et duplicis caeloque Ereboque parentis.   140<br>hic pater omnipotens ter caelo clarus ab alto<br>intonuit, radiisque ardentem lucis et auro<br>ipse manu quatiens ostendit ab aethere nubem.<br>diditur hic subito Troiana per agmina rumor<br>aduenisse diem quo debita moenia condant.   145<br>certatim instaurant epulas atque omine magno<br>crateras laeti statuunt et uina coronant.","st":"7"},{"sp":"N","t":"Postera cum prima lustrabat lampade terras<br>orta dies, urbem et finis et litora gentis<br>diuersi explorant: haec fontis stagna Numici,   150<br>hunc Thybrim fluuium, hic fortis habitare Latinos.<br>tum satus Anchisa delectos ordine ab omni<br>centum oratores augusta ad moenia regis<br>ire iubet, ramis uelatos Palladis omnis,<br>donaque ferre uiro pacemque exposcere Teucris.   155<br>haud mora, festinant iussi rapidisque feruntur<br>passibus. ipse humili designat moenia fossa<br>moliturque locum, primasque in litore sedes<br>castrorum in morem pinnis atque aggere cingit.<br>iamque iter emensi turris ac tecta Latinorum   160<br>ardua cernebant iuuenes muroque subibant.<br>ante urbem pueri et primaeuo flore iuuentus<br>exercentur equis domitantque in puluere currus,<br>aut acris tendunt arcus aut lenta lacertis<br>spicula contorquent, cursuque ictuque lacessunt:   165<br>cum praeuectus equo longaeui regis ad auris<br>nuntius ingentis ignota in ueste reportat<br>aduenisse uiros. ille intra tecta uocari<br>imperat et solio medius consedit auito.","st":"7"},{"sp":"N","t":"Tectum augustum, ingens, centum sublime columnis   170<br>urbe fuit summa, Laurentis regia Pici,<br>horrendum siluis et religione parentum.<br>hic sceptra accipere et primos attollere fascis<br>regibus omen erat; hoc illis curia templum,<br>hae sacris sedes epulis; hic ariete caeso   175<br>perpetuis soliti patres considere mensis.<br>quin etiam ueterum effigies ex ordine auorum<br>antiqua e cedro, Italusque paterque Sabinus<br>uitisator curuam seruans sub imagine falcem,<br>Saturnusque senex Ianique bifrontis imago   180<br>uestibulo astabant, aliique ab origine reges,<br>Martiaque ob patriam pugnando uulnera passi.<br>multaque praeterea sacris in postibus arma,<br>captiui pendent currus curuaeque secures<br>et cristae capitum et portarum ingentia claustra   185<br>spiculaque clipeique ereptaque rostra carinis.<br>ipse Quirinali lituo paruaque sedebat<br>succinctus trabea laeuaque ancile gerebat<br>Picus, equum domitor, quem capta cupidine coniunx<br>aurea percussum uirga uersumque uenenis   190<br>fecit auem Circe sparsitque coloribus alas.","st":"7"},{"sp":"N","t":"Tali intus templo diuum patriaque Latinus<br>sede sedens Teucros ad sese in tecta uocauit,<br>atque haec ingressis placido prior edidit ore:<br>‘dicite, Dardanidae (neque enim nescimus et urbem   195<br>et genus, auditique aduertitis aequore cursum),<br>quid petitis? quae causa rates aut cuius egentis<br>litus ad Ausonium tot per uada caerula uexit?<br>siue errore uiae seu tempestatibus acti,<br>qualia multa mari nautae patiuntur in alto,   200<br>fluminis intrastis ripas portuque sedetis,<br>ne fugite hospitium, neue ignorate Latinos<br>Saturni gentem haud uinclo nec legibus aequam,<br>sponte sua ueterisque dei se more tenentem.<br>atque equidem memini (fama est obscurior annis)   205<br>Auruncos ita ferre senes, his ortus ut agris<br>Dardanus Idaeas Phrygiae penetrarit ad urbes<br>Threiciamque Samum, quae nunc Samothracia fertur.<br>hinc illum Corythi Tyrrhena ab sede profectum<br>aurea nunc solio stellantis regia caeli   210<br>accipit et numerum diuorum altaribus auget.’","st":"7"},{"sp":"N","t":"Dixerat, et dicta Ilioneus sic uoce secutus:<br>‘rex, genus egregium Fauni, nec fluctibus actos<br>atra subegit hiems uestris succedere terris,<br>nec sidus regione uiae litusue fefellit:   215<br>consilio hanc omnes animisque uolentibus urbem<br>adferimur pulsi regnis, quae maxima quondam<br>extremo ueniens sol aspiciebat Olympo.<br>ab Ioue principium generis, Ioue Dardana pubes<br>gaudet auo, rex ipse Iouis de gente suprema:   220<br>Troius Aeneas tua nos ad limina misit.<br>quanta per Idaeos saeuis effusa Mycenis<br>tempestas ierit campos, quibus actus uterque<br>Europae atque Asiae fatis concurrerit orbis,<br>audiit et si quem tellus extrema refuso   225<br>summouet Oceano et si quem extenta plagarum<br>quattuor in medio dirimit plaga solis iniqui.<br>diluuio ex illo tot uasta per aequora uecti<br>dis sedem exiguam patriis litusque rogamus<br>innocuum et cunctis undamque auramque patentem.   230<br>non erimus regno indecores, nec uestra feretur<br>fama leuis tantique abolescet gratia facti,<br>nec Troiam Ausonios gremio excepisse pigebit.<br>fata per Aeneae iuro dextramque potentem,<br>siue fide seu quis bello est expertus et armis:   235<br>multi nos populi, multae (ne temne, quod ultro<br>praeferimus manibus uittas ac uerba precantia)<br>et petiere sibi et uoluere adiungere gentes;<br>sed nos fata deum uestras exquirere terras<br>imperiis egere suis. hinc Dardanus ortus,   240<br>huc repetit iussisque ingentibus urget Apollo<br>Tyrrhenum ad Thybrim et fontis uada sacra Numici.<br>dat tibi praeterea fortunae parua prioris<br>munera, reliquias Troia ex ardente receptas.<br>hoc pater Anchises auro libabat ad aras,   245<br>hoc Priami gestamen erat cum iura uocatis<br>more daret populis, sceptrumque sacerque tiaras<br>Iliadumque labor uestes.’","st":"7"},{"sp":"N","t":"Talibus Ilionei dictis defixa Latinus<br>obtutu tenet ora soloque immobilis haeret,    250<br>intentos uoluens oculos. nec purpura regem<br>picta mouet nec sceptra mouent Priameia tantum<br>quantum in conubio natae thalamoque moratur,<br>et ueteris Fauni uoluit sub pectore sortem:<br>hunc illum fatis externa ab sede profectum   255<br>portendi generum paribusque in regna uocari<br>auspiciis, huic progeniem uirtute futuram<br>egregiam et totum quae uiribus occupet orbem.<br>tandem laetus ait: ‘di nostra incepta secundent<br>auguriumque suum! dabitur, Troiane, quod optas.   260<br>munera nec sperno: non uobis rege Latino<br>diuitis uber agri Troiaeue opulentia deerit.<br>ipse modo Aeneas, nostri si tanta cupido est,<br>si iungi hospitio properat sociusque uocari,<br>adueniat, uultus neue exhorrescat amicos:   265<br>pars mihi pacis erit dextram tetigisse tyranni.<br>uos contra regi mea nunc mandata referte:<br>est mihi nata, uiro gentis quam iungere nostrae<br>non patrio ex adyto sortes, non plurima caelo<br>monstra sinunt; generos externis adfore ab oris,   270<br>hoc Latio restare canunt, qui sanguine nostrum<br>nomen in astra ferant. hunc illum poscere fata<br>et reor et, si quid ueri mens augurat, opto.’<br>haec effatus equos numero pater eligit omni<br>(stabant ter centum nitidi in praesepibus altis);   275<br>omnibus extemplo Teucris iubet ordine duci<br>instratos ostro alipedes pictisque tapetis<br>(aurea pectoribus demissa monilia pendent,<br>tecti auro fuluum mandunt sub dentibus aurum),<br>absenti Aeneae currum geminosque iugalis   280<br>semine ab aetherio spirantis naribus ignem,<br>illorum de gente patri quos daedala Circe<br>supposita de matre nothos furata creauit.<br>talibus Aeneadae donis dictisque Latini<br>sublimes in equis redeunt pacemque reportant.   285","st":"7"},{"sp":"N","t":"Ecce autem Inachiis sese referebat ab Argis<br>saeua Iouis coniunx aurasque inuecta tenebat,<br>et laetum Aenean classemque ex aethere longe<br>Dardaniam Siculo prospexit ab usque Pachyno.<br>moliri iam tecta uidet, iam fidere terrae,   290<br>deseruisse rates: stetit acri fixa dolore.<br>tum quassans caput haec effundit pectore dicta:<br>‘heu stirpem inuisam et fatis contraria nostris<br>fata Phrygum! num Sigeis occumbere campis,<br>num capti potuere capi? num incensa cremauit   295<br>Troia uiros? medias acies mediosque per ignis<br>inuenere uiam. at, credo, mea numina tandem<br>fessa iacent, odiis aut exsaturata quieui.<br>quin etiam patria excussos infesta per undas<br>ausa sequi et profugis toto me opponere ponto.   300<br>absumptae in Teucros uires caelique marisque.<br>quid Syrtes aut Scylla mihi, quid uasta Charybdis<br>profuit? optato conduntur Thybridis alueo<br>securi pelagi atque mei. Mars perdere gentem<br>immanem Lapithum ualuit, concessit in iras   305<br>ipse deum antiquam genitor Calydona Dianae,<br>quod scelus aut Lapithas tantum aut Calydona merentem?<br>ast ego, magna Iouis coniunx, nil linquere inausum<br>quae potui infelix, quae memet in omnia uerti,<br>uincor ab Aenea. quod si mea numina non sunt   310<br>magna satis, dubitem haud equidem implorare quod usquam est:<br>flectere si nequeo superos, Acheronta mouebo.<br>non dabitur regnis, esto, prohibere Latinis,<br>atque immota manet fatis Lauinia coniunx:<br>at trahere atque moras tantis licet addere rebus,   315<br>at licet amborum populos exscindere regum.<br>hac gener atque socer coeant mercede suorum:<br>sanguine Troiano et Rutulo dotabere, uirgo,<br>et Bellona manet te pronuba. nec face tantum<br>Cisseis praegnas ignis enixa iugalis;   320<br>quin idem Veneri partus suus et Paris alter,<br>funestaeque iterum recidiua in Pergama taedae.’","st":"7"},{"sp":"N","t":"Haec ubi dicta dedit, terras horrenda petiuit;<br>luctificam Allecto dirarum ab sede dearum<br>infernisque ciet tenebris, cui tristia bella   325<br>iraeque insidiaeque et crimina noxia cordi.<br>odit et ipse pater Pluton, odere sorores<br>Tartareae monstrum: tot sese uertit in ora,<br>tam saeuae facies, tot pullulat atra colubris.<br>quam Iuno his acuit uerbis ac talia fatur:   330<br>‘hunc mihi da proprium, uirgo sata Nocte, laborem,<br>hanc operam, ne noster honos infractaue cedat<br>fama loco, neu conubiis ambire Latinum<br>Aeneadae possint Italosue obsidere finis.<br>tu potes unanimos armare in proelia fratres   335<br>atque odiis uersare domos, tu uerbera tectis<br>funereasque inferre faces, tibi nomina mille,<br>mille nocendi artes. fecundum concute pectus,<br>dissice compositam pacem, sere crimina belli;<br>arma uelit poscatque simul rapiatque iuuentus.’   340","st":"7"},{"sp":"N","t":"Exim Gorgoneis Allecto infecta uenenis<br>principio Latium et Laurentis tecta tyranni<br>celsa petit, tacitumque obsedit limen Amatae,<br>quam super aduentu Teucrum Turnique hymenaeis<br>femineae ardentem curaeque iraeque coquebant.    345<br>huic dea caeruleis unum de crinibus anguem<br>conicit, inque sinum praecordia ad intima subdit,<br>quo furibunda domum monstro permisceat omnem.<br>ille inter uestis et leuia pectora lapsus<br>uoluitur attactu nullo, fallitque furentem   350<br>uipeream inspirans animam; fit tortile collo<br>aurum ingens coluber, fit longae taenia uittae<br>innectitque comas et membris lubricus errat.<br>ac dum prima lues udo sublapsa ueneno<br>pertemptat sensus atque ossibus implicat ignem   355<br>necdum animus toto percepit pectore flammam,<br>mollius et solito matrum de more locuta est,<br>multa super natae lacrimans Phrygiisque hymenaeis:<br>‘exsulibusne datur ducenda Lauinia Teucris,<br>o genitor, nec te miseret nataeque tuique?   360<br>nec matris miseret, quam primo Aquilone relinquet<br>perfidus alta petens abducta uirgine praedo?<br>at non sic Phrygius penetrat Lacedaemona pastor,<br>Ledaeamque Helenam Troianas uexit ad urbes?<br>quid tua sancta fides? quid cura antiqua tuorum   365<br>et consanguineo totiens data dextera Turno?<br>si gener externa petitur de gente Latinis,<br>idque sedet, Faunique premunt te iussa parentis,<br>omnem equidem sceptris terram quae libera nostris<br>dissidet externam reor et sic dicere diuos.   370<br>et Turno, si prima domus repetatur origo,<br>Inachus Acrisiusque patres mediaeque Mycenae.’","st":"7"},{"sp":"N","t":"His ubi nequiquam dictis experta Latinum<br>contra stare uidet, penitusque in uiscera lapsum<br>serpentis furiale malum totamque pererrat,   375<br>tum uero infelix ingentibus excita monstris<br>immensam sine more furit lymphata per urbem.<br>ceu quondam torto uolitans sub uerbere turbo,<br>quem pueri magno in gyro uacua atria circum<br>intenti ludo exercent — ille actus habena   380<br>curuatis fertur spatiis; stupet inscia supra<br>impubesque manus mirata uolubile buxum;<br>dant animos plagae: non cursu segnior illo<br>per medias urbes agitur populosque ferocis.<br>quin etiam in siluas simulato numine Bacchi   385<br>maius adorta nefas maioremque orsa furorem<br>euolat et natam frondosis montibus abdit,<br>quo thalamum eripiat Teucris taedasque moretur,<br>euhoe Bacche fremens, solum te uirgine dignum<br>uociferans: etenim mollis tibi sumere thyrsos,   390<br>te lustrare choro, sacrum tibi pascere crinem.<br>fama uolat, furiisque accensas pectore matres<br>idem omnis simul ardor agit noua quaerere tecta.<br>deseruere domos, uentis dant colla comasque;<br>ast aliae tremulis ululatibus aethera complent   395<br>pampineasque gerunt incinctae pellibus hastas.<br>ipsa inter medias flagrantem feruida pinum<br>sustinet ac natae Turnique canit hymenaeos<br>sanguineam torquens aciem, toruumque repente<br>clamat: ‘io matres, audite, ubi quaeque, Latinae:   400<br>si qua piis animis manet infelicis Amatae<br>gratia, si iuris materni cura remordet,<br>soluite crinalis uittas, capite orgia mecum.’<br>talem inter siluas, inter deserta ferarum<br>reginam Allecto stimulis agit undique Bacchi.   405","st":"7"},{"sp":"N","t":"Postquam uisa satis primos acuisse furores<br>consiliumque omnemque domum uertisse Latini,<br>protinus hinc fuscis tristis dea tollitur alis<br>audacis Rutuli ad muros, quam dicitur urbem<br>Acrisioneis Danae fundasse colonis    410<br>praecipiti delata Noto. locus Ardea quondam<br>dictus auis, et nunc magnum manet Ardea nomen,<br>sed fortuna fuit. tectis hic Turnus in altis<br>iam mediam nigra carpebat nocte quietem.<br>Allecto toruam faciem et furialia membra   415<br>exuit, in uultus sese transformat anilis<br>et frontem obscenam rugis arat, induit albos<br>cum uitta crinis, tum ramum innectit oliuae;<br>fit Calybe Iunonis anus templique sacerdos,<br>et iuueni ante oculos his se cum uocibus offert:   420<br>‘Turne, tot incassum fusos patiere labores,<br>et tua Dardaniis transcribi sceptra colonis?<br>rex tibi coniugium et quaesitas sanguine dotes<br>abnegat, externusque in regnum quaeritur heres.<br>i nunc, ingratis offer te, inrise, periclis;   425<br>Tyrrhenas, i, sterne acies, tege pace Latinos.<br>haec adeo tibi me, placida cum nocte iaceres,<br>ipsa palam fari omnipotens Saturnia iussit.<br>quare age et armari pubem portisque moueri<br>laetus in arua para, et Phrygios qui flumine pulchro   430<br>consedere duces pictasque exure carinas.<br>caelestum uis magna iubet. rex ipse Latinus,<br>ni dare coniugium et dicto parere fatetur,<br>sentiat et tandem Turnum experiatur in armis.’","st":"7"},{"sp":"N","t":"Hic iuuenis uatem inridens sic orsa uicissim   435<br>ore refert: ‘classis inuectas Thybridis undam<br>non, ut rere, meas effugit nuntius auris;<br>ne tantos mihi finge metus. nec regia Iuno<br>immemor est nostri.<br>sed te uicta situ uerique effeta senectus,   440<br>o mater, curis nequiquam exercet, et arma<br>regum inter falsa uatem formidine ludit.<br>cura tibi diuum effigies et templa tueri;<br>bella uiri pacemque gerent quis bella gerenda.’","st":"7"},{"sp":"N","t":"Talibus Allecto dictis exarsit in iras.   445<br>at iuueni oranti subitus tremor occupat artus,<br>deriguere oculi: tot Erinys sibilat hydris<br>tantaque se facies aperit; tum flammea torquens<br>lumina cunctantem et quaerentem dicere plura<br>reppulit, et geminos erexit crinibus anguis,   450<br>uerberaque insonuit rabidoque haec addidit ore:<br>‘en ego uicta situ, quam ueri effeta senectus<br>arma inter regum falsa formidine ludit.<br>respice ad haec: adsum dirarum ab sede sororum,<br>bella manu letumque gero.’   455<br>sic effata facem iuueni coniecit et atro<br>lumine fumantis fixit sub pectore taedas.<br>olli somnum ingens rumpit pauor, ossaque et artus<br>perfundit toto proruptus corpore sudor.<br>arma amens fremit, arma toro tectisque requirit;   460<br>saeuit amor ferri et scelerata insania belli,<br>ira super: magno ueluti cum flamma sonore<br>uirgea suggeritur costis undantis aeni<br>exsultantque aestu latices, furit intus aquai<br>fumidus atque alte spumis exuberat amnis,   465<br>nec iam se capit unda, uolat uapor ater ad auras.<br>ergo iter ad regem polluta pace Latinum<br>indicit primis iuuenum et iubet arma parari,<br>tutari Italiam, detrudere finibus hostem;<br>se satis ambobus Teucrisque uenire Latinisque.   470<br>haec ubi dicta dedit diuosque in uota uocauit,<br>certatim sese Rutuli exhortantur in arma.<br>hunc decus egregium formae mouet atque iuuentae,<br>hunc ataui reges, hunc claris dextera factis.","st":"7"},{"sp":"N","t":"Dum Turnus Rutulos animis audacibus implet,   475<br>Allecto in Teucros Stygiis se concitat alis,<br>arte noua, speculata locum, quo litore pulcher<br>insidiis cursuque feras agitabat Iulus.<br>hic subitam canibus rabiem Cocytia uirgo<br>obicit et noto naris contingit odore,   480<br>ut ceruum ardentes agerent; quae prima laborum<br>causa fuit belloque animos accendit agrestis.<br>ceruus erat forma praestanti et cornibus ingens,<br>Tyrrhidae pueri quem matris ab ubere raptum<br>nutribant Tyrrhusque pater, cui regia parent   485<br>armenta et late custodia credita campi.<br>adsuetum imperiis soror omni Siluia cura<br>mollibus intexens ornabat cornua sertis,<br>pectebatque ferum puroque in fonte lauabat.<br>ille manum patiens mensaeque adsuetus erili   490<br>errabat siluis rursusque ad limina nota<br>ipse domum sera quamuis se nocte ferebat.<br>hunc procul errantem rabidae uenantis Iuli<br>commouere canes, fluuio cum forte secundo<br>deflueret ripaque aestus uiridante leuaret.   495<br>ipse etiam eximiae laudis succensus amore<br>Ascanius curuo derexit spicula cornu;<br>nec dextrae erranti deus afuit, actaque multo<br>perque uterum sonitu perque ilia uenit harundo.<br>saucius at quadripes nota intra tecta refugit   500<br>successitque gemens stabulis, questuque cruentus<br>atque imploranti similis tectum omne replebat.<br>Siluia prima soror palmis percussa lacertos<br>auxilium uocat et duros conclamat agrestis.<br>olli (pestis enim tacitis latet aspera siluis)   505<br>improuisi adsunt, hic torre armatus obusto,<br>stipitis hic grauidi nodis; quod cuique repertum<br>rimanti telum ira facit. uocat agmina Tyrrhus,<br>quadrifidam quercum cuneis ut forte coactis<br>scindebat rapta spirans immane securi.   510","st":"7"},{"sp":"N","t":"At saeua e speculis tempus dea nacta nocendi<br>ardua tecta petit stabuli et de culmine summo<br>pastorale canit signum cornuque recuruo<br>Tartaream intendit uocem, qua protinus omne<br>contremuit nemus et siluae insonuere profundae;   515<br>audiit et Triuiae longe lacus, audiit amnis<br>sulpurea Nar albus aqua fontesque Velini,<br>et trepidae matres pressere ad pectora natos.<br>tum uero ad uocem celeres, qua bucina signum<br>dira dedit, raptis concurrunt undique telis   520<br>indomiti agricolae, nec non et Troia pubes<br>Ascanio auxilium castris effundit apertis.<br>derexere acies. non iam certamine agresti<br>stipitibus duris agitur sudibusue praeustis,<br>sed ferro ancipiti decernunt atraque late   525<br>horrescit strictis seges ensibus, aeraque fulgent<br>sole lacessita et lucem sub nubila iactant:<br>fluctus uti primo coepit cum albescere uento,<br>paulatim sese tollit mare et altius undas<br>erigit, inde imo consurgit ad aethera fundo.   530<br>hic iuuenis primam ante aciem stridente sagitta,<br>natorum Tyrrhi fuerat qui maximus, Almo,<br>sternitur; haesit enim sub gutture uulnus et udae<br>uocis iter tenuemque inclusit sanguine uitam.<br>corpora multa uirum circa seniorque Galaesus,   535<br>dum paci medium se offert, iustissimus unus<br>qui fuit Ausoniisque olim ditissimus aruis:<br>quinque greges illi balantum, quina redibant<br>armenta, et terram centum uertebat aratris.","st":"7"},{"sp":"N","t":"Atque ea per campos aequo dum Marte geruntur,   540<br>promissi dea facta potens, ubi sanguine bellum<br>imbuit et primae commisit funera pugnae,<br>deserit Hesperiam et caeli conuersa per auras<br>Iunonem uictrix adfatur uoce superba:<br>‘en, perfecta tibi bello discordia tristi;   545<br>dic in amicitiam coeant et foedera iungant.<br>quandoquidem Ausonio respersi sanguine Teucros,<br>hoc etiam his addam, tua si mihi certa uoluntas:<br>finitimas in bella feram rumoribus urbes,<br>accendamque animos insani Martis amore   550<br>undique ut auxilio ueniant; spargam arma per agros.’<br>tum contra Iuno: ‘terrorum et fraudis abunde est:<br>stant belli causae, pugnatur comminus armis,<br>quae fors prima dedit sanguis nouus imbuit arma.<br>talia coniugia et talis celebrent hymenaeos   555<br>egregium Veneris genus et rex ipse Latinus.<br>te super aetherias errare licentius auras<br>haud pater ille uelit, summi regnator Olympi.<br>cede locis. ego, si qua super fortuna laborum est,<br>ipsa regam.’ talis dederat Saturnia uoces;   560<br>illa autem attollit stridentis anguibus alas<br>Cocytique petit sedem supera ardua linquens.<br>est locus Italiae medio sub montibus altis,<br>nobilis et fama multis memoratus in oris,<br>Amsancti ualles; densis hunc frondibus atrum   565<br>urget utrimque latus nemoris, medioque fragosus<br>dat sonitum saxis et torto uertice torrens.<br>hic specus horrendum et saeui spiracula Ditis<br>monstrantur, ruptoque ingens Acheronte uorago<br>pestiferas aperit fauces, quis condita Erinys,   570<br>inuisum numen, terras caelumque leuabat.","st":"7"},{"sp":"N","t":"Nec minus interea extremam Saturnia bello<br>imponit regina manum. ruit omnis in urbem<br>pastorum ex acie numerus, caesosque reportant<br>Almonem puerum foedatique ora Galaesi,   575<br>implorantque deos obtestanturque Latinum.<br>Turnus adest medioque in crimine caedis et igni<br>terrorem ingeminat: Teucros in regna uocari,<br>stirpem admisceri Phrygiam, se limine pelli.<br>tum quorum attonitae Baccho nemora auia matres   580<br>insultant thiasis (neque enim leue nomen Amatae)<br>undique collecti coeunt Martemque fatigant.<br>ilicet infandum cuncti contra omina bellum,<br>contra fata deum peruerso numine poscunt.<br>certatim regis circumstant tecta Latini;   585<br>ille uelut pelago rupes immota resistit,<br>ut pelagi rupes magno ueniente fragore,<br>quae sese multis circum latrantibus undis<br>mole tenet; scopuli nequiquam et spumea circum<br>saxa fremunt laterique inlisa refunditur alga.   590<br>uerum ubi nulla datur caecum exsuperare potestas<br>consilium, et saeuae nutu Iunonis eunt res,<br>multa deos aurasque pater testatus inanis<br>‘frangimur heu fatis’ inquit ‘ferimurque procella!<br>ipsi has sacrilego pendetis sanguine poenas,   595<br>o miseri. te, Turne, nefas, te triste manebit<br>supplicium, uotisque deos uenerabere seris.<br>nam mihi parta quies, omnisque in limine portus<br>funere felici spolior.’ nec plura locutus<br>saepsit se tectis rerumque reliquit habenas.   600","st":"7"},{"sp":"N","t":"Mos erat Hesperio in Latio, quem protinus urbes<br>Albanae coluere sacrum, nunc maxima rerum<br>Roma colit, cum prima mouent in proelia Martem,<br>siue Getis inferre manu lacrimabile bellum<br>Hyrcanisue Arabisue parant, seu tendere ad Indos   605<br>Auroramque sequi Parthosque reposcere signa:<br>sunt geminae Belli portae (sic nomine dicunt)<br>religione sacrae et saeui formidine Martis;<br>centum aerei claudunt uectes aeternaque ferri<br>robora, nec custos absistit limine Ianus.   610<br>has, ubi certa sedet patribus sententia pugnae,<br>ipse Quirinali trabea cinctuque Gabino<br>insignis reserat stridentia limina consul,<br>ipse uocat pugnas; sequitur tum cetera pubes,<br>aereaque adsensu conspirant cornua rauco.   615<br>hoc et tum Aeneadis indicere bella Latinus<br>more iubebatur tristisque recludere portas.<br>abstinuit tactu pater auersusque refugit<br>foeda ministeria, et caecis se condidit umbris.<br>tum regina deum caelo delapsa morantis   620<br>impulit ipsa manu portas, et cardine uerso<br>Belli ferratos rumpit Saturnia postis.<br>ardet inexcita Ausonia atque immobilis ante;<br>pars pedes ire parat campis, pars arduus altis<br>puluerulentus equis furit; omnes arma requirunt.   625<br>pars leuis clipeos et spicula lucida tergent<br>aruina pingui subiguntque in cote securis;<br>signaque ferre iuuat sonitusque audire tubarum.<br>quinque adeo magnae positis incudibus urbes<br>tela nouant, Atina potens Tiburque superbum,   630<br>Ardea Crustumerique et turrigerae Antemnae.<br>tegmina tuta cauant capitum flectuntque salignas<br>umbonum cratis; alii thoracas aenos<br>aut leuis ocreas lento ducunt argento;<br>uomeris huc et falcis honos, huc omnis aratri   635<br>cessit amor; recoquunt patrios fornacibus ensis.<br>classica iamque sonant, it bello tessera signum;<br>hic galeam tectis trepidus rapit, ille trementis<br>ad iuga cogit equos, clipeumque auroque trilicem<br>loricam induitur fidoque accingitur ense.   640","st":"7"},{"sp":"N","t":"Pandite nunc Helicona, deae, cantusque mouete,<br>qui bello exciti reges, quae quemque secutae<br>complerint campos acies, quibus Itala iam tum<br>floruerit terra alma uiris, quibus arserit armis;<br>et meministis enim, diuae, et memorare potestis;   645<br>ad nos uix tenuis famae perlabitur aura.","st":"7"},{"sp":"N","t":"Primus init bellum Tyrrhenis asper ab oris<br>contemptor diuum Mezentius agminaque armat.<br>filius huic iuxta Lausus, quo pulchrior alter<br>non fuit excepto Laurentis corpore Turni;   650<br>Lausus, equum domitor debellatorque ferarum,<br>ducit Agyllina nequiquam ex urbe secutos<br>mille uiros, dignus patriis qui laetior esset<br>imperiis et cui pater haud Mezentius esset.","st":"7"},{"sp":"N","t":"Post hos insignem palma per gramina currum   655<br>uictoresque ostentat equos satus Hercule pulchro<br>pulcher Auentinus, clipeoque insigne paternum<br>centum anguis cinctamque gerit serpentibus Hydram;<br>collis Auentini silua quem Rhea sacerdos<br>furtiuum partu sub luminis edidit oras,   660<br>mixta deo mulier, postquam Laurentia uictor<br>Geryone exstincto Tirynthius attigit arua,<br>Tyrrhenoque boues in flumine lauit Hiberas.<br>pila manu saeuosque gerunt in bella dolones,<br>et tereti pugnant mucrone ueruque Sabello.   665<br>ipse pedes, tegimen torquens immane leonis,<br>terribili impexum saeta cum dentibus albis<br>indutus capiti, sic regia tecta subibat,<br>horridus Herculeoque umeros innexus amictu.","st":"7"},{"sp":"N","t":"Tum gemini fratres Tiburtia moenia linquunt,   670<br>fratris Tiburti dictam cognomine gentem,<br>Catillusque acerque Coras, Argiua iuuentus,<br>et primam ante aciem densa inter tela feruntur:<br>ceu duo nubigenae cum uertice montis ab alto<br>descendunt Centauri Homolen Othrymque niualem   675<br>linquentes cursu rapido; dat euntibus ingens<br>silua locum et magno cedunt uirgulta fragore.","st":"7"},{"sp":"N","t":"Nec Praenestinae fundator defuit urbis,<br>Volcano genitum pecora inter agrestia regem<br>inuentumque focis omnis quem credidit aetas,   680<br>Caeculus. hunc legio late comitatur agrestis:<br>quique altum Praeneste uiri quique arua Gabinae<br>Iunonis gelidumque Anienem et roscida riuis<br>Hernica saxa colunt, quos diues Anagnia pascis,<br>quos Amasene pater. non illis omnibus arma   685<br>nec clipei currusue sonant; pars maxima glandes<br>liuentis plumbi spargit, pars spicula gestat<br>bina manu, fuluosque lupi de pelle galeros<br>tegmen habent capiti; uestigia nuda sinistri<br>instituere pedis, crudus tegit altera pero.   690","st":"7"},{"sp":"N","t":"At Messapus, equum domitor, Neptunia proles,<br>quem neque fas igni cuiquam nec sternere ferro,<br>iam pridem resides populos desuetaque bello<br>agmina in arma uocat subito ferrumque retractat.<br>hi Fescenninas acies Aequosque Faliscos,   695<br>hi Soractis habent arces Flauiniaque arua<br>et Cimini cum monte lacum lucosque Capenos.<br>ibant aequati numero regemque canebant:<br>ceu quondam niuei liquida inter nubila cycni<br>cum sese e pastu referunt et longa canoros   700<br>dant per colla modos, sonat amnis et Asia longe<br>pulsa palus.<br>nec quisquam aeratas acies examine tanto<br>misceri putet, aeriam sed gurgite ab alto<br>urgeri uolucrum raucarum ad litora nubem.   705","st":"7"},{"sp":"N","t":"Ecce Sabinorum prisco de sanguine magnum<br>agmen agens Clausus magnique ipse agminis instar,<br>Claudia nunc a quo diffunditur et tribus et gens<br>per Latium, postquam in partem data Roma Sabinis.<br>una ingens Amiterna cohors priscique Quirites,   710<br>Ereti manus omnis oliuiferaeque Mutuscae;<br>qui Nomentum urbem, qui Rosea rura Velini,<br>qui Tetricae horrentis rupes montemque Seuerum<br>Casperiamque colunt Forulosque et flumen Himellae,<br>qui Tiberim Fabarimque bibunt, quos frigida misit   715<br>Nursia, et Ortinae classes populique Latini,<br>quosque secans infaustum interluit Allia nomen:<br>quam multi Libyco uoluuntur marmore fluctus<br>saeuus ubi Orion hibernis conditur undis,<br>uel cum sole nouo densae torrentur aristae   720<br>aut Hermi campo aut Lyciae flauentibus aruis.<br>scuta sonant pulsuque pedum conterrita tellus.","st":"7"},{"sp":"N","t":"Hinc Agamemnonius, Troiani nominis hostis,<br>curru iungit Halaesus equos Turnoque ferocis<br>mille rapit populos, uertunt felicia Baccho    725<br>Massica qui rastris, et quos de collibus altis<br>Aurunci misere patres Sidicinaque iuxta<br>aequora, quique Cales linquunt amnisque uadosi<br>accola Volturni, pariterque Saticulus asper<br>Oscorumque manus. teretes sunt aclydes illis   730<br>tela, sed haec lento mos est aptare flagello.<br>laeuas caetra tegit, falcati comminus enses.","st":"7"},{"sp":"N","t":"Nec tu carminibus nostris indictus abibis,<br>Oebale, quem generasse Telon Sebethide nympha<br>fertur, Teleboum Capreas cum regna teneret,   735<br>iam senior; patriis sed non et filius aruis<br>contentus late iam tum dicione premebat<br>Sarrastis populos et quae rigat aequora Sarnus,<br>quique Rufras Batulumque tenent atque arua Celemnae,<br>et quos maliferae despectant moenia Abellae,   740<br>Teutonico ritu soliti torquere cateias;<br>tegmina quis capitum raptus de subere cortex<br>aerataeque micant peltae, micat aereus ensis.","st":"7"},{"sp":"N","t":"Et te montosae misere in proelia Nersae,<br>Vfens, insignem fama et felicibus armis,   745<br>horrida praecipue cui gens adsuetaque multo<br>uenatu nemorum, duris Aequicula glaebis.<br>armati terram exercent semperque recentis<br>conuectare iuuat praedas et uiuere rapto.","st":"7"},{"sp":"N","t":"Quin et Marruuia uenit de gente sacerdos   750<br>fronde super galeam et felici comptus oliua<br>Archippi regis missu, fortissimus Vmbro,<br>uipereo generi et grauiter spirantibus hydris<br>spargere qui somnos cantuque manuque solebat,<br>mulcebatque iras et morsus arte leuabat.   755<br>sed non Dardaniae medicari cuspidis ictum<br>eualuit neque eum iuuere in uulnera cantus<br>somniferi et Marsis quaesitae montibus herbae.<br>te nemus Angitiae, uitrea te Fucinus unda,<br>te liquidi fleuere lacus.   760","st":"7"},{"sp":"N","t":"Ibat et Hippolyti proles pulcherrima bello,<br>Virbius, insignem quem mater Aricia misit,<br>eductum Egeriae lucis umentia circum<br>litora, pinguis ubi et placabilis ara Dianae.<br>namque ferunt fama Hippolytum, postquam arte nouercae   765<br>occiderit patriasque explerit sanguine poenas<br>turbatis distractus equis, ad sidera rursus<br>aetheria et superas caeli uenisse sub auras,<br>Paeoniis reuocatum herbis et amore Dianae.<br>tum pater omnipotens aliquem indignatus ab umbris   770<br>mortalem infernis ad lumina surgere uitae,<br>ipse repertorem medicinae talis et artis<br>fulmine Phoebigenam Stygias detrusit ad undas.<br>at Triuia Hippolytum secretis alma recondit<br>sedibus et nymphae Egeriae nemorique relegat,   775<br>solus ubi in siluis Italis ignobilis aeuum<br>exigeret uersoque ubi nomine Virbius esset.<br>unde etiam templo Triuiae lucisque sacratis<br>cornipedes arcentur equi, quod litore currum<br>et iuuenem monstris pauidi effudere marinis.   780<br>filius ardentis haud setius aequore campi<br>exercebat equos curruque in bella ruebat.","st":"7"},{"sp":"N","t":"Ipse inter primos praestanti corpore Turnus<br>uertitur arma tenens et toto uertice supra est.<br>cui triplici crinita iuba galea alta Chimaeram   785<br>sustinet Aetnaeos efflantem faucibus ignis;<br>tam magis illa fremens et tristibus effera flammis<br>quam magis effuso crudescunt sanguine pugnae.<br>at leuem clipeum sublatis cornibus Io<br>auro insignibat, iam saetis obsita, iam bos,   790<br>argumentum ingens, et custos uirginis Argus,<br>caelataque amnem fundens pater Inachus urna.<br>insequitur nimbus peditum clipeataque totis<br>agmina densentur campis, Argiuaque pubes<br>Auruncaeque manus, Rutuli ueteresque Sicani,   795<br>et Sacranae acies et picti scuta Labici;<br>qui saltus, Tiberine, tuos sacrumque Numici<br>litus arant Rutulosque exercent uomere collis<br>Circaeumque iugum, quis Iuppiter Anxurus aruis<br>praesidet et uiridi gaudens Feronia luco;   800<br>qua Saturae iacet atra palus gelidusque per imas<br>quaerit iter uallis atque in mare conditur Vfens.","st":"7"},{"sp":"N","t":"Hos super aduenit Volsca de gente Camilla<br>agmen agens equitum et florentis aere cateruas,<br>bellatrix, non illa colo calathisue Mineruae   805<br>femineas adsueta manus, sed proelia uirgo<br>dura pati cursuque pedum praeuertere uentos.<br>illa uel intactae segetis per summa uolaret<br>gramina nec teneras cursu laesisset aristas,<br>uel mare per medium fluctu suspensa tumenti   810<br>ferret iter celeris nec tingeret aequore plantas.<br>illam omnis tectis agrisque effusa iuuentus<br>turbaque miratur matrum et prospectat euntem,<br>attonitis inhians animis ut regius ostro<br>uelet honos leuis umeros, ut fibula crinem   815<br>auro internectat, Lyciam ut gerat ipsa pharetram<br>et pastoralem praefixa cuspide myrtum.","st":"7"},{"sp":"HDR","t":"Liber VIII","st":"8"},{"sp":"N","t":"Vt belli signum Laurenti Turnus ab arce<br>extulit et rauco strepuerunt cornua cantu,<br>utque acris concussit equos utque impulit arma,<br>extemplo turbati animi, simul omne tumultu<br>coniurat trepido Latium saeuitque iuuentus   5<br>effera. ductores primi Messapus et Vfens<br>contemptorque deum Mezentius undique cogunt<br>auxilia et latos uastant cultoribus agros.<br>mittitur et magni Venulus Diomedis ad urbem<br>qui petat auxilium, et Latio consistere Teucros,   10<br>aduectum Aenean classi uictosque penatis<br>inferre et fatis regem se dicere posci<br>edoceat, multasque uiro se adiungere gentis<br>Dardanio et late Latio increbrescere nomen:<br>quid struat his coeptis, quem, si fortuna sequatur,   15<br>euentum pugnae cupiat, manifestius ipsi<br>quam Turno regi aut regi apparere Latino.","st":"8"},{"sp":"N","t":"Talia per Latium. quae Laomedontius heros<br>cuncta uidens magno curarum fluctuat aestu,<br>atque animum nunc huc celerem nunc diuidit illuc   20<br>in partisque rapit uarias perque omnia uersat,<br>sicut aquae tremulum labris ubi lumen aenis<br>sole repercussum aut radiantis imagine lunae<br>omnia peruolitat late loca, iamque sub auras<br>erigitur summique ferit laquearia tecti.   25<br>nox erat et terras animalia fessa per omnis<br>alituum pecudumque genus sopor altus habebat,<br>cum pater in ripa gelidique sub aetheris axe<br>Aeneas, tristi turbatus pectora bello,<br>procubuit seramque dedit per membra quietem.   30<br>huic deus ipse loci fluuio Tiberinus amoeno<br>populeas inter senior se attollere frondes<br>uisus (eum tenuis glauco uelabat amictu<br>carbasus, et crinis umbrosa tegebat harundo),<br>tum sic adfari et curas his demere dictis:   35","st":"8"},{"sp":"N","t":"‘O sate gente deum, Troianam ex hostibus urbem<br>qui reuehis nobis aeternaque Pergama seruas,<br>exspectate solo Laurenti aruisque Latinis,<br>hic tibi certa domus, certi (ne absiste) penates.<br>neu belli terrere minis; tumor omnis et irae   40<br>concessere deum.<br>iamque tibi, ne uana putes haec fingere somnum,<br>litoreis ingens inuenta sub ilicibus sus<br>triginta capitum fetus enixa iacebit,<br>alba solo recubans, albi circum ubera nati.   45<br>[hic locus urbis erit, requies ea certa laborum,]<br>ex quo ter denis urbem redeuntibus annis<br>Ascanius clari condet cognominis Albam.<br>haud incerta cano. nunc qua ratione quod instat<br>expedias uictor, paucis (aduerte) docebo.   50<br>Arcades his oris, genus a Pallante profectum,<br>qui regem Euandrum comites, qui signa secuti,<br>delegere locum et posuere in montibus urbem<br>Pallantis proaui de nomine Pallanteum.<br>hi bellum adsidue ducunt cum gente Latina;   55<br>hos castris adhibe socios et foedera iunge.<br>ipse ego te ripis et recto flumine ducam,<br>aduersum remis superes subuectus ut amnem.<br>surge age, nate dea, primisque cadentibus astris<br>Iunoni fer rite preces, iramque minasque   60<br>supplicibus supera uotis. mihi uictor honorem<br>persolues. ego sum pleno quem flumine cernis<br>stringentem ripas et pinguia culta secantem,<br>caeruleus Thybris, caelo gratissimus amnis.<br>hic mihi magna domus, celsis caput urbibus exit.’   65","st":"8"},{"sp":"N","t":"Dixit, deinde lacu fluuius se condidit alto<br>ima petens; nox Aenean somnusque reliquit.<br>surgit et aetherii spectans orientia solis<br>lumina rite cauis undam de flumine palmis<br>sustinet ac talis effundit ad aethera uoces:   70<br>‘Nymphae, Laurentes Nymphae, genus amnibus unde est,<br>tuque, o Thybri tuo genitor cum flumine sancto,<br>accipite Aenean et tandem arcete periclis.<br>quo te cumque lacus miserantem incommoda nostra<br>fonte tenent, quocumque solo pulcherrimus exis,   75<br>semper honore meo, semper celebrabere donis<br>corniger Hesperidum fluuius regnator aquarum.<br>adsis o tantum et propius tua numina firmes.’<br>sic memorat, geminasque legit de classe biremis<br>remigioque aptat, socios simul instruit armis.   80","st":"8"},{"sp":"N","t":"Ecce autem subitum atque oculis mirabile monstrum,<br>candida per siluam cum fetu concolor albo<br>procubuit uiridique in litore conspicitur sus;<br>quam pius Aeneas tibi enim, tibi, maxima Iuno,<br>mactat sacra ferens et cum grege sistit ad aram.   85<br>Thybris ea fluuium, quam longa est, nocte tumentem<br>leniit, et tacita refluens ita substitit unda,<br>mitis ut in morem stagni placidaeque paludis<br>sterneret aequor aquis, remo ut luctamen abesset.<br>ergo iter inceptum celerant rumore secundo:   90<br>labitur uncta uadis abies; mirantur et undae,<br>miratur nemus insuetum fulgentia longe<br>scuta uirum fluuio pictasque innare carinas.<br>olli remigio noctemque diemque fatigant<br>et longos superant flexus, uariisque teguntur   95<br>arboribus, uiridisque secant placido aequore siluas.<br>sol medium caeli conscenderat igneus orbem<br>cum muros arcemque procul ac rara domorum<br>tecta uident, quae nunc Romana potentia caelo<br>aequauit, tum res inopes Euandrus habebat.   100<br>ocius aduertunt proras urbique propinquant.","st":"8"},{"sp":"N","t":"Forte die sollemnem illo rex Arcas honorem<br>Amphitryoniadae magno diuisque ferebat<br>ante urbem in luco. Pallas huic filius una,<br>una omnes iuuenum primi pauperque senatus   105<br>tura dabant, tepidusque cruor fumabat ad aras.<br>ut celsas uidere rates atque inter opacum<br>adlabi nemus et tacitos incumbere remis,<br>terrentur uisu subito cunctique relictis<br>consurgunt mensis. audax quos rumpere Pallas   110<br>sacra uetat raptoque uolat telo obuius ipse,<br>et procul e tumulo: ‘iuuenes, quae causa subegit<br>ignotas temptare uias? quo tenditis?’ inquit.<br>‘qui genus? unde domo? pacemne huc fertis an arma?’<br>tum pater Aeneas puppi sic fatur ab alta   115<br>paciferaeque manu ramum praetendit oliuae:<br>‘Troiugenas ac tela uides inimica Latinis,<br>quos illi bello profugos egere superbo.<br>Euandrum petimus. ferte haec et dicite lectos<br>Dardaniae uenisse duces socia arma rogantis.’    120<br>obstipuit tanto percussus nomine Pallas:<br>‘egredere o quicumque es’ ait ‘coramque parentem<br>adloquere ac nostris succede penatibus hospes.’<br>excepitque manu dextramque amplexus inhaesit;<br>progressi subeunt luco fluuiumque relinquunt.   125","st":"8"},{"sp":"N","t":"Tum regem Aeneas dictis adfatur amicis:<br>‘optime Graiugenum, cui me Fortuna precari<br>et uitta comptos uoluit praetendere ramos,<br>non equidem extimui Danaum quod ductor et Arcas<br>quodque a stirpe fores geminis coniunctus Atridis;   130<br>sed mea me uirtus et sancta oracula diuum<br>cognatique patres, tua terris didita fama,<br>coniunxere tibi et fatis egere uolentem.<br>Dardanus, Iliacae primus pater urbis et auctor,<br>Electra, ut Grai perhibent, Atlantide cretus,   135<br>aduehitur Teucros; Electram maximus Atlas<br>edidit, aetherios umero qui sustinet orbis.<br>uobis Mercurius pater est, quem candida Maia<br>Cyllenae gelido conceptum uertice fudit;<br>at Maiam, auditis si quicquam credimus, Atlas,   140<br>idem Atlas generat caeli qui sidera tollit.<br>sic genus amborum scindit se sanguine ab uno.<br>his fretus non legatos neque prima per artem<br>temptamenta tui pepigi; me, me ipse meumque<br>obieci caput et supplex ad limina ueni.   145<br>gens eadem, quae te, crudeli Daunia bello<br>insequitur; nos si pellant nihil afore credunt<br>quin omnem Hesperiam penitus sua sub iuga mittant,<br>et mare quod supra teneant quodque adluit infra.<br>accipe daque fidem. sunt nobis fortia bello   150<br>pectora, sunt animi et rebus spectata iuuentus.’","st":"8"},{"sp":"N","t":"Dixerat Aeneas. ille os oculosque loquentis<br>iamdudum et totum lustrabat lumine corpus.<br>tum sic pauca refert: ‘ut te, fortissime Teucrum,<br>accipio agnoscoque libens! ut uerba parentis   155<br>et uocem Anchisae magni uultumque recordor!<br>nam memini Hesionae uisentem regna sororis<br>Laomedontiaden Priamum Salamina petentem<br>protinus Arcadiae gelidos inuisere finis.<br>tum mihi prima genas uestibat flore iuuentas,   160<br>mirabarque duces Teucros, mirabar et ipsum<br>Laomedontiaden; sed cunctis altior ibat<br>Anchises. mihi mens iuuenali ardebat amore<br>compellare uirum et dextrae coniungere dextram;<br>accessi et cupidus Phenei sub moenia duxi.   165<br>ille mihi insignem pharetram Lyciasque sagittas<br>discedens chlamydemque auro dedit intertextam,<br>frenaque bina meus quae nunc habet aurea Pallas.<br>ergo et quam petitis iuncta est mihi foedere dextra,<br>et lux cum primum terris se crastina reddet,   170<br>auxilio laetos dimittam opibusque iuuabo.<br>interea sacra haec, quando huc uenistis amici,<br>annua, quae differre nefas, celebrate fauentes<br>nobiscum, et iam nunc sociorum adsuescite mensis.’","st":"8"},{"sp":"N","t":"Haec ubi dicta, dapes iubet et sublata reponi   175<br>pocula gramineoque uiros locat ipse sedili,<br>praecipuumque toro et uillosi pelle leonis<br>accipit Aenean solioque inuitat acerno.<br>tum lecti iuuenes certatim araeque sacerdos<br>uiscera tosta ferunt taurorum, onerantque canistris   180<br>dona laboratae Cereris, Bacchumque ministrant.<br>uescitur Aeneas simul et Troiana iuuentus<br>perpetui tergo bouis et lustralibus extis.","st":"8"},{"sp":"N","t":"Postquam exempta fames et amor compressus edendi,<br>rex Euandrus ait: ‘non haec sollemnia nobis,    185<br>has ex more dapes, hanc tanti numinis aram<br>uana superstitio ueterumque ignara deorum<br>imposuit: saeuis, hospes Troiane, periclis<br>seruati facimus meritosque nouamus honores.<br>iam primum saxis suspensam hanc aspice rupem,   190<br>disiectae procul ut moles desertaque montis<br>stat domus et scopuli ingentem traxere ruinam.<br>hic spelunca fuit uasto summota recessu,<br>semihominis Caci facies quam dira tenebat<br>solis inaccessam radiis; semperque recenti   195<br>caede tepebat humus, foribusque adfixa superbis<br>ora uirum tristi pendebant pallida tabo.<br>huic monstro Volcanus erat pater: illius atros<br>ore uomens ignis magna se mole ferebat.<br>attulit et nobis aliquando optantibus aetas   200<br>auxilium aduentumque dei. nam maximus ultor<br>tergemini nece Geryonae spoliisque superbus<br>Alcides aderat taurosque hac uictor agebat<br>ingentis, uallemque boues amnemque tenebant.<br>at furis Caci mens effera, ne quid inausum   205<br>aut intractatum scelerisue doliue fuisset,<br>quattuor a stabulis praestanti corpore tauros<br>auertit, totidem forma superante iuuencas.<br>atque hos, ne qua forent pedibus uestigia rectis,<br>cauda in speluncam tractos uersisque uiarum   210<br>indiciis raptor saxo occultabat opaco;<br>quaerenti nulla ad speluncam signa ferebant.<br>interea, cum iam stabulis saturata moueret<br>Amphitryoniades armenta abitumque pararet,<br>discessu mugire boues atque omne querelis    215<br>impleri nemus et colles clamore relinqui.<br>reddidit una boum uocem uastoque sub antro<br>mugiit et Caci spem custodita fefellit.<br>hic uero Alcidae furiis exarserat atro<br>felle dolor: rapit arma manu nodisque grauatum   220<br>robur, et aerii cursu petit ardua montis.<br>tum primum nostri Cacum uidere timentem<br>turbatumque oculis; fugit ilicet ocior Euro<br>speluncamque petit, pedibus timor addidit alas.<br>ut sese inclusit ruptisque immane catenis   225<br>deiecit saxum, ferro quod et arte paterna<br>pendebat, fultosque emuniit obice postis,<br>ecce furens animis aderat Tirynthius omnemque<br>accessum lustrans huc ora ferebat et illuc,<br>dentibus infrendens. ter totum feruidus ira   230<br>lustrat Auentini montem, ter saxea temptat<br>limina nequiquam, ter fessus ualle resedit.<br>stabat acuta silex praecisis undique saxis<br>speluncae dorso insurgens, altissima uisu,<br>dirarum nidis domus opportuna uolucrum.   235<br>hanc, ut prona iugo laeuum incumbebat ad amnem,<br>dexter in aduersum nitens concussit et imis<br>auulsam soluit radicibus, inde repente<br>impulit; impulsu quo maximus intonat aether,<br>dissultant ripae refluitque exterritus amnis.   240<br>at specus et Caci detecta apparuit ingens<br>regia, et umbrosae penitus patuere cauernae,<br>non secus ac si qua penitus ui terra dehiscens<br>infernas reseret sedes et regna recludat<br>pallida, dis inuisa, superque immane barathrum   245<br>cernatur, trepident immisso lumine Manes.<br>ergo insperata deprensum luce repente<br>inclusumque cauo saxo atque insueta rudentem<br>desuper Alcides telis premit, omniaque arma<br>aduocat et ramis uastisque molaribus instat.   250<br>ille autem, neque enim fuga iam super ulla pericli,<br>faucibus ingentem fumum (mirabile dictu)<br>euomit inuoluitque domum caligine caeca<br>prospectum eripiens oculis, glomeratque sub antro<br>fumiferam noctem commixtis igne tenebris.   255<br>non tulit Alcides animis, seque ipse per ignem<br>praecipiti iecit saltu, qua plurimus undam<br>fumus agit nebulaque ingens specus aestuat atra.<br>hic Cacum in tenebris incendia uana uomentem<br>corripit in nodum complexus, et angit inhaerens   260<br>elisos oculos et siccum sanguine guttur.<br>panditur extemplo foribus domus atra reuulsis<br>abstractaeque boues abiurataeque rapinae<br>caelo ostenduntur, pedibusque informe cadauer<br>protrahitur. nequeunt expleri corda tuendo   265<br>terribilis oculos, uultum uillosaque saetis<br>pectora semiferi atque exstinctos faucibus ignis.<br>ex illo celebratus honos laetique minores<br>seruauere diem, primusque Potitius auctor<br>et domus Herculei custos Pinaria sacri   270<br>hanc aram luco statuit, quae maxima semper<br>dicetur nobis et erit quae maxima semper.<br>quare agite, o iuuenes, tantarum in munere laudum<br>cingite fronde comas et pocula porgite dextris,","st":"8"},{"sp":"N","t":"communemque uocate deum et date uina uolentes.’   275<br>dixerat, Herculea bicolor cum populus umbra<br>uelauitque comas foliisque innexa pependit,<br>et sacer impleuit dextram scyphus. ocius omnes<br>in mensam laeti libant diuosque precantur.","st":"8"},{"sp":"N","t":"Deuexo interea propior fit Vesper Olympo.   280<br>iamque sacerdotes primusque Potitius ibant<br>pellibus in morem cincti, flammasque ferebant.<br>instaurant epulas et mensae grata secundae<br>dona ferunt cumulantque oneratis lancibus aras.<br>tum Salii ad cantus incensa altaria circum   285<br>populeis adsunt euincti tempora ramis,<br>hic iuuenum chorus, ille senum, qui carmine laudes<br>Herculeas et facta ferunt: ut prima nouercae<br>monstra manu geminosque premens eliserit anguis,<br>ut bello egregias idem disiecerit urbes,   290<br>Troiamque Oechaliamque, ut duros mille labores<br>rege sub Eurystheo fatis Iunonis iniquae<br>pertulerit. ‘tu nubigenas, inuicte, bimembris<br>Hylaeumque Pholumque manu, tu Cresia mactas<br>prodigia et uastum Nemeae sub rupe leonem.   295<br>te Stygii tremuere lacus, te ianitor Orci<br>ossa super recubans antro semesa cruento;<br>nec te ullae facies, non terruit ipse Typhoeus<br>arduus arma tenens; non te rationis egentem<br>Lernaeus turba capitum circumstetit anguis.   300<br>salue, uera Iouis proles, decus addite diuis,<br>et nos et tua dexter adi pede sacra secundo.’<br>talia carminibus celebrant; super omnia Caci<br>speluncam adiciunt spirantemque ignibus ipsum.<br>consonat omne nemus strepitu collesque resultant.   305","st":"8"},{"sp":"N","t":"Exim se cuncti diuinis rebus ad urbem<br>perfectis referunt. ibat rex obsitus aeuo,<br>et comitem Aenean iuxta natumque tenebat<br>ingrediens uarioque uiam sermone leuabat.<br>miratur facilisque oculos fert omnia circum   310<br>Aeneas, capiturque locis et singula laetus<br>exquiritque auditque uirum monimenta priorum.<br>tum rex Euandrus Romanae conditor arcis:<br>‘haec nemora indigenae Fauni Nymphaeque tenebant<br>gensque uirum truncis et duro robore nata,   315<br>quis neque mos neque cultus erat, nec iungere tauros<br>aut componere opes norant aut parcere parto,<br>sed rami atque asper uictu uenatus alebat.<br>primus ab aetherio uenit Saturnus Olympo<br>arma Iouis fugiens et regnis exsul ademptis.   320<br>is genus indocile ac dispersum montibus altis<br>composuit legesque dedit, Latiumque uocari<br>maluit, his quoniam latuisset tutus in oris.<br>aurea quae perhibent illo sub rege fuere<br>saecula: sic placida populos in pace regebat,   325<br>deterior donec paulatim ac decolor aetas<br>et belli rabies et amor successit habendi.<br>tum manus Ausonia et gentes uenere Sicanae,<br>saepius et nomen posuit Saturnia tellus;<br>tum reges asperque immani corpore Thybris,   330<br>a quo post Itali fluuium cognomine Thybrim<br>diximus; amisit uerum uetus Albula nomen.<br>me pulsum patria pelagique extrema sequentem<br>Fortuna omnipotens et ineluctabile fatum<br>his posuere locis, matrisque egere tremenda   335<br>Carmentis nymphae monita et deus auctor Apollo.’","st":"8"},{"sp":"N","t":"Vix ea dicta, dehinc progressus monstrat et aram<br>et Carmentalem Romani nomine portam<br>quam memorant, nymphae priscum Carmentis honorem,<br>uatis fatidicae, cecinit quae prima futuros   340<br>Aeneadas magnos et nobile Pallanteum.<br>hinc lucum ingentem, quem Romulus acer asylum<br>rettulit, et gelida monstrat sub rupe Lupercal<br>Parrhasio dictum Panos de more Lycaei.<br>nec non et sacri monstrat nemus Argileti   345<br>testaturque locum et letum docet hospitis Argi.<br>hinc ad Tarpeiam sedem et Capitolia ducit<br>aurea nunc, olim siluestribus horrida dumis.<br>iam tum religio pauidos terrebat agrestis<br>dira loci, iam tum siluam saxumque tremebant.   350<br>‘hoc nemus, hunc’ inquit ‘frondoso uertice collem<br>(quis deus incertum est) habitat deus; Arcades ipsum<br>credunt se uidisse Iouem, cum saepe nigrantem<br>aegida concuteret dextra nimbosque cieret.<br>haec duo praeterea disiectis oppida muris,   355<br>reliquias ueterumque uides monimenta uirorum.<br>hanc Ianus pater, hanc Saturnus condidit arcem;<br>Ianiculum huic, illi fuerat Saturnia nomen.’<br>talibus inter se dictis ad tecta subibant<br>pauperis Euandri, passimque armenta uidebant   360<br>Romanoque foro et lautis mugire Carinis.<br>ut uentum ad sedes, ‘haec’ inquit ‘limina uictor<br>Alcides subiit, haec illum regia cepit.<br>aude, hospes, contemnere opes et te quoque dignum<br>finge deo, rebusque ueni non asper egenis.’   365<br>dixit, et angusti subter fastigia tecti<br>ingentem Aenean duxit stratisque locauit<br>effultum foliis et pelle Libystidis ursae:<br>nox ruit et fuscis tellurem amplectitur alis.","st":"8"},{"sp":"N","t":"At Venus haud animo nequiquam exterrita mater   370<br>Laurentumque minis et duro mota tumultu<br>Volcanum adloquitur, thalamoque haec coniugis aureo<br>incipit et dictis diuinum aspirat amorem:<br>‘dum bello Argolici uastabant Pergama reges<br>debita casurasque inimicis ignibus arces,   375<br>non ullum auxilium miseris, non arma rogaui<br>artis opisque tuae, nec te, carissime coniunx,<br>incassumue tuos uolui exercere labores,<br>quamuis et Priami deberem plurima natis,<br>et durum Aeneae fleuissem saepe laborem.   380<br>nunc Iouis imperiis Rutulorum constitit oris:<br>ergo eadem supplex uenio et sanctum mihi numen<br>arma rogo, genetrix nato. te filia Nerei,<br>te potuit lacrimis Tithonia flectere coniunx.<br>aspice qui coeant populi, quae moenia clausis   385<br>ferrum acuant portis in me excidiumque meorum.’<br>dixerat et niueis hinc atque hinc diua lacertis<br>cunctantem amplexu molli fouet. ille repente<br>accepit solitam flammam, notusque medullas<br>intrauit calor et labefacta per ossa cucurrit,   390<br>non secus atque olim tonitru cum rupta corusco<br>ignea rima micans percurrit lumine nimbos;<br>sensit laeta dolis et formae conscia coniunx.<br>tum pater aeterno fatur deuinctus amore:<br>‘quid causas petis ex alto? fiducia cessit   395<br>quo tibi, diua, mei? similis si cura fuisset,<br>tum quoque fas nobis Teucros armare fuisset;<br>nec pater omnipotens Troiam nec fata uetabant<br>stare decemque alios Priamum superesse per annos.<br>et nunc, si bellare paras atque haec tibi mens est,   400<br>quidquid in arte mea possum promittere curae,<br>quod fieri ferro liquidoue potest electro,<br>quantum ignes animaeque ualent, absiste precando<br>uiribus indubitare tuis.’ ea uerba locutus<br>optatos dedit amplexus placidumque petiuit   405<br>coniugis infusus gremio per membra soporem.","st":"8"},{"sp":"N","t":"Inde ubi prima quies medio iam noctis abactae<br>curriculo expulerat somnum, cum femina primum,<br>cui tolerare colo uitam tenuique Minerua<br>impositum, cinerem et sopitos suscitat ignis   410<br>noctem addens operi, famulasque ad lumina longo<br>exercet penso, castum ut seruare cubile<br>coniugis et possit paruos educere natos:<br>haud secus ignipotens nec tempore segnior illo<br>mollibus e stratis opera ad fabrilia surgit.   415<br>insula Sicanium iuxta latus Aeoliamque<br>erigitur Liparen fumantibus ardua saxis,<br>quam subter specus et Cyclopum exesa caminis<br>antra Aetnaea tonant, ualidique incudibus ictus<br>auditi referunt gemitus, striduntque cauernis   420<br>stricturae Chalybum et fornacibus ignis anhelat,<br>Volcani domus et Volcania nomine tellus.<br>hoc tunc ignipotens caelo descendit ab alto.<br>ferrum exercebant uasto Cyclopes in antro,<br>Brontesque Steropesque et nudus membra Pyragmon.   425<br>his informatum manibus iam parte polita<br>fulmen erat, toto genitor quae plurima caelo<br>deicit in terras, pars imperfecta manebat.<br>tris imbris torti radios, tris nubis aquosae<br>addiderant, rutuli tris ignis et alitis Austri.   430<br>fulgores nunc terrificos sonitumque metumque<br>miscebant operi flammisque sequacibus iras.<br>parte alia Marti currumque rotasque uolucris<br>instabant, quibus ille uiros, quibus excitat urbes;<br>aegidaque horriferam, turbatae Palladis arma,   435<br>certatim squamis serpentum auroque polibant<br>conexosque anguis ipsamque in pectore diuae<br>Gorgona desecto uertentem lumina collo.<br>‘tollite cuncta’ inquit ‘coeptosque auferte labores,<br>Aetnaei Cyclopes, et huc aduertite mentem:   440<br>arma acri facienda uiro. nunc uiribus usus,<br>nunc manibus rapidis, omni nunc arte magistra.<br>praecipitate moras.’ nec plura effatus, at illi<br>ocius incubuere omnes pariterque laborem<br>sortiti. fluit aes riuis aurique metallum   445<br>uulnificusque chalybs uasta fornace liquescit.<br>ingentem clipeum informant, unum omnia contra<br>tela Latinorum, septenosque orbibus orbis<br>impediunt. alii uentosis follibus auras<br>accipiunt redduntque, alii stridentia tingunt   450<br>aera lacu; gemit impositis incudibus antrum;<br>illi inter sese multa ui bracchia tollunt<br>in numerum, uersantque tenaci forcipe massam.","st":"8"},{"sp":"N","t":"Haec pater Aeoliis properat dum Lemnius oris,<br>Euandrum ex humili tecto lux suscitat alma   455<br>et matutini uolucrum sub culmine cantus.<br>consurgit senior tunicaque inducitur artus<br>et Tyrrhena pedum circumdat uincula plantis.<br>tum lateri atque umeris Tegeaeum subligat ensem<br>demissa ab laeua pantherae terga retorquens.   460<br>nec non et gemini custodes limine ab alto<br>praecedunt gressumque canes comitantur erilem.<br>hospitis Aeneae sedem et secreta petebat<br>sermonum memor et promissi muneris heros.<br>nec minus Aeneas se matutinus agebat;   465<br>filius huic Pallas, illi comes ibat Achates.<br>congressi iungunt dextras mediisque residunt<br>aedibus et licito tandem sermone fruuntur.<br>rex prior haec:<br>‘maxime Teucrorum ductor, quo sospite numquam   470<br>res equidem Troiae uictas aut regna fatebor,<br>nobis ad belli auxilium pro nomine tanto<br>exiguae uires; hinc Tusco claudimur amni,<br>hinc Rutulus premit et murum circumsonat armis.<br>sed tibi ego ingentis populos opulentaque regnis   475<br>iungere castra paro, quam fors inopina salutem<br>ostentat: fatis huc te poscentibus adfers.<br>haud procul hinc saxo incolitur fundata uetusto<br>urbis Agyllinae sedes, ubi Lydia quondam<br>gens, bello praeclara, iugis insedit Etruscis.   480<br>hanc multos florentem annos rex deinde superbo<br>imperio et saeuis tenuit Mezentius armis.<br>quid memorem infandas caedes, quid facta tyranni<br>effera? di capiti ipsius generique reseruent!<br>mortua quin etiam iungebat corpora uiuis   485<br>componens manibusque manus atque oribus ora,<br>tormenti genus, et sanie taboque fluentis<br>complexu in misero longa sic morte necabat.<br>at fessi tandem ciues infanda furentem<br>armati circumsistunt ipsumque domumque,   490<br>obtruncant socios, ignem ad fastigia iactant.<br>ille inter caedem Rutulorum elapsus in agros<br>confugere et Turni defendier hospitis armis.<br>ergo omnis furiis surrexit Etruria iustis,<br>regem ad supplicium praesenti Marte reposcunt.   495<br>his ego te, Aenea, ductorem milibus addam.<br>toto namque fremunt condensae litore puppes<br>signaque ferre iubent, retinet longaeuus haruspex<br>fata canens: “o Maeoniae delecta iuuentus,<br>flos ueterum uirtusque uirum, quos iustus in hostem   500<br>fert dolor et merita accendit Mezentius ira,<br>nulli fas Italo tantam subiungere gentem:<br>externos optate duces.” tum Etrusca resedit<br>hoc acies campo monitis exterrita diuum.<br>ipse oratores ad me regnique coronam   505<br>cum sceptro misit mandatque insignia Tarchon,<br>succedam castris Tyrrhenaque regna capessam.<br>sed mihi tarda gelu saeclisque effeta senectus<br>inuidet imperium seraeque ad fortia uires.<br>natum exhortarer, ni mixtus matre Sabella   510<br>hinc partem patriae traheret. tu, cuius et annis<br>et generi fatum indulget, quem numina poscunt,<br>ingredere, o Teucrum atque Italum fortissime ductor.<br>hunc tibi praeterea, spes et solacia nostri,<br>Pallanta adiungam; sub te tolerare magistro   515<br>militiam et graue Martis opus, tua cernere facta<br>adsuescat, primis et te miretur ab annis.<br>Arcadas huic equites bis centum, robora pubis<br>lecta dabo, totidemque suo tibi nomine Pallas.’","st":"8"},{"sp":"N","t":"Vix ea fatus erat, defixique ora tenebant   520<br>Aeneas Anchisiades et fidus Achates,<br>multaque dura suo tristi cum corde putabant,<br>ni signum caelo Cytherea dedisset aperto.<br>namque improuiso uibratus ab aethere fulgor<br>cum sonitu uenit et ruere omnia uisa repente,   525<br>Tyrrhenusque tubae mugire per aethera clangor.<br>suspiciunt, iterum atque iterum fragor increpat ingens.<br>arma inter nubem caeli in regione serena<br>per sudum rutilare uident et pulsa tonare.<br>obstipuere animis alii, sed Troius heros   530<br>agnouit sonitum et diuae promissa parentis.<br>tum memorat: ‘ne uero, hospes, ne quaere profecto<br>quem casum portenta ferant: ego poscor Olympo.<br>hoc signum cecinit missuram diua creatrix,<br>si bellum ingrueret, Volcaniaque arma per auras   535<br>laturam auxilio.<br>heu quantae miseris caedes Laurentibus instant!<br>quas poenas mihi, Turne, dabis! quam multa sub undas<br>scuta uirum galeasque et fortia corpora uolues,<br>Thybri pater! poscant acies et foedera rumpant.’   540","st":"8"},{"sp":"N","t":"Haec ubi dicta dedit, solio se tollit ab alto<br>et primum Herculeis sopitas ignibus aras<br>excitat, hesternumque larem paruosque penatis<br>laetus adit; mactat lectas de more bidentis<br>Euandrus pariter, pariter Troiana iuuentus.   545<br>post hinc ad nauis graditur sociosque reuisit,<br>quorum de numero qui sese in bella sequantur<br>praestantis uirtute legit; pars cetera prona<br>fertur aqua segnisque secundo defluit amni,<br>nuntia uentura Ascanio rerumque patrisque.   550<br>dantur equi Teucris Tyrrhena petentibus arua;<br>ducunt exsortem Aeneae, quem fulua leonis<br>pellis obit totum praefulgens unguibus aureis.","st":"8"},{"sp":"N","t":"Fama uolat paruam subito uulgata per urbem<br>ocius ire equites Tyrrheni ad limina regis.   555<br>uota metu duplicant matres, propiusque periclo<br>it timor et maior Martis iam apparet imago.<br>tum pater Euandrus dextram complexus euntis<br>haeret inexpletus lacrimans ac talia fatur:<br>‘o mihi praeteritos referat si Iuppiter annos,   560<br>qualis eram cum primam aciem Praeneste sub ipsa<br>straui scutorumque incendi uictor aceruos<br>et regem hac Erulum dextra sub Tartara misi,<br>nascenti cui tris animas Feronia mater<br>(horrendum dictu) dederat, terna arma mouenda — 565<br>ter leto sternendus erat; cui tunc tamen omnis<br>abstulit haec animas dextra et totidem exuit armis:<br>non ego nunc dulci amplexu diuellerer usquam,<br>nate, tuo, neque finitimo Mezentius umquam<br>huic capiti insultans tot ferro saeua dedisset   570<br>funera, tam multis uiduasset ciuibus urbem.<br>at uos, o superi, et diuum tu maxime rector<br>Iuppiter, Arcadii, quaeso, miserescite regis<br>et patrias audite preces. si numina uestra<br>incolumem Pallanta mihi, si fata reseruant,   575<br>si uisurus eum uiuo et uenturus in unum,<br>uitam oro, patior quemuis durare laborem.<br>sin aliquem infandum casum, Fortuna, minaris,<br>nunc, nunc o liceat crudelem abrumpere uitam,<br>dum curae ambiguae, dum spes incerta futuri,   580<br>dum te, care puer, mea sola et sera uoluptas,<br>complexu teneo, grauior neu nuntius auris<br>uulneret.’ haec genitor digressu dicta supremo<br>fundebat; famuli conlapsum in tecta ferebant.","st":"8"},{"sp":"N","t":"Iamque adeo exierat portis equitatus apertis   585<br>Aeneas inter primos et fidus Achates,<br>inde alii Troiae proceres; ipse agmine Pallas<br>it medio chlamyde et pictis conspectus in armis,<br>qualis ubi Oceani perfusus Lucifer unda,<br>quem Venus ante alios astrorum diligit ignis,   590<br>extulit os sacrum caelo tenebrasque resoluit.<br>stant pauidae in muris matres oculisque sequuntur<br>pulueream nubem et fulgentis aere cateruas.<br>olli per dumos, qua proxima meta uiarum,<br>armati tendunt; it clamor, et agmine facto   595<br>quadripedante putrem sonitu quatit ungula campum.<br>est ingens gelidum lucus prope Caeritis amnem,<br>religione patrum late sacer; undique colles<br>inclusere caui et nigra nemus abiete cingunt.<br>Siluano fama est ueteres sacrasse Pelasgos,   600<br>aruorum pecorisque deo, lucumque diemque,<br>qui primi finis aliquando habuere Latinos.<br>haud procul hinc Tarcho et Tyrrheni tuta tenebant<br>castra locis, celsoque omnis de colle uideri<br>iam poterat legio et latis tendebat in aruis.   605<br>huc pater Aeneas et bello lecta iuuentus<br>succedunt, fessique et equos et corpora curant.","st":"8"},{"sp":"N","t":"At Venus aetherios inter dea candida nimbos<br>dona ferens aderat; natumque in ualle reducta<br>ut procul egelido secretum flumine uidit,   610<br>talibus adfata est dictis seque obtulit ultro:<br>‘en perfecta mei promissa coniugis arte<br>munera. ne mox aut Laurentis, nate, superbos<br>aut acrem dubites in proelia poscere Turnum.’<br>dixit, et amplexus nati Cytherea petiuit,   615<br>arma sub aduersa posuit radiantia quercu.<br>ille deae donis et tanto laetus honore<br>expleri nequit atque oculos per singula uoluit,<br>miraturque interque manus et bracchia uersat<br>terribilem cristis galeam flammasque uomentem,   620<br>fatiferumque ensem, loricam ex aere rigentem,<br>sanguineam, ingentem, qualis cum caerula nubes<br>solis inardescit radiis longeque refulget;<br>tum leuis ocreas electro auroque recocto,<br>hastamque et clipei non enarrabile textum.   625<br>illic res Italas Romanorumque triumphos<br>haud uatum ignarus uenturique inscius aeui<br>fecerat ignipotens, illic genus omne futurae<br>stirpis ab Ascanio pugnataque in ordine bella.<br>fecerat et uiridi fetam Mauortis in antro   630<br>procubuisse lupam, geminos huic ubera circum<br>ludere pendentis pueros et lambere matrem<br>impauidos, illam tereti ceruice reflexa<br>mulcere alternos et corpora fingere lingua.<br>nec procul hinc Romam et raptas sine more Sabinas   635<br>consessu caueae, magnis Circensibus actis,<br>addiderat, subitoque nouum consurgere bellum<br>Romulidis Tatioque seni Curibusque seueris.<br>post idem inter se posito certamine reges<br>armati Iouis ante aram paterasque tenentes   640<br>stabant et caesa iungebant foedera porca.<br>haud procul inde citae Mettum in diuersa quadrigae<br>distulerant (at tu dictis, Albane, maneres!),<br>raptabatque uiri mendacis uiscera Tullus<br>per siluam, et sparsi rorabant sanguine uepres.   645<br>nec non Tarquinium eiectum Porsenna iubebat<br>accipere ingentique urbem obsidione premebat;<br>Aeneadae in ferrum pro libertate ruebant.<br>illum indignanti similem similemque minanti<br>aspiceres, pontem auderet quia uellere Cocles   650<br>et fluuium uinclis innaret Cloelia ruptis.<br>in summo custos Tarpeiae Manlius arcis<br>stabat pro templo et Capitolia celsa tenebat,<br>Romuleoque recens horrebat regia culmo.<br>atque hic auratis uolitans argenteus anser   655<br>porticibus Gallos in limine adesse canebat;<br>Galli per dumos aderant arcemque tenebant<br>defensi tenebris et dono noctis opacae.<br>aurea caesaries ollis atque aurea uestis,<br>uirgatis lucent sagulis, tum lactea colla   660<br>auro innectuntur, duo quisque Alpina coruscant<br>gaesa manu, scutis protecti corpora longis.<br>hic exsultantis Salios nudosque Lupercos<br>lanigerosque apices et lapsa ancilia caelo<br>extuderat, castae ducebant sacra per urbem   665<br>pilentis matres in mollibus. hinc procul addit<br>Tartareas etiam sedes, alta ostia Ditis,<br>et scelerum poenas, et te, Catilina, minaci<br>pendentem scopulo Furiarumque ora trementem,<br>secretosque pios, his dantem iura Catonem.   670<br>haec inter tumidi late maris ibat imago<br>aurea, sed fluctu spumabant caerula cano,<br>et circum argento clari delphines in orbem<br>aequora uerrebant caudis aestumque secabant.<br>in medio classis aeratas, Actia bella,   675<br>cernere erat, totumque instructo Marte uideres<br>feruere Leucaten auroque effulgere fluctus.<br>hinc Augustus agens Italos in proelia Caesar<br>cum patribus populoque, penatibus et magnis dis,<br>stans celsa in puppi, geminas cui tempora flammas   680<br>laeta uomunt patriumque aperitur uertice sidus.<br>parte alia uentis et dis Agrippa secundis<br>arduus agmen agens, cui, belli insigne superbum,<br>tempora nauali fulgent rostrata corona.<br>hinc ope barbarica uariisque Antonius armis,   685<br>uictor ab Aurorae populis et litore rubro,<br>Aegyptum uirisque Orientis et ultima secum<br>Bactra uehit, sequiturque (nefas) Aegyptia coniunx.<br>una omnes ruere ac totum spumare reductis<br>conuulsum remis rostrisque tridentibus aequor.    690<br>alta petunt; pelago credas innare reuulsas<br>Cycladas aut montis concurrere montibus altos,<br>tanta mole uiri turritis puppibus instant.<br>stuppea flamma manu telisque uolatile ferrum<br>spargitur, arua noua Neptunia caede rubescunt.   695<br>regina in mediis patrio uocat agmina sistro,<br>necdum etiam geminos a tergo respicit anguis.<br>omnigenumque deum monstra et latrator Anubis","st":"8"},{"sp":"N","t":"contra Neptunum et Venerem contraque Mineruam<br>tela tenent. saeuit medio in certamine Mauors   700<br>caelatus ferro, tristesque ex aethere Dirae,<br>et scissa gaudens uadit Discordia palla,<br>quam cum sanguineo sequitur Bellona flagello.<br>Actius haec cernens arcum intendebat Apollo<br>desuper; omnis eo terrore Aegyptus et Indi,   705<br>omnis Arabs, omnes uertebant terga Sabaei.<br>ipsa uidebatur uentis regina uocatis<br>uela dare et laxos iam iamque immittere funis.<br>illam inter caedes pallentem morte futura<br>fecerat ignipotens undis et Iapyge ferri,   710<br>contra autem magno maerentem corpore Nilum<br>pandentemque sinus et tota ueste uocantem<br>caeruleum in gremium latebrosaque flumina uictos.<br>at Caesar, triplici inuectus Romana triumpho<br>moenia, dis Italis uotum immortale sacrabat,   715<br>maxima ter centum totam delubra per urbem.<br>laetitia ludisque uiae plausuque fremebant;<br>omnibus in templis matrum chorus, omnibus arae;<br>ante aras terram caesi strauere iuuenci.<br>ipse sedens niueo candentis limine Phoebi   720<br>dona recognoscit populorum aptatque superbis<br>postibus; incedunt uictae longo ordine gentes,<br>quam uariae linguis, habitu tam uestis et armis.<br>hic Nomadum genus et discinctos Mulciber Afros,<br>hic Lelegas Carasque sagittiferosque Gelonos   725<br>finxerat; Euphrates ibat iam mollior undis,<br>extremique hominum Morini, Rhenusque bicornis,<br>indomitique Dahae, et pontem indignatus Araxes.","st":"8"},{"sp":"N","t":"Talia per clipeum Volcani, dona parentis,<br>miratur rerumque ignarus imagine gaudet   730<br>attollens umero famamque et fata nepotum.","st":"8"},{"sp":"HDR","t":"Liber IX","st":"9"},{"sp":"N","t":"Atque ea diuersa penitus dum parte geruntur,<br>Irim de caelo misit Saturnia Iuno<br>audacem ad Turnum. luco tum forte parentis<br>Pilumni Turnus sacrata ualle sedebat.<br>ad quem sic roseo Thaumantias ore locuta est:   5<br>‘Turne, quod optanti diuum promittere nemo<br>auderet, uoluenda dies en attulit ultro.<br>Aeneas urbe et sociis et classe relicta<br>sceptra Palatini sedemque petit Euandri.<br>nec satis: extremas Corythi penetrauit ad urbes   10<br>Lydorumque manum, collectos armat agrestis.<br>quid dubitas? nunc tempus equos, nunc poscere currus.<br>rumpe moras omnis et turbata arripe castra.’<br>dixit, et in caelum paribus se sustulit alis<br>ingentemque fuga secuit sub nubibus arcum.   15<br>agnouit iuuenis duplicisque ad sidera palmas<br>sustulit ac tali fugientem est uoce secutus:<br>‘Iri, decus caeli, quis te mihi nubibus actam<br>detulit in terras? unde haec tam clara repente<br>tempestas? medium uideo discedere caelum   20<br>palantisque polo stellas. sequor omina tanta,<br>quisquis in arma uocas.’ et sic effatus ad undam<br>processit summoque hausit de gurgite lymphas<br>multa deos orans, onerauitque aethera uotis.","st":"9"},{"sp":"N","t":"Iamque omnis campis exercitus ibat apertis   25<br>diues equum, diues pictai uestis et auri;<br>Messapus primas acies, postrema coercent<br>Tyrrhidae iuuenes, medio dux agmine Turnus:<br>ceu septem surgens sedatis amnibus altus   30<br>per tacitum Ganges aut pingui flumine Nilus<br>cum refluit campis et iam se condidit alueo.<br>hic subitam nigro glomerari puluere nubem<br>prospiciunt Teucri ac tenebras insurgere campis.<br>primus ab aduersa conclamat mole Caicus:   35<br>‘quis globus, o ciues, caligine uoluitur atra?<br>ferte citi ferrum, date tela, ascendite muros,<br>hostis adest, heia!’ ingenti clamore per omnis<br>condunt se Teucri portas et moenia complent.<br>namque ita discedens praeceperat optimus armis   40<br>Aeneas: si qua interea fortuna fuisset,<br>neu struere auderent aciem neu credere campo;<br>castra modo et tutos seruarent aggere muros.<br>ergo etsi conferre manum pudor iraque monstrat,<br>obiciunt portas tamen et praecepta facessunt,   45<br>armatique cauis exspectant turribus hostem.","st":"9"},{"sp":"N","t":"Turnus, ut ante uolans tardum praecesserat agmen<br>uiginti lectis equitum comitatus et urbi<br>improuisus adest, maculis quem Thracius albis<br>portat equus cristaque tegit galea aurea rubra,   50<br>‘ecquis erit mecum, iuuenes, qui primus in hostem — ?<br>en,’ ait et iaculum attorquens emittit in auras,<br>principium pugnae, et campo sese arduus infert.<br>clamorem excipiunt socii fremituque sequuntur<br>horrisono; Teucrum mirantur inertia corda,    55<br>non aequo dare se campo, non obuia ferre<br>arma uiros, sed castra fouere. huc turbidus atque huc<br>lustrat equo muros aditumque per auia quaerit.<br>ac ueluti pleno lupus insidiatus ouili<br>cum fremit ad caulas uentos perpessus et imbris   60<br>nocte super media; tuti sub matribus agni<br>balatum exercent, ille asper et improbus ira<br>saeuit in absentis; collecta fatigat edendi<br>ex longo rabies et siccae sanguine fauces:<br>haud aliter Rutulo muros et castra tuenti   65<br>ignescunt irae, duris dolor ossibus ardet.<br>qua temptet ratione aditus, et quae uia clausos<br>excutiat Teucros uallo atque effundat in aequum?<br>classem, quae lateri castrorum adiuncta latebat,<br>aggeribus saeptam circum et fluuialibus undis,   70<br>inuadit sociosque incendia poscit ouantis<br>atque manum pinu flagranti feruidus implet.<br>tum uero incumbunt (urget praesentia Turni),<br>atque omnis facibus pubes accingitur atris.<br>diripuere focos: piceum fert fumida lumen   75<br>taeda et commixtam Volcanus ad astra fauillam.","st":"9"},{"sp":"N","t":"Quis deus, o Musae, tam saeua incendia Teucris<br>auertit? tantos ratibus quis depulit ignis?<br>dicite: prisca fides facto, sed fama perennis.<br>tempore quo primum Phrygia formabat in Ida   80<br>Aeneas classem et pelagi petere alta parabat,<br>ipsa deum fertur genetrix Berecyntia magnum<br>uocibus his adfata Iouem: ‘da, nate, petenti,<br>quod tua cara parens domito te poscit Olympo.<br>pinea silua mihi multos dilecta per annos,   85<br>lucus in arce fuit summa, quo sacra ferebant,<br>nigranti picea trabibusque obscurus acernis.<br>has ego Dardanio iuueni, cum classis egeret,<br>laeta dedi; nunc sollicitam timor anxius angit.<br>solue metus atque hoc precibus sine posse parentem,   90<br>ne cursu quassatae ullo neu turbine uenti<br>uincantur: prosit nostris in montibus ortas.’<br>filius huic contra, torquet qui sidera mundi:<br>‘o genetrix, quo fata uocas? aut quid petis istis?<br>mortaline manu factae immortale carinae   95<br>fas habeant? certusque incerta pericula lustret<br>Aeneas? cui tanta deo permissa potestas?<br>immo, ubi defunctae finem portusque tenebunt<br>Ausonios olim, quaecumque euaserit undis<br>Dardaniumque ducem Laurentia uexerit arua,   100<br>mortalem eripiam formam magnique iubebo<br>aequoris esse deas, qualis Nereia Doto<br>et Galatea secant spumantem pectore pontum.’<br>dixerat idque ratum Stygii per flumina fratris,<br>per pice torrentis atraque uoragine ripas   105<br>adnuit, et totum nutu tremefecit Olympum.","st":"9"},{"sp":"N","t":"Ergo aderat promissa dies et tempora Parcae<br>debita complerant, cum Turni iniuria Matrem<br>admonuit ratibus sacris depellere taedas.<br>hic primum noua lux oculis offulsit et ingens   110<br>uisus ab Aurora caelum transcurrere nimbus<br>Idaeique chori; tum uox horrenda per auras<br>excidit et Troum Rutulorumque agmina complet:<br>‘ne trepidate meas, Teucri, defendere nauis<br>neue armate manus; maria ante exurere Turno   115<br>quam sacras dabitur pinus. uos ite solutae,<br>ite deae pelagi; genetrix iubet.’ et sua quaeque<br>continuo puppes abrumpunt uincula ripis<br>delphinumque modo demersis aequora rostris<br>ima petunt. hinc uirgineae (mirabile monstrum)   120<br>reddunt se totidem facies pontoque feruntur.   122","st":"9"},{"sp":"N","t":"Obstipuere animis Rutuli, conterritus ipse<br>turbatis Messapus equis, cunctatur et amnis<br>rauca sonans reuocatque pedem Tiberinus ab alto.   125<br>at non audaci Turno fiducia cessit;<br>ultro animos tollit dictis atque increpat ultro:<br>‘Troianos haec monstra petunt, his Iuppiter ipse<br>auxilium solitum eripuit: non tela neque ignis<br>exspectant Rutulos. ergo maria inuia Teucris,   130<br>nec spes ulla fugae: rerum pars altera adempta est,<br>terra autem in nostris manibus, tot milia gentes<br>arma ferunt Italae. nil me fatalia terrent,<br>si qua Phryges prae se iactant, responsa deorum;<br>sat fatis Venerique datum, tetigere quod arua   135<br>fertilis Ausoniae Troes. sunt et mea contra<br>fata mihi, ferro sceleratam exscindere gentem<br>coniuge praerepta; nec solos tangit Atridas<br>iste dolor, solisque licet capere arma Mycenis.<br>“sed periisse semel satis est”: peccare fuisset   140<br>ante satis, penitus modo non genus omne perosos<br>femineum. quibus haec medii fiducia ualli<br>fossarumque morae, leti discrimina parua,<br>dant animos; at non uiderunt moenia Troiae<br>Neptuni fabricata manu considere in ignis?   145<br>sed uos, o lecti, ferro qui scindere uallum<br>apparat et mecum inuadit trepidantia castra?<br>non armis mihi Volcani, non mille carinis<br>est opus in Teucros. addant se protinus omnes<br>Etrusci socios. tenebras et inertia furta   150<br>Palladii caesis late custodibus arcis<br>ne timeant, nec equi caeca condemur in aluo:<br>luce palam certum est igni circumdare muros.<br>haud sibi cum Danais rem faxo et pube Pelasga<br>esse ferant, decimum quos distulit Hector in annum.   155<br>nunc adeo, melior quoniam pars acta diei,<br>quod superest, laeti bene gestis corpora rebus<br>procurate, uiri, et pugnam sperate parari.’<br>interea uigilum excubiis obsidere portas<br>cura datur Messapo et moenia cingere flammis.   160<br>bis septem Rutuli muros qui milite seruent<br>delecti, ast illos centeni quemque sequuntur<br>purpurei cristis iuuenes auroque corusci.<br>discurrunt uariantque uices, fusique per herbam<br>indulgent uino et uertunt crateras aenos.   165<br>conlucent ignes, noctem custodia ducit<br>insomnem ludo.","st":"9"},{"sp":"N","t":"Haec super e uallo prospectant Troes et armis<br>alta tenent, nec non trepidi formidine portas<br>explorant pontisque et propugnacula iungunt,   170<br>tela gerunt. instat Mnestheus acerque Serestus,<br>quos pater Aeneas, si quando aduersa uocarent,<br>rectores iuuenum et rerum dedit esse magistros.<br>omnis per muros legio sortita periclum<br>excubat exercetque uices, quod cuique tuendum est.   175","st":"9"},{"sp":"N","t":"Nisus erat portae custos, acerrimus armis,<br>Hyrtacides, comitem Aeneae quem miserat Ida<br>uenatrix iaculo celerem leuibusque sagittis,<br>et iuxta comes Euryalus, quo pulchrior alter<br>non fuit Aeneadum Troiana neque induit arma,   180<br>ora puer prima signans intonsa iuuenta.<br>his amor unus erat pariterque in bella ruebant;<br>tum quoque communi portam statione tenebant.<br>Nisus ait: ‘dine hunc ardorem mentibus addunt,<br>Euryale, an sua cuique deus fit dira cupido?   185<br>aut pugnam aut aliquid iamdudum inuadere magnum<br>mens agitat mihi, nec placida contenta quiete est.<br>cernis quae Rutulos habeat fiducia rerum:<br>lumina rara micant, somno uinoque soluti<br>procubuere, silent late loca. percipe porro   190<br>quid dubitem et quae nunc animo sententia surgat.<br>Aenean acciri omnes, populusque patresque,<br>exposcunt, mittique uiros qui certa reportent.<br>si tibi quae posco promittunt (nam mihi facti<br>fama sat est), tumulo uideor reperire sub illo   195<br>posse uiam ad muros et moenia Pallantea.’<br>obstipuit magno laudum percussus amore<br>Euryalus, simul his ardentem adfatur amicum:<br>‘mene igitur socium summis adiungere rebus,<br>Nise, fugis? solum te in tanta pericula mittam?   200<br>non ita me genitor, bellis adsuetus Opheltes,<br>Argolicum terrorem inter Troiaeque labores<br>sublatum erudiit, nec tecum talia gessi<br>magnanimum Aenean et fata extrema secutus:<br>est hic, est animus lucis contemptor et istum   205<br>qui uita bene credat emi, quo tendis, honorem.’<br>Nisus ad haec: ‘equidem de te nil tale uerebar,<br>nec fas; non ita me referat tibi magnus ouantem<br>Iuppiter aut quicumque oculis haec aspicit aequis.<br>sed si quis (quae multa uides discrimine tali)    210<br>si quis in aduersum rapiat casusue deusue,<br>te superesse uelim, tua uita dignior aetas.<br>sit qui me raptum pugna pretioue redemptum<br>mandet humo, solita aut si qua id Fortuna uetabit,<br>absenti ferat inferias decoretque sepulcro.   215<br>neu matri miserae tanti sim causa doloris,<br>quae te sola, puer, multis e matribus ausa<br>persequitur, magni nec moenia curat Acestae.’<br>ille autem: ‘causas nequiquam nectis inanis<br>nec mea iam mutata loco sententia cedit.   220<br>acceleremus’ ait, uigiles simul excitat. illi<br>succedunt seruantque uices; statione relicta<br>ipse comes Niso graditur regemque requirunt.","st":"9"},{"sp":"N","t":"Cetera per terras omnis animalia somno<br>laxabant curas et corda oblita laborum:   225<br>ductores Teucrum primi, delecta iuuentus,<br>consilium summis regni de rebus habebant,<br>quid facerent quisue Aeneae iam nuntius esset.<br>stant longis adnixi hastis et scuta tenentes<br>castrorum et campi medio. tum Nisus et una   230<br>Euryalus confestim alacres admittier orant:<br>rem magnam pretiumque morae fore. primus Iulus<br>accepit trepidos ac Nisum dicere iussit.<br>tum sic Hyrtacides: ‘audite o mentibus aequis<br>Aeneadae, neue haec nostris spectentur ab annis   235<br>quae ferimus. Rutuli somno uinoque soluti<br>conticuere. locum insidiis conspeximus ipsi,<br>qui patet in biuio portae quae proxima ponto.<br>interrupti ignes aterque ad sidera fumus<br>erigitur. si fortuna permittitis uti   240<br>quaesitum Aenean et moenia Pallantea,<br>mox hic cum spoliis ingenti caede peracta<br>adfore cernetis. nec nos uia fallit euntis:<br>uidimus obscuris primam sub uallibus urbem<br>uenatu adsiduo et totum cognouimus amnem.’   245<br>hic annis grauis atque animi maturus Aletes:<br>‘di patrii, quorum semper sub numine Troia est,<br>non tamen omnino Teucros delere paratis,<br>cum talis animos iuuenum et tam certa tulistis<br>pectora.’ sic memorans umeros dextrasque tenebat   250<br>amborum et uultum lacrimis atque ora rigabat.<br>‘quae uobis, quae digna, uiri, pro laudibus istis<br>praemia posse rear solui? pulcherrima primum<br>di moresque dabunt uestri: tum cetera reddet<br>actutum pius Aeneas atque integer aeui   255<br>Ascanius meriti tanti non immemor umquam.’<br>‘immo ego uos, cui sola salus genitore reducto,’<br>excipit Ascanius ‘per magnos, Nise, penatis<br>Assaracique larem et canae penetralia Vestae<br>obtestor, quaecumque mihi fortuna fidesque est,   260<br>in uestris pono gremiis. reuocate parentem,<br>reddite conspectum; nihil illo triste recepto.<br>bina dabo argento perfecta atque aspera signis<br>pocula, deuicta genitor quae cepit Arisba,<br>et tripodas geminos, auri duo magna talenta,   265<br>cratera antiquum quem dat Sidonia Dido.<br>si uero capere Italiam sceptrisque potiri<br>contigerit uictori et praedae dicere sortem,<br>uidisti, quo Turnus equo, quibus ibat in armis<br>aureus; ipsum illum, clipeum cristasque rubentis   270<br>excipiam sorti, iam nunc tua praemia, Nise.<br>praeterea bis sex genitor lectissima matrum<br>corpora captiuosque dabit suaque omnibus arma,<br>insuper his campi quod rex habet ipse Latinus.<br>te uero, mea quem spatiis propioribus aetas   275<br>insequitur, uenerande puer, iam pectore toto<br>accipio et comitem casus complector in omnis.<br>nulla meis sine te quaeretur gloria rebus:<br>seu pacem seu bella geram, tibi maxima rerum<br>uerborumque fides.’ contra quem talia fatur   280<br>Euryalus: ‘me nulla dies tam fortibus ausis<br>dissimilem arguerit; tantum fortuna secunda<br>haud aduersa cadat. sed te super omnia dona<br>unum oro: genetrix Priami de gente uetusta<br>est mihi, quam miseram tenuit non Ilia tellus   285<br>mecum excedentem, non moenia regis Acestae.<br>hanc ego nunc ignaram huius quodcumque pericli<br>inque salutatam linquo (nox et tua testis<br>dextera), quod nequeam lacrimas perferre parentis.<br>at tu, oro, solare inopem et succurre relictae.   290<br>hanc sine me spem ferre tui, audentior ibo<br>in casus omnis.’ percussa mente dedere<br>Dardanidae lacrimas, ante omnis pulcher Iulus,<br>atque animum patriae strinxit pietatis imago.<br>tum sic effatur:            295<br>‘sponde digna tuis ingentibus omnia coeptis.<br>namque erit ista mihi genetrix nomenque Creusae<br>solum defuerit, nec partum gratia talem<br>parua manet. casus factum quicumque sequentur,<br>per caput hoc iuro, per quod pater ante solebat:   300<br>quae tibi polliceor reduci rebusque secundis,<br>haec eadem matrique tuae generique manebunt.’<br>sic ait inlacrimans; umero simul exuit ensem<br>auratum, mira quem fecerat arte Lycaon<br>Cnosius atque habilem uagina aptarat eburna.   305<br>dat Niso Mnestheus pellem horrentisque leonis<br>exuuias, galeam fidus permutat Aletes.<br>protinus armati incedunt; quos omnis euntis<br>primorum manus ad portas, iuuenumque senumque,<br>prosequitur uotis. nec non et pulcher Iulus,   310<br>ante annos animumque gerens curamque uirilem,<br>multa patri mandata dabat portanda; sed aurae<br>omnia discerpunt et nubibus inrita donant.","st":"9"},{"sp":"N","t":"Egressi superant fossas noctisque per umbram<br>castra inimica petunt, multis tamen ante futuri   315<br>exitio. passim somno uinoque per herbam<br>corpora fusa uident, arrectos litore currus,<br>inter lora rotasque uiros, simul arma iacere,<br>uina simul. prior Hyrtacides sic ore locutus:<br>‘Euryale, audendum dextra: nunc ipsa uocat res.   320<br>hac iter est. tu, ne qua manus se attollere nobis<br>a tergo possit, custodi et consule longe;<br>haec ego uasta dabo et lato te limite ducam.’<br>sic memorat uocemque premit, simul ense superbum<br>Rhamnetem adgreditur, qui forte tapetibus altis   325<br>exstructus toto proflabat pectore somnum,<br>rex idem et regi Turno gratissimus augur,<br>sed non augurio potuit depellere pestem.<br>tris iuxta famulos temere inter tela iacentis<br>armigerumque Remi premit aurigamque sub ipsis   330<br>nactus equis ferroque secat pendentia colla.<br>tum caput ipsi aufert domino truncumque relinquit<br>sanguine singultantem; atro tepefacta cruore<br>terra torique madent. nec non Lamyrumque Lamumque<br>et iuuenem Serranum, illa qui plurima nocte   335<br>luserat, insignis facie, multoque iacebat<br>membra deo uictus — felix, si protinus illum<br>aequasset nocti ludum in lucemque tulisset:<br>impastus ceu plena leo per ouilia turbans<br>(suadet enim uesana fames) manditque trahitque   340<br>molle pecus mutumque metu, fremit ore cruento.<br>nec minor Euryali caedes; incensus et ipse<br>perfurit ac multam in medio sine nomine plebem,<br>Fadumque Herbesumque subit Rhoetumque Abarimque<br>ignaros; Rhoetum uigilantem et cuncta uidentem,   345<br>sed magnum metuens se post cratera tegebat.<br>pectore in aduerso totum cui comminus ensem<br>condidit adsurgenti et multa morte recepit.<br>purpuream uomit ille animam et cum sanguine mixta<br>uina refert moriens, hic furto feruidus instat.   350<br>iamque ad Messapi socios tendebat; ibi ignem<br>deficere extremum et religatos rite uidebat<br>carpere gramen equos, breuiter cum talia Nisus<br>(sensit enim nimia caede atque cupidine ferri)<br>‘absistamus’ ait, ‘nam lux inimica propinquat.   355<br>poenarum exhaustum satis est, uia facta per hostis.’<br>multa uirum solido argento perfecta relinquunt<br>armaque craterasque simul pulchrosque tapetas.<br>Euryalus phaleras Rhamnetis et aurea bullis<br>cingula, Tiburti Remulo ditissimus olim   360<br>quae mittit dona, hospitio cum iungeret absens,<br>Caedicus; ille suo moriens dat habere nepoti;<br>post mortem bello Rutuli pugnaque potiti:<br>haec rapit atque umeris nequiquam fortibus aptat.<br>tum galeam Messapi habilem cristisque decoram   365<br>induit. excedunt castris et tuta capessunt.","st":"9"},{"sp":"N","t":"Interea praemissi equites ex urbe Latina,<br>cetera dum legio campis instructa moratur,<br>ibant et Turno regi responsa ferebant,<br>ter centum, scutati omnes, Volcente magistro.    370<br>iamque propinquabant castris murosque subibant<br>cum procul hos laeuo flectentis limite cernunt,<br>et galea Euryalum sublustri noctis in umbra<br>prodidit immemorem radiisque aduersa refulsit.<br>haud temere est uisum. conclamat ab agmine Volcens:   375<br>‘state, uiri. quae causa uiae? quiue estis in armis?<br>quoue tenetis iter?’ nihil illi tendere contra,<br>sed celerare fugam in siluas et fidere nocti.<br>obiciunt equites sese ad diuortia nota<br>hinc atque hinc, omnemque aditum custode coronant.   380<br>silua fuit late dumis atque ilice nigra<br>horrida, quam densi complerant undique sentes;<br>rara per occultos lucebat semita callis.<br>Euryalum tenebrae ramorum onerosaque praeda<br>impediunt, fallitque timor regione uiarum.   385<br>Nisus abit; iamque imprudens euaserat hostis<br>atque locos qui post Albae de nomine dicti<br>Albani (tum rex stabula alta Latinus habebat),<br>ut stetit et frustra absentem respexit amicum:<br>‘Euryale infelix, qua te regione reliqui?   390<br>quaue sequar?’ rursus perplexum iter omne reuoluens<br>fallacis siluae simul et uestigia retro<br>obseruata legit dumisque silentibus errat.<br>audit equos, audit strepitus et signa sequentum;<br>nec longum in medio tempus, cum clamor ad auris   395<br>peruenit ac uidet Euryalum, quem iam manus omnis<br>fraude loci et noctis, subito turbante tumultu,<br>oppressum rapit et conantem plurima frustra.<br>quid faciat? qua ui iuuenem, quibus audeat armis<br>eripere? an sese medios moriturus in enses   400<br>inferat et pulchram properet per uulnera mortem?<br>ocius adducto torquet hastile lacerto<br>suspiciens altam Lunam et sic uoce precatur:<br>‘tu, dea, tu praesens nostro succurre labori,<br>astrorum decus et nemorum Latonia custos.   405<br>si qua tuis umquam pro me pater Hyrtacus aris<br>dona tulit, si qua ipse meis uenatibus auxi<br>suspendiue tholo aut sacra ad fastigia fixi,<br>hunc sine me turbare globum et rege tela per auras.’<br>dixerat et toto conixus corpore ferrum   410<br>conicit. hasta uolans noctis diuerberat umbras<br>et uenit auersi in tergum Sulmonis ibique<br>frangitur, ac fisso transit praecordia ligno.<br>uoluitur ille uomens calidum de pectore flumen<br>frigidus et longis singultibus ilia pulsat.   415<br>diuersi circumspiciunt. hoc acrior idem<br>ecce aliud summa telum librabat ab aure.<br>dum trepidant, it hasta Tago per tempus utrumque<br>stridens traiectoque haesit tepefacta cerebro.<br>saeuit atrox Volcens nec teli conspicit usquam   420<br>auctorem nec quo se ardens immittere possit.<br>‘tu tamen interea calido mihi sanguine poenas<br>persolues amborum’ inquit; simul ense recluso<br>ibat in Euryalum. tum uero exterritus, amens,<br>conclamat Nisus nec se celare tenebris   425<br>amplius aut tantum potuit perferre dolorem:<br>‘me, me, adsum qui feci, in me conuertite ferrum,<br>o Rutuli! mea fraus omnis, nihil iste nec ausus<br>nec potuit; caelum hoc et conscia sidera testor;<br>tantum infelicem nimium dilexit amicum.’   430<br>talia dicta dabat, sed uiribus ensis adactus<br>transadigit costas et candida pectora rumpit.<br>uoluitur Euryalus leto, pulchrosque per artus<br>it cruor inque umeros ceruix conlapsa recumbit:<br>purpureus ueluti cum flos succisus aratro   435<br>languescit moriens, lassoue papauera collo<br>demisere caput pluuia cum forte grauantur.<br>at Nisus ruit in medios solumque per omnis<br>Volcentem petit, in solo Volcente moratur.<br>quem circum glomerati hostes hinc comminus atque hinc   440<br>proturbant. instat non setius ac rotat ensem<br>fulmineum, donec Rutuli clamantis in ore<br>condidit aduerso et moriens animam abstulit hosti.<br>tum super exanimum sese proiecit amicum<br>confossus, placidaque ibi demum morte quieuit.   445","st":"9"},{"sp":"N","t":"Fortunati ambo! si quid mea carmina possunt,<br>nulla dies umquam memori uos eximet aeuo,<br>dum domus Aeneae Capitoli immobile saxum<br>accolet imperiumque pater Romanus habebit.","st":"9"},{"sp":"N","t":"Victores praeda Rutuli spoliisque potiti   450<br>Volcentem exanimum flentes in castra ferebant.<br>nec minor in castris luctus Rhamnete reperto<br>exsangui et primis una tot caede peremptis,<br>Serranoque Numaque. ingens concursus ad ipsa<br>corpora seminecisque uiros, tepidaque recentem   455<br>caede locum et pleno spumantis sanguine riuos.<br>agnoscunt spolia inter se galeamque nitentem<br>Messapi et multo phaleras sudore receptas.","st":"9"},{"sp":"N","t":"Et iam prima nouo spargebat lumine terras<br>Tithoni croceum linquens Aurora cubile.   460<br>iam sole infuso, iam rebus luce retectis<br>Turnus in arma uiros armis circumdatus ipse<br>suscitat: aeratasque acies in proelia cogunt,<br>quisque suos, uariisque acuunt rumoribus iras.<br>quin ipsa arrectis (uisu miserabile) in hastis   465<br>praefigunt capita et multo clamore sequuntur<br>Euryali et Nisi.<br>Aeneadae duri murorum in parte sinistra<br>opposuere aciem (nam dextera cingitur amni),<br>ingentisque tenent fossas et turribus altis   470<br>stant maesti; simul ora uirum praefixa mouebant<br>nota nimis miseris atroque fluentia tabo.","st":"9"},{"sp":"N","t":"Interea pauidam uolitans pennata per urbem<br>nuntia Fama ruit matrisque adlabitur auris<br>Euryali. at subitus miserae calor ossa reliquit,   475<br>excussi manibus radii reuolutaque pensa.<br>euolat infelix et femineo ululatu<br>scissa comam muros amens atque agmina cursu<br>prima petit, non illa uirum, non illa pericli<br>telorumque memor, caelum dehinc questibus implet:   480<br>‘hunc ego te, Euryale, aspicio? tune ille senectae<br>sera meae requies, potuisti linquere solam,<br>crudelis? nec te sub tanta pericula missum<br>adfari extremum miserae data copia matri?<br>heu, terra ignota canibus data praeda Latinis   485<br>alitibusque iaces! nec te tua funere mater<br>produxi pressiue oculos aut uulnera laui,<br>ueste tegens tibi quam noctes festina diesque<br>urgebam, et tela curas solabar anilis.<br>quo sequar? aut quae nunc artus auulsaque membra   490<br>et funus lacerum tellus habet? hoc mihi de te,<br>nate, refers? hoc sum terraque marique secuta?<br>figite me, si qua est pietas, in me omnia tela<br>conicite, o Rutuli, me primam absumite ferro;<br>aut tu, magne pater diuum, miserere, tuoque   495<br>inuisum hoc detrude caput sub Tartara telo,<br>quando aliter nequeo crudelem abrumpere uitam.’<br>hoc fletu concussi animi, maestusque per omnis<br>it gemitus, torpent infractae ad proelia uires.<br>illam incendentem luctus Idaeus et Actor   500<br>Ilionei monitu et multum lacrimantis Iuli<br>corripiunt interque manus sub tecta reponunt.","st":"9"},{"sp":"N","t":"At tuba terribilem sonitum procul aere canoro<br>increpuit, sequitur clamor caelumque remugit.<br>accelerant acta pariter testudine Volsci   505<br>et fossas implere parant ac uellere uallum;<br>quaerunt pars aditum et scalis ascendere muros,<br>qua rara est acies interlucetque corona<br>non tam spissa uiris. telorum effundere contra<br>omne genus Teucri ac duris detrudere contis,   510<br>adsueti longo muros defendere bello.<br>saxa quoque infesto uoluebant pondere, si qua<br>possent tectam aciem perrumpere, cum tamen omnis<br>ferre iuuet subter densa testudine casus.<br>nec iam sufficiunt. nam qua globus imminet ingens,   515<br>immanem Teucri molem uoluuntque ruuntque,<br>quae strauit Rutulos late armorumque resoluit<br>tegmina. nec curant caeco contendere Marte<br>amplius audaces Rutuli, sed pellere uallo<br>missilibus certant.             520<br>parte alia horrendus uisu quassabat Etruscam<br>pinum et fumiferos infert Mezentius ignis;<br>at Messapus equum domitor, Neptunia proles,<br>rescindit uallum et scalas in moenia poscit.","st":"9"},{"sp":"N","t":"Vos, o Calliope, precor, aspirate canenti   525<br>quas ibi tum ferro strages, quae funera Turnus<br>ediderit, quem quisque uirum demiserit Orco,<br>et mecum ingentis oras euoluite belli.","st":"9"},{"sp":"N","t":"Turris erat uasto suspectu et pontibus altis,   530<br>opportuna loco, summis quam uiribus omnes<br>expugnare Itali summaque euertere opum ui<br>certabant, Troes contra defendere saxis<br>perque cauas densi tela intorquere fenestras.<br>princeps ardentem coniecit lampada Turnus   535<br>et flammam adfixit lateri, quae plurima uento<br>corripuit tabulas et postibus haesit adesis.<br>turbati trepidare intus frustraque malorum<br>uelle fugam. dum se glomerant retroque residunt<br>in partem quae peste caret, tum pondere turris   540<br>procubuit subito et caelum tonat omne fragore.<br>semineces ad terram immani mole secuta<br>confixique suis telis et pectora duro<br>transfossi ligno ueniunt. uix unus Helenor<br>et Lycus elapsi; quorum primaeuus Helenor,   545<br>Maeonio regi quem serua Licymnia furtim<br>sustulerat uetitisque ad Troiam miserat armis,<br>ense leuis nudo parmaque inglorius alba.<br>isque ubi se Turni media inter milia uidit,<br>hinc acies atque hinc acies astare Latinas,   550<br>ut fera, quae densa uenantum saepta corona<br>contra tela furit seseque haud nescia morti<br>inicit et saltu supra uenabula fertur — <br>haud aliter iuuenis medios moriturus in hostis<br>inruit et qua tela uidet densissima tendit.   555<br>at pedibus longe melior Lycus inter et hostis<br>inter et arma fuga muros tenet, altaque certat<br>prendere tecta manu sociumque attingere dextras.<br>quem Turnus pariter cursu teloque secutus<br>increpat his uictor: ‘nostrasne euadere, demens,   560<br>sperasti te posse manus?’ simul arripit ipsum<br>pendentem et magna muri cum parte reuellit:<br>qualis ubi aut leporem aut candenti corpore cycnum<br>sustulit alta petens pedibus Iouis armiger uncis,<br>quaesitum aut matri multis balatibus agnum   565<br>Martius a stabulis rapuit lupus. undique clamor<br>tollitur: inuadunt et fossas aggere complent,<br>ardentis taedas alii ad fastigia iactant.<br>Ilioneus saxo atque ingenti fragmine montis<br>Lucetium portae subeuntem ignisque ferentem,   570<br>Emathiona Liger, Corynaeum sternit Asilas,<br>hic iaculo bonus, hic longe fallente sagitta,<br>Ortygium Caeneus, uictorem Caenea Turnus,<br>Turnus Ityn Cloniumque, Dioxippum Promolumque<br>et Sagarim et summis stantem pro turribus Idan,   575<br>Priuernum Capys. hunc primo leuis hasta Themillae<br>strinxerat, ille manum proiecto tegmine demens<br>ad uulnus tulit; ergo alis adlapsa sagitta<br>et laeuo infixa est alte lateri, abditaque intus<br>spiramenta animae letali uulnere rupit.   580<br>stabat in egregiis Arcentis filius armis<br>pictus acu chlamydem et ferrugine clarus Hibera,<br>insignis facie, genitor quem miserat Arcens<br>eductum Martis luco Symaethia circum<br>flumina, pinguis ubi et placabilis ara Palici:   585<br>stridentem fundam positis Mezentius hastis<br>ipse ter adducta circum caput egit habena<br>et media aduersi liquefacto tempora plumbo<br>diffidit ac multa porrectum extendit harena.","st":"9"},{"sp":"N","t":"Tum primum bello celerem intendisse sagittam   590<br>dicitur ante feras solitus terrere fugacis<br>Ascanius, fortemque manu fudisse Numanum,<br>cui Remulo cognomen erat, Turnique minorem<br>germanam nuper thalamo sociatus habebat.<br>is primam ante aciem digna atque indigna relatu   595<br>uociferans tumidusque nouo praecordia regno<br>ibat et ingentem sese clamore ferebat:<br>‘non pudet obsidione iterum ualloque teneri,<br>bis capti Phryges, et morti praetendere muros?<br>en qui nostra sibi bello conubia poscunt!   600<br>quis deus Italiam, quae uos dementia adegit?<br>non hic Atridae nec fandi fictor Vlixes:<br>durum a stirpe genus natos ad flumina primum<br>deferimus saeuoque gelu duramus et undis;<br>uenatu inuigilant pueri siluasque fatigant,   605<br>flectere ludus equos et spicula tendere cornu.<br>at patiens operum paruoque adsueta iuuentus<br>aut rastris terram domat aut quatit oppida bello.<br>omne aeuum ferro teritur, uersaque iuuencum<br>terga fatigamus hasta, nec tarda senectus   610<br>debilitat uiris animi mutatque uigorem:<br>canitiem galea premimus, semperque recentis<br>comportare iuuat praedas et uiuere rapto.<br>uobis picta croco et fulgenti murice uestis,<br>desidiae cordi, iuuat indulgere choreis,   615<br>et tunicae manicas et habent redimicula mitrae.<br>o uere Phrygiae, neque enim Phryges, ite per alta<br>Dindyma, ubi adsuetis biforem dat tibia cantum.<br>tympana uos buxusque uocat Berecyntia Matris<br>Idaeae; sinite arma uiris et cedite ferro.’    620","st":"9"},{"sp":"N","t":"Talia iactantem dictis ac dira canentem<br>non tulit Ascanius, neruoque obuersus equino<br>contendit telum diuersaque bracchia ducens<br>constitit, ante Iouem supplex per uota precatus:<br>‘Iuppiter omnipotens, audacibus adnue coeptis.   625<br>ipse tibi ad tua templa feram sollemnia dona,<br>et statuam ante aras aurata fronte iuuencum<br>candentem pariterque caput cum matre ferentem,<br>iam cornu petat et pedibus qui spargat harenam.’<br>audiit et caeli genitor de parte serena   630<br>intonuit laeuum, sonat una fatifer arcus.<br>effugit horrendum stridens adducta sagitta<br>perque caput Remuli uenit et caua tempora ferro<br>traicit. ‘i, uerbis uirtutem inlude superbis!<br>bis capti Phryges haec Rutulis responsa remittunt’:   635<br>hoc tantum Ascanius. Teucri clamore sequuntur<br>laetitiaque fremunt animosque ad sidera tollunt.","st":"9"},{"sp":"N","t":"Aetheria tum forte plaga crinitus Apollo<br>desuper Ausonias acies urbemque uidebat<br>nube sedens, atque his uictorem adfatur Iulum:   640<br>‘macte noua uirtute, puer, sic itur ad astra,<br>dis genite et geniture deos. iure omnia bella<br>gente sub Assaraci fato uentura resident,<br>nec te Troia capit.’ simul haec effatus ab alto<br>aethere se mittit, spirantis dimouet auras   645<br>Ascaniumque petit; forma tum uertitur oris<br>antiquum in Buten. hic Dardanio Anchisae<br>armiger ante fuit fidusque ad limina custos;<br>tum comitem Ascanio pater addidit. ibat Apollo<br>omnia longaeuo similis uocemque coloremque   650<br>et crinis albos et saeua sonoribus arma,<br>atque his ardentem dictis adfatur Iulum:<br>‘sit satis, Aenide, telis impune Numanum<br>oppetiisse tuis. primam hanc tibi magnus Apollo<br>concedit laudem et paribus non inuidet armis;   655<br>cetera parce, puer, bello.’ sic orsus Apollo<br>mortalis medio aspectus sermone reliquit<br>et procul in tenuem ex oculis euanuit auram.<br>agnouere deum proceres diuinaque tela<br>Dardanidae pharetramque fuga sensere sonantem.   660<br>ergo auidum pugnae dictis ac numine Phoebi<br>Ascanium prohibent, ipsi in certamina rursus<br>succedunt animasque in aperta pericula mittunt.<br>it clamor totis per propugnacula muris,<br>intendunt acris arcus amentaque torquent.   665<br>sternitur omne solum telis, tum scuta cauaeque<br>dant sonitum flictu galeae, pugna aspera surgit:<br>quantus ab occasu ueniens pluuialibus Haedis<br>uerberat imber humum, quam multa grandine nimbi<br>in uada praecipitant, cum Iuppiter horridus Austris   670<br>torquet aquosam hiemem et caelo caua nubila rumpit.","st":"9"},{"sp":"N","t":"Pandarus et Bitias, Idaeo Alcanore creti,<br>quos Iouis eduxit luco siluestris Iaera<br>abietibus iuuenes patriis et montibus aequos,<br>portam, quae ducis imperio commissa, recludunt   675<br>freti armis, ultroque inuitant moenibus hostem.<br>ipsi intus dextra ac laeua pro turribus astant<br>armati ferro et cristis capita alta corusci:<br>quales aeriae liquentia flumina circum<br>siue Padi ripis Athesim seu propter amoenum    680<br>consurgunt geminae quercus intonsaque caelo<br>attollunt capita et sublimi uertice nutant.<br>inrumpunt aditus Rutuli ut uidere patentis:<br>continuo Quercens et pulcher Aquiculus armis<br>et praeceps animi Tmarus et Mauortius Haemon   685<br>agminibus totis aut uersi terga dedere<br>aut ipso portae posuere in limine uitam.<br>tum magis increscunt animis discordibus irae,<br>et iam collecti Troes glomerantur eodem<br>et conferre manum et procurrere longius audent.   690","st":"9"},{"sp":"N","t":"Ductori Turno diuersa in parte furenti<br>turbantique uiros perfertur nuntius, hostem<br>feruere caede noua et portas praebere patentis.<br>deserit inceptum atque immani concitus ira<br>Dardaniam ruit ad portam fratresque superbos.   695<br>et primum Antiphaten (is enim se primus agebat),<br>Thebana de matre nothum Sarpedonis alti,<br>coniecto sternit iaculo: uolat Itala cornus<br>aera per tenerum stomachoque infixa sub altum<br>pectus abit; reddit specus atri uulneris undam   700<br>spumantem, et fixo ferrum in pulmone tepescit.<br>tum Meropem atque Erymanta manu, tum sternit Aphidnum,<br>tum Bitian ardentem oculis animisque frementem,<br>non iaculo (neque enim iaculo uitam ille dedisset),<br>sed magnum stridens contorta phalarica uenit   705<br>fulminis acta modo, quam nec duo taurea terga<br>nec duplici squama lorica fidelis et auro<br>sustinuit; conlapsa ruunt immania membra,<br>dat tellus gemitum et clipeum super intonat ingens.<br>talis in Euboico Baiarum litore quondam   710<br>saxea pila cadit, magnis quam molibus ante<br>constructam ponto iaciunt, sic illa ruinam<br>prona trahit penitusque uadis inlisa recumbit;<br>miscent se maria et nigrae attolluntur harenae,<br>tum sonitu Prochyta alta tremit durumque cubile   715<br>Inarime Iouis imperiis imposta Typhoeo.","st":"9"},{"sp":"N","t":"Hic Mars armipotens animum uirisque Latinis<br>addidit et stimulos acris sub pectore uertit,<br>immisitque Fugam Teucris atrumque Timorem.<br>undique conueniunt, quoniam data copia pugnae,   720<br>bellatorque animo deus incidit.<br>Pandarus, ut fuso germanum corpore cernit<br>et quo sit fortuna loco, qui casus agat res,<br>portam ui multa conuerso cardine torquet<br>obnixus latis umeris, multosque suorum   725<br>moenibus exclusos duro in certamine linquit;<br>ast alios secum includit recipitque ruentis,<br>demens, qui Rutulum in medio non agmine regem<br>uiderit inrumpentem ultroque incluserit urbi,<br>immanem ueluti pecora inter inertia tigrim.   730<br>continuo noua lux oculis effulsit et arma<br>horrendum sonuere, tremunt in uertice cristae<br>sanguineae clipeoque micantia fulmina mittit.<br>agnoscunt faciem inuisam atque immania membra<br>turbati subito Aeneadae. tum Pandarus ingens   735<br>emicat et mortis fraternae feruidus ira<br>effatur: ‘non haec dotalis regia Amatae,<br>nec muris cohibet patriis media Ardea Turnum.<br>castra inimica uides, nulla hinc exire potestas.’<br>olli subridens sedato pectore Turnus:   740<br>‘incipe, si qua animo uirtus, et consere dextram,<br>hic etiam inuentum Priamo narrabis Achillem.’<br>dixerat. ille rudem nodis et cortice crudo<br>intorquet summis adnixus uiribus hastam;<br>excepere aurae, uulnus Saturnia Iuno   745<br>detorsit ueniens, portaeque infigitur hasta.<br>‘at non hoc telum, mea quod ui dextera uersat,<br>effugies, neque enim is teli nec uulneris auctor’:<br>sic ait, et sublatum alte consurgit in ensem<br>et mediam ferro gemina inter tempora frontem   750<br>diuidit impubisque immani uulnere malas.<br>fit sonus, ingenti concussa est pondere tellus;<br>conlapsos artus atque arma cruenta cerebro<br>sternit humi moriens, atque illi partibus aequis<br>huc caput atque illuc umero ex utroque pependit.   755","st":"9"},{"sp":"N","t":"Diffugiunt uersi trepida formidine Troes,<br>et si continuo uictorem ea cura subisset,<br>rumpere claustra manu sociosque immittere portis,<br>ultimus ille dies bello gentique fuisset.<br>sed furor ardentem caedisque insana cupido   760<br>egit in aduersos.<br>principio Phalerim et succiso poplite Gygen<br>excipit, hinc raptas fugientibus ingerit hastas<br>in tergus, Iuno uiris animumque ministrat.<br>addit Halyn comitem et confixa Phegea parma,   765<br>ignaros deinde in muris Martemque cientis<br>Alcandrumque Haliumque Noemonaque Prytanimque.<br>Lyncea tendentem contra sociosque uocantem<br>uibranti gladio conixus ab aggere dexter<br>occupat, huic uno deiectum comminus ictu   770<br>cum galea longe iacuit caput. inde ferarum<br>uastatorem Amycum, quo non felicior alter<br>unguere tela manu ferrumque armare ueneno,<br>et Clytium Aeoliden et amicum Crethea Musis,<br>Crethea Musarum comitem, cui carmina semper   775<br>et citharae cordi numerosque intendere neruis,<br>semper equos atque arma uirum pugnasque canebat.","st":"9"},{"sp":"N","t":"Tandem ductores audita caede suorum<br>conueniunt Teucri, Mnestheus acerque Serestus,<br>palantisque uident socios hostemque receptum.   780<br>et Mnestheus: ‘quo deinde fugam, quo tenditis?’ inquit.<br>‘quos alios muros, quaeue ultra moenia habetis?<br>unus homo et uestris, o ciues, undique saeptus<br>aggeribus tantas strages impune per urbem<br>ediderit? iuuenum primos tot miserit Orco?   785<br>non infelicis patriae ueterumque deorum<br>et magni Aeneae, segnes, miseretque pudetque?’<br>talibus accensi firmantur et agmine denso<br>consistunt. Turnus paulatim excedere pugna<br>et fluuium petere ac partem quae cingitur unda.   790<br>acrius hoc Teucri clamore incumbere magno<br>et glomerare manum, ceu saeuum turba leonem<br>cum telis premit infensis; at territus ille,<br>asper, acerba tuens, retro redit et neque terga<br>ira dare aut uirtus patitur, nec tendere contra   795<br>ille quidem hoc cupiens potis est per tela uirosque.<br>haud aliter retro dubius uestigia Turnus<br>improperata refert et mens exaestuat ira.<br>quin etiam bis tum medios inuaserat hostis,<br>bis confusa fuga per muros agmina uertit;   800<br>sed manus e castris propere coit omnis in unum<br>nec contra uiris audet Saturnia Iuno<br>sufficere; aeriam caelo nam Iuppiter Irim<br>demisit germanae haud mollia iussa ferentem,<br>ni Turnus cedat Teucrorum moenibus altis.   805<br>ergo nec clipeo iuuenis subsistere tantum<br>nec dextra ualet, iniectis sic undique telis<br>obruitur. strepit adsiduo caua tempora circum<br>tinnitu galea et saxis solida aera fatiscunt<br>discussaeque iubae, capiti nec sufficit umbo   810<br>ictibus; ingeminant hastis et Troes et ipse<br>fulmineus Mnestheus. tum toto corpore sudor<br>liquitur et piceum (nec respirare potestas)<br>flumen agit, fessos quatit aeger anhelitus artus.<br>tum demum praeceps saltu sese omnibus armis   815<br>in fluuium dedit. ille suo cum gurgite flauo<br>accepit uenientem ac mollibus extulit undis<br>et laetum sociis abluta caede remisit.","st":"9"},{"sp":"HDR","t":"Liber X","st":"10"},{"sp":"N","t":"Panditur interea domus omnipotentis Olympi<br>conciliumque uocat diuum pater atque hominum rex<br>sideream in sedem, terras unde arduus omnis<br>castraque Dardanidum aspectat populosque Latinos.<br>considunt tectis bipatentibus, incipit ipse:   5<br>‘caelicolae magni, quianam sententia uobis<br>uersa retro tantumque animis certatis iniquis?<br>abnueram bello Italiam concurrere Teucris.<br>quae contra uetitum discordia? quis metus aut hos<br>aut hos arma sequi ferrumque lacessere suasit?   10<br>adueniet iustum pugnae (ne arcessite) tempus,<br>cum fera Karthago Romanis arcibus olim<br>exitium magnum atque Alpis immittet apertas:<br>tum certare odiis, tum res rapuisse licebit.<br>nunc sinite et placitum laeti componite foedus.’   15","st":"10"},{"sp":"N","t":"Iuppiter haec paucis; at non Venus aurea contra<br>pauca refert:<br>‘o pater, o hominum rerumque aeterna potestas<br>(namque aliud quid sit quod iam implorare queamus?),<br>cernis ut insultent Rutuli, Turnusque feratur   20<br>per medios insignis equis tumidusque secundo<br>Marte ruat? non clausa tegunt iam moenia Teucros;<br>quin intra portas atque ipsis proelia miscent<br>aggeribus murorum et inundant sanguine fossae.<br>Aeneas ignarus abest. numquamne leuari   25<br>obsidione sines? muris iterum imminet hostis<br>nascentis Troiae nec non exercitus alter,<br>atque iterum in Teucros Aetolis surgit ab Arpis<br>Tydides. equidem credo, mea uulnera restant<br>et tua progenies mortalia demoror arma.   30<br>si sine pace tua atque inuito numine Troes<br>Italiam petiere, luant peccata neque illos<br>iuueris auxilio; sin tot responsa secuti<br>quae superi manesque dabant, cur nunc tua quisquam<br>uertere iussa potest aut cur noua condere fata?   35<br>quid repetam exustas Erycino in litore classis,<br>quid tempestatum regem uentosque furentis<br>Aeolia excitos aut actam nubibus Irim?<br>nunc etiam manis (haec intemptata manebat<br>sors rerum) mouet et superis immissa repente   40<br>Allecto medias Italum bacchata per urbes.<br>nil super imperio moueor. sperauimus ista,<br>dum fortuna fuit. uincant, quos uincere mauis.<br>si nulla est regio Teucris quam det tua coniunx<br>dura, per euersae, genitor, fumantia Troiae   45<br>excidia obtestor: liceat dimittere ab armis<br>incolumem Ascanium, liceat superesse nepotem.<br>Aeneas sane ignotis iactetur in undis<br>et quacumque uiam dederit Fortuna sequatur:<br>hunc tegere et dirae ualeam subducere pugnae.   50<br>est Amathus, est celsa mihi Paphus atque Cythera<br>Idaliaeque domus: positis inglorius armis<br>exigat hic aeuum. magna dicione iubeto<br>Karthago premat Ausoniam; nihil urbibus inde<br>obstabit Tyriis. quid pestem euadere belli   55<br>iuuit et Argolicos medium fugisse per ignis<br>totque maris uastaeque exhausta pericula terrae,<br>dum Latium Teucri recidiuaque Pergama quaerunt?<br>non satius cineres patriae insedisse supremos<br>atque solum quo Troia fuit? Xanthum et Simoenta   60<br>redde, oro, miseris iterumque reuoluere casus<br>da, pater, Iliacos Teucris.’ tum regia Iuno<br>acta furore graui: ‘quid me alta silentia cogis<br>rumpere et obductum uerbis uulgare dolorem?<br>Aenean hominum quisquam diuumque subegit   65<br>bella sequi aut hostem regi se inferre Latino?<br>Italiam petiit fatis auctoribus (esto)<br>Cassandrae impulsus furiis: num linquere castra<br>hortati sumus aut uitam committere uentis?<br>num puero summam belli, num credere muros,   70<br>Tyrrhenamque fidem aut gentis agitare quietas?<br>quis deus in fraudem, quae dura potentia nostra<br>egit? ubi hic Iuno demissaue nubibus Iris?<br>indignum est Italos Troiam circumdare flammis<br>nascentem et patria Turnum consistere terra,   75<br>cui Pilumnus auus, cui diua Venilia mater:<br>quid face Troianos atra uim ferre Latinis,<br>arua aliena iugo premere atque auertere praedas?<br>quid soceros legere et gremiis abducere pactas,<br>pacem orare manu, praefigere puppibus arma?   80<br>tu potes Aenean manibus subducere Graium<br>proque uiro nebulam et uentos obtendere inanis,<br>et potes in totidem classem conuertere nymphas:<br>nos aliquid Rutulos contra iuuisse nefandum est?<br>“Aeneas ignarus abest”: ignarus et absit.   85<br>est Paphus Idaliumque tibi, sunt alta Cythera:<br>quid grauidam bellis urbem et corda aspera temptas?<br>nosne tibi fluxas Phrygiae res uertere fundo<br>conamur? nos? an miseros qui Troas Achiuis<br>obiecit? quae causa fuit consurgere in arma   90<br>Europamque Asiamque et foedera soluere furto?<br>me duce Dardanius Spartam expugnauit adulter,<br>aut ego tela dedi fouiue Cupidine bella?<br>tum decuit metuisse tuis: nunc sera querelis<br>haud iustis adsurgis et inrita iurgia iactas.’   95","st":"10"},{"sp":"N","t":"Talibus orabat Iuno, cunctique fremebant<br>caelicolae adsensu uario, ceu flamina prima<br>cum deprensa fremunt siluis et caeca uolutant<br>murmura uenturos nautis prodentia uentos.<br>tum pater omnipotens, rerum cui prima potestas,   100<br>infit (eo dicente deum domus alta silescit<br>et tremefacta solo tellus, silet arduus aether,<br>tum Zephyri posuere, premit placida aequora pontus):<br>‘accipite ergo animis atque haec mea figite dicta.<br>quandoquidem Ausonios coniungi foedere Teucris   105<br>haud licitum, nec uestra capit discordia finem,<br>quae cuique est fortuna hodie, quam quisque secat spem,<br>Tros Rutulusne fuat, nullo discrimine habebo,<br>seu fatis Italum castra obsidione tenentur<br>siue errore malo Troiae monitisque sinistris.   110<br>nec Rutulos soluo. sua cuique exorsa laborem<br>fortunamque ferent. rex Iuppiter omnibus idem.<br>fata uiam inuenient.’ Stygii per flumina fratris,<br>per pice torrentis atraque uoragine ripas<br>adnuit et totum nutu tremefecit Olympum.   115<br>hic finis fandi. solio tum Iuppiter aureo<br>surgit, caelicolae medium quem ad limina ducunt.","st":"10"},{"sp":"N","t":"Interea Rutuli portis circum omnibus instant<br>sternere caede uiros et moenia cingere flammis.<br>at legio Aeneadum uallis obsessa tenetur   120<br>nec spes ulla fugae. miseri stant turribus altis<br>nequiquam et rara muros cinxere corona<br>Asius Imbrasides Hicetaoniusque Thymoetes<br>Assaracique duo et senior cum Castore Thymbris,<br>prima acies; hos germani Sarpedonis ambo   125<br>et Clarus et Thaemon Lycia comitantur ab alta.<br>fert ingens toto conixus corpore saxum,<br>haud partem exiguam montis, Lyrnesius Acmon,<br>nec Clytio genitore minor nec fratre Menestheo.<br>hi iaculis, illi certant defendere saxis   130<br>molirique ignem neruoque aptare sagittas.<br>ipse inter medios, Veneris iustissima cura,<br>Dardanius caput, ecce, puer detectus honestum,<br>qualis gemma micat fuluum quae diuidit aurum,<br>aut collo decus aut capiti, uel quale per artem   135<br>inclusum buxo aut Oricia terebintho<br>lucet ebur; fusos ceruix cui lactea crinis<br>accipit et molli subnectens circulus auro.<br>te quoque magnanimae uiderunt, Ismare, gentes<br>uulnera derigere et calamos armare ueneno,   140<br>Maeonia generose domo, ubi pinguia culta<br>exercentque uiri Pactolusque inrigat auro.<br>adfuit et Mnestheus, quem pulsi pristina Turni<br>aggere murorum sublimem gloria tollit,<br>et Capys: hinc nomen Campanae ducitur urbi.   145","st":"10"},{"sp":"N","t":"Illi inter sese duri certamina belli<br>contulerant: media Aeneas freta nocte secabat.<br>namque ut ab Euandro castris ingressus Etruscis<br>regem adit et regi memorat nomenque genusque<br>quidue petat quidue ipse ferat, Mezentius arma   150<br>quae sibi conciliet, uiolentaque pectora Turni<br>edocet, humanis quae sit fiducia rebus<br>admonet immiscetque preces, haud fit mora, Tarchon<br>iungit opes foedusque ferit; tum libera fati<br>classem conscendit iussis gens Lydia diuum   155<br>externo commissa duci. Aeneia puppis<br>prima tenet rostro Phrygios subiuncta leones,<br>imminet Ida super, profugis gratissima Teucris.<br>hic magnus sedet Aeneas secumque uolutat<br>euentus belli uarios, Pallasque sinistro   160<br>adfixus lateri iam quaerit sidera, opacae<br>noctis iter, iam quae passus terraque marique.","st":"10"},{"sp":"N","t":"Pandite nunc Helicona, deae, cantusque mouete,<br>quae manus interea Tuscis comitetur ab oris<br>Aenean armetque rates pelagoque uehatur.   165","st":"10"},{"sp":"N","t":"Massicus aerata princeps secat aequora Tigri,<br>sub quo mille manus iuuenum, qui moenia Clusi<br>quique urbem liquere Cosas, quis tela sagittae<br>gorytique leues umeris et letifer arcus.<br>una toruus Abas: huic totum insignibus armis   170<br>agmen et aurato fulgebat Apolline puppis.<br>sescentos illi dederat Populonia mater<br>expertos belli iuuenes, ast Ilua trecentos<br>insula inexhaustis Chalybum generosa metallis.<br>tertius ille hominum diuumque interpres Asilas,   175<br>cui pecudum fibrae, caeli cui sidera parent<br>et linguae uolucrum et praesagi fulminis ignes,<br>mille rapit densos acie atque horrentibus hastis.<br>hos parere iubent Alpheae ab origine Pisae,<br>urbs Etrusca solo. sequitur pulcherrimus Astyr,   180<br>Astyr equo fidens et uersicoloribus armis.<br>ter centum adiciunt (mens omnibus una sequendi)<br>qui Caerete domo, qui sunt Minionis in aruis,<br>et Pyrgi ueteres intempestaeque Grauiscae.","st":"10"},{"sp":"N","t":"Non ego te, Ligurum ductor fortissime bello,   185<br>transierim, Cunare, et paucis comitate Cupauo,<br>cuius olorinae surgunt de uertice pennae<br>(crimen, Amor, uestrum) formaeque insigne paternae.<br>namque ferunt luctu Cycnum Phaethontis amati,<br>populeas inter frondes umbramque sororum   190<br>dum canit et maestum Musa solatur amorem,<br>canentem molli pluma duxisse senectam<br>linquentem terras et sidera uoce sequentem.<br>filius aequalis comitatus classe cateruas<br>ingentem remis Centaurum promouet: ille   195<br>instat aquae saxumque undis immane minatur<br>arduus, et longa sulcat maria alta carina.","st":"10"},{"sp":"N","t":"Ille etiam patriis agmen ciet Ocnus ab oris,<br>fatidicae Mantus et Tusci filius amnis,<br>qui muros matrisque dedit tibi, Mantua, nomen,   200<br>Mantua diues auis, sed non genus omnibus unum:<br>gens illi triplex, populi sub gente quaterni,<br>ipsa caput populis, Tusco de sanguine uires.<br>hinc quoque quingentos in se Mezentius armat,<br>quos patre Benaco uelatus harundine glauca   205<br>Mincius infesta ducebat in aequora pinu.<br>it grauis Aulestes centenaque arbore fluctum<br>uerberat adsurgens, spumant uada marmore uerso.<br>hunc uehit immanis Triton et caerula concha<br>exterrens freta, cui laterum tenus hispida nanti   210<br>frons hominem praefert, in pristim desinit aluus,<br>spumea semifero sub pectore murmurat unda.","st":"10"},{"sp":"N","t":"Tot lecti proceres ter denis nauibus ibant<br>subsidio Troiae et campos salis aere secabant.","st":"10"},{"sp":"N","t":"Iamque dies caelo concesserat almaque curru   215<br>noctiuago Phoebe medium pulsabat Olympum:<br>Aeneas (neque enim membris dat cura quietem)<br>ipse sedens clauumque regit uelisque ministrat.<br>atque illi medio in spatio chorus, ecce, suarum<br>occurrit comitum: nymphae, quas alma Cybebe   220<br>numen habere maris nymphasque e nauibus esse<br>iusserat, innabant pariter fluctusque secabant,<br>quot prius aeratae steterant ad litora prorae.<br>agnoscunt longe regem lustrantque choreis;<br>quarum quae fandi doctissima Cymodocea   225<br>pone sequens dextra puppim tenet ipsaque dorso<br>eminet ac laeua tacitis subremigat undis.<br>tum sic ignarum adloquitur: ‘uigilasne, deum gens,<br>Aenea? uigila et uelis immitte rudentis.<br>nos sumus, Idaeae sacro de uertice pinus,   230<br>nunc pelagi nymphae, classis tua. perfidus ut nos<br>praecipitis ferro Rutulus flammaque premebat,<br>rupimus inuitae tua uincula teque per aequor<br>quaerimus. hanc genetrix faciem miserata refecit<br>et dedit esse deas aeuumque agitare sub undis.   235<br>at puer Ascanius muro fossisque tenetur<br>tela inter media atque horrentis Marte Latinos.<br>iam loca iussa tenent forti permixtus Etrusco<br>Arcas eques; medias illis opponere turmas,<br>ne castris iungant, certa est sententia Turno.   240<br>surge age et Aurora socios ueniente uocari<br>primus in arma iube, et clipeum cape quem dedit ipse<br>inuictum ignipotens atque oras ambiit auro.<br>crastina lux, mea si non inrita dicta putaris,<br>ingentis Rutulae spectabit caedis aceruos.’   245<br>dixerat et dextra discedens impulit altam<br>haud ignara modi puppim: fugit illa per undas<br>ocior et iaculo et uentos aequante sagitta.<br>inde aliae celerant cursus. stupet inscius ipse<br>Tros Anchisiades, animos tamen omine tollit.   250<br>tum breuiter supera aspectans conuexa precatur:<br>‘alma parens Idaea deum, cui Dindyma cordi<br>turrigeraeque urbes biiugique ad frena leones,<br>tu mihi nunc pugnae princeps, tu rite propinques<br>augurium Phrygibusque adsis pede, diua, secundo.’   255<br>tantum effatus, et interea reuoluta ruebat<br>matura iam luce dies noctemque fugarat;<br>principio sociis edicit signa sequantur<br>atque animos aptent armis pugnaeque parent se.","st":"10"},{"sp":"N","t":"Iamque in conspectu Teucros habet et sua castra   260<br>stans celsa in puppi, clipeum cum deinde sinistra<br>extulit ardentem. clamorem ad sidera tollunt<br>Dardanidae e muris, spes addita suscitat iras,<br>tela manu iaciunt, quales sub nubibus atris<br>Strymoniae dant signa grues atque aethera tranant   265<br>cum sonitu, fugiuntque Notos clamore secundo.<br>at Rutulo regi ducibusque ea mira uideri<br>Ausoniis, donec uersas ad litora puppis<br>respiciunt totumque adlabi classibus aequor.<br>ardet apex capiti cristisque a uertice flamma   270<br>funditur et uastos umbo uomit aureus ignis:<br>non secus ac liquida si quando nocte cometae<br>sanguinei lugubre rubent, aut Sirius ardor<br>ille sitim morbosque ferens mortalibus aegris<br>nascitur et laeuo contristat lumine caelum.    275","st":"10"},{"sp":"N","t":"Haud tamen audaci Turno fiducia cessit<br>litora praecipere et uenientis pellere terra.<br>[ultro animos tollit dictis atque increpat ultro:]<br>‘quod uotis optastis adest, perfringere dextra.<br>in manibus Mars ipse uiris. nunc coniugis esto   280<br>quisque suae tectique memor, nunc magna referto<br>facta, patrum laudes. ultro occurramus ad undam<br>dum trepidi egressisque labant uestigia prima.<br>audentis Fortuna iuuat.’<br>haec ait, et secum uersat quos ducere contra   285<br>uel quibus obsessos possit concredere muros.","st":"10"},{"sp":"N","t":"Interea Aeneas socios de puppibus altis<br>pontibus exponit. multi seruare recursus<br>languentis pelagi et breuibus se credere saltu,<br>per remos alii. speculatus litora Tarchon,   290<br>qua uada non sperat nec fracta remurmurat unda,<br>sed mare inoffensum crescenti adlabitur aestu,<br>aduertit subito proras sociosque precatur:<br>‘nunc, o lecta manus, ualidis incumbite remis;<br>tollite, ferte rates, inimicam findite rostris   295<br>hanc terram, sulcumque sibi premat ipsa carina.<br>frangere nec tali puppim statione recuso<br>arrepta tellure semel.’ quae talia postquam<br>effatus Tarchon, socii consurgere tonsis<br>spumantisque rates aruis inferre Latinis,   300<br>donec rostra tenent siccum et sedere carinae<br>omnes innocuae. sed non puppis tua, Tarchon:<br>namque inflicta uadis, dorso dum pendet iniquo<br>anceps sustentata diu fluctusque fatigat,<br>soluitur atque uiros mediis exponit in undis,   305<br>fragmina remorum quos et fluitantia transtra<br>impediunt retrahitque pedes simul unda relabens.","st":"10"},{"sp":"N","t":"Nec Turnum segnis retinet mora, sed rapit acer<br>totam aciem in Teucros et contra in litore sistit.<br>signa canunt. primus turmas inuasit agrestis   310<br>Aeneas, omen pugnae, strauitque Latinos<br>occiso Therone, uirum qui maximus ultro<br>Aenean petit. huic gladio perque aerea suta,<br>per tunicam squalentem auro latus haurit apertum.<br>inde Lichan ferit exsectum iam matre perempta   315<br>et tibi, Phoebe, sacrum: casus euadere ferri<br>quo licuit paruo? nec longe Cissea durum<br>immanemque Gyan sternentis agmina claua<br>deiecit leto; nihil illos Herculis arma<br>nec ualidae iuuere manus genitorque Melampus,   320<br>Alcidae comes usque grauis dum terra labores<br>praebuit. ecce Pharo, uoces dum iactat inertis,<br>intorquens iaculum clamanti sistit in ore.<br>tu quoque, flauentem prima lanugine malas<br>dum sequeris Clytium infelix, noua gaudia, Cydon,   325<br>Dardania stratus dextra, securus amorum<br>qui iuuenum tibi semper erant, miserande iaceres,<br>ni fratrum stipata cohors foret obuia, Phorci<br>progenies, septem numero, septenaque tela<br>coniciunt; partim galea clipeoque resultant   330<br>inrita, deflexit partim stringentia corpus<br>alma Venus. fidum Aeneas adfatur Achaten:<br>‘suggere tela mihi, non ullum dextera frustra<br>torserit in Rutulos, steterunt quae in corpore Graium<br>Iliacis campis.’ tum magnam corripit hastam   335<br>et iacit: illa uolans clipei transuerberat aera<br>Maeonis et thoraca simul cum pectore rumpit.<br>huic frater subit Alcanor fratremque ruentem<br>sustentat dextra: traiecto missa lacerto<br>protinus hasta fugit seruatque cruenta tenorem,   340<br>dexteraque ex umero neruis moribunda pependit.<br>tum Numitor iaculo fratris de corpore rapto<br>Aenean petiit: sed non et figere contra<br>est licitum, magnique femur perstrinxit Achatae.","st":"10"},{"sp":"N","t":"Hic Curibus fidens primaeuo corpore Clausus   345<br>aduenit et rigida Dryopem ferit eminus hasta<br>sub mentum grauiter pressa, pariterque loquentis<br>uocem animamque rapit traiecto gutture; at ille<br>fronte ferit terram et crassum uomit ore cruorem.<br>tris quoque Threicios Boreae de gente suprema   350<br>et tris quos Idas pater et patria Ismara mittit,<br>per uarios sternit casus. accurrit Halaesus<br>Auruncaeque manus, subit et Neptunia proles,<br>insignis Messapus equis. expellere tendunt<br>nunc hi, nunc illi: certatur limine in ipso   355<br>Ausoniae. magno discordes aethere uenti<br>proelia ceu tollunt animis et uiribus aequis;<br>non ipsi inter se, non nubila, non mare cedit;<br>anceps pugna diu, stant obnixa omnia contra:<br>haud aliter Troianae acies aciesque Latinae   360<br>concurrunt, haeret pede pes densusque uiro uir.","st":"10"},{"sp":"N","t":"At parte ex alia, qua saxa rotantia late<br>intulerat torrens arbustaque diruta ripis,<br>Arcadas insuetos acies inferre pedestris<br>ut uidit Pallas Latio dare terga sequaci,   365<br>aspera aquis natura loci dimittere quando<br>suasit equos, unum quod rebus restat egenis,<br>nunc prece, nunc dictis uirtutem accendit amaris;<br>‘quo fugitis, socii? per uos et fortia facta,<br>per ducis Euandri nomen deuictaque bella   370<br>spemque meam, patriae quae nunc subit aemula laudi,<br>fidite ne pedibus. ferro rumpenda per hostis<br>est uia. qua globus ille uirum densissimus urget,<br>hac uos et Pallanta ducem patria alta reposcit.<br>numina nulla premunt, mortali urgemur ab hoste   375<br>mortales; totidem nobis animaeque manusque.<br>ecce maris magna claudit nos obice pontus,<br>deest iam terra fugae: pelagus Troiamne petamus?’<br>haec ait, et medius densos prorumpit in hostis.","st":"10"},{"sp":"N","t":"Obuius huic primum fatis adductus iniquis   380<br>fit Lagus. hunc, uellit magno dum pondere saxum,<br>intorto figit telo, discrimina costis<br>per medium qua spina dabat, hastamque receptat<br>ossibus haerentem. quem non super occupat Hisbo,<br>ille quidem hoc sperans; nam Pallas ante ruentem,   385<br>dum furit, incautum crudeli morte sodalis<br>excipit atque ensem tumido in pulmone recondit.<br>hinc Sthenium petit et Rhoeti de gente uetusta<br>Anchemolum thalamos ausum incestare nouercae.<br>uos etiam, gemini, Rutulis cecidistis in aruis,   390<br>Daucia, Laride Thymberque, simillima proles,<br>indiscreta suis gratusque parentibus error;<br>at nunc dura dedit uobis discrimina Pallas.<br>nam tibi, Thymbre, caput Euandrius abstulit ensis;<br>te decisa suum, Laride, dextera quaerit   395<br>semianimesque micant digiti ferrumque retractant.<br>Arcadas accensos monitu et praeclara tuentis<br>facta uiri mixtus dolor et pudor armat in hostis.","st":"10"},{"sp":"N","t":"Tum Pallas biiugis fugientem Rhoetea praeter<br>traicit. hoc spatium tantumque morae fuit Ilo;   400<br>Ilo namque procul ualidam derexerat hastam,<br>quam medius Rhoeteus intercipit, optime Teuthra,<br>te fugiens fratremque Tyren, curruque uolutus<br>caedit semianimis Rutulorum calcibus arua.<br>ac uelut optato uentis aestate coortis   405<br>dispersa immittit siluis incendia pastor,<br>correptis subito mediis extenditur una<br>horrida per latos acies Volcania campos,<br>ille sedens uictor flammas despectat ouantis:<br>non aliter socium uirtus coit omnis in unum   410<br>teque iuuat, Palla. sed bellis acer Halaesus<br>tendit in aduersos seque in sua colligit arma.<br>hic mactat Ladona Pheretaque Demodocumque,<br>Strymonio dextram fulgenti deripit ense<br>elatam in iugulum, saxo ferit ora Thoantis   415<br>ossaque dispersit cerebro permixta cruento.<br>fata canens siluis genitor celarat Halaesum;<br>ut senior leto canentia lumina soluit,<br>iniecere manum Parcae telisque sacrarunt<br>Euandri. quem sic Pallas petit ante precatus:   420<br>‘da nunc, Thybri pater, ferro, quod missile libro,<br>fortunam atque uiam duri per pectus Halaesi.<br>haec arma exuuiasque uiri tua quercus habebit.’<br>audiit illa deus; dum texit Imaona Halaesus,<br>Arcadio infelix telo dat pectus inermum.   425","st":"10"},{"sp":"N","t":"At non caede uiri tanta perterrita Lausus,<br>pars ingens belli, sinit agmina: primus Abantem<br>oppositum interimit, pugnae nodumque moramque.<br>sternitur Arcadiae proles, sternuntur Etrusci<br>et uos, o Grais imperdita corpora, Teucri.    430<br>agmina concurrunt ducibusque et uiribus aequis;<br>extremi addensent acies nec turba moueri<br>tela manusque sinit. hinc Pallas instat et urget,<br>hinc contra Lausus, nec multum discrepat aetas,<br>egregii forma, sed quis Fortuna negarat   435<br>in patriam reditus. ipsos concurrere passus<br>haud tamen inter se magni regnator Olympi;<br>mox illos sua fata manent maiore sub hoste.","st":"10"},{"sp":"N","t":"Interea soror alma monet succedere Lauso<br>Turnum, qui uolucri curru medium secat agmen.   440<br>ut uidit socios: ‘tempus desistere pugnae;<br>solus ego in Pallanta feror, soli mihi Pallas<br>debetur; cuperem ipse parens spectator adesset.’<br>haec ait, et socii cesserunt aequore iusso.<br>at Rutulum abscessu iuuenis tum iussa superba   445<br>miratus stupet in Turno corpusque per ingens<br>lumina uoluit obitque truci procul omnia uisu,<br>talibus et dictis it contra dicta tyranni:<br>‘aut spoliis ego iam raptis laudabor opimis<br>aut leto insigni: sorti pater aequus utrique est.   450<br>tolle minas.’ fatus medium procedit in aequor;<br>frigidus Arcadibus coit in praecordia sanguis.<br>desiluit Turnus biiugis, pedes apparat ire<br>comminus; utque leo, specula cum uidit ab alta<br>stare procul campis meditantem in proelia taurum,   455<br>aduolat, haud alia est Turni uenientis imago.<br>hunc ubi contiguum missae fore credidit hastae,<br>ire prior Pallas, si qua fors adiuuet ausum<br>uiribus imparibus, magnumque ita ad aethera fatur:<br>‘per patris hospitium et mensas, quas aduena adisti,   460<br>te precor, Alcide, coeptis ingentibus adsis.<br>cernat semineci sibi me rapere arma cruenta<br>uictoremque ferant morientia lumina Turni.’<br>audiit Alcides iuuenem magnumque sub imo<br>corde premit gemitum lacrimasque effundit inanis.   465<br>tum genitor natum dictis adfatur amicis:<br>‘stat sua cuique dies, breue et inreparabile tempus<br>omnibus est uitae; sed famam extendere factis,<br>hoc uirtutis opus. Troiae sub moenibus altis<br>tot gnati cecidere deum, quin occidit una   470<br>Sarpedon, mea progenies; etiam sua Turnum<br>fata uocant metasque dati peruenit ad aeui.’<br>sic ait, atque oculos Rutulorum reicit aruis.","st":"10"},{"sp":"N","t":"At Pallas magnis emittit uiribus hastam<br>uaginaque caua fulgentem deripit ensem.   475<br>illa uolans umeri surgunt qua tegmina summa<br>incidit, atque uiam clipei molita per oras<br>tandem etiam magno strinxit de corpore Turni.<br>hic Turnus ferro praefixum robur acuto<br>in Pallanta diu librans iacit atque ita fatur:   480<br>‘aspice num mage sit nostrum penetrabile telum.’<br>dixerat; at clipeum, tot ferri terga, tot aeris,<br>quem pellis totiens obeat circumdata tauri,<br>uibranti cuspis medium transuerberat ictu<br>loricaeque moras et pectus perforat ingens.   485<br>ille rapit calidum frustra de uulnere telum:<br>una eademque uia sanguis animusque sequuntur.<br>corruit in uulnus (sonitum super arma dedere)<br>et terram hostilem moriens petit ore cruento.<br>quem Turnus super adsistens:   490<br>‘Arcades, haec’ inquit ‘memores mea dicta referte<br>Euandro: qualem meruit, Pallanta remitto.<br>quisquis honos tumuli, quidquid solamen humandi est,<br>largior. haud illi stabunt Aeneia paruo<br>hospitia.’ et laeuo pressit pede talia fatus   495<br>exanimem rapiens immania pondera baltei<br>impressumque nefas: una sub nocte iugali<br>caesa manus iuuenum foede thalamique cruenti,<br>quae Clonus Eurytides multo caelauerat auro;<br>quo nunc Turnus ouat spolio gaudetque potitus.   500<br>nescia mens hominum fati sortisque futurae<br>et seruare modum rebus sublata secundis!<br>Turno tempus erit magno cum optauerit emptum<br>intactum Pallanta, et cum spolia ista diemque<br>oderit. at socii multo gemitu lacrimisque   505<br>impositum scuto referunt Pallanta frequentes.<br>o dolor atque decus magnum rediture parenti,<br>haec te prima dies bello dedit, haec eadem aufert,<br>cum tamen ingentis Rutulorum linquis aceruos!","st":"10"},{"sp":"N","t":"Nec iam fama mali tanti, sed certior auctor   510<br>aduolat Aeneae tenui discrimine leti<br>esse suos, tempus uersis succurrere Teucris.<br>proxima quaeque metit gladio latumque per agmen<br>ardens limitem agit ferro, te, Turne, superbum<br>caede noua quaerens. Pallas, Euander, in ipsis   515<br>omnia sunt oculis, mensae quas aduena primas<br>tunc adiit, dextraeque datae. Sulmone creatos<br>quattuor hic iuuenes, totidem quos educat Vfens,<br>uiuentis rapit, inferias quos immolet umbris<br>captiuoque rogi perfundat sanguine flammas.   520<br>inde Mago procul infensam contenderat hastam:<br>ille astu subit, at tremibunda superuolat hasta,<br>et genua amplectens effatur talia supplex:<br>‘per patrios manis et spes surgentis Iuli<br>te precor, hanc animam serues gnatoque patrique.    525<br>est domus alta, iacent penitus defossa talenta<br>caelati argenti, sunt auri pondera facti<br>infectique mihi. non hic uictoria Teucrum<br>uertitur aut anima una dabit discrimina tanta.’<br>dixerat. Aeneas contra cui talia reddit:   530<br>‘argenti atque auri memoras quae multa talenta<br>gnatis parce tuis. belli commercia Turnus<br>sustulit ista prior iam tum Pallante perempto.<br>hoc patris Anchisae manes, hoc sentit Iulus.’<br>sic fatus galeam laeua tenet atque reflexa   535<br>ceruice orantis capulo tenus applicat ensem.<br>nec procul Haemonides, Phoebi Triuiaeque sacerdos,<br>infula cui sacra redimibat tempora uitta,<br>totus conlucens ueste atque insignibus albis.<br>quem congressus agit campo, lapsumque superstans   540<br>immolat ingentique umbra tegit, arma Serestus<br>lecta refert umeris tibi, rex Gradiue, tropaeum.","st":"10"},{"sp":"N","t":"Instaurant acies Volcani stirpe creatus<br>Caeculus et ueniens Marsorum montibus Vmbro.<br>Dardanides contra furit: Anxuris ense sinistram   545<br>et totum clipei ferro deiecerat orbem<br>(dixerat ille aliquid magnum uimque adfore uerbo<br>crediderat, caeloque animum fortasse ferebat<br>canitiemque sibi et longos promiserat annos);<br>Tarquitus exsultans contra fulgentibus armis,   550<br>siluicolae Fauno Dryope quem nympha crearat,<br>obuius ardenti sese obtulit. ille reducta<br>loricam clipeique ingens onus impedit hasta,<br>tum caput orantis nequiquam et multa parantis<br>dicere deturbat terrae, truncumque tepentem   555<br>prouoluens super haec inimico pectore fatur:<br>‘istic nunc, metuende, iace. non te optima mater<br>condet humi patrioque onerabit membra sepulcro:<br>alitibus linquere feris, aut gurgite mersum<br>unda feret piscesque impasti uulnera lambent.’   560<br>protinus Antaeum et Lucam, prima agmina Turni,<br>persequitur, fortemque Numam fuluumque Camertem,<br>magnanimo Volcente satum, ditissimus agri<br>qui fuit Ausonidum et tacitis regnauit Amyclis.<br>Aegaeon qualis, centum cui bracchia dicunt   565<br>centenasque manus, quinquaginta oribus ignem<br>pectoribusque arsisse, Iouis cum fulmina contra<br>tot paribus streperet clipeis, tot stringeret ensis:<br>sic toto Aeneas desaeuit in aequore uictor<br>ut semel intepuit mucro. quin ecce Niphaei   570<br>quadriiugis in equos aduersaque pectora tendit.<br>atque illi longe gradientem et dira frementem<br>ut uidere, metu uersi retroque ruentes<br>effunduntque ducem rapiuntque ad litora currus.","st":"10"},{"sp":"N","t":"Interea biiugis infert se Lucagus albis   575<br>in medios fraterque Liger; sed frater habenis<br>flectit equos, strictum rotat acer Lucagus ensem.<br>haud tulit Aeneas tanto feruore furentis;<br>inruit aduersaque ingens apparuit hasta.<br>cui Liger:               580<br>‘non Diomedis equos nec currum cernis Achilli<br>aut Phrygiae campos: nunc belli finis et aeui<br>his dabitur terris.’ uesano talia late<br>dicta uolant Ligeri. sed non et Troius heros<br>dicta parat contra, iaculum nam torquet in hostis.   585<br>Lucagus ut pronus pendens in uerbera telo<br>admonuit biiugos, proiecto dum pede laeuo<br>aptat se pugnae, subit oras hasta per imas<br>fulgentis clipei, tum laeuum perforat inguen;<br>excussus curru moribundus uoluitur aruis.   590<br>quem pius Aeneas dictis adfatur amaris:<br>‘Lucage, nulla tuos currus fuga segnis equorum<br>prodidit aut uanae uertere ex hostibus umbrae:<br>ipse rotis saliens iuga deseris.’ haec ita fatus<br>arripuit biiugos; frater tendebat inertis   595<br>infelix palmas curru delapsus eodem:<br>‘per te, per qui te talem genuere parentes,<br>uir Troiane, sine hanc animam et miserere precantis.’<br>pluribus oranti Aeneas: ‘haud talia dudum<br>dicta dabas. morere et fratrem ne desere frater.’   600<br>tum latebras animae pectus mucrone recludit.<br>talia per campos edebat funera ductor<br>Dardanius torrentis aquae uel turbinis atri<br>more furens. tandem erumpunt et castra relinquunt<br>Ascanius puer et nequiquam obsessa iuuentus.   605","st":"10"},{"sp":"N","t":"Iunonem interea compellat Iuppiter ultro:<br>‘o germana mihi atque eadem gratissima coniunx,<br>ut rebare, Venus (nec te sententia fallit)<br>Troianas sustentat opes, non uiuida bello<br>dextra uiris animusque ferox patiensque pericli.’   610<br>cui Iuno summissa: ‘quid, o pulcherrime coniunx,<br>sollicitas aegram et tua tristia dicta timentem?<br>si mihi, quae quondam fuerat quamque esse decebat,<br>uis in amore foret, non hoc mihi namque negares,<br>omnipotens, quin et pugnae subducere Turnum   615<br>et Dauno possem incolumem seruare parenti.<br>nunc pereat Teucrisque pio det sanguine poenas.<br>ille tamen nostra deducit origine nomen<br>Pilumnusque illi quartus pater, et tua larga<br>saepe manu multisque onerauit limina donis.’   620<br>cui rex aetherii breuiter sic fatur Olympi:<br>‘si mora praesentis leti tempusque caduco<br>oratur iuueni meque hoc ita ponere sentis,<br>tolle fuga Turnum atque instantibus eripe fatis:<br>hactenus indulsisse uacat. sin altior istis   625<br>sub precibus uenia ulla latet totumque moueri<br>mutariue putas bellum, spes pascis inanis.’<br>et Iuno adlacrimans: ‘quid si, quae uoce grauaris,<br>mente dares atque haec Turno rata uita maneret?<br>nunc manet insontem grauis exitus, aut ego ueri   630<br>uana feror. quod ut o potius formidine falsa<br>ludar, et in melius tua, qui potes, orsa reflectas!’","st":"10"},{"sp":"N","t":"Haec ubi dicta dedit, caelo se protinus alto<br>misit agens hiemem nimbo succincta per auras,<br>Iliacamque aciem et Laurentia castra petiuit.   635<br>tum dea nube caua tenuem sine uiribus umbram<br>in faciem Aeneae (uisu mirabile monstrum)<br>Dardaniis ornat telis, clipeumque iubasque<br>diuini adsimulat capitis, dat inania uerba,<br>dat sine mente sonum gressusque effingit euntis,   640<br>morte obita qualis fama est uolitare figuras<br>aut quae sopitos deludunt somnia sensus.<br>at primas laeta ante acies exsultat imago<br>inritatque uirum telis et uoce lacessit.<br>instat cui Turnus stridentemque eminus hastam   645<br>conicit; illa dato uertit uestigia tergo.<br>tum uero Aenean auersum ut cedere Turnus<br>credidit atque animo spem turbidus hausit inanem:<br>‘quo fugis, Aenea? thalamos ne desere pactos;<br>hac dabitur dextra tellus quaesita per undas.’   650<br>talia uociferans sequitur strictumque coruscat<br>mucronem, nec ferre uidet sua gaudia uentos.","st":"10"},{"sp":"N","t":"Forte ratis celsi coniuncta crepidine saxi<br>expositis stabat scalis et ponte parato,<br>qua rex Clusinis aduectus Osinius oris.   655<br>huc sese trepida Aeneae fugientis imago<br>conicit in latebras, nec Turnus segnior instat<br>exsuperatque moras et pontis transilit altos.<br>uix proram attigerat, rumpit Saturnia funem<br>auulsamque rapit reuoluta per aequora nauem.   660<br>tum leuis haud ultra latebras iam quaerit imago,   663<br>sed sublime uolans nubi se immiscuit atrae,<br>illum autem Aeneas absentem in proelia poscit;   661<br>obuia multa uirum demittit corpora morti,<br>cum Turnum medio interea fert aequore turbo.   665<br>respicit ignarus rerum ingratusque salutis<br>et duplicis cum uoce manus ad sidera tendit:<br>‘omnipotens genitor, tanton me crimine dignum<br>duxisti et talis uoluisti expendere poenas?<br>quo feror? unde abii? quae me fuga quemue reducit?   670<br>Laurentisne iterum muros aut castra uidebo?<br>quid manus illa uirum, qui me meaque arma secuti?<br>quosque (nefas) omnis infanda in morte reliqui<br>et nunc palantis uideo, gemitumque cadentum<br>accipio? quid ago? aut quae iam satis ima dehiscat   675<br>terra mihi? uos o potius miserescite, uenti;<br>in rupes, in saxa (uolens uos Turnus adoro)<br>ferte ratem saeuisque uadis immittite syrtis,<br>quo nec me Rutuli nec conscia fama sequatur.’<br>haec memorans animo nunc huc, nunc fluctuat illuc,   680<br>an sese mucrone ob tantum dedecus amens<br>induat et crudum per costas exigat ensem,<br>fluctibus an iaciat mediis et litora nando<br>curua petat Teucrumque iterum se reddat in arma.<br>ter conatus utramque uiam, ter maxima Iuno   685<br>continuit iuuenemque animi miserata repressit.<br>labitur alta secans fluctuque aestuque secundo<br>et patris antiquam Dauni defertur ad urbem.","st":"10"},{"sp":"N","t":"At Iouis interea monitis Mezentius ardens<br>succedit pugnae Teucrosque inuadit ouantis.   690<br>concurrunt Tyrrhenae acies atque omnibus uni,<br>uni odiisque uiro telisque frequentibus instant.<br>ille (uelut rupes uastum quae prodit in aequor,<br>obuia uentorum furiis expostaque ponto,<br>uim cunctam atque minas perfert caelique marisque   695<br>ipsa immota manens) prolem Dolichaonis Hebrum<br>sternit humi, cum quo Latagum Palmumque fugacem,<br>sed Latagum saxo atque ingenti fragmine montis<br>occupat os faciemque aduersam, poplite Palmum<br>succiso uolui segnem sinit, armaque Lauso   700<br>donat habere umeris et uertice figere cristas.<br>nec non Euanthen Phrygium Paridisque Mimanta<br>aequalem comitemque, una quem nocte Theano<br>in lucem genitore Amyco dedit et face praegnas<br>Cisseis regina Parim; Paris urbe paterna   705<br>occubat, ignarum Laurens habet ora Mimanta.<br>ac uelut ille canum morsu de montibus altis<br>actus aper, multos Vesulus quem pinifer annos<br>defendit multosque palus Laurentia silua<br>pascit harundinea, postquam inter retia uentum est,   710<br>substitit infremuitque ferox et inhorruit armos,<br>nec cuiquam irasci propiusue accedere uirtus,<br>sed iaculis tutisque procul clamoribus instant;<br>ille autem impauidus partis cunctatur in omnis   717<br>dentibus infrendens et tergo decutit hastas:<br>haud aliter, iustae quibus est Mezentius irae,   714<br>non ulli est animus stricto concurrere ferro,<br>missilibus longe et uasto clamore lacessunt.","st":"10"},{"sp":"N","t":"Venerat antiquis Corythi de finibus Acron,   719<br>Graius homo, infectos linquens profugus hymenaeos.<br>hunc ubi miscentem longe media agmina uidit,<br>purpureum pennis et pactae coniugis ostro,<br>impastus stabula alta leo ceu saepe peragrans<br>(suadet enim uesana fames), si forte fugacem<br>conspexit capream aut surgentem in cornua ceruum,   725<br>gaudet hians immane comasque arrexit et haeret<br>uisceribus super incumbens; lauit improba taeter<br>ora cruor — <br>sic ruit in densos alacer Mezentius hostis.<br>sternitur infelix Acron et calcibus atram   730<br>tundit humum exspirans infractaque tela cruentat.<br>atque idem fugientem haud est dignatus Oroden<br>sternere nec iacta caecum dare cuspide uulnus;<br>obuius aduersoque occurrit seque uiro uir<br>contulit, haud furto melior sed fortibus armis.   735<br>tum super abiectum posito pede nixus et hasta:<br>‘pars belli haud temnenda, uiri, iacet altus Orodes.’<br>conclamant socii laetum paeana secuti;<br>ille autem exspirans: ‘non me, quicumque es, inulto,<br>uictor, nec longum laetabere; te quoque fata   740<br>prospectant paria atque eadem mox arua tenebis.’<br>ad quem subridens mixta Mezentius ira:<br>‘nunc morere. ast de me diuum pater atque hominum rex<br>uiderit.’ hoc dicens eduxit corpore telum.<br>olli dura quies oculos et ferreus urget   745<br>somnus, in aeternam clauduntur lumina noctem.","st":"10"},{"sp":"N","t":"Caedicus Alcathoum obtruncat, Sacrator Hydaspen<br>partheniumque Rapo et praedurum uiribus Orsen,<br>Messapus Cloniumque Lycaoniumque Erichaeten,<br>illum infrenis equi lapsu tellure iacentem,   750<br>hunc peditem. pedes et Lycius processerat Agis,<br>quem tamen haud expers Valerus uirtutis auitae<br>deicit; at Thronium Salius Saliumque Nealces<br>insidiis, iaculo et longe fallente sagitta.","st":"10"},{"sp":"N","t":"Iam grauis aequabat luctus et mutua Mauors   755<br>funera; caedebant pariter pariterque ruebant<br>uictores uictique, neque his fuga nota neque illis.<br>di Iouis in tectis iram miserantur inanem<br>amborum et tantos mortalibus esse labores;<br>hinc Venus, hinc contra spectat Saturnia Iuno.   760<br>pallida Tisiphone media inter milia saeuit.","st":"10"},{"sp":"N","t":"At uero ingentem quatiens Mezentius hastam<br>turbidus ingreditur campo. quam magnus Orion,<br>cum pedes incedit medii per maxima Nerei<br>stagna uiam scindens, umero supereminet undas,   765<br>aut summis referens annosam montibus ornum<br>ingrediturque solo et caput inter nubila condit,<br>talis se uastis infert Mezentius armis.<br>huic contra Aeneas speculatus in agmine longo<br>obuius ire parat. manet imperterritus ille   770<br>hostem magnanimum opperiens, et mole sua stat;<br>atque oculis spatium emensus quantum satis hastae:<br>‘dextra mihi deus et telum, quod missile libro,<br>nunc adsint! uoueo praedonis corpore raptis<br>indutum spoliis ipsum te, Lause, tropaeum   775<br>Aeneae.’ dixit, stridentemque eminus hastam<br>iecit. at illa uolans clipeo est excussa proculque<br>egregium Antoren latus inter et ilia figit,<br>Herculis Antoren comitem, qui missus ab Argis<br>haeserat Euandro atque Itala consederat urbe.   780<br>sternitur infelix alieno uulnere, caelumque<br>aspicit et dulcis moriens reminiscitur Argos.<br>tum pius Aeneas hastam iacit; illa per orbem<br>aere cauum triplici, per linea terga tribusque<br>transiit intextum tauris opus, imaque sedit   785<br>inguine, sed uiris haud pertulit. ocius ensem<br>Aeneas uiso Tyrrheni sanguine laetus<br>eripit a femine et trepidanti feruidus instat.<br>ingemuit cari grauiter genitoris amore,<br>ut uidit, Lausus, lacrimaeque per ora uolutae — 790<br>hic mortis durae casum tuaque optima facta,<br>si qua fidem tanto est operi latura uetustas,<br>non equidem nec te, iuuenis memorande, silebo — <br>ille pedem referens et inutilis inque ligatus<br>cedebat clipeoque inimicum hastile trahebat.   795<br>proripuit iuuenis seseque immiscuit armis,<br>iamque adsurgentis dextra plagamque ferentis<br>Aeneae subiit mucronem ipsumque morando<br>sustinuit; socii magno clamore sequuntur,<br>dum genitor nati parma protectus abiret,   800<br>telaque coniciunt perturbantque eminus hostem<br>missilibus. furit Aeneas tectusque tenet se.<br>ac uelut effusa si quando grandine nimbi<br>praecipitant, omnis campis diffugit arator<br>omnis et agricola, et tuta latet arce uiator    805<br>aut amnis ripis aut alti fornice saxi,<br>dum pluit in terris, ut possint sole reducto<br>exercere diem: sic obrutus undique telis<br>Aeneas nubem belli, dum detonet omnis,<br>sustinet et Lausum increpitat Lausoque minatur:   810<br>‘quo moriture ruis maioraque uiribus audes?<br>fallit te incautum pietas tua.’ nec minus ille<br>exsultat demens, saeuae iamque altius irae<br>Dardanio surgunt ductori, extremaque Lauso<br>Parcae fila legunt. ualidum namque exigit ensem   815<br>per medium Aeneas iuuenem totumque recondit;<br>transiit et parmam mucro, leuia arma minacis,<br>et tunicam molli mater quam neuerat auro,<br>impleuitque sinum sanguis; tum uita per auras<br>concessit maesta ad Manis corpusque reliquit.   820","st":"10"},{"sp":"N","t":"At uero ut uultum uidit morientis et ora,<br>ora modis Anchisiades pallentia miris,<br>ingemuit miserans grauiter dextramque tetendit,<br>et mentem patriae subiit pietatis imago.<br>‘quid tibi nunc, miserande puer, pro laudibus istis,   825<br>quid pius Aeneas tanta dabit indole dignum?<br>arma, quibus laetatus, habe tua; teque parentum<br>manibus et cineri, si qua est ea cura, remitto.<br>hoc tamen infelix miseram solabere mortem:<br>Aeneae magni dextra cadis.’ increpat ultro   830<br>cunctantis socios et terra subleuat ipsum<br>sanguine turpantem comptos de more capillos.","st":"10"},{"sp":"N","t":"Interea genitor Tiberini ad fluminis undam<br>uulnera siccabat lymphis corpusque leuabat<br>arboris acclinis trunco. procul aerea ramis    835<br>dependet galea et prato grauia arma quiescunt.<br>stant lecti circum iuuenes; ipse aeger anhelans<br>colla fouet fusus propexam in pectore barbam;<br>multa super Lauso rogitat, multumque remittit<br>qui reuocent maestique ferant mandata parentis.   840<br>at Lausum socii exanimem super arma ferebant<br>flentes, ingentem atque ingenti uulnere uictum.<br>agnouit longe gemitum praesaga mali mens.<br>canitiem multo deformat puluere et ambas<br>ad caelum tendit palmas et corpore inhaeret.   845<br>‘tantane me tenuit uiuendi, nate, uoluptas,<br>ut pro me hostili paterer succedere dextrae,<br>quem genui? tuane haec genitor per uulnera seruor<br>morte tua uiuens? heu, nunc misero mihi demum<br>exitium infelix, nunc alte uulnus adactum!   850<br>idem ego, nate, tuum maculaui crimine nomen,<br>pulsus ob inuidiam solio sceptrisque paternis.<br>debueram patriae poenas odiisque meorum:<br>omnis per mortis animam sontem ipse dedissem!<br>nunc uiuo neque adhuc homines lucemque relinquo.   855<br>sed linquam.’ simul hoc dicens attollit in aegrum<br>se femur et, quamquam uis alto uulnere tardat,<br>haud deiectus equum duci iubet. hoc decus illi,<br>hoc solamen erat, bellis hoc uictor abibat<br>omnibus. adloquitur maerentem et talibus infit:   860<br>‘Rhaebe, diu, res si qua diu mortalibus ulla est,<br>uiximus. aut hodie uictor spolia illa cruenti<br>et caput Aeneae referes Lausique dolorum<br>ultor eris mecum, aut, aperit si nulla uiam uis,<br>occumbes pariter; neque enim, fortissime, credo,   865<br>iussa aliena pati et dominos dignabere Teucros.’<br>dixit, et exceptus tergo consueta locauit<br>membra manusque ambas iaculis onerauit acutis,<br>aere caput fulgens cristaque hirsutus equina.<br>sic cursum in medios rapidus dedit. aestuat ingens   870<br>uno in corde pudor mixtoque insania luctu.<br>atque hic Aenean magna ter uoce uocauit.   873<br>Aeneas agnouit enim laetusque precatur:<br>‘sic pater ille deum faciat, sic altus Apollo!<br>incipias conferre manum.’<br>tantum effatus et infesta subit obuius hasta.<br>ille autem: ‘quid me erepto, saeuissime, nato<br>terres? haec uia sola fuit qua perdere posses:<br>nec mortem horremus nec diuum parcimus ulli.   880<br>desine, nam uenio moriturus et haec tibi porto<br>dona prius.’ dixit, telumque intorsit in hostem;<br>inde aliud super atque aliud figitque uolatque<br>ingenti gyro, sed sustinet aureus umbo.<br>ter circum astantem laeuos equitauit in orbis   885<br>tela manu iaciens, ter secum Troius heros<br>immanem aerato circumfert tegmine siluam.<br>inde ubi tot traxisse moras, tot spicula taedet<br>uellere, et urgetur pugna congressus iniqua,<br>multa mouens animo iam tandem erumpit et inter   890<br>bellatoris equi caua tempora conicit hastam.<br>tollit se arrectum quadripes et calcibus auras<br>uerberat, effusumque equitem super ipse secutus<br>implicat eiectoque incumbit cernuus armo.<br>clamore incendunt caelum Troesque Latinique.   895<br>aduolat Aeneas uaginaque eripit ensem<br>et super haec: ‘ubi nunc Mezentius acer et illa<br>effera uis animi?’ contra Tyrrhenus, ut auras<br>suspiciens hausit caelum mentemque recepit:<br>‘hostis amare, quid increpitas mortemque minaris?   900<br>nullum in caede nefas, nec sic ad proelia ueni,<br>nec tecum meus haec pepigit mihi foedera Lausus.<br>unum hoc per si qua est uictis uenia hostibus oro:<br>corpus humo patiare tegi. scio acerba meorum<br>circumstare odia: hunc, oro, defende furorem   905<br>et me consortem nati concede sepulcro.’<br>haec loquitur, iuguloque haud inscius accipit ensem<br>undantique animam diffundit in arma cruore.","st":"10"},{"sp":"HDR","t":"Liber XI","st":"11"},{"sp":"N","t":"Oceanum interea surgens Aurora reliquit:<br>Aeneas, quamquam et sociis dare tempus humandis<br>praecipitant curae turbataque funere mens est,<br>uota deum primo uictor soluebat Eoo.<br>ingentem quercum decisis undique ramis   5<br>constituit tumulo fulgentiaque induit arma,<br>Mezenti ducis exuuias, tibi magne tropaeum<br>bellipotens; aptat rorantis sanguine cristas<br>telaque trunca uiri, et bis sex thoraca petitum<br>perfossumque locis, clipeumque ex aere sinistrae   10<br>subligat atque ensem collo suspendit eburnum.<br>tum socios (namque omnis eum stipata tegebat<br>turba ducum) sic incipiens hortatur ouantis:<br>‘maxima res effecta, uiri; timor omnis abesto,<br>quod superest; haec sunt spolia et de rege superbo   15<br>primitiae manibusque meis Mezentius hic est.<br>nunc iter ad regem nobis murosque Latinos.<br>arma parate, animis et spe praesumite bellum,<br>ne qua mora ignaros, ubi primum uellere signa<br>adnuerint superi pubemque educere castris,   20<br>impediat segnisue metu sententia tardet.<br>interea socios inhumataque corpora terrae<br>mandemus, qui solus honos Acheronte sub imo est.<br>ite,’ ait ‘egregias animas, quae sanguine nobis<br>hanc patriam peperere suo, decorate supremis   25<br>muneribus, maestamque Euandri primus ad urbem<br>mittatur Pallas, quem non uirtutis egentem<br>abstulit atra dies et funere mersit acerbo.’","st":"11"},{"sp":"N","t":"Sic ait inlacrimans, recipitque ad limina gressum<br>corpus ubi exanimi positum Pallantis Acoetes   30<br>seruabat senior, qui Parrhasio Euandro<br>armiger ante fuit, sed non felicibus aeque<br>tum comes auspiciis caro datus ibat alumno.<br>circum omnis famulumque manus Troianaque turba<br>et maestum Iliades crinem de more solutae.   35<br>ut uero Aeneas foribus sese intulit altis<br>ingentem gemitum tunsis ad sidera tollunt<br>pectoribus, maestoque immugit regia luctu.<br>ipse caput niuei fultum Pallantis et ora<br>ut uidit leuique patens in pectore uulnus   40<br>cuspidis Ausoniae, lacrimis ita fatur obortis:<br>‘tene,’ inquit ‘miserande puer, cum laeta ueniret,<br>inuidit Fortuna mihi, ne regna uideres<br>nostra neque ad sedes uictor ueherere paternas?<br>non haec Euandro de te promissa parenti   45<br>discedens dederam, cum me complexus euntem<br>mitteret in magnum imperium metuensque moneret<br>acris esse uiros, cum dura proelia gente.<br>et nunc ille quidem spe multum captus inani<br>fors et uota facit cumulatque altaria donis,   50<br>nos iuuenem exanimum et nil iam caelestibus ullis<br>debentem uano maesti comitamur honore.<br>infelix, nati funus crudele uidebis!<br>hi nostri reditus exspectatique triumphi?<br>haec mea magna fides? at non, Euandre, pudendis   55<br>uulneribus pulsum aspicies, nec sospite dirum<br>optabis nato funus pater. ei mihi quantum<br>praesidium, Ausonia, et quantum tu perdis, Iule!’","st":"11"},{"sp":"N","t":"Haec ubi defleuit, tolli miserabile corpus<br>imperat, et toto lectos ex agmine mittit   60<br>mille uiros qui supremum comitentur honorem<br>intersintque patris lacrimis, solacia luctus<br>exigua ingentis, misero sed debita patri.<br>haud segnes alii cratis et molle feretrum<br>arbuteis texunt uirgis et uimine querno   65<br>exstructosque toros obtentu frondis inumbrant.<br>hic iuuenem agresti sublimem stramine ponunt:<br>qualem uirgineo demessum pollice florem<br>seu mollis uiolae seu languentis hyacinthi,<br>cui neque fulgor adhuc nec dum sua forma recessit,   70<br>non iam mater alit tellus uirisque ministrat.<br>tum geminas uestis auroque ostroque rigentis<br>extulit Aeneas, quas illi laeta laborum<br>ipsa suis quondam manibus Sidonia Dido<br>fecerat et tenui telas discreuerat auro.   75<br>harum unam iuueni supremum maestus honorem<br>induit arsurasque comas obnubit amictu,<br>multaque praeterea Laurentis praemia pugnae<br>aggerat et longo praedam iubet ordine duci;<br>addit equos et tela quibus spoliauerat hostem.   80<br>uinxerat et post terga manus, quos mitteret umbris<br>inferias, caeso sparsurus sanguine flammas,<br>indutosque iubet truncos hostilibus armis<br>ipsos ferre duces inimicaque nomina figi.<br>ducitur infelix aeuo confectus Acoetes,   85<br>pectora nunc foedans pugnis, nunc unguibus ora,<br>sternitur et toto proiectus corpore terrae;<br>ducunt et Rutulo perfusos sanguine currus.<br>post bellator equus positis insignibus Aethon<br>it lacrimans guttisque umectat grandibus ora.   90<br>hastam alii galeamque ferunt, nam cetera Turnus<br>uictor habet. tum maesta phalanx Teucrique sequuntur<br>Tyrrhenique omnes et uersis Arcades armis.<br>postquam omnis longe comitum praecesserat ordo,<br>substitit Aeneas gemituque haec addidit alto:   95<br>‘nos alias hinc ad lacrimas eadem horrida belli<br>fata uocant: salue aeternum mihi, maxime Palla,<br>aeternumque uale.’ nec plura effatus ad altos<br>tendebat muros gressumque in castra ferebat.","st":"11"},{"sp":"N","t":"Iamque oratores aderant ex urbe Latina   100<br>uelati ramis oleae ueniamque rogantes:<br>corpora, per campos ferro quae fusa iacebant,<br>redderet ac tumulo sineret succedere terrae;<br>nullum cum uictis certamen et aethere cassis;<br>parceret hospitibus quondam socerisque uocatis.   105<br>quos bonus Aeneas haud aspernanda precantis<br>prosequitur uenia et uerbis haec insuper addit:<br>‘quaenam uos tanto fortuna indigna, Latini,<br>implicuit bello, qui nos fugiatis amicos?<br>pacem me exanimis et Martis sorte peremptis   110<br>oratis? equidem et uiuis concedere uellem.<br>nec ueni, nisi fata locum sedemque dedissent,<br>nec bellum cum gente gero; rex nostra reliquit<br>hospitia et Turni potius se credidit armis.<br>aequius huic Turnum fuerat se opponere morti.   115<br>si bellum finire manu, si pellere Teucros<br>apparat, his mecum decuit concurrere telis:<br>uixet cui uitam deus aut sua dextra dedisset.<br>nunc ite et miseris supponite ciuibus ignem.’<br>dixerat Aeneas. illi obstipuere silentes   120<br>conuersique oculos inter se atque ora tenebant.","st":"11"},{"sp":"N","t":"Tum senior semperque odiis et crimine Drances<br>infensus iuueni Turno sic ore uicissim<br>orsa refert: ‘o fama ingens, ingentior armis,<br>uir Troiane, quibus caelo te laudibus aequem?   125<br>iustitiaene prius mirer belline laborum?<br>nos uero haec patriam grati referemus ad urbem<br>et te, si qua uiam dederit Fortuna, Latino<br>iungemus regi. quaerat sibi foedera Turnus.<br>quin et fatalis murorum attollere moles   130<br>saxaque subuectare umeris Troiana iuuabit.’<br>dixerat haec unoque omnes eadem ore fremebant.<br>bis senos pepigere dies, et pace sequestra<br>per siluas Teucri mixtique impune Latini<br>errauere iugis. ferro sonat alta bipenni   135<br>fraxinus, euertunt actas ad sidera pinus,<br>robora nec cuneis et olentem scindere cedrum<br>nec plaustris cessant uectare gementibus ornos.","st":"11"},{"sp":"N","t":"Et iam Fama uolans, tanti praenuntia luctus,<br>Euandrum Euandrique domos et moenia replet,   140<br>quae modo uictorem Latio Pallanta ferebat.<br>Arcades ad portas ruere et de more uetusto<br>funereas rapuere faces; lucet uia longo<br>ordine flammarum et late discriminat agros.<br>contra turba Phrygum ueniens plangentia iungit   145<br>agmina. quae postquam matres succedere tectis<br>uiderunt, maestam incendunt clamoribus urbem.<br>at non Euandrum potis est uis ulla tenere,<br>sed uenit in medios. feretro Pallante reposto<br>procubuit super atque haeret lacrimansque gemensque,   150<br>et uia uix tandem uoci laxata dolore est:<br>‘non haec, o Palla, dederas promissa parenti,<br>cautius ut saeuo uelles te credere Marti.<br>haud ignarus eram quantum noua gloria in armis<br>et praedulce decus primo certamine posset.   155<br>primitiae iuuenis miserae bellique propinqui<br>dura rudimenta, et nulli exaudita deorum<br>uota precesque meae! tuque, o sanctissima coniunx,<br>felix morte tua neque in hunc seruata dolorem!<br>contra ego uiuendo uici mea fata, superstes   160<br>restarem ut genitor. Troum socia arma secutum<br>obruerent Rutuli telis! animam ipse dedissem<br>atque haec pompa domum me, non Pallanta, referret!<br>nec uos arguerim, Teucri, nec foedera nec quas<br>iunximus hospitio dextras: sors ista senectae   165<br>debita erat nostrae. quod si immatura manebat<br>mors gnatum, caesis Volscorum milibus ante<br>ducentem in Latium Teucros cecidisse iuuabit.<br>quin ego non alio digner te funere, Palla,<br>quam pius Aeneas et quam magni Phryges et quam   170<br>Tyrrhenique duces, Tyrrhenum exercitus omnis.<br>magna tropaea ferunt quos dat tua dextera leto;<br>tu quoque nunc stares immanis truncus in aruis,<br>esset par aetas et idem si robur ab annis,<br>Turne. sed infelix Teucros quid demoror armis?   175<br>uadite et haec memores regi mandata referte:<br>quod uitam moror inuisam Pallante perempto<br>dextera causa tua est, Turnum gnatoque patrique<br>quam debere uides. meritis uacat hic tibi solus<br>fortunaeque locus. non uitae gaudia quaero,   180<br>nec fas, sed gnato manis perferre sub imos.’","st":"11"},{"sp":"N","t":"Aurora interea miseris mortalibus almam<br>extulerat lucem referens opera atque labores:<br>iam pater Aeneas, iam curuo in litore Tarchon<br>constituere pyras. huc corpora quisque suorum   185<br>more tulere patrum, subiectisque ignibus atris<br>conditur in tenebras altum caligine caelum.<br>ter circum accensos cincti fulgentibus armis<br>decurrere rogos, ter maestum funeris ignem<br>lustrauere in equis ululatusque ore dedere.   190<br>spargitur et tellus lacrimis, sparguntur et arma,<br>it caelo clamorque uirum clangorque tubarum.<br>hic alii spolia occisis derepta Latinis<br>coniciunt igni, galeas ensisque decoros<br>frenaque feruentisque rotas; pars munera nota,   195<br>ipsorum clipeos et non felicia tela.<br>multa boum circa mactantur corpora Morti,<br>saetigerosque sues raptasque ex omnibus agris<br>in flammam iugulant pecudes. tum litore toto<br>ardentis spectant socios semustaque seruant   200<br>busta, neque auelli possunt, nox umida donec<br>inuertit caelum stellis ardentibus aptum.","st":"11"},{"sp":"N","t":"Nec minus et miseri diuersa in parte Latini<br>innumeras struxere pyras, et corpora partim<br>multa uirum terrae infodiunt, auectaque partim   205<br>finitimos tollunt in agros urbique remittunt.<br>cetera confusaeque ingentem caedis aceruum<br>nec numero nec honore cremant; tunc undique uasti<br>certatim crebris conlucent ignibus agri.<br>tertia lux gelidam caelo dimouerat umbram:   210<br>maerentes altum cinerem et confusa ruebant<br>ossa focis tepidoque onerabant aggere terrae.<br>iam uero in tectis, praediuitis urbe Latini,<br>praecipuus fragor et longi pars maxima luctus.<br>hic matres miseraeque nurus, hic cara sororum   215<br>pectora maerentum puerique parentibus orbi<br>dirum exsecrantur bellum Turnique hymenaeos;<br>ipsum armis ipsumque iubent decernere ferro,<br>qui regnum Italiae et primos sibi poscat honores.<br>ingrauat haec saeuus Drances solumque uocari   220<br>testatur, solum posci in certamina Turnum.<br>multa simul contra uariis sententia dictis<br>pro Turno, et magnum reginae nomen obumbrat,<br>multa uirum meritis sustentat fama tropaeis.","st":"11"},{"sp":"N","t":"Hos inter motus, medio in flagrante tumultu,   225<br>ecce super maesti magna Diomedis ab urbe<br>legati responsa ferunt: nihil omnibus actum<br>tantorum impensis operum, nil dona neque aurum<br>nec magnas ualuisse preces, alia arma Latinis<br>quaerenda, aut pacem Troiano ab rege petendum.   230<br>deficit ingenti luctu rex ipse Latinus:<br>fatalem Aenean manifesto numine ferri<br>admonet ira deum tumulique ante ora recentes.<br>ergo concilium magnum primosque suorum<br>imperio accitos alta intra limina cogit.   235<br>olli conuenere fluuntque ad regia plenis<br>tecta uiis. sedet in mediis et maximus aeuo<br>et primus sceptris haud laeta fronte Latinus.<br>atque hic legatos Aetola ex urbe remissos<br>quae referant fari iubet, et responsa reposcit   240<br>ordine cuncta suo. tum facta silentia linguis,<br>et Venulus dicto parens ita farier infit:","st":"11"},{"sp":"N","t":"‘Vidimus, o ciues, Diomedem Argiuaque castra,<br>atque iter emensi casus superauimus omnis,<br>contigimusque manum qua concidit Ilia tellus.   245<br>ille urbem Argyripam patriae cognomine gentis<br>uictor Gargani condebat Iapygis agris.<br>postquam introgressi et coram data copia fandi,<br>munera praeferimus, nomen patriamque docemus,<br>qui bellum intulerint, quae causa attraxerit Arpos.   250<br>auditis ille haec placido sic reddidit ore:<br>“o fortunatae gentes, Saturnia regna,<br>antiqui Ausonii, quae uos fortuna quietos<br>sollicitat suadetque ignota lacessere bella?<br>quicumque Iliacos ferro uiolauimus agros   255<br>(mitto ea quae muris bellando exhausta sub altis,<br>quos Simois premat ille uiros) infanda per orbem<br>supplicia et scelerum poenas expendimus omnes,<br>uel Priamo miseranda manus; scit triste Mineruae<br>sidus et Euboicae cautes ultorque Caphereus.   260<br>militia ex illa diuersum ad litus abacti<br>Atrides Protei Menelaus adusque columnas<br>exsulat, Aetnaeos uidit Cyclopas Vlixes.<br>regna Neoptolemi referam uersosque penatis<br>Idomenei? Libycone habitantis litore Locros?   265<br>ipse Mycenaeus magnorum ductor Achiuum<br>coniugis infandae prima inter limina dextra<br>oppetiit, deuictam Asiam subsedit adulter.<br>inuidisse deos, patriis ut redditus aris<br>coniugium optatum et pulchram Calydona uiderem?   270<br>nunc etiam horribili uisu portenta sequuntur<br>et socii amissi petierunt aethera pennis<br>fluminibusque uagantur aues (heu, dira meorum<br>supplicia!) et scopulos lacrimosis uocibus implent.<br>haec adeo ex illo mihi iam speranda fuerunt   275<br>tempore cum ferro caelestia corpora demens<br>appetii et Veneris uiolaui uulnere dextram.<br>ne uero, ne me ad talis impellite pugnas.<br>nec mihi cum Teucris ullum post eruta bellum<br>Pergama nec ueterum memini laetorue malorum.   280<br>munera quae patriis ad me portatis ab oris<br>uertite ad Aenean. stetimus tela aspera contra<br>contulimusque manus: experto credite quantus<br>in clipeum adsurgat, quo turbine torqueat hastam.<br>si duo praeterea talis Idaea tulisset   285<br>terra uiros, ultro Inachias uenisset ad urbes<br>Dardanus, et uersis lugeret Graecia fatis.<br>quidquid apud durae cessatum est moenia Troiae,<br>Hectoris Aeneaeque manu uictoria Graium<br>haesit et in decimum uestigia rettulit annum.   290<br>ambo animis, ambo insignes praestantibus armis,<br>hic pietate prior. coeant in foedera dextrae,<br>qua datur; ast armis concurrant arma cauete.”<br>et responsa simul quae sint, rex optime, regis<br>audisti et quae sit magno sententia bello.’   295","st":"11"},{"sp":"N","t":"Vix ea legati, uariusque per ora cucurrit<br>Ausonidum turbata fremor, ceu saxa morantur<br>cum rapidos amnis, fit clauso gurgite murmur<br>uicinaeque fremunt ripae crepitantibus undis.<br>ut primum placati animi et trepida ora quierunt,   300<br>praefatus diuos solio rex infit ab alto:","st":"11"},{"sp":"N","t":"‘Ante equidem summa de re statuisse, Latini,<br>et uellem et fuerat melius, non tempore tali<br>cogere concilium, cum muros adsidet hostis.<br>bellum importunum, ciues, cum gente deorum   305<br>inuictisque uiris gerimus, quos nulla fatigant<br>proelia nec uicti possunt absistere ferro.<br>spem si quam ascitis Aetolum habuistis in armis,<br>ponite. spes sibi quisque; sed haec quam angusta uidetis.<br>cetera qua rerum iaceant perculsa ruina,   310<br>ante oculos interque manus sunt omnia uestras.<br>nec quemquam incuso: potuit quae plurima uirtus<br>esse, fuit; toto certatum est corpore regni.<br>nunc adeo quae sit dubiae sententia menti,<br>expediam et paucis (animos adhibete) docebo.   315<br>est antiquus ager Tusco mihi proximus amni,<br>longus in occasum, finis super usque Sicanos;<br>Aurunci Rutulique serunt, et uomere duros<br>exercent collis atque horum asperrima pascunt.<br>haec omnis regio et celsi plaga pinea montis   320<br>cedat amicitiae Teucrorum, et foederis aequas<br>dicamus leges sociosque in regna uocemus:<br>considant, si tantus amor, et moenia condant.<br>sin alios finis aliamque capessere gentem<br>est animus possuntque solo decedere nostro,   325<br>bis denas Italo texamus robore nauis;<br>seu pluris complere ualent, iacet omnis ad undam<br>materies: ipsi numerumque modumque carinis<br>praecipiant, nos aera, manus, naualia demus.<br>praeterea, qui dicta ferant et foedera firment   330<br>centum oratores prima de gente Latinos<br>ire placet pacisque manu praetendere ramos,<br>munera portantis aurique eborisque talenta<br>et sellam regni trabeamque insignia nostri.<br>consulite in medium et rebus succurrite fessis.’   335","st":"11"},{"sp":"N","t":"Tum Drances idem infensus, quem gloria Turni<br>obliqua inuidia stimulisque agitabat amaris,<br>largus opum et lingua melior, sed frigida bello<br>dextera, consiliis habitus non futtilis auctor,<br>seditione potens (genus huic materna superbum   340<br>nobilitas dabat, incertum de patre ferebat),<br>surgit et his onerat dictis atque aggerat iras:<br>‘rem nulli obscuram nostrae nec uocis egentem<br>consulis, o bone rex: cuncti se scire fatentur<br>quid fortuna ferat populi, sed dicere mussant.   345<br>det libertatem fandi flatusque remittat,<br>cuius ob auspicium infaustum moresque sinistros<br>(dicam equidem, licet arma mihi mortemque minetur)<br>lumina tot cecidisse ducum totamque uidemus<br>consedisse urbem luctu, dum Troia temptat   350<br>castra fugae fidens et caelum territat armis.<br>unum etiam donis istis, quae plurima mitti<br>Dardanidis dicique iubes, unum, optime regum,<br>adicias, nec te ullius uiolentia uincat<br>quin natam egregio genero dignisque hymenaeis   355<br>des pater, et pacem hanc aeterno foedere iungas.<br>quod si tantus habet mentes et pectora terror,<br>ipsum obtestemur ueniamque oremus ab ipso:<br>cedat, ius proprium regi patriaeque remittat.<br>quid miseros totiens in aperta pericula ciuis   360<br>proicis, o Latio caput horum et causa malorum?<br>nulla salus bello, pacem te poscimus omnes,<br>Turne, simul pacis solum inuiolabile pignus.<br>primus ego, inuisum quem tu tibi fingis (et esse<br>nil moror), en supplex uenio. miserere tuorum,   365<br>pone animos et pulsus abi. sat funera fusi<br>uidimus ingentis et desolauimus agros.<br>aut, si fama mouet, si tantum pectore robur<br>concipis et si adeo dotalis regia cordi est,<br>aude atque aduersum fidens fer pectus in hostem.   370<br>scilicet ut Turno contingat regia coniunx,<br>nos animae uiles, inhumata infletaque turba,<br>sternamur campis. etiam tu, si qua tibi uis,<br>si patrii quid Martis habes, illum aspice contra<br>qui uocat.’   375","st":"11"},{"sp":"N","t":"Talibus exarsit dictis uiolentia Turni.<br>dat gemitum rumpitque has imo pectore uoces:<br>‘larga quidem semper, Drance, tibi copia fandi<br>tum cum bella manus poscunt, patribusque uocatis<br>primus ades. sed non replenda est curia uerbis,   380<br>quae tuto tibi magna uolant, dum distinet hostem<br>agger murorum nec inundant sanguine fossae.<br>proinde tona eloquio (solitum tibi) meque timoris<br>argue tu, Drance, quando tot stragis aceruos<br>Teucrorum tua dextra dedit, passimque tropaeis   385<br>insignis agros. possit quid uiuida uirtus<br>experiare licet, nec longe scilicet hostes<br>quaerendi nobis; circumstant undique muros.<br>imus in aduersos — quid cessas? an tibi Mauors<br>uentosa in lingua pedibusque fugacibus istis   390<br>semper erit?<br>pulsus ego? aut quisquam merito, foedissime, pulsum<br>arguet, Iliaco tumidum qui crescere Thybrim<br>sanguine et Euandri totam cum stirpe uidebit<br>procubuisse domum atque exutos Arcadas armis?   395<br>haud ita me experti Bitias et Pandarus ingens<br>et quos mille die uictor sub Tartara misi,<br>inclusus muris hostilique aggere saeptus.<br>nulla salus bello? capiti cane talia, demens,<br>Dardanio rebusque tuis. proinde omnia magno   400<br>ne cessa turbare metu atque extollere uiris<br>gentis bis uictae, contra premere arma Latini.<br>nunc et Myrmidonum proceres Phrygia arma tremescunt,<br>nunc et Tydides et Larisaeus Achilles,<br>amnis et Hadriacas retro fugit Aufidus undas.   405<br>uel cum se pauidum contra mea iurgia fingit,<br>artificis scelus, et formidine crimen acerbat.<br>numquam animam talem dextra hac (absiste moueri)<br>amittes: habitet tecum et sit pectore in isto.<br>nunc ad te et tua magna, pater, consulta reuertor.   410<br>si nullam nostris ultra spem ponis in armis,<br>si tam deserti sumus et semel agmine uerso<br>funditus occidimus neque habet Fortuna regressum,<br>oremus pacem et dextras tendamus inertis.<br>quamquam o si solitae quicquam uirtutis adesset!   415<br>ille mihi ante alios fortunatusque laborum<br>egregiusque animi, qui, ne quid tale uideret,<br>procubuit moriens et humum semel ore momordit.<br>sin et opes nobis et adhuc intacta iuuentus<br>auxilioque urbes Italae populique supersunt,   420<br>sin et Troianis cum multo gloria uenit<br>sanguine (sunt illis sua funera, parque per omnis<br>tempestas), cur indecores in limine primo<br>deficimus? cur ante tubam tremor occupat artus?<br>multa dies uariique labor mutabilis aeui   425<br>rettulit in melius, multos alterna reuisens<br>lusit et in solido rursus Fortuna locauit.<br>non erit auxilio nobis Aetolus et Arpi:<br>at Messapus erit felixque Tolumnius et quos<br>tot populi misere duces, nec parua sequetur   430<br>gloria delectos Latio et Laurentibus agris.<br>est et Volscorum egregia de gente Camilla<br>agmen agens equitum et florentis aere cateruas.<br>quod si me solum Teucri in certamina poscunt<br>idque placet tantumque bonis communibus obsto,   435<br>non adeo has exosa manus Victoria fugit<br>ut tanta quicquam pro spe temptare recusem.<br>ibo animis contra, uel magnum praestet Achillem<br>factaque Volcani manibus paria induat arma<br>ille licet. uobis animam hanc soceroque Latino   440<br>Turnus ego, haud ulli ueterum uirtute secundus,<br>deuoui. solum Aeneas uocat? et uocet oro;<br>nec Drances potius, siue est haec ira deorum,<br>morte luat, siue est uirtus et gloria, tollat.’","st":"11"},{"sp":"N","t":"Illi haec inter se dubiis de rebus agebant   445<br>certantes: castra Aeneas aciemque mouebat.<br>nuntius ingenti per regia tecta tumultu<br>ecce ruit magnisque urbem terroribus implet:<br>instructos acie Tiberino a flumine Teucros<br>Tyrrhenamque manum totis descendere campis.   450<br>extemplo turbati animi concussaque uulgi<br>pectora et arrectae stimulis haud mollibus irae.<br>arma manu trepidi poscunt, fremit arma iuuentus,<br>flent maesti mussantque patres. hic undique clamor<br>dissensu uario magnus se tollit in auras,   455<br>haud secus atque alto in luco cum forte cateruae<br>consedere auium, piscosoue amne Padusae<br>dant sonitum rauci per stagna loquacia cycni.<br>‘immo,’ ait ‘o ciues,’ arrepto tempore Turnus,<br>‘cogite concilium et pacem laudate sedentes;   460<br>illi armis in regna ruunt.’ nec plura locutus<br>corripuit sese et tectis citus extulit altis.<br>‘tu, Voluse, armari Volscorum edice maniplis,<br>duc’ ait ‘et Rutulos. equitem Messapus in armis,<br>et cum fratre Coras latis diffundite campis.   465<br>pars aditus urbis firment turrisque capessant;<br>cetera, qua iusso, mecum manus inferat arma.’","st":"11"},{"sp":"N","t":"Ilicet in muros tota discurritur urbe.<br>concilium ipse pater et magna incepta Latinus<br>deserit ac tristi turbatus tempore differt,    470<br>multaque se incusat qui non acceperit ultro<br>Dardanium Aenean generumque asciuerit urbi.<br>praefodiunt alii portas aut saxa sudesque<br>subuectant. bello dat signum rauca cruentum<br>bucina. tum muros uaria cinxere corona   475<br>matronae puerique, uocat labor ultimus omnis.<br>nec non ad templum summasque ad Palladis arces<br>subuehitur magna matrum regina caterua<br>dona ferens, iuxtaque comes Lauinia uirgo,<br>causa mali tanti, oculos deiecta decoros.   480<br>succedunt matres et templum ture uaporant<br>et maestas alto fundunt de limine uoces:<br>‘armipotens, praeses belli, Tritonia uirgo,<br>frange manu telum Phrygii praedonis, et ipsum<br>pronum sterne solo portisque effunde sub altis.’   485<br>cingitur ipse furens certatim in proelia Turnus.<br>iamque adeo rutilum thoraca indutus aenis<br>horrebat squamis surasque incluserat auro,<br>tempora nudus adhuc, laterique accinxerat ensem,<br>fulgebatque alta decurrens aureus arce   490<br>exsultatque animis et spe iam praecipit hostem:<br>qualis ubi abruptis fugit praesepia uinclis<br>tandem liber equus, campoque potitus aperto<br>aut ille in pastus armentaque tendit equarum<br>aut adsuetus aquae perfundi flumine noto   495<br>emicat, arrectisque fremit ceruicibus alte<br>luxurians luduntque iubae per colla, per armos.","st":"11"},{"sp":"N","t":"Obuia cui Volscorum acie comitante Camilla<br>occurrit portisque ab equo regina sub ipsis<br>desiluit, quam tota cohors imitata relictis   500<br>ad terram defluxit equis; tum talia fatur:<br>‘Turne, sui merito si qua est fiducia forti,<br>audeo et Aeneadum promitto occurrere turmae<br>solaque Tyrrhenos equites ire obuia contra.<br>me sine prima manu temptare pericula belli,   505<br>tu pedes ad muros subsiste et moenia serua.’<br>Turnus ad haec oculos horrenda in uirgine fixus:<br>‘o decus Italiae uirgo, quas dicere grates<br>quasue referre parem? sed nunc, est omnia quando<br>iste animus supra, mecum partire laborem.   510<br>Aeneas, ut fama fidem missique reportant<br>exploratores, equitum leuia improbus arma<br>praemisit, quaterent campos; ipse ardua montis<br>per deserta iugo superans aduentat ad urbem.<br>furta paro belli conuexo in tramite siluae,   515<br>ut biuias armato obsidam milite fauces.<br>tu Tyrrhenum equitem conlatis excipe signis;<br>tecum acer Messapus erit turmaeque Latinae<br>Tiburtique manus, ducis et tu concipe curam.’<br>sic ait, et paribus Messapum in proelia dictis   520<br>hortatur sociosque duces et pergit in hostem.","st":"11"},{"sp":"N","t":"Est curuo anfractu ualles, accommoda fraudi<br>armorumque dolis, quam densis frondibus atrum<br>urget utrimque latus, tenuis quo semita ducit<br>angustaeque ferunt fauces aditusque maligni.   525<br>hanc super in speculis summoque in uertice montis<br>planities ignota iacet tutique receptus,<br>seu dextra laeuaque uelis occurrere pugnae<br>siue instare iugis et grandia uoluere saxa.<br>huc iuuenis nota fertur regione uiarum   530<br>arripuitque locum et siluis insedit iniquis.","st":"11"},{"sp":"N","t":"Velocem interea superis in sedibus Opim,<br>unam ex uirginibus sociis sacraque caterua,<br>compellabat et has tristis Latonia uoces<br>ore dabat: ‘graditur bellum ad crudele Camilla,   535<br>o uirgo, et nostris nequiquam cingitur armis,<br>cara mihi ante alias. neque enim nouus iste Dianae<br>uenit amor subitaque animum dulcedine mouit.<br>pulsus ob inuidiam regno uirisque superbas<br>Priuerno antiqua Metabus cum excederet urbe,   540<br>infantem fugiens media inter proelia belli<br>sustulit exsilio comitem, matrisque uocauit<br>nomine Casmillae mutata parte Camillam.<br>ipse sinu prae se portans iuga longa petebat<br>solorum nemorum: tela undique saeua premebant   545<br>et circumfuso uolitabant milite Volsci.<br>ecce fugae medio summis Amasenus abundans<br>spumabat ripis, tantus se nubibus imber<br>ruperat. ille innare parans infantis amore<br>tardatur caroque oneri timet. omnia secum   550<br>uersanti subito uix haec sententia sedit:<br>telum immane manu ualida quod forte gerebat<br>bellator, solidum nodis et robore cocto,<br>huic natam libro et siluestri subere clausam<br>implicat atque habilem mediae circumligat hastae;   555<br>quam dextra ingenti librans ita ad aethera fatur:<br>“alma, tibi hanc, nemorum cultrix, Latonia uirgo,<br>ipse pater famulam uoueo; tua prima per auras<br>tela tenens supplex hostem fugit. accipe, testor,<br>diua tuam, quae nunc dubiis committitur auris.”   560<br>dixit, et adducto contortum hastile lacerto<br>immittit: sonuere undae, rapidum super amnem<br>infelix fugit in iaculo stridente Camilla.<br>at Metabus magna propius iam urgente caterua<br>dat sese fluuio, atque hastam cum uirgine uictor   565<br>gramineo, donum Triuiae, de caespite uellit.<br>non illum tectis ullae, non moenibus urbes<br>accepere (neque ipse manus feritate dedisset),<br>pastorum et solis exegit montibus aeuum.<br>hic natam in dumis interque horrentia lustra   570<br>armentalis equae mammis et lacte ferino<br>nutribat teneris immulgens ubera labris.<br>utque pedum primis infans uestigia plantis<br>institerat, iaculo palmas armauit acuto<br>spiculaque ex umero paruae suspendit et arcum.   575<br>pro crinali auro, pro longae tegmine pallae<br>tigridis exuuiae per dorsum a uertice pendent.<br>tela manu iam tum tenera puerilia torsit<br>et fundam tereti circum caput egit habena<br>Strymoniamque gruem aut album deiecit olorem.   580<br>multae illam frustra Tyrrhena per oppida matres<br>optauere nurum; sola contenta Diana<br>aeternum telorum et uirginitatis amorem<br>intemerata colit. uellem haud correpta fuisset<br>militia tali conata lacessere Teucros:   585<br>cara mihi comitumque foret nunc una mearum.<br>uerum age, quandoquidem fatis urgetur acerbis,<br>labere, nympha, polo finisque inuise Latinos,<br>tristis ubi infausto committitur omine pugna.<br>haec cape et ultricem pharetra deprome sagittam:   590<br>hac, quicumque sacrum uiolarit uulnere corpus,<br>Tros Italusque, mihi pariter det sanguine poenas.<br>post ego nube caua miserandae corpus et arma<br>inspoliata feram tumulo patriaeque reponam.’<br>dixit, at illa leuis caeli delapsa per auras   595<br>insonuit nigro circumdata turbine corpus.","st":"11"},{"sp":"N","t":"At manus interea muris Troiana propinquat,<br>Etruscique duces equitumque exercitus omnis<br>compositi numero in turmas. fremit aequore toto<br>insultans sonipes et pressis pugnat habenis   600<br>huc conuersus et huc; tum late ferreus hastis<br>horret ager campique armis sublimibus ardent.<br>nec non Messapus contra celeresque Latini<br>et cum fratre Coras et uirginis ala Camillae<br>aduersi campo apparent, hastasque reductis   605<br>protendunt longe dextris et spicula uibrant,<br>aduentusque uirum fremitusque ardescit equorum.<br>iamque intra iactum teli progressus uterque<br>substiterat: subito erumpunt clamore furentisque<br>exhortantur equos, fundunt simul undique tela   610<br>crebra niuis ritu, caelumque obtexitur umbra.<br>continuo aduersis Tyrrhenus et acer Aconteus<br>conixi incurrunt hastis primique ruinam<br>dant sonitu ingenti perfractaque quadripedantum<br>pectora pectoribus rumpunt; excussus Aconteus   615<br>fulminis in morem aut tormento ponderis acti<br>praecipitat longe et uitam dispergit in auras.","st":"11"},{"sp":"N","t":"Extemplo turbatae acies, uersique Latini<br>reiciunt parmas et equos ad moenia uertunt;<br>Troes agunt, princeps turmas inducit Asilas.   620<br>iamque propinquabant portis rursusque Latini<br>clamorem tollunt et mollia colla reflectunt;<br>hi fugiunt penitusque datis referuntur habenis.<br>qualis ubi alterno procurrens gurgite pontus<br>nunc ruit ad terram scopulosque superiacit unda   625<br>spumeus extremamque sinu perfundit harenam,<br>nunc rapidus retro atque aestu reuoluta resorbens<br>saxa fugit litusque uado labente relinquit:<br>bis Tusci Rutulos egere ad moenia uersos,<br>bis reiecti armis respectant terga tegentes.   630<br>tertia sed postquam congressi in proelia totas<br>implicuere inter se acies legitque uirum uir,<br>tum uero et gemitus morientum et sanguine in alto<br>armaque corporaque et permixti caede uirorum<br>semianimes uoluuntur equi, pugna aspera surgit.   635<br>Orsilochus Remuli, quando ipsum horrebat adire,<br>hastam intorsit equo ferrumque sub aure reliquit;<br>quo sonipes ictu furit arduus altaque iactat<br>uulneris impatiens arrecto pectore crura,<br>uoluitur ille excussus humi. Catillus Iollan   640<br>ingentemque animis, ingentem corpore et armis<br>deicit Herminium, nudo cui uertice fulua<br>caesaries nudique umeri nec uulnera terrent;<br>tantus in arma patet. latos huic hasta per armos<br>acta tremit duplicatque uirum transfixa dolore.   645<br>funditur ater ubique cruor; dant funera ferro<br>certantes pulchramque petunt per uulnera mortem.","st":"11"},{"sp":"N","t":"At medias inter caedes exsultat Amazon<br>unum exserta latus pugnae, pharetrata Camilla,<br>et nunc lenta manu spargens hastilia denset,   650<br>nunc ualidam dextra rapit indefessa bipennem;<br>aureus ex umero sonat arcus et arma Dianae.<br>illa etiam, si quando in tergum pulsa recessit,<br>spicula conuerso fugientia derigit arcu.<br>at circum lectae comites, Larinaque uirgo   655<br>Tullaque et aeratam quatiens Tarpeia securim,<br>Italides, quas ipsa decus sibi dia Camilla<br>delegit pacisque bonas bellique ministras:<br>quales Threiciae cum flumina Thermodontis<br>pulsant et pictis bellantur Amazones armis,   660<br>seu circum Hippolyten seu cum se Martia curru<br>Penthesilea refert, magnoque ululante tumultu<br>feminea exsultant lunatis agmina peltis.","st":"11"},{"sp":"N","t":"Quem telo primum, quem postremum, aspera uirgo,<br>deicis? aut quot humi morientia corpora fundis?   665<br>Eunaeum Clytio primum patre, cuius apertum<br>aduersi longa transuerberat abiete pectus.<br>sanguinis ille uomens riuos cadit atque cruentam<br>mandit humum moriensque suo se in uulnere uersat.<br>tum Lirim Pagasumque super, quorum alter habenas   670<br>suffuso reuolutus equo dum colligit, alter<br>dum subit ac dextram labenti tendit inermem,<br>praecipites pariterque ruunt. his addit Amastrum<br>Hippotaden, sequiturque incumbens eminus hasta<br>Tereaque Harpalycumque et Demophoonta Chromimque;   675<br>quotque emissa manu contorsit spicula uirgo,<br>tot Phrygii cecidere uiri. procul Ornytus armis<br>ignotis et equo uenator Iapyge fertur,<br>cui pellis latos umeros erepta iuuenco<br>pugnatori operit, caput ingens oris hiatus   680<br>et malae texere lupi cum dentibus albis,<br>agrestisque manus armat sparus; ipse cateruis<br>uertitur in mediis et toto uertice supra est.<br>hunc illa exceptum (neque enim labor agmine uerso)<br>traicit et super haec inimico pectore fatur:   685<br>‘siluis te, Tyrrhene, feras agitare putasti?<br>aduenit qui uestra dies muliebribus armis<br>uerba redargueret. nomen tamen haud leue patrum<br>manibus hoc referes, telo cecidisse Camillae.’","st":"11"},{"sp":"N","t":"Protinus Orsilochum et Buten, duo maxima Teucrum    690<br>corpora, sed Buten auersum cuspide fixit<br>loricam galeamque inter, qua colla sedentis<br>lucent et laeuo dependet parma lacerto;<br>Orsilochum fugiens magnumque agitata per orbem<br>eludit gyro interior sequiturque sequentem;   695<br>tum ualidam perque arma uiro perque ossa securim<br>altior exsurgens oranti et multa precanti<br>congeminat; uulnus calido rigat ora cerebro.<br>incidit huic subitoque aspectu territus haesit<br>Appenninicolae bellator filius Auni,   700<br>haud Ligurum extremus, dum fallere fata sinebant.<br>isque ubi se nullo iam cursu euadere pugnae<br>posse neque instantem reginam auertere cernit,<br>consilio uersare dolos ingressus et astu<br>incipit haec: ‘quid tam egregium, si femina forti   705<br>fidis equo? dimitte fugam et te comminus aequo<br>mecum crede solo pugnaeque accinge pedestri:<br>iam nosces uentosa ferat cui gloria fraudem.’<br>dixit, at illa furens acrique accensa dolore<br>tradit equum comiti paribusque resistit in armis   710<br>ense pedes nudo puraque interrita parma.<br>at iuuenis uicisse dolo ratus auolat ipse<br>(haud mora), conuersisque fugax aufertur habenis<br>quadripedemque citum ferrata calce fatigat.<br>‘uane Ligus frustraque animis elate superbis,   715<br>nequiquam patrias temptasti lubricus artis,<br>nec fraus te incolumem fallaci perferet Auno.’<br>haec fatur uirgo, et pernicibus ignea plantis<br>transit equum cursu frenisque aduersa prehensis<br>congreditur poenasque inimico ex sanguine sumit:   720<br>quam facile accipiter saxo sacer ales ab alto<br>consequitur pennis sublimem in nube columbam<br>comprensamque tenet pedibusque euiscerat uncis;<br>tum cruor et uulsae labuntur ab aethere plumae.","st":"11"},{"sp":"N","t":"At non haec nullis hominum sator atque deorum   725<br>obseruans oculis summo sedet altus Olympo.<br>Tyrrhenum genitor Tarchonem in proelia saeua<br>suscitat et stimulis haud mollibus inicit iras.<br>ergo inter caedes cedentiaque agmina Tarchon<br>fertur equo uariisque instigat uocibus alas   730<br>nomine quemque uocans, reficitque in proelia pulsos.<br>‘quis metus, o numquam dolituri, o semper inertes<br>Tyrrheni, quae tanta animis ignauia uenit?<br>femina palantis agit atque haec agmina uertit!<br>quo ferrum quidue haec gerimus tela inrita dextris?   735<br>at non in Venerem segnes nocturnaque bella,<br>aut ubi curua choros indixit tibia Bacchi.<br>exspectate dapes et plenae pocula mensae<br>(hic amor, hoc studium) dum sacra secundus haruspex<br>nuntiet ac lucos uocet hostia pinguis in altos!’   740<br>haec effatus equum in medios moriturus et ipse<br>concitat, et Venulo aduersum se turbidus infert<br>dereptumque ab equo dextra complectitur hostem<br>et gremium ante suum multa ui concitus aufert.<br>tollitur in caelum clamor cunctique Latini   745<br>conuertere oculos. uolat igneus aequore Tarchon<br>arma uirumque ferens; tum summa ipsius ab hasta<br>defringit ferrum et partis rimatur apertas,<br>qua uulnus letale ferat; contra ille repugnans<br>sustinet a iugulo dextram et uim uiribus exit.   750<br>utque uolans alte raptum cum fulua draconem<br>fert aquila implicuitque pedes atque unguibus haesit,<br>saucius at serpens sinuosa uolumina uersat<br>arrectisque horret squamis et sibilat ore<br>arduus insurgens, illa haud minus urget obunco    755<br>luctantem rostro, simul aethera uerberat alis:<br>haud aliter praedam Tiburtum ex agmine Tarchon<br>portat ouans. ducis exemplum euentumque secuti<br>Maeonidae incurrunt. tum fatis debitus Arruns<br>uelocem iaculo et multa prior arte Camillam   760<br>circuit, et quae sit fortuna facillima temptat.<br>qua se cumque furens medio tulit agmine uirgo,<br>hac Arruns subit et tacitus uestigia lustrat;<br>qua uictrix redit illa pedemque ex hoste reportat,<br>hac iuuenis furtim celeris detorquet habenas.   765<br>hos aditus iamque hos aditus omnemque pererrat<br>undique circuitum et certam quatit improbus hastam.","st":"11"},{"sp":"N","t":"Forte sacer Cybelo Chloreus olimque sacerdos<br>insignis longe Phrygiis fulgebat in armis<br>spumantemque agitabat equum, quem pellis aenis   770<br>in plumam squamis auro conserta tegebat.<br>ipse peregrina ferrugine clarus et ostro<br>spicula torquebat Lycio Gortynia cornu;<br>aureus ex umeris erat arcus et aurea uati<br>cassida; tum croceam chlamydemque sinusque crepantis   775<br>carbaseos fuluo in nodum collegerat auro<br>pictus acu tunicas et barbara tegmina crurum.<br>hunc uirgo, siue ut templis praefigeret arma<br>Troia, captiuo siue ut se ferret in auro<br>uenatrix, unum ex omni certamine pugnae   780<br>caeca sequebatur totumque incauta per agmen<br>femineo praedae et spoliorum ardebat amore,<br>telum ex insidiis cum tandem tempore capto<br>concitat et superos Arruns sic uoce precatur:<br>‘summe deum, sancti custos Soractis Apollo,   785<br>quem primi colimus, cui pineus ardor aceruo<br>pascitur, et medium freti pietate per ignem<br>cultores multa premimus uestigia pruna,<br>da, pater, hoc nostris aboleri dedecus armis,<br>omnipotens. non exuuias pulsaeue tropaeum   790<br>uirginis aut spolia ulla peto, mihi cetera laudem<br>facta ferent; haec dira meo dum uulnere pestis<br>pulsa cadat, patrias remeabo inglorius urbes.’","st":"11"},{"sp":"N","t":"Audiit et uoti Phoebus succedere partem<br>mente dedit, partem uolucris dispersit in auras:   795<br>sterneret ut subita turbatam morte Camillam<br>adnuit oranti; reducem ut patria alta uideret<br>non dedit, inque Notos uocem uertere procellae.<br>ergo ut missa manu sonitum dedit hasta per auras,<br>conuertere animos acris oculosque tulere   800<br>cuncti ad reginam Volsci. nihil ipsa nec aurae<br>nec sonitus memor aut uenientis ab aethere teli,<br>hasta sub exsertam donec perlata papillam<br>haesit uirgineumque alte bibit acta cruorem.<br>concurrunt trepidae comites dominamque ruentem   805<br>suscipiunt. fugit ante omnis exterritus Arruns<br>laetitia mixtoque metu, nec iam amplius hastae<br>credere nec telis occurrere uirginis audet.<br>ac uelut ille, prius quam tela inimica sequantur,<br>continuo in montis sese auius abdidit altos   810<br>occiso pastore lupus magnoue iuuenco,<br>conscius audacis facti, caudamque remulcens<br>subiecit pauitantem utero siluasque petiuit:<br>haud secus ex oculis se turbidus abstulit Arruns<br>contentusque fuga mediis se immiscuit armis.   815<br>illa manu moriens telum trahit, ossa sed inter<br>ferreus ad costas alto stat uulnere mucro.<br>labitur exsanguis, labuntur frigida leto<br>lumina, purpureus quondam color ora reliquit.<br>tum sic exspirans Accam ex aequalibus unam   820<br>adloquitur, fida ante alias quae sola Camillae<br>quicum partiri curas, atque haec ita fatur:<br>‘hactenus, Acca soror, potui: nunc uulnus acerbum<br>conficit, et tenebris nigrescunt omnia circum.<br>effuge et haec Turno mandata nouissima perfer:   825<br>succedat pugnae Troianosque arceat urbe.<br>iamque uale.’ simul his dictis linquebat habenas<br>ad terram non sponte fluens. tum frigida toto<br>paulatim exsoluit se corpore, lentaque colla<br>et captum leto posuit caput, arma relinquens,   830<br>uitaque cum gemitu fugit indignata sub umbras.<br>tum uero immensus surgens ferit aurea clamor<br>sidera: deiecta crudescit pugna Camilla;<br>incurrunt densi simul omnis copia Teucrum<br>Tyrrhenique duces Euandrique Arcades alae.   835","st":"11"},{"sp":"N","t":"At Triuiae custos iamdudum in montibus Opis<br>alta sedet summis spectatque interrita pugnas.<br>utque procul medio iuuenum in clamore furentum<br>prospexit tristi mulcatam morte Camillam,<br>ingemuitque deditque has imo pectore uoces:   840<br>‘heu nimium, uirgo, nimium crudele luisti<br>supplicium Teucros conata lacessere bello!<br>nec tibi desertae in dumis coluisse Dianam<br>profuit aut nostras umero gessisse pharetras.<br>non tamen indecorem tua te regina reliquit   845<br>extrema iam in morte, neque hoc sine nomine letum<br>per gentis erit aut famam patieris inultae.<br>nam quicumque tuum uiolauit uulnere corpus<br>morte luet merita.’ fuit ingens monte sub alto<br>regis Dercenni terreno ex aggere bustum   850<br>antiqui Laurentis opacaque ilice tectum;<br>hic dea se primum rapido pulcherrima nisu<br>sistit et Arruntem tumulo speculatur ab alto.<br>ut uidit fulgentem armis ac uana tumentem,<br>‘cur’ inquit ‘diuersus abis? huc derige gressum,   855<br>huc periture ueni, capias ut digna Camillae<br>praemia. tune etiam telis moriere Dianae?’<br>dixit, et aurata uolucrem Threissa sagittam<br>deprompsit pharetra cornuque infensa tetendit<br>et duxit longe, donec curuata coirent   860<br>inter se capita et manibus iam tangeret aequis,<br>laeua aciem ferri, dextra neruoque papillam.<br>extemplo teli stridorem aurasque sonantis<br>audiit una Arruns haesitque in corpore ferrum.<br>illum exspirantem socii atque extrema gementem   865<br>obliti ignoto camporum in puluere linquunt;<br>Opis ad aetherium pennis aufertur Olympum.","st":"11"},{"sp":"N","t":"Prima fugit domina amissa leuis ala Camillae,<br>turbati fugiunt Rutuli, fugit acer Atinas,<br>disiectique duces desolatique manipli   870<br>tuta petunt et equis auersi ad moenia tendunt.<br>nec quisquam instantis Teucros letumque ferentis<br>sustentare ualet telis aut sistere contra,<br>sed laxos referunt umeris languentibus arcus,<br>quadripedumque putrem cursu quatit ungula campum.   875<br>uoluitur ad muros caligine turbidus atra<br>puluis, et e speculis percussae pectora matres<br>femineum clamorem ad caeli sidera tollunt.<br>qui cursu portas primi inrupere patentis,<br>hos inimica super mixto premit agmine turba,   880<br>nec miseram effugiunt mortem, sed limine in ipso,<br>moenibus in patriis atque inter tuta domorum<br>confixi exspirant animas. pars claudere portas,<br>nec sociis aperire uiam nec moenibus audent<br>accipere orantis, oriturque miserrima caedes   885<br>defendentum armis aditus inque arma ruentum.<br>exclusi ante oculos lacrimantumque ora parentum<br>pars in praecipitis fossas urgente ruina<br>uoluitur, immissis pars caeca et concita frenis<br>arietat in portas et duros obice postis.   890<br>ipsae de muris summo certamine matres<br>(monstrat amor uerus patriae, ut uidere Camillam)<br>tela manu trepidae iaciunt ac robore duro<br>stipitibus ferrum sudibusque imitantur obustis<br>praecipites, primaeque mori pro moenibus ardent.   895","st":"11"},{"sp":"N","t":"Interea Turnum in siluis saeuissimus implet<br>nuntius et iuueni ingentem fert Acca tumultum:<br>deletas Volscorum acies, cecidisse Camillam,<br>ingruere infensos hostis et Marte secundo<br>omnia corripuisse, metum iam ad moenia ferri.   900<br>ille furens (et saeua Iouis sic numina poscunt)<br>deserit obsessos collis, nemora aspera linquit.<br>uix e conspectu exierat campumque tenebat,<br>cum pater Aeneas saltus ingressus apertos<br>exsuperatque iugum siluaque euadit opaca.   905<br>sic ambo ad muros rapidi totoque feruntur<br>agmine nec longis inter se passibus absunt;<br>ac simul Aeneas fumantis puluere campos<br>prospexit longe Laurentiaque agmina uidit,<br>et saeuum Aenean agnouit Turnus in armis   910<br>aduentumque pedum flatusque audiuit equorum.<br>continuoque ineant pugnas et proelia temptent,<br>ni roseus fessos iam gurgite Phoebus Hibero<br>tingat equos noctemque die labente reducat.<br>considunt castris ante urbem et moenia uallant.","st":"11"},{"sp":"HDR","t":"Liber XII","st":"12"},{"sp":"N","t":"Turnus ut infractos aduerso Marte Latinos<br>defecisse uidet, sua nunc promissa reposci,<br>se signari oculis, ultro implacabilis ardet<br>attollitque animos. Poenorum qualis in aruis<br>saucius ille graui uenantum uulnere pectus   5<br>tum demum mouet arma leo, gaudetque comantis<br>excutiens ceruice toros fixumque latronis<br>impauidus frangit telum et fremit ore cruento:<br>haud secus accenso gliscit uiolentia Turno.<br>tum sic adfatur regem atque ita turbidus infit:   10<br>‘nulla mora in Turno; nihil est quod dicta retractent<br>ignaui Aeneadae, nec quae pepigere recusent:<br>congredior. fer sacra, pater, et concipe foedus.<br>aut hac Dardanium dextra sub Tartara mittam<br>desertorem Asiae (sedeant spectentque Latini),   15<br>et solus ferro crimen commune refellam,<br>aut habeat uictos, cedat Lauinia coniunx.’","st":"12"},{"sp":"N","t":"Olli sedato respondit corde Latinus:<br>‘o praestans animi iuuenis, quantum ipse feroci<br>uirtute exsuperas, tanto me impensius aequum est   20<br>consulere atque omnis metuentem expendere casus.<br>sunt tibi regna patris Dauni, sunt oppida capta<br>multa manu, nec non aurumque animusque Latino est;<br>sunt aliae innuptae Latio et Laurentibus aruis<br>nec genus indecores. sine me haec haud mollia fatu    25<br>sublatis aperire dolis, simul hoc animo hauri:<br>me natam nulli ueterum sociare procorum<br>fas erat, idque omnes diuique hominesque canebant.<br>uictus amore tui, cognato sanguine uictus<br>coniugis et maestae lacrimis, uincla omnia rupi;   30<br>promissam eripui genero, arma impia sumpsi.<br>ex illo qui me casus, quae, Turne, sequantur<br>bella, uides, quantos primus patiare labores.<br>bis magna uicti pugna uix urbe tuemur<br>spes Italas; recalent nostro Thybrina fluenta   35<br>sanguine adhuc campique ingentes ossibus albent.<br>quo referor totiens? quae mentem insania mutat?<br>si Turno exstincto socios sum ascire paratus,<br>cur non incolumi potius certamina tollo?<br>quid consanguinei Rutuli, quid cetera dicet   40<br>Italia, ad mortem si te (fors dicta refutet!)<br>prodiderim, natam et conubia nostra petentem?<br>respice res bello uarias, miserere parentis<br>longaeui, quem nunc maestum patria Ardea longe<br>diuidit.’ haudquaquam dictis uiolentia Turni   45<br>flectitur; exsuperat magis aegrescitque medendo.<br>ut primum fari potuit, sic institit ore:<br>‘quam pro me curam geris, hanc precor, optime, pro me<br>deponas letumque sinas pro laude pacisci.<br>et nos tela, pater, ferrumque haud debile dextra   50<br>spargimus, et nostro sequitur de uulnere sanguis.<br>longe illi dea mater erit, quae nube fugacem<br>feminea tegat et uanis sese occulat umbris.’","st":"12"},{"sp":"N","t":"At regina noua pugnae conterrita sorte<br>flebat et ardentem generum moritura tenebat:   55<br>‘Turne, per has ego te lacrimas, per si quis Amatae<br>tangit honos animum: spes tu nunc una, senectae<br>tu requies miserae, decus imperiumque Latini<br>te penes, in te omnis domus inclinata recumbit.<br>unum oro: desiste manum committere Teucris.   60<br>qui te cumque manent isto certamine casus<br>et me, Turne, manent; simul haec inuisa relinquam<br>lumina nec generum Aenean captiua uidebo.’<br>accepit uocem lacrimis Lauinia matris<br>flagrantis perfusa genas, cui plurimus ignem   65<br>subiecit rubor et calefacta per ora cucurrit.<br>Indum sanguineo ueluti uiolauerit ostro<br>si quis ebur, aut mixta rubent ubi lilia multa<br>alba rosa, talis uirgo dabat ore colores.<br>illum turbat amor figitque in uirgine uultus;   70<br>ardet in arma magis paucisque adfatur Amatam:<br>‘ne, quaeso, ne me lacrimis neue omine tanto<br>prosequere in duri certamina Martis euntem,<br>o mater; neque enim Turno mora libera mortis.<br>nuntius haec, Idmon, Phrygio mea dicta tyranno   75<br>haud placitura refer. cum primum crastina caelo<br>puniceis inuecta rotis Aurora rubebit,<br>non Teucros agat in Rutulos, Teucrum arma quiescant<br>et Rutuli; nostro dirimamus sanguine bellum,<br>illo quaeratur coniunx Lauinia campo.’   80","st":"12"},{"sp":"N","t":"Haec ubi dicta dedit rapidusque in tecta recessit,<br>poscit equos gaudetque tuens ante ora frementis,<br>Pilumno quos ipsa decus dedit Orithyia,<br>qui candore niues anteirent, cursibus auras.<br>circumstant properi aurigae manibusque lacessunt   85<br>pectora plausa cauis et colla comantia pectunt.<br>ipse dehinc auro squalentem alboque orichalco<br>circumdat loricam umeris, simul aptat habendo<br>ensemque clipeumque et rubrae cornua cristae,<br>ensem quem Dauno ignipotens deus ipse parenti    90<br>fecerat et Stygia candentem tinxerat unda.<br>exim quae mediis ingenti adnixa columnae<br>aedibus astabat, ualidam ui corripit hastam,<br>Actoris Aurunci spolium, quassatque trementem<br>uociferans: ‘nunc, o numquam frustrata uocatus   95<br>hasta meos, nunc tempus adest: te maximus Actor,<br>te Turni nunc dextra gerit; da sternere corpus<br>loricamque manu ualida lacerare reuulsam<br>semiuiri Phrygis et foedare in puluere crinis<br>uibratos calido ferro murraque madentis.’   100<br>his agitur furiis, totoque ardentis ab ore<br>scintillae absistunt, oculis micat acribus ignis,<br>mugitus ueluti cum prima in proelia taurus<br>terrificos ciet aut irasci in cornua temptat<br>arboris obnixus trunco, uentosque lacessit   105<br>ictibus aut sparsa ad pugnam proludit harena.","st":"12"},{"sp":"N","t":"Nec minus interea maternis saeuus in armis<br>Aeneas acuit Martem et se suscitat ira,<br>oblato gaudens componi foedere bellum.<br>tum socios maestique metum solatur Iuli   110<br>fata docens, regique iubet responsa Latino<br>certa referre uiros et pacis dicere leges.","st":"12"},{"sp":"N","t":"Postera uix summos spargebat lumine montis<br>orta dies, cum primum alto se gurgite tollunt<br>Solis equi lucemque elatis naribus efflant:   115<br>campum ad certamen magnae sub moenibus urbis<br>dimensi Rutulique uiri Teucrique parabant<br>in medioque focos et dis communibus aras<br>gramineas. alii fontemque ignemque ferebant<br>uelati limo et uerbena tempora uincti.    120<br>procedit legio Ausonidum, pilataque plenis<br>agmina se fundunt portis. hinc Troius omnis<br>Tyrrhenusque ruit uariis exercitus armis,<br>haud secus instructi ferro quam si aspera Martis<br>pugna uocet. nec non mediis in milibus ipsi   125<br>ductores auro uolitant ostroque superbi,<br>et genus Assaraci Mnestheus et fortis Asilas<br>et Messapus equum domitor, Neptunia proles;<br>utque dato signo spatia in sua quisque recessit,<br>defigunt tellure hastas et scuta reclinant.   130<br>tum studio effusae matres et uulgus inermum<br>inualidique senes turris ac tecta domorum<br>obsedere, alii portis sublimibus astant.","st":"12"},{"sp":"N","t":"At Iuno ex summo (qui nunc Albanus habetur;<br>tum neque nomen erat neque honos aut gloria monti)   135<br>prospiciens tumulo campum aspectabat et ambas<br>Laurentum Troumque acies urbemque Latini.<br>extemplo Turni sic est adfata sororem<br>diua deam, stagnis quae fluminibusque sonoris<br>praesidet (hunc illi rex aetheris altus honorem   140<br>Iuppiter erepta pro uirginitate sacrauit):<br>‘nympha, decus fluuiorum, animo gratissima nostro,<br>scis ut te cunctis unam, quaecumque Latinae<br>magnanimi Iouis ingratum ascendere cubile,<br>praetulerim caelique libens in parte locarim:   145<br>disce tuum, ne me incuses, Iuturna, dolorem.<br>qua uisa est Fortuna pati Parcaeque sinebant<br>cedere res Latio, Turnum et tua moenia texi;<br>nunc iuuenem imparibus uideo concurrere fatis,<br>Parcarumque dies et uis inimica propinquat.   150<br>non pugnam aspicere hanc oculis, non foedera possum.<br>tu pro germano si quid praesentius audes,<br>perge; decet. forsan miseros meliora sequentur.’<br>uix ea, cum lacrimas oculis Iuturna profundit<br>terque quaterque manu pectus percussit honestum.   155<br>‘non lacrimis hoc tempus’ ait Saturnia Iuno:<br>‘accelera et fratrem, si quis modus, eripe morti;<br>aut tu bella cie conceptumque excute foedus.<br>auctor ego audendi.’ sic exhortata reliquit<br>incertam et tristi turbatam uulnere mentis.   160","st":"12"},{"sp":"N","t":"Interea reges ingenti mole Latinus<br>quadriiugo uehitur curru (cui tempora circum<br>aurati bis sex radii fulgentia cingunt,<br>Solis aui specimen), bigis it Turnus in albis,<br>bina manu lato crispans hastilia ferro.   165<br>hinc pater Aeneas, Romanae stirpis origo,<br>sidereo flagrans clipeo et caelestibus armis<br>et iuxta Ascanius, magnae spes altera Romae,<br>procedunt castris, puraque in ueste sacerdos<br>saetigeri fetum suis intonsamque bidentem   170<br>attulit admouitque pecus flagrantibus aris.<br>illi ad surgentem conuersi lumina solem<br>dant fruges manibus salsas et tempora ferro<br>summa notant pecudum, paterisque altaria libant.","st":"12"},{"sp":"N","t":"Tum pius Aeneas stricto sic ense precatur:   175<br>‘esto nunc Sol testis et haec mihi terra uocanti,<br>quam propter tantos potui perferre labores,<br>et pater omnipotens et tu Saturnia coniunx<br>(iam melior, iam, diua, precor), tuque inclute Mauors,<br>cuncta tuo qui bella, pater, sub numine torques;   180<br>fontisque fluuiosque uoco, quaeque aetheris alti<br>religio et quae caeruleo sunt numina ponto:<br>cesserit Ausonio si fors uictoria Turno,<br>conuenit Euandri uictos discedere ad urbem,<br>cedet Iulus agris, nec post arma ulla rebelles   185<br>Aeneadae referent ferroue haec regna lacessent.<br>sin nostrum adnuerit nobis uictoria Martem<br>(ut potius reor et potius di numine firment),<br>non ego nec Teucris Italos parere iubebo<br>nec mihi regna peto: paribus se legibus ambae   190<br>inuictae gentes aeterna in foedera mittant.<br>sacra deosque dabo; socer arma Latinus habeto,<br>imperium sollemne socer; mihi moenia Teucri<br>constituent urbique dabit Lauinia nomen.’","st":"12"},{"sp":"N","t":"Sic prior Aeneas, sequitur sic deinde Latinus   195<br>suspiciens caelum, tenditque ad sidera dextram:<br>‘haec eadem, Aenea, terram, mare, sidera, iuro<br>Latonaeque genus duplex Ianumque bifrontem,<br>uimque deum infernam et duri sacraria Ditis;<br>audiat haec genitor qui foedera fulmine sancit.   200<br>tango aras, medios ignis et numina testor:<br>nulla dies pacem hanc Italis nec foedera rumpet,<br>quo res cumque cadent; nec me uis ulla uolentem<br>auertet, non, si tellurem effundat in undas<br>diluuio miscens caelumque in Tartara soluat,   205<br>ut sceptrum hoc’ (dextra sceptrum nam forte gerebat)<br>‘numquam fronde leui fundet uirgulta nec umbras,<br>cum semel in siluis imo de stirpe recisum<br>matre caret posuitque comas et bracchia ferro,<br>olim arbos, nunc artificis manus aere decoro   210<br>inclusit patribusque dedit gestare Latinis.’<br>talibus inter se firmabant foedera dictis<br>conspectu in medio procerum. tum rite sacratas<br>in flammam iugulant pecudes et uiscera uiuis<br>eripiunt, cumulantque oneratis lancibus aras.    215","st":"12"},{"sp":"N","t":"At uero Rutulis impar ea pugna uideri<br>iamdudum et uario misceri pectora motu,<br>tum magis ut propius cernunt non uiribus aequos.<br>adiuuat incessu tacito progressus et aram<br>suppliciter uenerans demisso lumine Turnus   220<br>pubentesque genae et iuuenali in corpore pallor.<br>quem simul ac Iuturna soror crebrescere uidit<br>sermonem et uulgi uariare labantia corda,<br>in medias acies formam adsimulata Camerti,<br>cui genus a proauis ingens clarumque paternae   225<br>nomen erat uirtutis, et ipse acerrimus armis,<br>in medias dat sese acies haud nescia rerum<br>rumoresque serit uarios ac talia fatur:<br>‘non pudet, o Rutuli, pro cunctis talibus unam<br>obiectare animam? numerone an uiribus aequi   230<br>non sumus? en, omnes et Troes et Arcades hi sunt,<br>fatalisque manus, infensa Etruria Turno:<br>uix hostem, alterni si congrediamur, habemus.<br>ille quidem ad superos, quorum se deuouet aris,<br>succedet fama uiuusque per ora feretur;   235<br>nos patria amissa dominis parere superbis<br>cogemur, qui nunc lenti consedimus aruis.’","st":"12"},{"sp":"N","t":"Talibus incensa est iuuenum sententia dictis<br>iam magis atque magis, serpitque per agmina murmur:<br>ipsi Laurentes mutati ipsique Latini.   240<br>qui sibi iam requiem pugnae rebusque salutem<br>sperabant, nunc arma uolunt foedusque precantur<br>infectum et Turni sortem miserantur iniquam.<br>his aliud maius Iuturna adiungit et alto<br>dat signum caelo, quo non praesentius ullum    245<br>turbauit mentes Italas monstroque fefellit.<br>namque uolans rubra fuluus Iouis ales in aethra<br>litoreas agitabat auis turbamque sonantem<br>agminis aligeri, subito cum lapsus ad undas<br>cycnum excellentem pedibus rapit improbus uncis.   250<br>arrexere animos Itali, cunctaeque uolucres<br>conuertunt clamore fugam (mirabile uisu),<br>aetheraque obscurant pennis hostemque per auras<br>facta nube premunt, donec ui uictus et ipso<br>pondere defecit praedamque ex unguibus ales   255<br>proiecit fluuio, penitusque in nubila fugit.","st":"12"},{"sp":"N","t":"Tum uero augurium Rutuli clamore salutant<br>expediuntque manus, primusque Tolumnius augur<br>‘hoc erat, hoc uotis’ inquit ‘quod saepe petiui.<br>accipio agnoscoque deos; me, me duce ferrum   260<br>corripite, o miseri, quos improbus aduena bello<br>territat inualidas ut auis, et litora uestra<br>ui populat. petet ille fugam penitusque profundo<br>uela dabit. uos unanimi densete cateruas<br>et regem uobis pugna defendite raptum.’   265<br>dixit, et aduersos telum contorsit in hostis<br>procurrens; sonitum dat stridula cornus et auras<br>certa secat. simul hoc, simul ingens clamor et omnes<br>turbati cunei calefactaque corda tumultu.<br>hasta uolans, ut forte nouem pulcherrima fratrum   270<br>corpora constiterant contra, quos fida crearat<br>una tot Arcadio coniunx Tyrrhena Gylippo,<br>horum unum ad medium, teritur qua sutilis aluo<br>balteus et laterum iuncturas fibula mordet,<br>egregium forma iuuenem et fulgentibus armis,   275<br>transadigit costas fuluaque effundit harena.<br>at fratres, animosa phalanx accensaque luctu,<br>pars gladios stringunt manibus, pars missile ferrum<br>corripiunt caecique ruunt. quos agmina contra<br>procurrunt Laurentum, hinc densi rursus inundant   280<br>Troes Agyllinique et pictis Arcades armis:<br>sic omnis amor unus habet decernere ferro.<br>diripuere aras, it toto turbida caelo<br>tempestas telorum ac ferreus ingruit imber,<br>craterasque focosque ferunt. fugit ipse Latinus   285<br>pulsatos referens infecto foedere diuos.<br>infrenant alii currus aut corpora saltu<br>subiciunt in equos et strictis ensibus adsunt.<br>Messapus regem regisque insigne gerentem<br>Tyrrhenum Aulesten, auidus confundere foedus,   290<br>aduerso proterret equo; ruit ille recedens<br>et miser oppositis a tergo inuoluitur aris<br>in caput inque umeros. at feruidus aduolat hasta<br>Messapus teloque orantem multa trabali<br>desuper altus equo grauiter ferit atque ita fatur:   295<br>‘hoc habet, haec melior magnis data uictima diuis.’<br>concurrunt Itali spoliantque calentia membra.<br>obuius ambustum torrem Corynaeus ab ara<br>corripit et uenienti Ebyso plagamque ferenti<br>occupat os flammis: olli ingens barba reluxit   300<br>nidoremque ambusta dedit. super ipse secutus<br>caesariem laeua turbati corripit hostis<br>impressoque genu nitens terrae applicat ipsum;<br>sic rigido latus ense ferit. Podalirius Alsum<br>pastorem primaque acie per tela ruentem   305<br>ense sequens nudo superimminet; ille securi<br>aduersi frontem mediam mentumque reducta<br>dissicit et sparso late rigat arma cruore.<br>olli dura quies oculos et ferreus urget<br>somnus, in aeternam conduntur lumina noctem.    310","st":"12"},{"sp":"N","t":"At pius Aeneas dextram tendebat inermem<br>nudato capite atque suos clamore uocabat:<br>‘quo ruitis? quaeue ista repens discordia surgit?<br>o cohibete iras! ictum iam foedus et omnes<br>compositae leges. mihi ius concurrere soli;   315<br>me sinite atque auferte metus. ego foedera faxo<br>firma manu; Turnum debent haec iam mihi sacra.’<br>has inter uoces, media inter talia uerba<br>ecce uiro stridens alis adlapsa sagitta est,<br>incertum qua pulsa manu, quo turbine adacta,   320<br>quis tantam Rutulis laudem, casusne deusne,<br>attulerit; pressa est insignis gloria facti,<br>nec sese Aeneae iactauit uulnere quisquam.<br>Turnus ut Aenean cedentem ex agmine uidit<br>turbatosque duces, subita spe feruidus ardet;   325<br>poscit equos atque arma simul, saltuque superbus<br>emicat in currum et manibus molitur habenas.<br>multa uirum uolitans dat fortia corpora leto.<br>seminecis uoluit multos: aut agmina curru<br>proterit aut raptas fugientibus ingerit hastas.   330<br>qualis apud gelidi cum flumina concitus Hebri<br>sanguineus Mauors clipeo increpat atque furentis<br>bella mouens immittit equos, illi aequore aperto<br>ante Notos Zephyrumque uolant, gemit ultima pulsu<br>Thraca pedum circumque atrae Formidinis ora   335<br>Iraeque Insidiaeque, dei comitatus, aguntur:<br>talis equos alacer media inter proelia Turnus<br>fumantis sudore quatit, miserabile caesis<br>hostibus insultans; spargit rapida ungula rores<br>sanguineos mixtaque cruor calcatur harena.   340<br>iamque neci Sthenelumque dedit Thamyrumque Pholumque,<br>hunc congressus et hunc, illum eminus; eminus ambo<br>Imbrasidas, Glaucum atque Laden, quos Imbrasus ipse<br>nutrierat Lycia paribusque ornauerat armis<br>uel conferre manum uel equo praeuertere uentos.   345","st":"12"},{"sp":"N","t":"Parte alia media Eumedes in proelia fertur,<br>antiqui proles bello praeclara Dolonis,<br>nomine auum referens, animo manibusque parentem,<br>qui quondam, castra ut Danaum speculator adiret,<br>ausus Pelidae pretium sibi poscere currus;   350<br>illum Tydides alio pro talibus ausis<br>adfecit pretio nec equis aspirat Achilli.<br>hunc procul ut campo Turnus prospexit aperto,<br>ante leui iaculo longum per inane secutus<br>sistit equos biiugis et curru desilit atque   355<br>semianimi lapsoque superuenit, et pede collo<br>impresso dextrae mucronem extorquet et alto<br>fulgentem tingit iugulo atque haec insuper addit:<br>‘en agros et, quam bello, Troiane, petisti,<br>Hesperiam metire iacens: haec praemia, qui me   360<br>ferro ausi temptare, ferunt, sic moenia condunt.’<br>huic comitem Asbyten coniecta cuspide mittit<br>Chloreaque Sybarimque Daretaque Thersilochumque<br>et sternacis equi lapsum ceruice Thymoeten.<br>ac uelut Edoni Boreae cum spiritus alto   365<br>insonat Aegaeo sequiturque ad litora fluctus,<br>qua uenti incubuere, fugam dant nubila caelo:<br>sic Turno, quacumque uiam secat, agmina cedunt<br>conuersaeque ruunt acies; fert impetus ipsum<br>et cristam aduerso curru quatit aura uolantem.   370<br>non tulit instantem Phegeus animisque frementem<br>obiecit sese ad currum et spumantia frenis<br>ora citatorum dextra detorsit equorum.<br>dum trahitur pendetque iugis, hunc lata retectum<br>lancea consequitur rumpitque infixa bilicem   375<br>loricam et summum degustat uulnere corpus.<br>ille tamen clipeo obiecto conuersus in hostem<br>ibat et auxilium ducto mucrone petebat,<br>cum rota praecipitem et procursu concitus axis<br>impulit effunditque solo, Turnusque secutus   380<br>imam inter galeam summi thoracis et oras<br>abstulit ense caput truncumque reliquit harenae.","st":"12"},{"sp":"N","t":"Atque ea dum campis uictor dat funera Turnus,<br>interea Aenean Mnestheus et fidus Achates<br>Ascaniusque comes castris statuere cruentum   385<br>alternos longa nitentem cuspide gressus.<br>saeuit et infracta luctatur harundine telum<br>eripere auxilioque uiam, quae proxima, poscit:<br>ense secent lato uulnus telique latebram<br>rescindant penitus, seseque in bella remittant.   390<br>iamque aderat Phoebo ante alios dilectus Iapyx<br>Iasides, acri quondam cui captus amore<br>ipse suas artis, sua munera, laetus Apollo<br>augurium citharamque dabat celerisque sagittas.<br>ille, ut depositi proferret fata parentis,   395<br>scire potestates herbarum usumque medendi<br>maluit et mutas agitare inglorius artis.<br>stabat acerba fremens ingentem nixus in hastam<br>Aeneas magno iuuenum et maerentis Iuli<br>concursu, lacrimis immobilis. ille retorto   400<br>Paeonium in morem senior succinctus amictu<br>multa manu medica Phoebique potentibus herbis<br>nequiquam trepidat, nequiquam spicula dextra<br>sollicitat prensatque tenaci forcipe ferrum.<br>nulla uiam Fortuna regit, nihil auctor Apollo    405<br>subuenit, et saeuus campis magis ac magis horror<br>crebrescit propiusque malum est. iam puluere caelum<br>stare uident: subeunt equites et spicula castris<br>densa cadunt mediis. it tristis ad aethera clamor<br>bellantum iuuenum et duro sub Marte cadentum.   410","st":"12"},{"sp":"N","t":"Hic Venus indigno nati concussa dolore<br>dictamnum genetrix Cretaea carpit ab Ida,<br>puberibus caulem foliis et flore comantem<br>purpureo; non illa feris incognita capris<br>gramina, cum tergo uolucres haesere sagittae.   415<br>hoc Venus obscuro faciem circumdata nimbo<br>detulit, hoc fusum labris splendentibus amnem<br>inficit occulte medicans, spargitque salubris<br>ambrosiae sucos et odoriferam panaceam.<br>fouit ea uulnus lympha longaeuus Iapyx   420<br>ignorans, subitoque omnis de corpore fugit<br>quippe dolor, omnis stetit imo uulnere sanguis.<br>iamque secuta manum nullo cogente sagitta<br>excidit, atque nouae rediere in pristina uires.<br>‘arma citi properate uiro! quid statis?’ Iapyx   425<br>conclamat primusque animos accendit in hostem.<br>‘non haec humanis opibus, non arte magistra<br>proueniunt, neque te, Aenea, mea dextera seruat:<br>maior agit deus atque opera ad maiora remittit.’<br>ille auidus pugnae suras incluserat auro   430<br>hinc atque hinc oditque moras hastamque coruscat.<br>postquam habilis lateri clipeus loricaque tergo est,<br>Ascanium fusis circum complectitur armis<br>summaque per galeam delibans oscula fatur:<br>‘disce, puer, uirtutem ex me uerumque laborem,   435<br>fortunam ex aliis. nunc te mea dextera bello<br>defensum dabit et magna inter praemia ducet.<br>tu facito, mox cum matura adoleuerit aetas,<br>sis memor et te animo repetentem exempla tuorum<br>et pater Aeneas et auunculus excitet Hector.’   440","st":"12"},{"sp":"N","t":"Haec ubi dicta dedit, portis sese extulit ingens<br>telum immane manu quatiens; simul agmine denso<br>Antheusque Mnestheusque ruunt, omnisque relictis<br>turba fluit castris. tum caeco puluere campus<br>miscetur pulsuque pedum tremit excita tellus.   445<br>uidit ab aduerso uenientis aggere Turnus,<br>uidere Ausonii, gelidusque per ima cucurrit<br>ossa tremor; prima ante omnis Iuturna Latinos<br>audiit agnouitque sonum et tremefacta refugit.<br>ille uolat campoque atrum rapit agmen aperto.   450<br>qualis ubi ad terras abrupto sidere nimbus<br>it mare per medium (miseris, heu, praescia longe<br>horrescunt corda agricolis: dabit ille ruinas<br>arboribus stragemque satis, ruet omnia late),<br>ante uolant sonitumque ferunt ad litora uenti:   455<br>talis in aduersos ductor Rhoeteius hostis<br>agmen agit, densi cuneis se quisque coactis<br>adglomerant. ferit ense grauem Thymbraeus Osirim,<br>Arcetium Mnestheus, Epulonem obtruncat Achates<br>Vfentemque Gyas; cadit ipse Tolumnius augur,   460<br>primus in aduersos telum qui torserat hostis.<br>tollitur in caelum clamor, uersique uicissim<br>puluerulenta fuga Rutuli dant terga per agros.<br>ipse neque auersos dignatur sternere morti<br>nec pede congressos aequo nec tela ferentis   465<br>insequitur: solum densa in caligine Turnum<br>uestigat lustrans, solum in certamina poscit.","st":"12"},{"sp":"N","t":"Hoc concussa metu mentem Iuturna uirago<br>aurigam Turni media inter lora Metiscum<br>excutit et longe lapsum temone reliquit;   470<br>ipsa subit manibusque undantis flectit habenas<br>cuncta gerens, uocemque et corpus et arma Metisci.<br>nigra uelut magnas domini cum diuitis aedes<br>peruolat et pennis alta atria lustrat hirundo<br>pabula parua legens nidisque loquacibus escas,   475<br>et nunc porticibus uacuis, nunc umida circum<br>stagna sonat: similis medios Iuturna per hostis<br>fertur equis rapidoque uolans obit omnia curru,<br>iamque hic germanum iamque hic ostentat ouantem<br>nec conferre manum patitur, uolat auia longe.   480<br>haud minus Aeneas tortos legit obuius orbis,<br>uestigatque uirum et disiecta per agmina magna<br>uoce uocat. quotiens oculos coniecit in hostem<br>alipedumque fugam cursu temptauit equorum,<br>auersos totiens currus Iuturna retorsit.   485<br>heu, quid agat? uario nequiquam fluctuat aestu,<br>diuersaeque uocant animum in contraria curae.<br>huic Messapus, uti laeua duo forte gerebat<br>lenta, leuis cursu, praefixa hastilia ferro,<br>horum unum certo contorquens derigit ictu.   490<br>substitit Aeneas et se collegit in arma<br>poplite subsidens; apicem tamen incita summum<br>hasta tulit summasque excussit uertice cristas.<br>tum uero adsurgunt irae, insidiisque subactus,<br>diuersos ubi sensit equos currumque referri,   495<br>multa Iouem et laesi testatus foederis aras<br>iam tandem inuadit medios et Marte secundo<br>terribilis saeuam nullo discrimine caedem<br>suscitat, irarumque omnis effundit habenas.","st":"12"},{"sp":"N","t":"Quis mihi nunc tot acerba deus, quis carmine caedes   500<br>diuersas obitumque ducum, quos aequore toto<br>inque uicem nunc Turnus agit, nunc Troius heros,<br>expediat? tanton placuit concurrere motu,<br>Iuppiter, aeterna gentis in pace futuras?<br>Aeneas Rutulum Sucronem (ea prima ruentis   505<br>pugna loco statuit Teucros) haud multa morantem<br>excipit in latus et, qua fata celerrima, crudum<br>transadigit costas et cratis pectoris ensem.<br>Turnus equo deiectum Amycum fratremque Dioren,<br>congressus pedes, hunc uenientem cuspide longa,   510<br>hunc mucrone ferit, curruque abscisa duorum<br>suspendit capita et rorantia sanguine portat.<br>ille Talon Tanaimque neci fortemque Cethegum,<br>tris uno congressu, et maestum mittit Oniten,<br>nomen Echionium matrisque genus Peridiae;   515<br>hic fratres Lycia missos et Apollinis agris<br>et iuuenem exosum nequiquam bella Menoeten,<br>Arcada, piscosae cui circum flumina Lernae<br>ars fuerat pauperque domus nec nota potentum<br>munera, conductaque pater tellure serebat.   520<br>ac uelut immissi diuersis partibus ignes<br>arentem in siluam et uirgulta sonantia lauro,<br>aut ubi decursu rapido de montibus altis<br>dant sonitum spumosi amnes et in aequora currunt<br>quisque suum populatus iter: non segnius ambo   525<br>Aeneas Turnusque ruunt per proelia; nunc, nunc<br>fluctuat ira intus, rumpuntur nescia uinci<br>pectora, nunc totis in uulnera uiribus itur.","st":"12"},{"sp":"N","t":"Murranum hic, atauos et auorum antiqua sonantem<br>nomina per regesque actum genus omne Latinos,   530<br>praecipitem scopulo atque ingentis turbine saxi<br>excutit effunditque solo; hunc lora et iuga subter<br>prouoluere rotae, crebro super ungula pulsu<br>incita nec domini memorum proculcat equorum.<br>ille ruenti Hyllo animisque immane frementi   535<br>occurrit telumque aurata ad tempora torquet:<br>olli per galeam fixo stetit hasta cerebro.<br>dextera nec tua te, Graium fortissime Cretheu,<br>eripuit Turno, nec di texere Cupencum<br>Aenea ueniente sui: dedit obuia ferro   540<br>pectora, nec misero clipei mora profuit aerei.<br>te quoque Laurentes uiderunt, Aeole, campi<br>oppetere et late terram consternere tergo.<br>occidis, Argiuae quem non potuere phalanges<br>sternere nec Priami regnorum euersor Achilles;   545<br>hic tibi mortis erant metae, domus alta sub Ida,<br>Lyrnesi domus alta, solo Laurente sepulcrum.<br>totae adeo conuersae acies omnesque Latini,<br>omnes Dardanidae, Mnestheus acerque Serestus<br>et Messapus equum domitor et fortis Asilas   550<br>Tuscorumque phalanx Euandrique Arcades alae,<br>pro se quisque uiri summa nituntur opum ui;<br>nec mora nec requies, uasto certamine tendunt.","st":"12"},{"sp":"N","t":"Hic mentem Aeneae genetrix pulcherrima misit<br>iret ut ad muros urbique aduerteret agmen   555<br>ocius et subita turbaret clade Latinos.<br>ille ut uestigans diuersa per agmina Turnum<br>huc atque huc acies circumtulit, aspicit urbem<br>immunem tanti belli atque impune quietam.<br>continuo pugnae accendit maioris imago:   560<br>Mnesthea Sergestumque uocat fortemque Serestum<br>ductores, tumulumque capit quo cetera Teucrum<br>concurrit legio, nec scuta aut spicula densi<br>deponunt. celso medius stans aggere fatur:<br>‘ne qua meis esto dictis mora, Iuppiter hac stat,   565<br>neu quis ob inceptum subitum mihi segnior ito.<br>urbem hodie, causam belli, regna ipsa Latini,<br>ni frenum accipere et uicti parere fatentur,<br>eruam et aequa solo fumantia culmina ponam.<br>scilicet exspectem libeat dum proelia Turno   570<br>nostra pati rursusque uelit concurrere uictus?<br>hoc caput, o ciues, haec belli summa nefandi.<br>ferte faces propere foedusque reposcite flammis.’<br>dixerat, atque animis pariter certantibus omnes<br>dant cuneum densaque ad muros mole feruntur;   575<br>scalae improuiso subitusque apparuit ignis.<br>discurrunt alii ad portas primosque trucidant,<br>ferrum alii torquent et obumbrant aethera telis.<br>ipse inter primos dextram sub moenia tendit<br>Aeneas, magnaque incusat uoce Latinum   580<br>testaturque deos iterum se ad proelia cogi,<br>bis iam Italos hostis, haec altera foedera rumpi.<br>exoritur trepidos inter discordia ciuis:<br>urbem alii reserare iubent et pandere portas<br>Dardanidis ipsumque trahunt in moenia regem;   585<br>arma ferunt alii et pergunt defendere muros,<br>inclusas ut cum latebroso in pumice pastor<br>uestigauit apes fumoque impleuit amaro;<br>illae intus trepidae rerum per cerea castra<br>discurrunt magnisque acuunt stridoribus iras;   590<br>uoluitur ater odor tectis, tum murmure caeco<br>intus saxa sonant, uacuas it fumus ad auras.","st":"12"},{"sp":"N","t":"Accidit haec fessis etiam fortuna Latinis,<br>quae totam luctu concussit funditus urbem.<br>regina ut tectis uenientem prospicit hostem,   595<br>incessi muros, ignis ad tecta uolare,<br>nusquam acies contra Rutulas, nulla agmina Turni,<br>infelix pugnae iuuenem in certamine credit<br>exstinctum et subito mentem turbata dolore<br>se causam clamat crimenque caputque malorum,   600<br>multaque per maestum demens effata furorem<br>purpureos moritura manu discindit amictus<br>et nodum informis leti trabe nectit ab alta.<br>quam cladem miserae postquam accepere Latinae,<br>filia prima manu flauos Lauinia crinis   605<br>et roseas laniata genas, tum cetera circum<br>turba furit, resonant late plangoribus aedes.<br>hinc totam infelix uulgatur fama per urbem:<br>demittunt mentes, it scissa ueste Latinus<br>coniugis attonitus fatis urbisque ruina,   610<br>canitiem immundo perfusam puluere turpans.","st":"12"},{"sp":"N","t":"Interea extremo bellator in aequore Turnus   614<br>palantis sequitur paucos iam segnior atque<br>iam minus atque minus successu laetus equorum.<br>attulit hunc illi caecis terroribus aura<br>commixtum clamorem, arrectasque impulit auris<br>confusae sonus urbis et inlaetabile murmur.<br>‘ei mihi! quid tanto turbantur moenia luctu?   620<br>quisue ruit tantus diuersa clamor ab urbe?’<br>sic ait, adductisque amens subsistit habenis.<br>atque huic, in faciem soror ut conuersa Metisci<br>aurigae currumque et equos et lora regebat,<br>talibus occurrit dictis: ‘hac, Turne, sequamur   625<br>Troiugenas, qua prima uiam uictoria pandit;<br>sunt alii qui tecta manu defendere possint.<br>ingruit Aeneas Italis et proelia miscet,<br>et nos saeua manu mittamus funera Teucris.<br>nec numero inferior pugnae neque honore recedes.’   630<br>Turnus ad haec:<br>‘o soror, et dudum agnoui, cum prima per artem<br>foedera turbasti teque haec in bella dedisti,<br>et nunc nequiquam fallis dea. sed quis Olympo<br>demissam tantos uoluit te ferre labores?   635<br>an fratris miseri letum ut crudele uideres?<br>nam quid ago? aut quae iam spondet Fortuna salutem?<br>uidi oculos ante ipse meos me uoce uocantem<br>Murranum, quo non superat mihi carior alter,<br>oppetere ingentem atque ingenti uulnere uictum.   640<br>occidit infelix ne nostrum dedecus Vfens<br>aspiceret; Teucri potiuntur corpore et armis.<br>exscindine domos (id rebus defuit unum)<br>perpetiar, dextra nec Drancis dicta refellam?<br>terga dabo et Turnum fugientem haec terra uidebit?   645<br>usque adeone mori miserum est? uos o mihi, Manes,<br>este boni, quoniam superis auersa uoluntas.<br>sancta ad uos anima atque istius inscia culpae<br>descendam magnorum haud umquam indignus auorum.’","st":"12"},{"sp":"N","t":"Vix ea fatus erat: medios uolat ecce per hostis   650<br>uectus equo spumante Saces, aduersa sagitta<br>saucius ora, ruitque implorans nomine Turnum:<br>‘Turne, in te suprema salus, miserere tuorum.<br>fulminat Aeneas armis summasque minatur<br>deiecturum arces Italum excidioque daturum,   655<br>iamque faces ad tecta uolant. in te ora Latini,<br>in te oculos referunt; mussat rex ipse Latinus<br>quos generos uocet aut quae sese ad foedera flectat.<br>praeterea regina, tui fidissima, dextra<br>occidit ipsa sua lucemque exterrita fugit.   660<br>soli pro portis Messapus et acer Atinas<br>sustentant acies. circum hos utrimque phalanges<br>stant densae strictisque seges mucronibus horret<br>ferrea; tu currum deserto in gramine uersas.’<br>obstipuit uaria confusus imagine rerum   665<br>Turnus et obtutu tacito stetit; aestuat ingens<br>uno in corde pudor mixtoque insania luctu<br>et furiis agitatus amor et conscia uirtus.<br>ut primum discussae umbrae et lux reddita menti,<br>ardentis oculorum orbis ad moenia torsit   670<br>turbidus eque rotis magnam respexit ad urbem.","st":"12"},{"sp":"N","t":"Ecce autem flammis inter tabulata uolutus<br>ad caelum undabat uertex turrimque tenebat,<br>turrim compactis trabibus quam eduxerat ipse<br>subdideratque rotas pontisque instrauerat altos.   675<br>‘iam iam fata, soror, superant, absiste morari;<br>quo deus et quo dura uocat Fortuna sequamur.<br>stat conferre manum Aeneae, stat, quidquid acerbi est,<br>morte pati, neque me indecorem, germana, uidebis<br>amplius. hunc, oro, sine me furere ante furorem.’   680<br>dixit, et e curru saltum dedit ocius aruis<br>perque hostis, per tela ruit maestamque sororem<br>deserit ac rapido cursu media agmina rumpit.<br>ac ueluti montis saxum de uertice praeceps<br>cum ruit auulsum uento, seu turbidus imber   685<br>proluit aut annis soluit sublapsa uetustas;<br>fertur in abruptum magno mons improbus actu<br>exsultatque solo, siluas armenta uirosque<br>inuoluens secum: disiecta per agmina Turnus<br>sic urbis ruit ad muros, ubi plurima fuso   690<br>sanguine terra madet striduntque hastilibus aurae,<br>significatque manu et magno simul incipit ore:<br>‘parcite iam, Rutuli, et uos tela inhibete, Latini.<br>quaecumque est fortuna, mea est; me uerius unum<br>pro uobis foedus luere et decernere ferro.’   695<br>discessere omnes medii spatiumque dedere.","st":"12"},{"sp":"N","t":"At pater Aeneas audito nomine Turni<br>deserit et muros et summas deserit arces<br>praecipitatque moras omnis, opera omnia rumpit<br>laetitia exsultans horrendumque intonat armis:   700<br>quantus Athos aut quantus Eryx aut ipse coruscis<br>cum fremit ilicibus quantus gaudetque niuali<br>uertice se attollens pater Appenninus ad auras.<br>iam uero et Rutuli certatim et Troes et omnes<br>conuertere oculos Itali, quique alta tenebant   705<br>moenia quique imos pulsabant ariete muros,<br>armaque deposuere umeris. stupet ipse Latinus<br>ingentis, genitos diuersis partibus orbis,<br>inter se coiisse uiros et cernere ferro.<br>atque illi, ut uacuo patuerunt aequore campi,   710<br>procursu rapido coniectis eminus hastis<br>inuadunt Martem clipeis atque aere sonoro.<br>dat gemitum tellus; tum crebros ensibus ictus<br>congeminant, fors et uirtus miscetur in unum.<br>ac uelut ingenti Sila summoue Taburno   715<br>cum duo conuersis inimica in proelia tauri<br>frontibus incurrunt, pauidi cessere magistri,<br>stat pecus omne metu mutum, mussantque iuuencae<br>quis nemori imperitet, quem tota armenta sequantur;<br>illi inter sese multa ui uulnera miscent   720<br>cornuaque obnixi infigunt et sanguine largo<br>colla armosque lauant, gemitu nemus omne remugit:<br>non aliter Tros Aeneas et Daunius heros<br>concurrunt clipeis, ingens fragor aethera complet.<br>Iuppiter ipse duas aequato examine lances   725<br>sustinet et fata imponit diuersa duorum,<br>quem damnet labor et quo uergat pondere letum.","st":"12"},{"sp":"N","t":"Emicat hic impune putans et corpore toto<br>alte sublatum consurgit Turnus in ensem<br>et ferit; exclamant Troes trepidique Latini,   730<br>arrectaeque amborum acies. at perfidus ensis<br>frangitur in medioque ardentem deserit ictu,<br>ni fuga subsidio subeat. fugit ocior Euro<br>ut capulum ignotum dextramque aspexit inermem.<br>fama est praecipitem, cum prima in proelia iunctos   735<br>conscendebat equos, patrio mucrone relicto,<br>dum trepidat, ferrum aurigae rapuisse Metisci;<br>idque diu, dum terga dabant palantia Teucri,<br>suffecit; postquam arma dei ad Volcania uentum est,<br>mortalis mucro glacies ceu futtilis ictu   740<br>dissiluit, fulua resplendent fragmina harena.<br>ergo amens diuersa fuga petit aequora Turnus<br>et nunc huc, inde huc incertos implicat orbis;<br>undique enim densa Teucri inclusere corona<br>atque hinc uasta palus, hinc ardua moenia cingunt.   745","st":"12"},{"sp":"N","t":"Nec minus Aeneas, quamquam tardata sagitta<br>interdum genua impediunt cursumque recusant,<br>insequitur trepidique pedem pede feruidus urget:<br>inclusum ueluti si quando flumine nactus<br>ceruum aut puniceae saeptum formidine pennae   750<br>uenator cursu canis et latratibus instat;<br>ille autem insidiis et ripa territus alta<br>mille fugit refugitque uias, at uiuidus Vmber<br>haeret hians, iam iamque tenet similisque tenenti<br>increpuit malis morsuque elusus inani est;   755<br>tum uero exoritur clamor ripaeque lacusque<br>responsant circa et caelum tonat omne tumultu.<br>ille simul fugiens Rutulos simul increpat omnis<br>nomine quemque uocans notumque efflagitat ensem.<br>Aeneas mortem contra praesensque minatur   760<br>exitium, si quisquam adeat, terretque trementis<br>excisurum urbem minitans et saucius instat.<br>quinque orbis explent cursu totidemque retexunt<br>huc illuc; neque enim leuia aut ludicra petuntur<br>praemia, sed Turni de uita et sanguine certant.   765","st":"12"},{"sp":"N","t":"Forte sacer Fauno foliis oleaster amaris<br>hic steterat, nautis olim uenerabile lignum,<br>seruati ex undis ubi figere dona solebant<br>Laurenti diuo et uotas suspendere uestis;<br>sed stirpem Teucri nullo discrimine sacrum   770<br>sustulerant, puro ut possent concurrere campo.<br>hic hasta Aeneae stabat, huc impetus illam<br>detulerat fixam et lenta radice tenebat.<br>incubuit uoluitque manu conuellere ferrum<br>Dardanides, teloque sequi quem prendere cursu   775<br>non poterat. tum uero amens formidine Turnus<br>‘Faune, precor, miserere’ inquit ‘tuque optima ferrum<br>Terra tene, colui uestros si semper honores,<br>quos contra Aeneadae bello fecere profanos.’<br>dixit, opemque dei non cassa in uota uocauit.   780<br>namque diu luctans lentoque in stirpe moratus<br>uiribus haud ullis ualuit discludere morsus<br>roboris Aeneas. dum nititur acer et instat,<br>rursus in aurigae faciem mutata Metisci<br>procurrit fratrique ensem dea Daunia reddit.   785<br>quod Venus audaci nymphae indignata licere<br>accessit telumque alta ab radice reuellit.<br>olli sublimes armis animisque refecti,<br>hic gladio fidens, hic acer et arduus hasta,<br>adsistunt contra certamina Martis anheli.   790","st":"12"},{"sp":"N","t":"Iunonem interea rex omnipotentis Olympi<br>adloquitur fulua pugnas de nube tuentem:<br>‘quae iam finis erit, coniunx? quid denique restat?<br>indigetem Aenean scis ipsa et scire fateris<br>deberi caelo fatisque ad sidera tolli.   795<br>quid struis? aut qua spe gelidis in nubibus haeres?<br>mortalin decuit uiolari uulnere diuum?<br>aut ensem (quid enim sine te Iuturna ualeret?)<br>ereptum reddi Turno et uim crescere uictis?<br>desine iam tandem precibusque inflectere nostris,   800<br>ne te tantus edit tacitam dolor et mihi curae<br>saepe tuo dulci tristes ex ore recursent.<br>uentum ad supremum est. terris agitare uel undis<br>Troianos potuisti, infandum accendere bellum,<br>deformare domum et luctu miscere hymenaeos:   805<br>ulterius temptare ueto.’ sic Iuppiter orsus;<br>sic dea summisso contra Saturnia uultu:<br>‘ista quidem quia nota mihi tua, magne, uoluntas,<br>Iuppiter, et Turnum et terras inuita reliqui;<br>nec tu me aeria solam nunc sede uideres   810<br>digna indigna pati, sed flammis cincta sub ipsa<br>starem acie traheremque inimica in proelia Teucros.<br>Iuturnam misero (fateor) succurrere fratri<br>suasi et pro uita maiora audere probaui,<br>non ut tela tamen, non ut contenderet arcum;   815<br>adiuro Stygii caput implacabile fontis,<br>una superstitio superis quae reddita diuis.<br>et nunc cedo equidem pugnasque exosa relinquo.<br>illud te, nulla fati quod lege tenetur,<br>pro Latio obtestor, pro maiestate tuorum:   820<br>cum iam conubiis pacem felicibus (esto)<br>component, cum iam leges et foedera iungent,<br>ne uetus indigenas nomen mutare Latinos<br>neu Troas fieri iubeas Teucrosque uocari<br>aut uocem mutare uiros aut uertere uestem.   825<br>sit Latium, sint Albani per saecula reges,<br>sit Romana potens Itala uirtute propago:<br>occidit, occideritque sinas cum nomine Troia.’<br>olli subridens hominum rerumque repertor:<br>‘es germana Iouis Saturnique altera proles,   830<br>irarum tantos uoluis sub pectore fluctus.<br>uerum age et inceptum frustra summitte furorem:<br>do quod uis, et me uictusque uolensque remitto.<br>sermonem Ausonii patrium moresque tenebunt,<br>utque est nomen erit; commixti corpore tantum   835<br>subsident Teucri. morem ritusque sacrorum<br>adiciam faciamque omnis uno ore Latinos.<br>hinc genus Ausonio mixtum quod sanguine surget,<br>supra homines, supra ire deos pietate uidebis,<br>nec gens ulla tuos aeque celebrabit honores.’   840<br>adnuit his Iuno et mentem laetata retorsit;<br>interea excedit caelo nubemque relinquit.","st":"12"},{"sp":"N","t":"His actis aliud genitor secum ipse uolutat<br>Iuturnamque parat fratris dimittere ab armis.<br>dicuntur geminae pestes cognomine Dirae,   845<br>quas et Tartaream Nox intempesta Megaeram<br>uno eodemque tulit partu, paribusque reuinxit<br>serpentum spiris uentosasque addidit alas.<br>hae Iouis ad solium saeuique in limine regis<br>apparent acuuntque metum mortalibus aegris,   850<br>si quando letum horrificum morbosque deum rex<br>molitur, meritas aut bello territat urbes.<br>harum unam celerem demisit ab aethere summo<br>Iuppiter inque omen Iuturnae occurrere iussit:<br>illa uolat celerique ad terram turbine fertur.   855<br>non secus ac neruo per nubem impulsa sagitta,<br>armatam saeui Parthus quam felle ueneni,<br>Parthus siue Cydon, telum immedicabile, torsit,<br>stridens et celeris incognita transilit umbras:<br>talis se sata Nocte tulit terrasque petiuit.   860<br>postquam acies uidet Iliacas atque agmina Turni,<br>alitis in paruae subitam collecta figuram,<br>quae quondam in bustis aut culminibus desertis<br>nocte sedens serum canit importuna per umbras — <br>hanc uersa in faciem Turni se pestis ob ora   865<br>fertque refertque sonans clipeumque euerberat alis.<br>illi membra nouus soluit formidine torpor,<br>arrectaeque horrore comae et uox faucibus haesit.","st":"12"},{"sp":"N","t":"At procul ut Dirae stridorem agnouit et alas,<br>infelix crinis scindit Iuturna solutos   870<br>unguibus ora soror foedans et pectora pugnis:<br>‘quid nunc te tua, Turne, potest germana iuuare?<br>aut quid iam durae superat mihi? qua tibi lucem<br>arte morer? talin possum me opponere monstro?<br>iam iam linquo acies. ne me terrete timentem,   875<br>obscenae uolucres: alarum uerbera nosco<br>letalemque sonum, nec fallunt iussa superba<br>magnanimi Iouis. haec pro uirginitate reponit?<br>quo uitam dedit aeternam? cur mortis adempta est<br>condicio? possem tantos finire dolores   880<br>nunc certe, et misero fratri comes ire per umbras!<br>immortalis ego? aut quicquam mihi dulce meorum<br>te sine, frater, erit? o quae satis ima dehiscat<br>terra mihi, Manisque deam demittat ad imos?’<br>tantum effata caput glauco contexit amictu   885<br>multa gemens et se fluuio dea condidit alto.","st":"12"},{"sp":"N","t":"Aeneas instat contra telumque coruscat<br>ingens arboreum, et saeuo sic pectore fatur:<br>‘quae nunc deinde mora est? aut quid iam, Turne, retractas?<br>non cursu, saeuis certandum est comminus armis.   890<br>uerte omnis tete in facies et contrahe quidquid<br>siue animis siue arte uales; opta ardua pennis<br>astra sequi clausumque caua te condere terra.’<br>ille caput quassans: ‘non me tua feruida terrent<br>dicta, ferox; di me terrent et Iuppiter hostis.’   895<br>nec plura effatus saxum circumspicit ingens,<br>saxum antiquum ingens, campo quod forte iacebat,<br>limes agro positus litem ut discerneret aruis.<br>uix illum lecti bis sex ceruice subirent,<br>qualia nunc hominum producit corpora tellus;   900<br>ille manu raptum trepida torquebat in hostem<br>altior insurgens et cursu concitus heros.<br>sed neque currentem se nec cognoscit euntem<br>tollentemue manu saxumue immane mouentem;<br>genua labant, gelidus concreuit frigore sanguis.   905<br>tum lapis ipse uiri uacuum per inane uolutus<br>nec spatium euasit totum neque pertulit ictum.<br>ac uelut in somnis, oculos ubi languida pressit<br>nocte quies, nequiquam auidos extendere cursus<br>uelle uidemur et in mediis conatibus aegri   910<br>succidimus; non lingua ualet, non corpore notae<br>sufficiunt uires nec uox aut uerba sequuntur:<br>sic Turno, quacumque uiam uirtute petiuit,<br>successum dea dira negat. tum pectore sensus<br>uertuntur uarii; Rutulos aspectat et urbem   915<br>cunctaturque metu letumque instare tremescit,<br>nec quo se eripiat, nec qua ui tendat in hostem,<br>nec currus usquam uidet aurigamue sororem.","st":"12"},{"sp":"N","t":"Cunctanti telum Aeneas fatale coruscat,<br>sortitus fortunam oculis, et corpore toto   920<br>eminus intorquet. murali concita numquam<br>tormento sic saxa fremunt nec fulmine tanti<br>dissultant crepitus. uolat atri turbinis instar<br>exitium dirum hasta ferens orasque recludit<br>loricae et clipei extremos septemplicis orbis;   925<br>per medium stridens transit femur. incidit ictus<br>ingens ad terram duplicato poplite Turnus.<br>consurgunt gemitu Rutuli totusque remugit<br>mons circum et uocem late nemora alta remittunt.<br>ille humilis supplex oculos dextramque precantem   930<br>protendens ‘equidem merui nec deprecor’ inquit;<br>‘utere sorte tua. miseri te si qua parentis<br>tangere cura potest, oro (fuit et tibi talis<br>Anchises genitor) Dauni miserere senectae<br>et me, seu corpus spoliatum lumine mauis,   935<br>redde meis. uicisti et uictum tendere palmas<br>Ausonii uidere; tua est Lauinia coniunx,<br>ulterius ne tende odiis.’ stetit acer in armis<br>Aeneas uoluens oculos dextramque repressit;<br>et iam iamque magis cunctantem flectere sermo   940<br>coeperat, infelix umero cum apparuit alto<br>balteus et notis fulserunt cingula bullis<br>Pallantis pueri, uictum quem uulnere Turnus<br>strauerat atque umeris inimicum insigne gerebat.<br>ille, oculis postquam saeui monimenta doloris   945<br>exuuiasque hausit, furiis accensus et ira<br>terribilis: ‘tune hinc spoliis indute meorum<br>eripiare mihi? Pallas te hoc uulnere, Pallas<br>immolat et poenam scelerato ex sanguine sumit.’<br>hoc dicens ferrum aduerso sub pectore condit   950<br>feruidus; ast illi soluuntur frigore membra<br>uitaque cum gemitu fugit indignata sub umbras.","st":"12"}]);})();
